\section{Preliminary proofs} \label{App:proofs}


\begin{proof}[\textbf{Proof of Proposition \ref{Prop:Probabilities}}]
The result is well known and established in \cite{shiryaev2007optimal} in a more general context. We also refer to \cite[Proposition 2.1]{deangelis2022quickestdetectionproblemfalse} for a proof similar to the one presented here. In our case, some additional care is required due to the specific structure of the filtration under consideration.

First, we show \eqref{Probabilities_and_Pi}. 
Take $A\in \cG^Y_t$, 
\begin{align}
    \begin{aligned}
        \media_\pi [\ind_A \Pi_t] &= \media_\pi [\ind_A \ind_{\{\xi\leq t\}}]\\
        &= \pi \media^0[\ind_A\ind_{\{\xi\leq t\}}]+ (1-\pi)\int_0^\infty  \media^s[\ind_A\ind_{\{\xi\leq t\}}] \lambda \e^{-\lambda s} \ud s\\
        &= \pi \media^0[\ind_A]+ (1-\pi)\int_0^t \media^s[\ind_A] \lambda \e^{-\lambda s} \ud s\\
        &= \media_\pi \bigg[\ind_A \bigg( \pi \frac{\ud \prob^0}{\ud \prob_\pi}\Big|_{ \cG^Y_t} + (1-\pi)\int_0^t \frac{\ud \prob^s}{\ud \prob_\pi}\Big|_{ \cG^Y_t} \lambda \e^{-\lambda s} \ud s \bigg) \bigg],
    \end{aligned}
\end{align}
where the first equality comes from the definition of $\Pi_t$, see \eqref{DefinitionPi}, the second equality use the definition of $\prob_\pi$ in \eqref{definitionProbPi}, the third one uses the definitions of $\prob^0$ and $\prob^s$ given in \eqref{definitionProbs}.

Next, we show \eqref{Probabilities_and_1-Pi}. 
First, we need to prove that for $s > t$\begin{align} \label{eqprob}
\prob^s\given \cG^Y_t=\prob^\infty \given \cG^Y_t.     
\end{align}
Observe that \begin{align}
\begin{aligned}
    \cG^Y_t=&\sigma((Y_{t_1}, H_{t_1})\in A_1,..,(Y_{t_n}, H_{t_n})\in A_n, \\
    &\quad t_1<...<t_n \in [0,t], \  A_1, ...A_n \in \mathcal{B}(\reali\times\{0,1\}), \ n\in \naturali),
\end{aligned}
\end{align}
and since $\reali\times\{0,1\}$ is separable, then $\mathcal{B}(\reali\times\{0,1\})=\mathcal{B}(\reali)\times\mathcal{B}(\{0,1\})$, see \cite[p. 244]{billingsley2013convergence}, it yields
\begin{align}
\begin{aligned}
    \cG^Y_t=&\sigma((Y_{t_1}, H_{t_1})\in C_1\times D_1,..,(Y_{t_n}, H_{t_n})\in C_n\times D_n, \\
    &\quad t_1<...<t_n \in [0,t], \  C_1, ...C_n \in \mathcal{B}(\reali), \ \  D_1, ...D_n \in \mathcal{B}(\{0,1\}),  \ n\in \naturali).
\end{aligned}
\end{align}
Now, take a set $A$ from the generator of $\cG^Y_t$,
\begin{align}
    \begin{aligned}
     \prob^s(A)= \prob^s((Y_{t_1}, H_{t_1})\in C_1\times D_1,..,(Y_{t_n}, H_{t_n})\in C_n\times D_n)
    \end{aligned}
\end{align}
In Remark \ref{HunderPs}, we observed that $H_t=\ind_{\{\mu_1 t\ge \Theta\}}$ $\prob^s-a.s.$ and from \eqref{Eq:dY} we have that $Y_t=\beta B_t$ under $\prob^s$. Hence, denoting $Z_t:=\ind_{\{\mu_1 t\ge \Theta\}}$,
\begin{align}
    \begin{aligned}
     \prob^s(A)&= \prob^s((\beta B_{t_1}, Z_{t_1})\in C_1\times D_1,..,(\beta B_{t_n}, Z_{t_n})\in C_n\times D_n)\\
     &=\mathbb{Q}((\beta B_{t_1}, Z_{t_1})\in C_1\times D_1,..,(\beta B_{t_n}, Z_{t_n})\in C_n\times D_n)
    \end{aligned}
\end{align}
where $\mathbb{Q}$ denotes the probability law of the process $(\beta B_{t}, Z_{t})_{t\ge0}$. By similar arguments,
\begin{align}
    \begin{aligned}
     \prob^\infty(A)=\mathbb{Q}((\beta B_{t_1}, Z_{t_1})\in C_1\times D_1,..,(\beta B_{t_n}, Z_{t_n})\in C_n\times D_n)
    \end{aligned}
\end{align}
from which it follows \eqref{eqprob}. To prove \eqref{Probabilities_and_1-Pi},

take $A\in  \cG^Y_t$,
\begin{align}
    \begin{aligned}
        \media_\pi [\ind_A (1-\Pi_t)] &= \media_\pi [\ind_A \ind_{\{\xi > t\}}]\\
        &=  (1-\pi)\int_0^\infty \media^s[\ind_A \ind_{\{\xi > t\}}] \lambda \e^{-\lambda s} \ud s\\
        &= \media_\pi \bigg[\ind_A  (1-\pi)\int_t^\infty \frac{\ud \prob^s}{\ud \prob_\pi}\Big|_{ \cG^Y_t} \lambda \e^{-\lambda s} \ud s  \bigg]\\
        &= \media_\pi \bigg[\ind_A  (1-\pi)\frac{\ud \prob^\infty}{\ud \prob_\pi}\Big|_{ \cG^Y_t}\int_t^\infty  \lambda \e^{-\lambda s} \ud s  \bigg]\\
        &= \media_\pi \bigg[\ind_A  (1-\pi)\e^{-\lambda t}\frac{\ud \prob^\infty}{\ud \prob_\pi}\Big|_{ \cG^Y_t}    \bigg],
    \end{aligned}
\end{align}
where in the fourth equality, we used \eqref{eqprob}. The proof is complete.

\end{proof}



\begin{proof}[\textbf{Proof of Proposition \ref{App:hatBhatm}}]
We start by proving that $(\hat B_t)_{t\ge 0}$ is a $(\bG^Y,\prob_\pi)$-Brownian motion. 
First, we show that $(\hat B_t)_{t\ge 0}$ is a $(\bG^Y,\prob_\pi)$-martingale.
Observe that $(\hat B_t)_{t\ge 0}$ is integrable and $(\bG^Y,\prob_\pi)$-adapted, and, for $t\ge s$
\begin{align}
    \begin{aligned}
        \media_\pi [\hat B_t\given \cG^Y_s]
        &=\frac{1}{\beta} \media_\pi\bigg[ Y_t-Y_s-\Delta \mu \int_s^t \Pi_u \ud u \Given  \cG^Y_s \bigg]+\frac{1}{\beta} \bigg(Y_s-\Delta \mu \int_0^s \Pi_u \ud u\bigg) \\
        &=\frac{1}{\beta} \media_\pi\bigg[ \beta(B_t-B_s)-\Delta \mu \int_s^t (\ind_{\{u\ge \xi\}}-\Pi_u) \ud u \Given  \cG^Y_s \bigg]+ \hat B_s\\
        &=\frac{1}{\beta} \media_\pi[ \beta(B_t-B_s) \given  \cG^Y_s]+ \hat B_s,
    \end{aligned}
\end{align}
where in the third equality we used the definition of $(Y_t)_{t\ge 0}$ \eqref{Eq:dY} and the last equality we used the tower property.
The process $(B_t)_{t\ge 0}$ is, by definition, a $(\bF,\prob_\pi)$-Brownian motion and, using the immersion property (cf. Remark \ref{Rm:immersion}), it is also a $(\bG,\prob_\pi)$-Brownian motion. By tower property, \[\media_\pi[B_t-B_s\given \cG^Y_s]=\media_\pi[\media_\pi[B_t-B_s\given \cG_s] \given \cG^Y_s]=0.\]

The continuity of $(\hat B_t)_{t\ge 0}$ follows from its definition, and next we show that its quadratic variation is $t$.
From \eqref{Eq:dY}, the quadratic variation of $(Y_t)_{t\ge 0}$ is $\langle Y \rangle_t=\beta^2 t$, yielding $\langle \hat B \rangle_t = \beta^{-2} \langle Y \rangle_t = t.$
From the L\'evy Martingale characterization of the Brownian motion \cite[Theorem 3.16]{karatzas1991brownian}, it follows that $(\hat B_t)_{t\ge 0}$ is a $(\bG^Y,\prob_\pi)$-Brownian motion.

Next, we show that $(\hat m_t)_{t\ge 0}$ is a $(\bG^Y,\prob_\pi)$-martingale. For $t \geq 0$, denote \begin{align}
    M_t:= H_t- \int_0^t (1-H_s)\mu_s \ud s,
\end{align} and observe that $(M_t)_{t\ge 0}$ is a $( \bG,\prob_\pi)$-martingale (cf. Remark \ref{Rm:immersion}). Let 
\begin{align}
   \hat M_t:= \media_\pi[M_t\given \cG^Y_t] , \quad t \geq 0
\end{align}
Since $\bG^Y\subset \bG$, by tower property, $(\hat M_t)_{t\ge 0}$ is a $(\bG^Y,\prob_\pi)$-martingale. Moreover
\begin{align}
    \begin{aligned}
        \hat M_t&=\media_\pi\bigg[H_t- \int_0^t (1-H_s)\mu_s \ud s \Given \cG^Y_t\bigg]\\
        &=H_t- \int_0^t (1-H_s)\hat \mu_s \ud s + \widetilde M_t=\hat m_t + \widetilde M_t
    \end{aligned}
\end{align}
where $(\widetilde M_t)_{t\ge 0}$ is a $(\bG^Y,\prob_\pi)$-martingale. In the second equality, we used the $\bG^Y_t$-measurability of $H_t$ and \cite[Lemma 8.4]{liptser2013statistics}. This shows that $(\hat m_t)_{t\ge 0}$ is a $(\bG^Y,\prob_\pi)$-martingale and the proof is complete.
\end{proof}

