We need to further restrict the range of $\upsilon$ to a compact set such that it contains at least one optimal solution $\upsilon^*$ of Problem \eqref{simplified_problem}. To this end, we first show in Proposition \ref{simpleProposition2} below that the range of $\upsilon$ can be restricted to a compact set. %$\Upsilon\triangleq [ \underline{\upsilon}, \bar{\upsilon}]$ with 
%$$
%\underline{\upsilon} < m(\underline{y}, \bar{y})\in\mathbb{R}, \;\;\;\; \bar{\upsilon} > M(\underline{y}, \bar{y})\in\mathbb{R},
%$$
%where $m(\underline{y}, \bar{y})$ and $M(\underline{y}, \bar{y})$ are as defined in Proposition \ref{simpleProposition2}. 
However, in some cases, the conditions in Proposition \ref{simpleProposition2} may not be satisfied (see Remark \ref{entropic_var_case}) and we have to assume that the minimum of the objective is attained on $[\underline{\upsilon},\bar{\upsilon}]$ for some pre-known $\underline{\upsilon},\bar{\upsilon}\in\mathbb{R}.$ This assumption is commonly used in some existing studies in RL; see \cite{baxter2001infinite}. 
Note that even when this assumption is not fulfilled, we can still find $\epsilon$-correct range for $\upsilon,$ i.e., that for any $\epsilon>0,$ there exists an interval $[\underline{\upsilon}^{\epsilon},\bar{\upsilon}^{\epsilon}]$ such that
\begin{equation}
    \min_{\upsilon \in [\underline{\upsilon}^{\epsilon},\bar{\upsilon}^{\epsilon}]} h(\E[ f\left(Y,\upsilon\right)],\upsilon)\leq \inf_{\upsilon\in\mathbb{R}}h(\E[ f\left(Y,\upsilon\right)],\upsilon) +\epsilon,\notag
\end{equation}
for any random variable $Y$ satisfying $\underline{y}\leq Y \leq \bar{Y}$ almost surely.
To address a similar issue, \cite{ni2022policy} derives a lower bound of the optimal $\upsilon$ (which agrees with Remark \ref{entropic_var_case}) and imposes an assumption on its upper bound for the entropic VaR. %risk measure. 

\begin{proposition}
     \label{simpleProposition2}
Assume that there exists a strictly increasing function $g$ such that
\begin{itemize}
\item[(1)] $g(h(\cdot,\cdot))$ is convex on $f(\mathcal{D})\times\mathbb{R}$; and  
\item[(2)]  for any $y\in \mathcal[\underline{y},\bar{y}],$ the minimal value of $h(f(y,\cdot),\cdot)$ can be attained at some $\upsilon^*\in\mathbb{R}$; and
\item[(3)] it holds that \begin{equation}
\label{condition3_lim}
\lim_{\upsilon\to \pm\infty}g\left(h\left(\min_{y\in[\underline{y},\bar{y}]}f(y,\upsilon),\upsilon\right)\right) = \infty,
\end{equation}
or $h(y,\cdot)$ is constant for any fixed $y\in[\underline{y},\bar{y}],$ and $f(y,\upsilon) =w(y)+\phi(\upsilon-\psi(y)),$ for some continuous functions $w,\phi,\psi.$
\end{itemize}
Then there exist some $m^{\underline{y},\bar{y}},M^{\underline{y},\bar{y}}\in\mathbb{R}$ such that $m^{\underline{y},\bar{y}}<M^{\underline{y},\bar{y}}$ and the minimum of $h(\E[ f\left(Y,\cdot\right)],\cdot)$ is attained on $
\left[m^{\underline{y},\bar{y}},M^{\underline{y},\bar{y}}\right],$  for any random variable $Y$ satisfying  $\underline{y}\leq Y\leq \bar{y}$ almost surely. 
\end{proposition}
\begin{remark}
If $f$ and $h$ are constants of $\upsilon,$ i.e., there admit univariate functions $\tilde{h}$ and $\tilde{f}$ such that $\rho(Y) = \tilde{h}(\E[\tilde{f}(Y)]),$ then we take $g = \tilde{h}^{-1}$ and the conditions (1) and (2) are satisfied (since $h$ is strictly increasing w.r.t. its first argument, $\tilde{h}$ must be strictly increasing). We further take $w = \tilde{f},\phi=\psi=0$ and the condition (3) is satisfied. This is true for the expectation and the entropic risk measure.


If $h(x,\upsilon) = \tilde{h}(x),$ i.e. $\rho(Y)=\tilde{h}(\min_{\upsilon\in\mathbb{R}}\E [f(Y,\upsilon)]),$ then we take $g(x) = \tilde{h}^{-1}(x)$ and Assumption \ref{ass1} is sufficient for condition (1). In this case, condition (2) is equivalent to the statement that $f(y,\upsilon)$ has a minimum for any fixed $y\in[\underline{y},\bar{y}],$ which is true for Expected Shortfall, variance, MAD, and mean-risk utility. \eqref{condition3_lim} is true for Expected Shortfall, MAD, variance, asymmetric variance, and mean-variance utility. 
\begin{comment}
The scoring function of semi-variance and semi-deviation can be represented as $f(y,\upsilon) =w(y)+\phi(\upsilon-\psi(y))$ by choosing $w(y)=0,\phi(x)=((-x)^+)^2,\psi(y)=y.$ For mean-semi-variance utility, we can choose $w(y)=-y,\phi(x)=\lambda((-x)^+)^2,\psi(y)=y.$
\end{comment}
\end{remark}
\begin{remark}
\label{entropic_var_case}
Consider the entropic VaR mentioned in Example \ref{rm_exam3}. With $f(y,\upsilon)=\frac{1}{\alpha}\exp(e^{\upsilon}y)$, $h(x,\upsilon)=e^{-\upsilon}\log(x)$ and $g(x)=\exp(x),$ condition (1) holds for the entropic VaR if $[\underline{y},\bar{y}]\subset [0,\infty)$. However, conditions (2) and (3) are not satisfied because $g(h(f(y,\upsilon),\upsilon))$ is strictly decreasing for $\upsilon\in\mathbb{R}$ for fixed $y.$ In this case, for any $\epsilon>0,$ we can find $[\underline{\upsilon}^{\epsilon},\bar{\upsilon}^{\epsilon}]$ such that
\begin{equation}
    \min_{\upsilon \in [\underline{\upsilon}^{\epsilon},\bar{\upsilon}^{\epsilon}]} h(\E[ f\left(Y,\upsilon\right)],\upsilon)\leq \inf_{\upsilon\in\mathbb{R}}h(\E[ f\left(Y,\upsilon\right)],\upsilon) +\epsilon,\notag
\end{equation}
for any $Y$ satisfying $\underline{y}\leq Y \leq \bar{Y}$ almost surely.
\end{remark}



For a fixed $\upsilon\in \Upsilon,$ denote by $\mathbb{E}_{\pi} $ the expectation under policy $\pi$ and by $\mathbb{P}_{\pi} $ the probability measure under policy $\pi.$ The value function under policy $\pi$ is defined by 
\begin{equation}
\label{hh}
    V^{\pi}_{t,\upsilon}(s,y) = \mathbb{E}_{\pi} \left.\left[f\left(\sum_{k=t}^{T-1}c(S_k,A_k,S_{k+1})-Y_t,\upsilon\right)\right|S_t=s,Y_t=y\right],\  \text{for} \ t=T-1,\ldots,0
\end{equation}
and 
\begin{equation}
    V^{\pi}_{T,\upsilon}(s,y) = f(-y,\upsilon).\notag
    \end{equation}
Then we have the recursive formulation of the value function
\begin{align}
    V^{\pi}_{t,\upsilon}(s,y) &= \mathbb{E}_{\pi} \left.\left[f\left(\sum_{k=t+1}^{T-1}c(S_k,A_k,S_{k+1})-\left(y-c\left(S_t,A_t,S_{t+1}\right)\right),\upsilon\right)\right|S_t = s,Y_t = y\right]\notag\\
    & = \mathbb{E}_{\pi} \left.\left[V^{\pi}_{t+1,\upsilon}\left(S_{t+1},y-c\left(s,A_t,S_{t+1}\right)\right)\right|S_t=s,Y_t=y\right]\notag\\
   & = \mathbb{E}_{\pi} \left.\left[V^{\pi}_{t+1,\upsilon}\left(S_{t+1},Y_{t+1}\right)\right|S_t=s,Y_t=y\right].\label{resur} 
\end{align}
The idea behind this formula is similar to the approach proposed by \cite{bauerle2011markov} to reduce the MDP under ES. However, their approach relies on the specific form of $(y-\upsilon)^+$ in the scoring function for ES, which facilitates the simple fusion of $Y$ and $\upsilon$ into one state process. For the convex scoring function, their approach no longer holds. However, our proposed method separates the variable $\upsilon$ and the augmented state process $Y$ such that we can devise the RL algorithm to accommodate more types of risk measures. 


For a function $V:\mathcal{S}\times\mathcal{Y}\to\R,$ define the Bellman recursive operators 
\begin{align}
    \mathcal{J}_{t,\pi} V(s,y) &=\int_{\mathcal{A}} \int_{\mathcal{S}} \pi(a|t,s,y) p(s'|s,a)V\left(s',y-c\left(s,a,s'\right)\right) \nu_{\mathcal{S}}(\d s') \nu_{\mathcal{A}}(\d a), \notag\\
    \mathcal{J}_{t} V(s,y) &=  \inf_{a\in\mathcal{A}}\int_{\mathcal{S}}  p(s'|s,a)V\left(s',y-c\left(s,a,s'\right)\right) \nu_{\mathcal{S}}(\d s') .\notag
\end{align}

\begin{theorem}[Bellman Equation]
\label{t_Bellman}
For any fixed  $\upsilon \in \Upsilon,$ there exists a family of value functions $\left\{V_{t,\upsilon}^*(\cdot,\cdot)\right\}_{t=0,1\ldots,T}$ satisfying the following recursive system
\begin{equation}\label{BellmanEq}
\begin{aligned}
V_{T,\upsilon}^*(s,y) &= f(-y,\upsilon),\\
     V_{t,\upsilon}^*(s,y) &= \mathcal{J}_t V^*_{t+1,\upsilon}(s,y),\quad t=T-1,\ldots,0,
\end{aligned}
\end{equation}
and the inequality
\begin{equation}
    V_{t,\upsilon}^*(s,y) \leq  V^{\pi}_{t,\upsilon}(s,y), \notag
\end{equation}
for any $t=0,1,\ldots,T,$ $s \in \mathcal{S},$  $y \in \mathcal{Y},$ and policy $\pi\in\tilde{\Pi}.$ Furthermore, there exists a policy sequence $\left\{\pi_{\upsilon,n}\right\}^{\infty}_{n=1} \subset \tilde {\Pi}$ such that 
\begin{equation}
  \left[ V_{t,\upsilon}^{\pi_{\upsilon,n}}(s,y) -V_{t,\upsilon}^*(s,y)\right]\to 0 \ (n\to\infty),\notag
\end{equation}
for any $t=0,1\ldots,T,s\in\mathcal{S},y\in\mathcal{Y}.$
\end{theorem}
\begin{remark}
\label{remark_optimalpolicy}
If Assumption C in \cite{bauerle2011markov} is satisfied, then there exists an optimal policy $\pi^*_{\upsilon}\in\tilde{\Pi}$ such that 
\begin{equation}
   V_{t,\upsilon}^{\pi^*_{\upsilon}}(s,y) =V_{t,\upsilon}^*(s,y)\notag
\end{equation}
for any $t\in\mathcal{T},s\in\mathcal{S},y\in\mathcal{Y}.$ Such a conclusion is widely discussed in the MDP-related literature (see %\cite{bellman1957markovian} and 
\cite{sutton2018reinforcement} and \cite{bauerle2022markov}).
\end{remark}


 Combining Theorem \ref{t_Bellman}, the dominated convergence theorem and the continuity of $h,$ the next proposition holds.
\begin{proposition}
\label{prop_appro}
For any $\upsilon\in\Upsilon$ and $\epsilon>0,$ there exists a policy $\pi_{\upsilon,\epsilon} \in \tilde {\Pi}$ such that \begin{equation}
        \mathbb E [V^{\pi_{\upsilon,\epsilon}}_{0,\upsilon}(S_0,0)]-\mathbb E [V^{*}_{0,\upsilon}(S_0,0)]\leq \epsilon,\notag
    \end{equation}
    and \begin{equation}
        h(\mathbb E [V^{\pi_{\upsilon,\epsilon}}_{0,\upsilon}(S_0,0)],\upsilon)-h(\mathbb E [V^{*}_{0,\upsilon}(S_0,0)],\upsilon)\leq \epsilon.\notag
    \end{equation}
\end{proposition}

Note that \eqref{simplified_problem} is equivalent to
\begin{equation}
    \min_{\upsilon\in\Upsilon}h(\mathbb E [V^*_{0,\upsilon}(S_0,0)],\upsilon).\notag
\end{equation}
Therefore, studying the properties of $\mathbb E [V^*_{0,\upsilon}(S_0,0)]$ is of fundamental importance. Proposition \ref{propmin} establishes the continuity of $\upsilon\mapsto \mathbb E [V^*_{0,\upsilon}(S_0,0)]$, a key result in showing the approximation of our RL algorithm in later subsections. Notably, our analysis does not require a continuity assumption on the MDP, rendering the proof of Proposition \ref{propmin} technically nonstandard. 

\begin{proposition}\label{propmin}
     We have that $\upsilon\mapsto\mathbb E [V^*_{0,\upsilon}(S_0,0)]$ is continuous on $\Upsilon$ and   
    $\upsilon\mapsto h(\mathbb E[ V^*_{0,\upsilon}(S_0,0) ],\upsilon)$ has a minimizer (not necessarily unique) on $\mathbb{R}.$ Furthermore, \begin{equation}
       \min_{\upsilon\in\Upsilon} h(\mathbb E [V^*_{0,\upsilon}(S_0,0) ],\upsilon)= \min_{\upsilon\in\mathbb{R}}  h(\mathbb E[V^*_{0,\upsilon}(S_0,0)],\upsilon).\notag
    \end{equation}
Hence, we can define the set of minimizers as 
\begin{equation}
    \mathscr{U}^* = \arg\min_{\upsilon\in \Upsilon} h(\mathbb E [V^*_{0,\upsilon}(S_0,0)] ,\upsilon).\notag
\end{equation}
\end{proposition}




\subsection{Part 1: Gradient Calculation and Neural Network (NN) Training}
We adopt the policy gradient Actor-Critic RL algorithm for the inner optimization problem; see \cite{konda2003onactor}. That is, for the inner dynamic optimization problem, 
we alternatively learn two functions, the value function $V$ and the policy $\pi.$ In our work, both the value function and the policy are characterized by fully connected and multilayered feed-forward networks, for which the parameters are denoted by $\theta\in\Theta$ and $\phi\in\Phi$, respectively. The inputs to both networks include $(t, \upsilon, s, y).$ The network's outputs are continuous with respect to  $(t, \upsilon, s, y)$; 
see also some existing studies using the policy gradient approach on SRP in \cite{tamar2016sequential},  \cite{zhang2021mean}, \cite{ni2022policy} and \cite{CJ2024}. In contrast to these studies, our algorithm does not require the simulation-upon-simulation approach or the sample-average-approximation approach, which greatly reduces the computational complexity in simulating trajectories.

We denote the outputs of the two networks by $\pi^{\theta}(\cdot|t,\upsilon,s,y)$ and $V^{\phi}_{t,\upsilon}(s,y;\theta),$ respectively. We define
\begin{equation}
\label{hh}
    V_{t,\upsilon}(s,y;\theta) = \mathbb{E}_{\pi^{\theta}_{\upsilon}} \left.\left[f\left(\sum_{k=t}^{T-1}c(S^{\theta}_k,A^{\theta}_k,S^{\theta}_{k+1})-Y_t^{\theta},\upsilon\right)\right|S_t^{\theta}=s,Y_t^{\theta}=y\right], t=T-1,\ldots,0,
\end{equation}
where $\pi^{\theta}_{\upsilon}\in \tilde{\Pi}$ is defined by
\begin{equation}
    \pi^{\theta}_{\upsilon}(a|t,s,y) = \pi^{\theta}(a|t,\upsilon,s,y).\notag
\end{equation}
We have the following continuity result.
\begin{lemma}
For any fixed $s\in\mathcal{S}$ and $t\in\mathcal{T}$,   
$V_{t,\upsilon}(s,y;\theta)$ is continuous in $\upsilon\in\Upsilon$ and $y\in\mathcal{Y}$. 
\end{lemma}


In the Critic-step, we use Equation \eqref{resur} to update the value function. The following Theorem \ref{t1} shows that under some assumptions, the value function $V^{\phi}_{t,\upsilon}(s,y;\theta)$ produced from the NN can approximate the true value function $V_{t,\upsilon}(s,y;\theta)$ uniformly on $(s, y,\upsilon) \in S \times \mathcal{Y}\times\Upsilon$. The algorithm for the Critic-step is provided in Algorithm \ref{alg:alg2}.

\begin{theorem}[Approximation of the value function]
    \label{t1}
    Let $\pi^{\theta}$ be a fixed parameterized policy, with the corresponding value function defined in Equation \eqref{hh}. For any $\epsilon^*>0$ and $\gamma^*>0,$ there exists ANN parameters $\phi$ such that
    \begin{equation}
  \nu_{\mathcal{S}}\left( \left\{ s:\sup_{t\in\mathcal{T},\upsilon\in\Upsilon,y\in\mathcal{Y}} | V_{t,\upsilon}(s,y;\theta) -V^{\phi}_{t,\upsilon}(s,y;\theta)| > \gamma^*\right\}\right)< \epsilon^*.\notag
    \end{equation}
\end{theorem}
\begin{remark}
Note that we do not assume any continuity or semi-continuity on the transition probability $p$ or the cost function $c.$ If we further assume that $p$ and $c$ are both continuous in $(s,a,s'),$ the conclusion of Theorem \ref{t1} can be strengthened: there exists an ANN $V^{\phi},$ such that  
\begin{equation} \sup_{s\in\mathcal{S},t\in\mathcal{T},\upsilon\in\Upsilon,y\in\mathcal{Y}} | V_{t,\upsilon}(s,y;\theta) -V^{\phi}_{t,\upsilon}(s,y;\theta)| \leq \gamma^*.\notag
\end{equation}
\end{remark}





\begin{algorithm}[htb]
	\caption{Policy Evaluation (Critic-step)}
	\label{alg:alg2}
	\begin{algorithmic}
        \STATE \textbf{Input:} ANNs for the value function $V^{\phi}$ and the policy $\pi^{\theta},$ the replay buffer $\mathcal{M},$ epochs $K,$ the batch size $B.$

        \FOR {each epoch $\kappa=1$ to $K$} 
        \STATE Set the gradients of $V^{\phi}$ to zero;
        \FOR {each  $t=T-1$ to $0$} 
        \STATE Sample $B$ states $\left(s^{(t,b)},y^{(t,b)},a^{(t,b)},s^{(t+1,b)},y^{(t+1,b)},\upsilon^{(b)}\right)(b=1,\ldots,B)$ from $\mathcal{M};$
        \ENDFOR
               \FOR{each state $b=1,\ldots,B$ and  $t=T-1$ to $0$}
               \STATE Compute the predicted values $\hat{v}_t^b=V_{t,\upsilon^{(b)}}^{\phi}\left(s^{(t,b)},y^{(t,b)};\theta\right);$
               \STATE Compute the cost $c^{(t,b)}=c(s^{(t,b)},a^{(t,b)},s^{(t+1,b)});$
               \IF {$t=T-1$}
               \STATE Set the target value as
               $$v^b_t= f\left(c^{(t,b)}-y^{(t,b)},\upsilon^{(b)}\right);
               $$
               \ELSE 
               \STATE Set the target value as
               $$v^b_t= V_{t+1,y^{(b)}_0}^{\phi}\left(s^{(t+1,b)},y^{(t,b)}-c^{(t,b)};\theta\right);
               $$
               \ENDIF
               \ENDFOR
               \STATE Compute the expected square loss  $\frac{1}{BT}\sum_{b=1}^B\sum_{t=0}^{T-1}\left(v_{t}^b -\hat{v}_t^b\right)^2;$
               \STATE Update $\phi$ by performing an Adam optimizer step;

             \ENDFOR
            \STATE \textbf{Output:} The value function $V_{t,\upsilon}^{\phi}(s,y;\theta)$ under the policy evaluation. 
	\end{algorithmic}
\end{algorithm}

In the Actor-step, we have the following computations of the policy gradient. For $t = T-1,$ 
\begin{align}
    \nabla_{\theta}V_{T-1,\upsilon}\left(s,y;\theta\right)  =&\nabla_{\theta}\mathbb{E}_{\pi^{\theta}}\left[f\left(c\left(s,A^{\theta}_{T-1},S^{\theta}_{T}\right)-y,\upsilon\right)\right]\notag\\
    =& \nabla_{\theta}  \int_{\mathcal{S}} \int_{\mathcal{A}} \pi^{\theta}(a|t,\upsilon,s,y) p(s'|s,a)f(c(s,a,s')-y,\upsilon) \nu_{\mathcal{A}}(\d a) \nu_{\mathcal{S}}(\d s')\notag\\
    = &   \int_{\mathcal{S}} \int_{\mathcal{A}} \nabla_{\theta}\pi^{\theta}(a|t,\upsilon,s,y) p(s'|s,a)f(c(s,a,s')-y,\upsilon) \nu_{\mathcal{A}}(\d a) \nu_{\mathcal{S}}(\d s')\notag\\
    =&  \int_{\mathcal{S}} \int_{\mathcal{A}}\pi^{\theta}(a|t,\upsilon,s,y)  p(s'|s,a)f(c(s,a,s')-y,\upsilon) \nabla_{\theta}\log\pi^{\theta}(a|t,\upsilon,s,y)\nu_{\mathcal{A}}(\d a) \nu_{\mathcal{S}}(\d s')\notag\\
     =& \mathbb{E}_{\pi^{\theta}}\left.\left[\nabla_{\theta}\log \pi^{\theta}\left(A_{T-1}^{\theta}\right.|t,\upsilon,s,y\right)f\left(c\left(s,A_{T-1}^{\theta},S_{T}^{\theta}\right)-y,\upsilon\right)\right].\notag
\end{align}
For $t < T-1,$ 
\begin{align}
\label{Tpg}
    \nabla_{\theta}V_{t,\upsilon}(s,y;\theta) &= \nabla_{\theta} \int_{\mathcal{S}} \int_{\mathcal{A}} \pi^{\theta}(a|t,\upsilon,s,y)p(s'|s,a)V_{t+1,\upsilon}(s',y-c(s,a,s');\theta) \nu_{\mathcal{A}}(\d a) \nu_{\mathcal{S}}(\d s')\notag\\
    &= \int_{\mathcal{S}} \int_{\mathcal{A}} V_{t+1,\upsilon}(s',y-c(s,a,s');\theta)\nabla_{\theta}\pi^{\theta}(a|t,\upsilon,s,y) p(s'|s,a)  \nu_{\mathcal{A}}(\d a) \nu_{\mathcal{S}}(\d s')\notag\\
    &\qquad+\int_{\mathcal{S}} \int_{\mathcal{A}}\pi^{\theta}(a|t,\upsilon,s,y)p(s'|s,a)\nabla_{\theta}V_{t+1,\upsilon}(s',y-c(s,a,s');\theta)  \nu_{\mathcal{A}}(\d a) \nu_{\mathcal{S}}(\d s')\notag\\
     &=  \mathbb{E}_{\pi^{\theta}}\left.\left[\nabla_{\theta}\log \pi^{\theta}\left(A_{t}^{\theta}\right |t,\upsilon,s,y\right)
     V_{t+1,\upsilon}\left(S^{\theta}_{t+1},y-c\left(s,A_t^{\theta},S_{t+1}^{\theta}\right);\theta\right)\right]\notag\\
&\qquad+\mathbb{E}_{\pi^{\theta}}\left[\nabla_{\theta}V_{t+1,\upsilon}\left(S^{\theta}_{t+1},y-c\left(s,A_t^{\theta},S_{t+1}^{\theta}\right);\theta\right)\right].
\end{align}

When optimizing the policy $\pi^{\theta}$, the value function $V^{\phi}$ is treated as a fixed constant, implying that its parameter $\phi$ does not vary during the computation of the policy gradient. This constancy ensures that the gradient of $V^{\phi}$ with respect to $\phi$ does not contribute to the policy optimization process. As a result, the second term in Equation \eqref{Tpg} vanishes. This principle is commonly adopted in Actor-Critic methods. For a detailed discussion of this approach, see \cite{sutton2018reinforcement} and \cite{peters2008natural}. The algorithm for the Actor-step is provided in Algorithm \ref{alg:alg3}.

We call $\theta$ is a $\gamma$-optimal parameter if 
\begin{equation}
\sup_{\upsilon\in \Upsilon}|\mathbb E [V_{0,\upsilon}(S_0,0;\theta)]-\mathbb E[V^*_{0,\upsilon}(S_0,0)]| \leq \gamma.\notag
\end{equation}
From \cite{agarwal2021theory}, we know that as long as we sample $\upsilon$ from a distribution that has a positive p.d.f. on $\Upsilon,$ $\theta$ will converge to a $\gamma$-optimal parameter for any $\gamma>0.$


\begin{algorithm}[htb]
	\caption{Policy Gradient (Actor-step)} 
	\label{alg:alg3}
	\begin{algorithmic}
       \STATE \textbf{Input:} ANNs for the value function $V^{\phi}$ and the policy $\pi^{\theta},$ the replay buffer $\mathcal{M},$ epochs $K,$ the batch size $B.$

            \FOR {each epoch $\kappa=1$ to $K$} 
                \STATE Set the gradients of $\pi^{\theta}$ to be zero;
                \FOR {each $t=T-1$ to $0$} 
        \STATE Sample $B$ elements $\left(s^{(t,b)},y^{(t,b)},a^{(t,b)},s^{(t+1,b)},y^{(t+1,b)},\upsilon^{(b)}\right)(b=1,\ldots,B)$ from $\mathcal{M};$
        \ENDFOR
               \FOR{each state $b=1,\ldots,B$ and  $t=T-1$ to $0$}
               \STATE Obtain $\hat{z}^{(t,b)}=\nabla_{\theta}\log \pi^{\theta}\left.\left(a^{(t,b)}\right|t,\upsilon^{(b)},s^{(t,b)},y^{(t,b)}\right);$
              \IF {$t=T-1$}
               \STATE Calculate the gradient
               $$l_t^b=\hat{z}^{(t,b)}f\left(c^{(t,b)}-y^{(t,b)},\upsilon^{(b)}\right);
               $$
               \ELSE 
               \STATE Calculate the gradient
               $$l_t^b= \hat{z}^{(t,b)}V_{t+1,y^{(b)}_0}^{\phi}\left(s^{(t+1,b)},y^{(t,b)}-c^{(t,b)};\theta\right);
               $$
                \ENDIF
               \ENDFOR
               \STATE Take the average  $l = \frac{1}{BT}\sum_{b=1}^B\sum_{t=0}^{T-1}l_t^b;$
               \STATE Update $\theta$ by performing an Adam optimizer step;

             \ENDFOR
            \STATE \textbf{Output:} An updated policy $\pi^{\theta}.$
	\end{algorithmic}
\end{algorithm}


\subsection{Part 2: Selection of the Optimal Auxiliary Variable}\label{sec:select}

We next turn to the outer optimization problem and employ the SGD to solve
\begin{equation}
\label{ystar}
    \upsilon^*(\theta,\phi) \in \arg\min_{\upsilon\in\Upsilon} \left\{ h(\mathbb{E}[V^{\phi}_{0,\upsilon}(S_0,0;\theta)],\upsilon)\right\}.
\end{equation}
Then the optimal learned policy is given by
$
    \pi^{\theta}\left(\cdot|0,\upsilon^*(\theta,\phi),s,0\right)\notag
$ at time $0$ and
and $
    \pi^{\theta}\left(\cdot|t,\upsilon^*(\theta,\phi),s,y_t\right)  \notag
$ at time $t\geq 1 $. The algorithm to search for the optimal auxiliary variable $\upsilon^*$ is provided in Algorithm \ref{alg:alg4}.


\begin{algorithm}[htb]
	\caption{Searching the optimal auxiliary variable $\upsilon^*$} 
	\label{alg:alg4}
	\begin{algorithmic}
        \STATE \textbf{Input:} ANNs for the value function $V^{\phi},$ 
        epochs $K,$ simulations $M.$
        \STATE Initialize $\upsilon^*=0;$
        \STATE Sample $M$ states $s^{(m)}_0$ from the initial distribution;
            \FOR {each epoch $\kappa=1$ to $K$} 
            \STATE Calculate $$l=\frac{1}{M}\sum_{m=1}^{M}h\left(V^{\phi}_{0,\upsilon^*}\left(s^{(m)}_0,0;\theta\right),\upsilon^*\right);$$
                \STATE Update $\upsilon^*$ by performing an SGD optimizer step;
             \ENDFOR
            \STATE \textbf{Output:} An optimal $\upsilon^{*}.$
	\end{algorithmic}
\end{algorithm}

Next, we examine the correctness of our calculation of $\upsilon^*(\theta,\phi)$ in Equation \eqref{ystar}. 
We evaluate the accuracy of $\upsilon^*(\theta,\phi)$ by using the distance from the point $\upsilon^*(\theta,\phi)$ to the set $\mathscr{U}^*$, which is defined as 
\begin{equation}
    d\left(\mathscr{U}^*,\upsilon^*(\theta,\phi)\right) = \inf \left\{\left|\upsilon-\upsilon^*(\theta,\phi)\right|:\upsilon\in \mathscr{U}^*\right\}.\notag
\end{equation}
This type of distance is reasonable in our context, because for any $\upsilon\in\mathscr{U}^*,$ there exists an asymptotically optimal policy sequence $\left\{\pi_{\upsilon,n}\right\}_{n=1}^{\infty}$ to Problem \eqref{simplified_problem}. On the other hand, as $\pi^{\theta}$ is continuous w.r.t. $\upsilon,$ $\pi^{\theta}_{\upsilon^*(\theta,\phi)}$ approximates $\pi^{\theta}_{\upsilon}$ well for some $\upsilon\in\mathscr{U}^*$ if the distance is small. 

%Having established the framework for evaluating the accuracy of $\upsilon^*(\theta,\phi)$ through the distance metric $d\left(\mathscr{U}^*,\upsilon^*(\theta,\phi)\right)$, 
We now turn to the conditions under which %this distance can be made arbitrarily small. This is crucial for ensuring that 
$\upsilon^*(\theta,\phi)$ approximates the optimal set $\mathscr{U}^*$ sufficiently well. The following lemmas provide the foundational steps toward this goal.
\begin{lemma}
    \label{l0}
For any $\gamma'>0,$ there exists some $\gamma''>0$ such that 
\begin{equation}
\underset{\upsilon \in \Upsilon}{\text{sup}} |h(\mathbb E [V^*_{0,\upsilon}(S_0,0)],\upsilon)- h(\mathbb E [V_{0,\upsilon}^{\phi}(S_0,0;\theta)],\upsilon)|    < \gamma'\notag
\end{equation}
holds for any parameters $(\theta,\phi)$ satisfying
\begin{equation}
\underset{\upsilon \in \Upsilon}{\text{sup}} |\mathbb E [V^*_{0,\upsilon}(S_0,0)] - \mathbb E [V_{0,\upsilon}^{\phi}(S_0,0;\theta)]|    < \gamma''.\notag
\end{equation} 
\end{lemma}
Lemma \ref{l0} demonstrates that the discrepancy between the expected values of the true and approximated value functions can be controlled by carefully selecting the parameters $(\theta,\phi)$. Building on this, Lemma \ref{l2} establishes a direct connection between the accuracy of $h(\cdot, \upsilon)$ and the proximity of $\upsilon^*(\theta,\phi)$ to $\mathscr{U}^*$. %Specifically, it shows that a sufficiently small error in $h(\cdot, \upsilon)$ guarantees that $\upsilon^*(\theta,\phi)$ lies within a desired neighborhood of $\mathscr{U}^*$.
\begin{lemma}
  \label{l2} 
For any $\gamma>0,$ there exists some $\gamma'>0$ such that
\begin{equation}
   d\left(\mathscr{U}^*,\upsilon^*({\theta},\phi)\right)\leq \gamma\notag
\end{equation}
holds for any parameters $(\theta,\phi)$ satisfying
\begin{equation}
\label{condition11}
    \underset{\upsilon \in \Upsilon}{\text{sup}}\  |h(\mathbb E[V^*_{0,\upsilon}(S_0,0) ],\upsilon)- h(\mathbb E [V_{0,\upsilon}^{\phi}(S_0,0;\theta)],\upsilon)|    < \gamma'.
\end{equation}

\end{lemma}

The results of Lemmas \ref{l0} and \ref{l2} describe how the parameters $(\theta,\phi)$ may influence the optimality of $\upsilon^*(\theta,\phi)$. Theorem \ref{t2} synthesizes these insights into a practical criterion for selecting $\upsilon^*(\theta,\phi)$. By imposing conditions on the optimality of $\theta$ and the approximation quality of $\phi$, the theorem ensures the proximity of $\upsilon^*(\theta,\phi)$ to $\mathscr{U}^*$ in the sense of the distance metric. 
\begin{theorem}[Selection of the optimal $\upsilon$]
\label{t2}
If the distribution of $S_0$ has a p.d.f. $p(\cdot)$ w.r.t. $\nu_{\mathcal{S}},$ then for any $\gamma>0,$ there exist some $\epsilon_1',\gamma'_1>0$ such that 
\begin{equation}
    d\left(\mathscr{U}^*,\upsilon^*(\theta,\phi) \right)\leq\gamma\notag
\end{equation}holds for any parameters $(\theta,\phi)$ satisfying
\begin{itemize}
    \item[(1)] $\theta$ is a $\gamma'_1$-optimal parameter;
    \item[(2)] $\phi$ satisfies that $\nu_{\mathcal{S}}\left(  \sup_{t\in\mathcal{T}, y\in\mathcal{Y},\upsilon\in\Upsilon}| V_{t,\upsilon}(s,y;\theta) -V^{\phi}_{t,\upsilon}(s,y;\theta)|>\gamma'_1 \right)<\epsilon_1'.$
\end{itemize}
\end{theorem}
The above theorem highlights the importance of the initial state distribution in determining the conditions for optimality. As elaborated in the subsequent remark, the case where $S_0$ is deterministic (i.e., a point mass) requires a more stringent condition on the approximation error of $\phi$. 
\begin{remark}
    If $S_0$ has a point mass at $s_0,$ i.e., $S_0=s_0$ almost surely, then the condition (2) should be replaced by \begin{equation}
        \sup_{t\in\mathcal{T}, y\in\mathcal{Y},\upsilon\in\Upsilon}| V_{t,\upsilon}(s,y;\theta) -V^{\phi}_{t,\upsilon}(s,y;\theta)|\leq\gamma'_1. \notag
    \end{equation}
\end{remark}



\subsection{Part 3: Sampling the auxiliary variable $\upsilon$}\label{sec:sample}
Regarding the computational cost, the method proposed in this paper avoids the simulation-upon-simulation convention but expands $Y_t$ and $\upsilon$ as inputs to the neural network as a tradeoff. Although we only use $Y_t$ as the augmented state of the MDP, learning based on the sampled $\upsilon$ also adds computational complexity in both Critic and Actor steps. Therefore, it is important to explore an efficient sampling of $\upsilon$ that makes the agent quickly converge to the optimal policy.

\cite{agarwal2021theory} shows that sampling from any distribution that has a positive p.d.f. on $\Upsilon$ will lead to a $\gamma$-optimal parameter. We can simply choose a uniform distribution on $\Upsilon.$ Here we propose an alternative approach with a higher efficiency. For any initial $\upsilon^*_0$ and parameters $\phi_0$ and $\theta_0,$ we sample $\upsilon$ and update the parameters according to the following process: in stage $n\ (n\geq 1),$ we 
\begin{equation}
    \begin{aligned}
    & \text{Sample } \upsilon \sim \mathrm{N} \left(\upsilon^*_{n-1},\sigma_n^2\right)\text{ and generate trajectories};\notag \\
    &  \text{Perform $L(n)$ Critic-steps and get $\phi_n$};\notag\\
    &  \text{Perform $L(n)$ Actor-steps and get $\theta_n$};\notag\\
    &  \text{Calculate } \upsilon^*_n\in\arg\min_{\upsilon\in\Upsilon} \left\{ h(\mathbb{E}\left[V^{\phi_n}_{0,\upsilon}(S_0,0;\theta_n)\right],\upsilon)\right\}.\notag
\end{aligned}\end{equation}
Both $L(n)$ and $\sigma^2_n$ are decreasing w.r.t. $n$ in order to fully explore in early iterations and ensure a faster convergence in later iterations. This sampling method is related to the alternating minimization algorithm. We sample $\upsilon$ from a normal distribution with a mean of $\upsilon^*_n$ and a small variance at epoch $n$. This leads to a faster convergence of $\pi^{\theta}_{\upsilon^*_n}$ to minimize $h(\E [V_{0,\upsilon^*_n}(S_0,0;\theta)],\upsilon)$ compared to sampling uniformly over $\Upsilon.$ Theorem \ref{thm:am_converge} shows that under some regularization conditions, this method will lead to a solution of \eqref{simplified_problem} even without any exploration on $\upsilon.$ The proof of Theorem \ref{thm:am_converge} is imitated from \cite{niesen2007adaptive} and \cite{csiszar1984information}.

\begin{theorem}
\label{thm:am_converge}
For any $\epsilon>0,$ $\upsilon_1\in\Upsilon,$  
\begin{equation}
   \pi_{n,\epsilon}\in \left\{\pi\in\tilde{\Pi}:h(\E [V^{\pi}_{0,\upsilon_n}(S_0,0)],\upsilon_n)-h(\E [V^{*}_{0,\upsilon_n}(S_0,0)],\upsilon_n)<\frac{\epsilon}{n^2}\right\},\notag
\end{equation}
and \begin{equation}
\label{argmin}
    \upsilon_{n+1} \in\arg\min_{\upsilon\in\Upsilon} h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon}(S_0,0)],\upsilon),\notag
\end{equation}
we have $\lim_{n\to\infty}h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0)],\upsilon_{n+1})$ exists finitely. Furthermore, if there exists a nonnegative function $\delta:\Upsilon\times\Upsilon\to[0,\infty)$ such that for any $\upsilon'\in\Upsilon,\ \pi\in\tilde{\Pi},$ the following two conditions hold: 
\begin{itemize}
    \item[(1)] for any $\upsilon\in\arg\min_{\upsilon\in\Upsilon}h(\E [V^{\pi}_{0,\upsilon}(S_0,0)],\upsilon), $ it holds that
\begin{equation}
    \delta(\upsilon',\upsilon) + h(\E [V^{\pi}_{0,\upsilon}(S_0,0)],\upsilon)\leq h(\E [V^{\pi}_{0,\upsilon'}(S_0,0)],\upsilon');\notag
\end{equation}
    \item[(2)] for any $\gamma>0,\ \upsilon\in\Upsilon,$ there exists $\epsilon>0$ such that 
\begin{equation}
    h(\E [V^{\pi_{\upsilon,\epsilon}}_{0,\upsilon'}(S_0,0)],\upsilon')\leq h(\E [V^{\pi}_{0,\upsilon'}(S_0,0)],\upsilon')+\delta(\upsilon',\upsilon)+\gamma,\notag
\end{equation}
for any  $ \pi_{\upsilon,\epsilon}\in \left\{\pi\in\tilde{\Pi}:\E [V^{\pi}_{0,\upsilon}(S_0,0)]-\E [V^{*}_{0,\upsilon}(S_0,0)]<{\epsilon}\right\},$ 
\end{itemize} 
then we have 
\begin{equation}
   \lim_{n\to\infty,\epsilon\to0} h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0) ],\upsilon_{n+1})= \min_{\upsilon\in\Upsilon}h(\E [V^{*}_{0,\upsilon}(S_0,0)],\upsilon).\notag
\end{equation}
\end{theorem}
\begin{remark}
    If Assumption C in \cite{bauerle2011markov} is satisfied, then there exists an optimal policy $\pi^*_{\upsilon}$ for any $\upsilon\in\Upsilon,$ which is defined in Remark \ref{remark_optimalpolicy}. As a result, condition (2) can be replaced by that
    \begin{equation}
    h(\E[ V^{\pi^*_{\upsilon}}_{0,\upsilon'}(S_0,0)],\upsilon')\leq h(\E [V^{\pi}_{0,\upsilon'}(S_0,0)],\upsilon')+\delta(\upsilon',\upsilon),\notag
\end{equation} for any $\upsilon,\upsilon'\in\Upsilon.$
\end{remark}


We summarize the complete Actor-Critic algorithm in Algorithm \ref{alg:alg1}.


\begin{algorithm}[h]
	\caption{Complete Recipe based on a Convex Scoring Function} 
	\label{alg:alg1}
	\begin{algorithmic}
        \STATE \textbf{Input:} ANNs for the value function $V^{\phi}$ and the policy $\pi^{\theta},$
        the number of episodes $N,$  epochs $K,$ the batch size $B,$ simulations $M,$ updating frequency $L,$ variance for exploration $\sigma^2.$
        \STATE Set initial guesses for $V^{\phi},\pi ^{\theta};$
        \STATE Initialize the environment and optimizers; 
        \STATE Initialize the buffer $\mathcal{M} = \emptyset$; 
        \STATE Initialize auxiliary variable $\upsilon^*=0;$
        \STATE Initialize counter $c=0;$
            \FOR {each epoch $\kappa=1$ to $K$} 
                \FOR {each episode $n=1$ to $N$}
                \STATE Sample initial state $s_0^{(n)}$ from initial distribution $S_0;$
                \STATE Sample $\upsilon^{(n)}$ from normal distribution $\mathcal{N}(\upsilon^*,\sigma^2);$
                \STATE Simulate episodes from $(s=s^{(n)}_0,y=0,\upsilon=y^{(n)}_0)$ under $\pi^{\theta};$ 
                \STATE Put every $\left(s^{(t,n)},y^{(t,n)},a^{(t,n)},s^{(t+1,n)},y^{(t+1,n)},\upsilon^{(n)}\right)$ into $\mathcal{M};$
                \ENDFOR
                \STATE Freeze $\tilde{\pi} = \pi^{\theta};$
                \STATE Estimate $V^{\phi}$ using $\tilde{\pi}:$
                \STATE \qquad Algorithm \ref{alg:alg2} $(V^{\phi},\tilde{\pi},\mathcal{M},K,B);$
                \STATE Freeze $\tilde{V} = V^{\phi};$ 
                \STATE Update $\pi^{\theta}$ using $\tilde{V}:$
                \STATE \qquad Algorithm \ref{alg:alg3} $(\tilde{V},{\pi}^{\theta},\mathcal{M},K,B);$
                \STATE Freeze $\tilde{V} = V^{\phi}$ and $\tilde{\pi} = \pi^{\theta};$                  \IF{$c\text{ mod }L=0$}
                \STATE Update $\upsilon^*$ using $\tilde{V}:$
                \STATE \qquad Algorithm \ref{alg:alg4} $(\tilde{V},K,M);$
                \STATE Reset $c=0;$
                \STATE Decrease $L$ and $\sigma^2;$
                \ENDIF
                \STATE Add counter $c$ by $1;$
                \STATE Clear buffer $\mathcal{M} = \emptyset$;  
            \ENDFOR
            \STATE \textbf{Output:} $\pi^{\theta}$ and $V^{\phi}.$ 
	\end{algorithmic}
\end{algorithm}



\subsubsection{Expected Shortfall (ES) Case}
$\ES$ is widely used in risk-sensitive RL (see \cite{bauerle2011markov}, \cite{chow2015risk}, \cite{tamar2015optimizing}, \cite{kashima2007risk}, \cite{du2022provably}, \cite{godbout2021acrel}). Our approach can handle the $\ES$ objective by taking $f(y,\upsilon)=\upsilon+(y-\upsilon)^+$ and $h(x,\upsilon)=x.$ We present here that under the $\ES$ objective, the sampling method described above can be further simplified to avoid the iterative use of SGD to solve \eqref{ystar}. For any initial $\upsilon^*_0$ and parameters $\phi_0$ and $\theta_0,$ we sample $\upsilon$ and update the parameters according to the following process: in stage $n\ (n\geq 1),$ we 
\begin{equation}
    \begin{aligned}
    & \text{Sample } \upsilon \sim \mathrm{N} \left(\upsilon^*_{n-1},\sigma_n^2\right)\text{ and generate trajectories}; \notag\\
    &  \text{Perform $L(n)$ Critic-steps and get $\phi_n$};\notag\\
    &  \text{Perform $L(n)$ Actor-steps and get $\theta_n$};\notag\\
    &  \text{Calculate } \upsilon^*_n \text{ as the }\alpha\text{-quantile of simulated total costs}.\notag
\end{aligned}
\end{equation}

Before discussing the theoretical convergence of this method, we introduce two notations. Given a policy $\pi\in\tilde{\Pi}$, we denote 
\begin{equation}
    F_{\pi}(y) := \mathbb{P}_{\pi}\left.\left(\sum_{t = 0}^{T-1} c(S_t, A_t,S_{t+1})\leq y\right|Y_0=0\right)\notag
\end{equation}
  and 
  \begin{equation}
      q_{\alpha}(F_{\pi}) := \inf\left\{y:F_{\pi}(y)\geq\alpha\right\}.\notag
  \end{equation}

\begin{proposition}\label{thm:limit}
Take $f(y,\upsilon) = \upsilon+\frac{1}{1-\alpha}(y-\upsilon)^+$ and $h(x,\upsilon)=x.$  For any $\epsilon>0,$ $\upsilon_1\in\Upsilon,$ define 
\begin{equation}
    \upsilon_{n+1} = q_{\alpha} (F_{\pi_{n,\epsilon}}).\notag
\end{equation}
It holds that $\lim_{n\to\infty}\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0)]$ exists finitely. Furthermore, if  there exists some $\Delta>0$ such that for any $\upsilon'\in\Upsilon$ and $\pi\in\tilde{\Pi},$ the following two conditions hold:
\begin{itemize}
    \item[(1)] for any $\upsilon\in\arg\min_{\upsilon\in\Upsilon}\E [V^{\pi}_{0,\upsilon}(S_0,0)],$ we have
\begin{equation}
    \left|F_{\pi}(\upsilon')-F_{\pi}(\upsilon)\right| \geq (1-\alpha)\Delta\left|\upsilon'-\upsilon\right|;\notag
\end{equation}
    \item[(2)] for any $\gamma>0,$ $\upsilon\in\Upsilon,$ there exists $\epsilon>0$ such that
\begin{equation}
    \E [V^{\pi_{\upsilon,\epsilon}}_{0,\upsilon'}(S_0,0)]\leq \E [V^{\pi}_{0,\upsilon'}(S_0,0)]+\frac{\Delta}{2}(\upsilon'-\upsilon)^2+\gamma,\notag
\end{equation} for any $ \pi_{\upsilon,\epsilon}\in \left\{\pi\in\tilde{\Pi}:\E [V^{\pi}_{0,\upsilon}(S_0,0)]-\E[ V^{*}_{0,\upsilon}(S_0,0)]<{\epsilon}\right\},$
\end{itemize} then we have 
\begin{equation}
   \lim_{n\to\infty,\epsilon\to0} \E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0)] = \min_{\upsilon\in\Upsilon}\E [V^{*}_{0,\upsilon}(S_0,0)].\notag
\end{equation}
\end{proposition}

Based on the above result, we can implement the AC algorithm for the ES objective similar to Algorithm \ref{alg:alg1}, where we can update the auxiliary variable $\upsilon^*$ as the $\alpha$-quantile of 
$$\left\{\sum^{T-1}_{t=0}c(s^{(t,n)},a^{(t,n)},s^{(t+1,n)}):1\leq n\leq N\right\}.
$$



