\section{Proofs}\label{sec:proof}
This section collects all proofs of the results in the previous sections. 


\begin{proof}[Proof of Proposition \ref{simpleProposition2}]
We first show that $\upsilon\mapsto g(h(\E [f(Y,\upsilon)],\upsilon))$ is convex. For any $\lambda\in(0,1)$ and $\upsilon_1,\upsilon_2\in\Upsilon$, note that
\begin{align}
   &g( h(\E [f(Y,\lambda\upsilon_1+(1-\lambda)\upsilon_2)],\lambda\upsilon_1+(1-\lambda)\upsilon_2)))\notag\\
   \leq &g( h(\lambda\E [f(Y,\upsilon_1)]+(1-\lambda)\E [f(Y,\upsilon_2)],\lambda\upsilon_1+(1-\lambda)\upsilon_2)))\notag\\
   \leq & \lambda g(h(\E [f(Y,\upsilon_1)],\upsilon_1))+ (1-\lambda) g(h(\E [f(Y,\upsilon_2)],\upsilon_2)).\notag
\end{align}
The first inequality is due to the fact that $\E[ f(Y,\cdot)]$ is convex by Proposition \ref{simpleProposition1}, and the second inequality is because of the convexity of $g(h(\cdot,\cdot))$. As a result, for any $y\in[\underline{y},\bar{y}],$ $g(h( f(y,\upsilon),\upsilon))$ is convex in $\upsilon.$ Moreover, 
\begin{equation}
\label{bound_neq}
g\left(h\left(\min_{y\in[\underline{y},\bar{y}]}f(y,\upsilon),\upsilon\right)\right) \leq g(h(\E[ f(Y,\upsilon)],\upsilon)).
\end{equation}

\textbf{Case 1:}
\begin{equation}
\lim_{\upsilon\to \pm\infty}g\left(h\left(\min_{y\in[\underline{y},\bar{y}]}f(y,\upsilon),\upsilon\right)\right) = \infty.\notag
\end{equation}
In this case, by \eqref{bound_neq} we have
\begin{equation}
     \lim_{\upsilon \to \infty}g(h(\E [f(Y,\upsilon)],\upsilon))=\lim_{\upsilon \to -\infty}g(h(\E [f(Y,\upsilon)],\upsilon))=\infty,\notag
\end{equation}
which implies that $\upsilon\mapsto g(h(\E[ f(Y,\upsilon)],\upsilon))$ has a minimizer. Suppose that the claim in Proposition \ref{simpleProposition2} does not hold. Then there exist random variables $Y_1,Y_2,\ldots,$ and 
real numbers $\upsilon_1,\upsilon_2,\ldots,$ such that: 
\begin{itemize}
\item either $\upsilon_n\to\infty \ (n\to\infty)$ and $\upsilon\mapsto g(h(\E [f(Y_n,\upsilon)],\upsilon))$ is strictly decreasing on $(-\infty,\upsilon_n]$;
\item or $\upsilon_n\to-\infty \ (n\to\infty)$ and $\upsilon\mapsto g(h(\E [f(Y_n,\upsilon)],\upsilon))$ is strictly increasing on $[\upsilon_n,\infty).$  
\end{itemize}
Here we only discuss the first case, as the other case can be handled similarly. Then, we have
\begin{align}
g\left(h\left(\max_{y\in[\underline{y},\bar{y}]}f(y,\upsilon_0),\upsilon_0\right)\right) &\geq g(h(\E [f(Y_n,\upsilon_0)],\upsilon_0))\notag\\
    &\geq g(h(\E [f(Y_n,\upsilon_n)],\upsilon_n))\notag\\
    &\geq g\left(h\left(\min_{y\in[\underline{y},\bar{y}]}f(y,\upsilon_n),\upsilon_n\right)\right),\notag
\end{align}
which implies
\begin{equation}
g\left(h\left(\max_{y\in[\underline{y},\bar{y}]}f(y,\upsilon_0),\upsilon_0\right)\right)\geq \lim_{n\to\infty} g\left(h\left(\min_{y\in[\underline{y},\bar{y}]}f(y,\upsilon_n),\upsilon_n\right)\right) = \infty,\notag
\end{equation}
leading to a contradiction.

\textbf{Case 2:}  $h(\cdot,\cdot)$ is constant with respect to its second argument, i.e., $h(x,\upsilon)=\tilde{h}(x),$ and $f(y,\upsilon) =w(y)+\phi(\upsilon-\psi(y)),$ for some continuous functions $w,\phi,\psi.$ Let 
\begin{align}
\bar{\upsilon}^*     &= \sup_{y\in[\underline{y},\bar{y}]}\left\{\inf\left\{\upsilon\in\mathbb{R}:\tilde{h}(f(y,\upsilon)) = \min_{\upsilon\in\mathbb{R}}\tilde{h}(f(y,\upsilon))\right\}\right\},\notag\\
     \underline{\upsilon}^* &= \inf_{y\in[\underline{y},\bar{y}]}\left\{\sup\left\{\upsilon\in\mathbb{R}:\tilde{h}(f(y,\upsilon)) = \min_{\upsilon\in\mathbb{R}}\tilde{h}(f(y,\upsilon))\right\}\right\}.\notag
\end{align}
Then $\underline{\upsilon}^*,\bar{\upsilon}^*\in\{\infty,-\infty\}\cup\mathbb{R}.$ As $h$ is strictly increasing in the first argument, $\tilde{h}$ must be strictly increasing. 
Then $\upsilon\mapsto f(y,\upsilon)$ and $\upsilon\mapsto\tilde{h}(f(y,\upsilon))$ are strictly decreasing on $( -\infty,\bar{\upsilon}^*),$ and strictly increasing on $( \underline{\upsilon}^*,\infty)$ for any $y\in[\underline{y},\bar{y}].$ 
Thus $\upsilon\mapsto\E [f(Y,\upsilon)]$ is also strictly decreasing on $( -\infty,\bar{\upsilon}^*)$ and strictly increasing on $( \underline{\upsilon}^*,\infty).$ 
Note that $\upsilon\mapsto f(y,\upsilon)$ is convex. We also have that $\upsilon\mapsto f(y,\upsilon)$ is increasing on $(\bar{\upsilon}^*,\infty),$ and decreasing on $( -\infty,\underline{\upsilon}^*),$ so is $\upsilon\mapsto\E [f(Y,\upsilon)].$
We now show that $\bar{\upsilon}^*<\infty$ and $\underline{\upsilon}^*>-\infty.$ We only need to prove $\bar{\upsilon}^*<\infty$ and the other is similar. Assume that $\bar{\upsilon}^*=\infty.$ Then there exist $y_1,y_2,\ldots,$ and $\upsilon_1,\upsilon_2,\ldots,$ such that 
\begin{equation}
   \upsilon_n =  \inf\left\{\upsilon\in\mathbb{R}:\tilde{h}(f(y_n,\upsilon)) = \min_{\upsilon\in\mathbb{R}}\tilde{h}(f(y_n,\upsilon))\right\}>-\infty,\notag
\end{equation}
and $\upsilon_n\to\infty\ (n\to\infty).$ Note that
\begin{equation}
    \upsilon_n -\psi(y_n) =\inf\{\arg\min_{x\in\mathbb{R}} \phi(x)\},\notag
\end{equation}
which implies $\upsilon_n-\psi(y_n)=\upsilon_1-\psi(y_1).$ Thus we have
\begin{align}
    |\upsilon_n| &\leq |\upsilon_1| + |\psi(y_1)|+|\psi(y_n)|\notag\\
    &\leq  |\upsilon_1| + 2\max_{y\in[\underline{y},\bar{y}]} |\psi(y)|,\notag
\end{align}
which leads to a contradiction with $\upsilon_n$ tending to infinity. Thus, we have $\bar{\upsilon}^*<\infty$ and $\underline{\upsilon}^*>-\infty.$ As $\upsilon\mapsto\E [f(Y,\upsilon)]$ is convex and $\upsilon^*$ is a minimizer of $\upsilon\mapsto \E [f(Y,\upsilon)]$ iff it is a minimizer of $\upsilon\mapsto\tilde{h}(\E [f(Y,\upsilon)]),$ we can define an interval $[m^{\underline{y},\bar{y}},M^{\underline{y},\bar{y}}]$ as follows: If $\bar{\upsilon}^*,\underline{\upsilon}^*\in\mathbb{R},$ then we take $m^{\underline{y},\bar{y}}<\min\{\bar{\upsilon}^*,\underline{\upsilon}^*\},$ $M^{\underline{y},\bar{y}}>\max\{\bar{\upsilon}^*,\underline{\upsilon}^*\}$ and the conclusion follows; If $\bar{\upsilon}^*=-\infty$ and $\underline{\upsilon}^*=\infty,$ then $\tilde{h}(\E [f(Y,\upsilon)])$ is constant of $\upsilon$ on $\mathbb{R}$ and the conclusion follows on any sub-interval of $\mathbb{R};$ If $\bar{\upsilon}^*=-\infty$ and $\underline{\upsilon}^*\in\mathbb{R},$  then $\tilde{h}(\E [f(Y,\upsilon)])$ is constant of $\upsilon$ on $(-\infty,\underline{\upsilon}^*]$ and is increasing on $[\underline{\upsilon}^*,\infty),$ and we take $m^{\underline{y},\bar{y}}<\underline{\upsilon}^*,$ $M^{\underline{y},\bar{y}}>\underline{\upsilon}^*$;  If $\bar{\upsilon}^*\in\mathbb{R}$ and $\underline{\upsilon}^*=\infty,$ then $\tilde{h}(\E [f(Y,\upsilon)])$ is constant of $\upsilon$ on $[\bar{\upsilon}^*,\infty)$ and is increasing on $(-\infty,\bar{\upsilon}^*]$, and we take $m^{\underline{y},\bar{y}}<\bar{\upsilon}^*,$ $M^{\underline{y},\bar{y}}>\bar{\upsilon}^*.$ 
\end{proof}


\begin{proof}[Proof of Theorem \ref{t_Bellman}]
Define $V_{T,\upsilon}^*(s,y) = f(-y,\upsilon),$ and define $V_{t,\upsilon}^*(s,y) = \mathcal{J}_t V^*_{t+1,\upsilon}(s,y)$ recursively for $t=T-1.\ldots,1,0.$ Below, we use the backward induction to show that $V_{t,\upsilon}^*(s,y) \leq  V^{\pi}_{t,\upsilon}(s,y)$ for any $s \in \mathcal{S},$  $y \in \mathcal{Y}$ and $t=0,\ldots,T.$ At time $T,$ $V_{T,\upsilon}^*(s,y) = V^{\pi}_{T,\upsilon}(s,y) = f(-y,\upsilon).$ Assuming the assertion holds for $t+1,$ we obtain at time $t,$
\begin{align}
    V^{\pi}_{t,\upsilon}(s,y) &= \mathbb{E}_{\pi} \left.\left[V^{\pi}_{t+1,\upsilon}\left(S_{t+1},y-c\left(s,A_t,S_{t+1}\right)\right)\right|S_t=s,Y_t=y\right]\notag\\
    &= \int_{\mathcal{A}} \int_{\mathcal{S}} \pi(a|t,s,y) p(s'|s,a)V^{\pi}_{t+1,\upsilon}\left(s',y-c\left(s,a,s'\right)\right) \nu_{\mathcal{S}}(\d s') \nu_{\mathcal{A}}(\d a)\notag\\
    &\geq \int_{\mathcal{A}} \int_{\mathcal{S}} \pi(a|t,s,y) p(s'|s,a)V^*_{t+1,\upsilon}\left(s',y-c\left(s,a,s'\right)\right) \nu_{\mathcal{S}}(\d s') \nu_{\mathcal{A}}(\d a)\notag\\
    & \geq \int_{\mathcal{A}}  \pi(a|t,s,y)\left( \inf_{a'\in\mathcal{A}}\int_{\mathcal{S}} p(s'|s,a')V^*_{t+1,\upsilon}\left(s',y-c\left(s,a',s'\right)\right) \nu_{\mathcal{S}}(\d s') \right)\nu_{\mathcal{A}}(\d a) \notag\\
    &= \inf_{a\in\mathcal{A}}\int_{\mathcal{S}} p(s'|s,a)V^*_{t+1,\upsilon}\left(s',y-c\left(s,a,s'\right)\right) \nu_{\mathcal{S}}(\d s')\notag\\
    &= V_{t,\upsilon}^*(s,y).\notag
\end{align}
By induction, the assertion holds for $0\leq t\leq T.$

For any $(s,y)\in\mathcal{S}\times\mathcal{Y},$ there exists a sequence $\{a_n\}_{n=1}^{\infty}\subset\mathcal{A}$ such that 
\begin{align}
& \int_{\mathcal{S}}  p(s'|s,a_n)f\left(c\left(s,a_n,s'\right)-y,\upsilon\right) \nu_{\mathcal{S}}(\d s')\notag\\
&\quad\to \inf_{a\in\mathcal{A}}\left\{\int_{\mathcal{S}}  p(s'|s,a)f\left(c\left(s,a,s'\right)-y,\upsilon\right) \nu_{\mathcal{S}}(\d s')\right\}.\notag
\end{align}
We hence let $\pi_{\upsilon,n} (\cdot|T-1,s,y)$ be a point mass on $a_n.$ Moreover, for any $(s,y)\in\mathcal{S}\times\mathcal{Y},$ there exists a sequence $\{a_n\}_{n=1}^{\infty}\in\mathcal{A}$ such that 
\begin{align}
&\int_{\mathcal{S}}  p(s'|s,a_n){V}^*_{t+1,\upsilon}\left(s',y-c\left(s,a_n,s'\right)\right) \nu_{\mathcal{S}}(\d s')\notag\\
&\quad\to   \inf_{a\in\mathcal{A}}\left\{\int_{\mathcal{S}}  p(s'|s,a){V}^*_{t+1,\upsilon}\left(s',y-c\left(s,a,s'\right)\right) \nu_{\mathcal{S}}(\d s')\right\}.\notag
\end{align}
We define $\pi_{\upsilon,n} (\cdot|t,s,y)$ recursively as a point mass on $a_n.$ By the dominated convergence theorem, it is easy to see that
\begin{equation}
  \left[ V_{t,\upsilon}^{\pi_{\upsilon,n}}(s,y) -V_{t,\upsilon}^*(s,y)\right]\to 0 \ (n\to\infty),\notag
\end{equation}
for any $t\in\mathcal{T},s\in\mathcal{S},y\in\mathcal{Y}.$
\end{proof}



The proof of Proposition \ref{propmin} needs the following lemma.

\begin{lemma}
\label{lpxs_lemma}
There exists a $\Delta>0$ such that 
\begin{equation}
    \left|\E[f(Y,\upsilon_1)]-\E [f(Y,\upsilon_2)]\right| \leq \Delta |\upsilon_1-\upsilon_2|,\notag
\end{equation}
for any $\upsilon_1,\upsilon_2\in\Upsilon$ and random variable $Y$ satisfying $\underline{y}\leq Y\leq\bar{y}$ almost surely. 
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lpxs_lemma}]
For any $y\in\mathcal{Y},$ and $\upsilon_1<\upsilon_2\in\Upsilon,$ let
\begin{equation}
    L(y,\upsilon_1,\upsilon_2) := \frac{f(y,\upsilon_2)-f(y,\upsilon_1)}{\upsilon_2-\upsilon_1}.\notag
\end{equation}
As $f(y,\upsilon)$ is convex in $\upsilon\in\mathbb{R},$ $L$ is increasing in $\upsilon_2$ and $\upsilon_1$ respectively. Hence, it is sufficient to show 
\begin{equation}
\label{leftside}\inf_{y\in\mathcal{Y},\upsilon_2\downarrow\underline{\upsilon}}L(y,\underline{\upsilon},\upsilon_2) >-\infty,\\
\end{equation} and \begin{equation}\label{rightside}\sup_{y\in\mathcal{Y},\upsilon_1\uparrow \bar{\upsilon}}L(y,\upsilon_1,\bar{\upsilon}) <\infty,
\end{equation}
which then imply
\begin{equation}
    -\infty<\inf_{y\in\mathcal{Y},\upsilon_1<\upsilon_2\in\Upsilon} \frac{f(y,\upsilon_2)-f(y,\upsilon_1)}{\upsilon_2-\upsilon_1}\leq\sup_{y\in\mathcal{Y},\upsilon_1<\upsilon_2\in\Upsilon} \frac{f(y,\upsilon_2)-f(y,\upsilon_1)}{\upsilon_2-\upsilon_1} <\infty.\notag
\end{equation}
In what follows, we only show \eqref{rightside}, and the proof for \eqref{leftside} is similar. We prove by contradiction and suppose that \eqref{rightside} does not hold. Then there exist $\left\{y_n\right\}^{\infty}_{n=1}\subset \mathcal{Y}$ and $\upsilon_n\uparrow\bar{\upsilon}\ (n\to\infty)$ such that 
$f(y_n,\bar{\upsilon})-f(y_n,\upsilon_n)>n(\bar{\upsilon}-\upsilon_n).$ 
Since $\underline{y}\leq y_n \leq \bar{y}$ for all $n\geq 1,$ there exists a convergent subsequence $y_{n_k}\to y_0 \; (k\to\infty).$ Thus, we have
\begin{equation}
\liminf_{k\to\infty}   \frac{ f(y_0,\bar{\upsilon})-f(y_0,\upsilon_{n_k})}{\bar{\upsilon}-\upsilon_{n_k}} =\liminf_{k\to\infty}   \frac{ f(y_{n_k},\bar{\upsilon})-f(y_{n_k},\upsilon_{n_k})}{\bar{\upsilon}-\upsilon_{n_k}} \geq  \liminf_{k\to\infty} n_k = \infty,\notag
\end{equation}
which implies 
\begin{equation}
    \lim_{k\to\infty}   \frac{ f(y_0,\bar{\upsilon})-f(y_0,\upsilon_{n_k})}{\bar{\upsilon}-\upsilon_{n_k}} = \infty.\notag
\end{equation}
This leads to a contradiction with the fact that $f(y_0,\cdot)$ is convex on $\mathbb{R}.$ Therefore, there exists $\Delta>0$ such that 
\begin{equation}
    \sup_{y\in\mathcal{Y},\upsilon_1<\upsilon_2\in\Upsilon} \frac{|f(y,\upsilon_2)-f(y,\upsilon_1)|}{|\upsilon_2-\upsilon_1|} \leq \Delta.\notag
\end{equation}
Finally, we have
\begin{align}
    \left|\E[ f(Y,\upsilon_1)]-\E [f(Y,\upsilon_2)]\right| = &\left|\int_{\mathcal{Y}}f(y,\upsilon_1) \d F(y)-\int_{\mathcal{Y}}f(y,\upsilon_2) \d F(y)\right|\notag\\
   \leq &\int_{\mathcal{Y}}\left|f(y,\upsilon_1) -f(y,\upsilon_2) \right|\d F(y)
   \leq \Delta|\upsilon_1-\upsilon_2|.\notag\qedhere
\end{align}
\end{proof}

\begin{proof}[Proof of Proposition \ref{propmin}]
First, we prove that $\upsilon\mapsto h(\mathbb E [V^*_{0,\upsilon}(S_0,0)] ,\upsilon)$ is a continuous function on $\Upsilon.$ We prove this claim by contradiction, and suppose that $\upsilon \mapsto h(\mathbb E [V^*_{0,\upsilon}(S_0,0)], \upsilon)$ has a discontinuous point at $\upsilon_0.$ Then, there exists a sequence $\left\{\upsilon_n\right\}_{n=1}^{\infty}$ satisfying 
     $\upsilon_n\to\upsilon_0\ (n\to\infty)$
and
\begin{equation}
\label{abs_gap}
    \left|\mathbb E [V^*_{0,\upsilon_n}(S_0,0)]-\mathbb E [V^*_{0,\upsilon_0}(S_0,0)]\right| \geq \delta
\end{equation}
for some $\delta>0.$ We note that 
\begin{align}
    &\mathbb E [V^*_{0,\upsilon_0}(S_0,0)]\notag\\
    =&\inf_{\pi\in\tilde{\Pi}}\lim_{\upsilon\to\upsilon_0}  \mathbb{E}_{\pi} \left[f\left(\sum_{k=0}^{T-1}c(S_k,A_k,S_{k+1})-Y_t,\upsilon\right)\right]\notag\\
    \geq&\lim_{\upsilon\to\upsilon_0}\inf_{\pi\in\tilde{\Pi}} \mathbb{E}_{\pi} \left[f\left(\sum_{k=0}^{T-1}c(S_k,A_k,S_{k+1})-Y_t,\upsilon\right)\right]\notag\\
    =&\lim_{\upsilon\to\upsilon_0}\mathbb E [V^*_{0,\upsilon}(S_0,0)],\notag
\end{align}
which implies that $\mathbb E [V^*_{0,\upsilon}(S_0,0)]$ is upper semi-continuous in $\upsilon.$ Therefore, we only need to show
\begin{equation}
    \mathbb E [V^*_{0,\upsilon_n}(S_0,0)]-\mathbb E [V^*_{0,\upsilon_0}(S_0,0)] \leq -\delta. \notag
\end{equation}
For any $\epsilon>0,$ take  
\begin{equation}
   \pi_{n,\epsilon}\in \left\{\pi\in\tilde{\Pi}:\E [V^{\pi}_{0,\upsilon_n}(S_0,0)]-\E [V^{*}_{0,\upsilon_n}(S_0,0)]<\epsilon\right\}. \notag
\end{equation}
Then, it holds that 
\begin{equation}
     \mathbb E [V^*_{0,\upsilon_0}(S_0,0)]\leq \liminf_{\epsilon\to 0} \E [V^{\pi_{n,\epsilon}}_{0,\upsilon_0}(S_0,0)],\notag
\end{equation}
which implies
\begin{equation}
  \limsup_{\epsilon\to 0} \E [V^{\pi_{n,\epsilon}}_{0,\upsilon_n}(S_0,0)]  =\mathbb E [V^*_{0,\upsilon_n}(S_0,0)]\leq \liminf_{\epsilon\to 0} \E [V^{\pi_{n,\epsilon}}_{0,\upsilon_0}(S_0,0)]-\delta.\notag
\end{equation}
Thus we have 
\begin{equation}
\label{eq_contra}
    \limsup_{\epsilon\to 0} \frac{\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_n}(S_0,0)]-\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_0}(S_0,0)]}{|\upsilon_n-\upsilon_0|}\leq -\frac{\delta}{|\upsilon_n-\upsilon_0|} .
\end{equation}
In \eqref{eq_contra}, as $n\to\infty,$ the $\text{RHS}\to-\infty$ while the $\text{LHS}\geq-\Delta$ by Lemma \ref{lpxs_lemma}. This leads to a contradiction.

As $\upsilon\mapsto h(\mathbb E [V^*_{0,\upsilon}(S_0,0) ],\upsilon)$ is a continuous function on $\Upsilon,$ it attains a minimal value $l$ on $\Upsilon.$ We next prove that $l$ is also the minimal value of $h(\mathbb E [V^*_{0,\upsilon}(S_0,0)] ,\upsilon)$ on $\mathbb{R}.$ Assume that there exists $\upsilon_0\notin \Upsilon,$ such that  $h(\mathbb E [V^*_{0,\upsilon_0}(S_0,0)] ,\upsilon_0)<l.$ By Proposition  \ref{prop_appro}
, there exists a $\pi\in\tilde{\Pi}$ such that $h(\mathbb E [V^{\pi}_{0,\upsilon_0}(S_0,0)] ,\upsilon_0)<l.$ Then by Lemma \ref{simpleProposition1}  and Proposition \ref{simpleProposition2}, $h(\mathbb E [V^{\pi}_{0,\upsilon}(S_0,0)] ,\upsilon)$ attains its minimal value on $\upsilon_1\in\Upsilon,$ and thus we have
\begin{equation}
   h(\mathbb E [V^{\pi}_{0,\upsilon_1}(S_0,0)] ,\upsilon_1)\leq h(\mathbb E [V^{\pi}_{0,\upsilon_0}(S_0,0)] ,\upsilon_0)<l,\notag
\end{equation}
which leads to a contradiction with the fact that $l$ is the minimal value on $\Upsilon.$
\end{proof}

\begin{proof}[Proof of Theorem \ref{t1}]
By Theorem 2.2 in \cite{hornik1989multilayer} and the fact that
\begin{align}
    V_{t,\upsilon}(s,y;\theta) &= \E_{\pi_{\upsilon}^\theta} \left[f\left(\sum_{k=t}^{T-1}c(S^{\theta}_k,A^{\theta}_k,S^{\theta}_{k+1})-Y_t^{\theta},\upsilon\right) \Big|S_t^{\theta}=s, Y_t^{\theta}=y\right]\notag\\
    &=\E_{\pi_{\upsilon}^\theta} \left[f\left(\sum_{k=t+1}^{T-1}c(S^{\theta}_k,A^{\theta}_k,S^{\theta}_{k+1})+c(s,A^{\theta}_t,S^{\theta}_{t+1})-y,\upsilon\right) \right]\notag
\end{align}
is measurable in $(s,y,\upsilon)$ and continuous in $(y,\upsilon),$ for any $\gamma_{t},\epsilon_{t}>0,$ there exists a neural network with parameter $\phi_t$ such that
\begin{equation}
         \nu_{\mathcal{S}}\left(\sup_{y\in\mathcal{Y},\upsilon\in\Upsilon}| V_{t,\upsilon}(s,y;\theta) -V^{\phi_t}_{t,\upsilon}(s,y;\theta)| > \gamma_{t}\right)< \epsilon_{t}.\notag
    \end{equation}
By Lemma 6.4 in \cite{CJ2024}, we know that, for any $\hat{\gamma}>0$, there exists a neural network $\phi$ such that
\begin{equation}
    \underset{t\in\mathcal{T},s\in S,y \in \mathcal{Y},\upsilon\in \Upsilon}{\sup}\  \left| V^{\phi_t}_{t,\upsilon}(s,y;\theta)-V^{\phi}_{t,\upsilon}(s,y;\theta)\right| < \hat{\gamma},\notag
\end{equation}
which implies
\begin{equation}
     \nu_{\mathcal{S}}\left(\sup_{t\in\mathcal{T},y\in\mathcal{Y},\upsilon\in \Upsilon}| V^{\phi_t}_{t,\upsilon}(s,y;\theta) -V^{\phi}_{t,\upsilon}(s,y;\theta)| > \hat{\gamma}\right) = 0.\notag
\end{equation}
Thus, we have 
\begin{align}
     &\nu_{\mathcal{S}}\left(\sup_{t\in\mathcal{T},y\in\mathcal{Y},\upsilon\in\Upsilon}| V_{t,\upsilon}(s,y;\theta) -V^{\phi}_{t,\upsilon}(s,y;\theta)| > \sum_{i=0}^{T-1}\gamma_{i}+\hat{\gamma}\right)\notag\\
     \leq & \nu_{\mathcal{S}}\left(\sup_{t\in\mathcal{T},y\in\mathcal{Y},\upsilon\in\Upsilon}| V_{t,\upsilon}(s,y;\theta) -V^{\phi}_{t,\upsilon}(s,y;\theta)| > \sum_{i=0}^{T-1}\gamma_{i}+\hat{\gamma},\sup_{t\in\mathcal{T},y\in\mathcal{Y},\upsilon\in\Upsilon}| V^{\phi_t}_{t,\upsilon}(s,y;\theta) -V^{\phi}_{t,\upsilon}(s,y;\theta)| \leq \hat{\gamma}\right)\notag\notag\\
     &\quad+ \nu_{\mathcal{S}}\left(\sup_{t\in\mathcal{T},y\in\mathcal{Y},\upsilon\in\Upsilon}| V^{\phi_t}_{t,\upsilon}(s,y;\theta) -V^{\phi}_{t,\upsilon}(s,y;\theta)| > \hat{\gamma}\right)\notag\\
     \leq & \nu_{\mathcal{S}}\left(\sup_{t\in\mathcal{T},y\in\mathcal{Y},\upsilon\in\Upsilon}| V_{t,\upsilon}(s,y;\theta) -V^{\phi_t}_{t,\upsilon}(s,y;\theta)| > \sum_{i=0}^{T-1}\gamma_{i}\right)\notag\\
      \leq & \sum_{t=0}^{T-1}\nu_{\mathcal{S}}\left(\sup_{y\in\mathcal{Y},\upsilon\in\Upsilon}| V_{t,\upsilon}(s,y;\theta) -V^{\phi_t}_{t,\upsilon}(s,y;\theta)| > \sum_{i=0}^{T-1}\gamma_{i}\right)\notag\\
      \leq & \sum_{t=0}^{T-1}\nu_{\mathcal{S}}\left(\sup_{y\in\mathcal{Y},\upsilon\in\Upsilon}| V_{t,\upsilon}(s,y;\theta) -V^{\phi_t}_{t,\upsilon}(s,y;\theta)| > \gamma_{t}\right)\notag\\
     <&  \sum_{t=0}^{T-1}\epsilon_t.\notag
\end{align}
By taking $\gamma_t=\frac{\epsilon^*}{2T},\hat{\gamma}=\frac{\epsilon^*}{2}$ and $\epsilon_t = \frac{\epsilon^*}{T}$ for all $t\in\mathcal{T},$ the conclusion holds.
\end{proof}

\begin{proof}[Proof of Lemma \ref{l0}]
As $\mathcal{S},\mathcal{Y},\Upsilon$ are compact and $f(\cdot,\cdot)$ is continuous,  it follows that $|\E [V_{0,\upsilon}(S_0,0;\theta)]|$ and $|\E [V^{\phi}_{0,\upsilon}(S_0,0;\theta)]|$ are bounded in $\upsilon\in\Upsilon$. Denote the upper bound by $B.$ As $h$ is continuous, it is uniformly continuous on $[-B,B]\times\Upsilon,$ i.e., for any $(V_1,\upsilon_1),(V_2,\upsilon_2)\in [-B,B]\times\Upsilon,$ $\gamma'>0,\gamma''>0,$ and we have
\begin{equation}
    |h(V_1,\upsilon_1)-h(V_2,\upsilon_2)|\leq\gamma'',\notag
\end{equation}
if 
\begin{equation}
    \sqrt{|V_1-V_2|^2+|\upsilon_1-\upsilon_2|^2} \leq \gamma'\notag
\end{equation}
holds. Taking $\upsilon_1=\upsilon_2=\upsilon$ yields that $V_1 = \E [V_{0,\upsilon}(S_0,0;\theta)]$ and $V_2=\E [V^{\phi}_{0,\upsilon}(S_0,0;\theta)]$. Hence, the conclusion follows. 
\end{proof}

\begin{proof}[Proof of Lemma \ref{l2}]
If $\mathscr{U}^*=\Upsilon,$ the conclusion is trivial. We only need to consider the case where $\mathscr{U}^*$ is a proper subset of $\Upsilon.$ We prove by contradiction and suppose that there exist $\gamma_0>0$ and $\left\{(\phi_n,\theta_n)\right\}_{n=1}^{\infty}$ such that
\begin{equation}
\label{limassumption}
    \lim_{n\to\infty} \underset{\upsilon \in \Upsilon}{\text{sup}} |h(\mathbb E [V^*_{0,\upsilon}(S_0,0)],\upsilon) - h(\mathbb E [V_{0,\upsilon}^{\phi_n}(S_0,0;\theta_n)],\upsilon)| = 0,
\end{equation}
and $d\left(\mathscr{U}^*,\upsilon^*({\theta_n},\phi_n)\right)>\gamma_0.$ We denote
\begin{equation}
    l_0 = \inf\left\{h(\mathbb E [V^*_{0,\upsilon}(S_0,0)],\upsilon):\upsilon\in\Upsilon\right\}\notag,
\end{equation}
and
\begin{equation}
    l_1 = \inf\left\{h(\mathbb E [V^*_{0,\upsilon}(S_0,0)],\upsilon):\upsilon\in\Upsilon,d\left(\mathscr{U}^*,\upsilon\right)>\gamma_0\right\}.\notag
\end{equation}
In view that $\upsilon\mapsto h(\mathbb E[ V^*_{0,\upsilon}(S_0,0)],\upsilon)$ is continuous on $\Upsilon,$ we have $l_1>l_0.$ Fix $\upsilon'\in \mathscr{U}^*.$ It holds that
\begin{align}
    \liminf_{n\to\infty}h(\mathbb E [V_{0,\upsilon'}^{\phi_n}(S_0,0;\theta_n)],\upsilon')&\geq \liminf_{n\to\infty}h(\mathbb E [V_{0,\upsilon^*({\theta_n},\phi_n)}^{\phi_n}(S_0,0;\theta_n)],\upsilon^*({\theta_n},\phi_n))\notag\\
    &\geq l_1>l_0=h(\mathbb E [V^*_{0,\upsilon'}(S_0,0)],\upsilon'),\notag
\end{align}
which leads to a contradiction to \eqref{limassumption}.\end{proof}

\begin{proof}[Proof of Theorem \ref{t2}]
Because $\mathcal{S},\mathcal{Y},\Upsilon$ are all compact and $f(\cdot,\cdot)$ is continuous, we have $|V_{0,\upsilon}(s_0,0;\theta)|$ and $|V^{\phi}_{0,\upsilon}(s_0,0;\theta)|$ are bounded for $(s_0,\upsilon)\in\mathcal{S}\times\Upsilon$. Denote the upper bound by $B.$ If the third condition holds, we have
\begin{align}
      \underset{\upsilon\in\Upsilon}{\text{sup}} |\mathbb E [V_{0,\upsilon}(S_0,0;\theta)]- \mathbb E[V^{\phi}_{0,\upsilon}(S_0,0;\theta)]| &\leq \mathbb E[\underset{\upsilon\in\Upsilon}{\text{sup}}| V_{0,\upsilon}(S_0,0;\theta) - V^{\phi}_{0,\upsilon}(S_0,0;\theta)|]\notag\\
       &=\int_{\mathcal{S}_1}\underset{\upsilon\in\Upsilon}{\text{sup}}| V_{0,\upsilon}(s_0,0;\theta) - V^{\phi}_{0,\upsilon}(s_0,0;\theta)|p(s_0)\d s_0 \notag\\
       & \quad+\int_{\mathcal{S}
       \backslash \mathcal{S}_1}\underset{\upsilon\in\Upsilon}{\text{sup}}| V_{0,\upsilon}(s_0,0;\theta) - V^{\phi}_{0,\upsilon}(s_0,0;\theta)|p(s_0)\d s_0\notag\\
       &\leq 2B\epsilon_1'+\gamma_1'.\notag
   \end{align}
For any $\gamma'>0,$ we take $\gamma_1' = \frac{\gamma'}{4},$ $\epsilon_1'=\frac{\gamma'}{4B}$ and have
\begin{align}
    \underset{\upsilon\in\Upsilon}{\text{sup}} |\mathbb E[V^*_{0,\upsilon}(S_0,0)] - \mathbb E[V^{\phi}_{0,\upsilon}(S_0,0;\theta)]|&\leq \underset{\upsilon\in\Upsilon}{\text{sup}} |\mathbb E [V_{0,\upsilon}(S_0,0;\theta)] - \mathbb E[V^{\phi}_{0,\upsilon}(S_0,0;\theta)]|\notag\\
    &\quad+ \sup_{\upsilon\in \mathcal{Y}}|\mathbb E [V_{0,\upsilon}^{\phi}(S_0,0;\theta)]-\mathbb E[V^*_{0,\upsilon}(S_0,0)]| \notag\\
    &< (2B\epsilon_1'+\gamma_1') + \gamma_1'\notag\\
    &=\gamma'.\notag
\end{align}
By Lemmas \ref{l0}-\ref{l2},  the desired conclusion holds.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:am_converge}]
From \eqref{argmin}, it follows that $\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0)]\leq\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n}}(S_0,0)]$ holds for all $n\geq1$. Hence, we have 
\begin{align}
\label{chain_neq}h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0)],\upsilon_{n+1})\leq &h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n}}(S_0,0)],\upsilon_n)\notag\\
< &h(\E [V^{*}_{0,\upsilon_{n}}(S_0,0)],\upsilon_n)+\frac{\epsilon}{n^2}\notag\\
\leq &h(\E [V^{\pi_{n-1,\epsilon}}_{0,\upsilon_{n}}(S_0,0)],\upsilon_n)+\frac{\epsilon}{n^2}\notag\\
\leq &h(\E [V^{\pi_{n-1,\epsilon}}_{0,\upsilon_{n}}(S_0,0)],\upsilon_n)+\frac{\epsilon}{n-1}-\frac{\epsilon}{n},
\end{align}
    which implies \begin{equation}
        h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0)],\upsilon_{n+1})+\frac{\epsilon}{n} < h(\E [V^{\pi_{n-1,\epsilon}}_{0,\upsilon_{n}}(S_0,0)],\upsilon_{n})+\frac{\epsilon}{n-1},\notag
    \end{equation}
    for all $n\geq 1.$ As a result, $\left\{A^{\epsilon}_n= h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0)],\upsilon_{n+1})+\frac{\epsilon}{n}\right\}_{n=1}^{\infty}$ is a decreasing sequence with the lower bound $\min_{\upsilon\in\Upsilon}h(\E [V^{*}_{0,\upsilon}(S_0,0)],\upsilon)$, which converges to some $A^{\epsilon}\geq \min_{\upsilon\in\Upsilon}h(\E [V^{*}_{0,\upsilon}(S_0,0)],\upsilon)>-\infty,$ i.e., 
    \begin{equation}
        \lim_{n\to\infty}h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0)],\upsilon_{n+1})=\lim_{n\to\infty}h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0)],\upsilon_{n+1})+\frac{\epsilon}{n} = A^{\epsilon}.\notag
    \end{equation}
    Fix a $\gamma>0$. For any $N\geq 1,$ there exists some $\epsilon_N>0$ such that \begin{equation}
          h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon}(S_0,0)],\upsilon)\leq h(\E [V^{\pi}_{0,\upsilon}(S_0,0)],\upsilon)+\delta(\upsilon,\upsilon_n)+\frac{\gamma}{(n+1)^2},\notag
     \end{equation}
     for any $\upsilon\in\Upsilon,\pi\in\tilde{\Pi},0<\epsilon<\epsilon_N$ and $1\leq n\leq N.$ Thus, we have \begin{equation}
         \delta(\upsilon,\upsilon_{n+1})+h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0)],\upsilon_{n+1})\leq h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon}(S_0,0)],\upsilon)\leq h(\E [V^{\pi}_{0,\upsilon}(S_0,0)],\upsilon)+\delta(\upsilon,\upsilon_n)+\frac{\gamma}{(n+1)^2},\notag
 \end{equation}
 which yields that
 \begin{equation}
 \label{recursiv_neq}
    h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0)],\upsilon_{n+1})-h(\E [V^{\pi}_{0,\upsilon}(S_0,0)],\upsilon)\leq\delta(\upsilon,\upsilon_n)-\delta(\upsilon,\upsilon_{n+1})+\frac{\gamma}{(n+1)^2},
      \end{equation}
for any $\upsilon\in\Upsilon,\pi\in\tilde{\Pi},0<\epsilon<\epsilon_N$ and $1\leq n\leq N.$ 
Summing equation \eqref{recursiv_neq} from $n=1$ to $n = N$, we deduce that
\begin{align}
   \sum_{n=1}^{N}[ h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0)],\upsilon_{n+1})-h(\E [V^{\pi}_{0,\upsilon}(S_0,0)],\upsilon)] \leq& \delta(\upsilon,\upsilon_1)-\delta(\upsilon,\upsilon_{N+1})+\sum_{n=1}^N\frac{1}{(n+1)^2}\gamma\notag\\ \leq& \delta(\upsilon,\upsilon_1)-\delta(\upsilon,\upsilon_{N+1})+\gamma.\notag
\end{align}
Sending $N$ to infinity, we get
\begin{equation}
    \limsup_{N\to\infty} \sum_{n=1}^{N} [h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0)],\upsilon_{n+1})-h(\E [V^{\pi}_{0,\upsilon}(S_0,0)],\upsilon)]\leq \delta(\upsilon,\upsilon_1)+\gamma<\infty,\notag
\end{equation}
which implies 
\begin{equation}
    \limsup_{N\to\infty,\epsilon\to0} h(\E [V^{\pi_{N,\epsilon}}_{0,\upsilon_{N+1}}(S_0,0)],\upsilon_{N+1})=\limsup_{N\to\infty,\epsilon<\epsilon_N} h(\E [V^{\pi_{N,\epsilon}}_{0,\upsilon_{N+1}}(S_0,0)],\upsilon_{N+1})\leq h(\E [V^{\pi}_{0,\upsilon}(S_0,0)],\upsilon).\notag
\end{equation}
By the arbitrariness of $\upsilon$ and $\pi,$ we obtain that 
\begin{equation}
    \limsup_{n\to\infty,\epsilon\to 0 } h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0)],\upsilon_{n+1})\leq h(\min_{\upsilon\in\Upsilon}\E [V^{*}_{0,\upsilon}(S_0,0)],\upsilon)\leq \liminf_{n\to\infty,\epsilon\to 0 }h(\E [V^{\pi_{n,\epsilon}}_{0,\upsilon_{n+1}}(S_0,0)],\upsilon_{n+1}),\notag
\end{equation}
which completes the proof.
\end{proof}

The proof of Proposition \ref{thm:limit} requires the following lemma. 
\begin{lemma}
\label{p_qa}
If $f(y,\upsilon) = \upsilon+\frac{1}{1-\alpha}(y-\upsilon)^+,$ for any $\pi\in\tilde{\Pi},$ we have 
\begin{equation}
     \E [V^{\pi}_{0,\upsilon}(S_0,0)]|_{\upsilon=q_{\alpha}(F_{\pi})} = \min_{\upsilon\in \mathbb{R}} \E [V^{\pi}_{0,\upsilon}(S_0,0)].\notag
\end{equation}
\end{lemma}

\begin{proof}[Proof of Lemma \ref{p_qa}]
  We have \begin{align}
       &\frac{\partial}{\partial \upsilon}\mathbb{E}_{\pi} \left.\left[\upsilon+\frac{1}{1-\alpha}\left(\sum_{k=0}^{T-1}c(S_k,A_k,S_{k+1})-\upsilon\right)^+\right|Y_0=0\right]\notag\\
       =&\mathbb{E}_{\pi}  \left.\left[1-\frac{1}{1-\alpha}\mathds{1}\left(\sum_{k=0}^{T-1}c(S_k,A_k,S_{k+1})-\upsilon>0\right)\right|Y_0=0\right]\notag\\
       =&1-\frac{1}{1-\alpha}\mathbb{P}_{\pi} \left.\left(\sum_{k=0}^{T-1}c\left(S_{k},A_k,S_{k+1}\right)> \upsilon\right|Y_0=0\right)\notag\\
       =& \frac{1}{1-\alpha}(F_{\pi}(\upsilon)-\alpha).\notag
\end{align}
Clearly, the function $\upsilon\mapsto \E[V^{\pi}_{0,\upsilon}(S_0,0)]$ attains its minimum at $F_{\pi}(\upsilon)=\alpha.$ 

\end{proof}


\begin{proof}[Proof of Proposition \ref{thm:limit}]
Taking $\delta(\upsilon_1,\upsilon_2)=\frac{\Delta}{2}(\upsilon_1-\upsilon_2)^2$, together with Theorem \ref{thm:am_converge} and Lemma \ref{p_qa}, leads to the conclusion.
\end{proof}


