\title{Perpetual American Standard and Lookback Options in Insider Models with Progressively Enlarged Filtrations}


\author{Pavel V. Gapeev\footnote{(Corresponding author) London School of Economics,
Department of Mathematics, Houghton Street, London WC2A 2AE, United
Kingdom; e-mail: p.v.gapeev{\char'100}lse.ac.uk} \and Libo Li\footnote{University of New South Wales, School of Mathematics and Statistics, Sydney NSW 2052, Australia; e-mail: libo.li{\char'100}unsw.edu.au}}


