\section{\dot Introduction}


%The main aim of this paper is to present

     Let us consider a probability space $(\Omega, {\cal F}, \PP)$ with a standard Brownian motion
     $B=(B_t)_{t \ge 0}$ and define the process $X=(X_t)_{t \ge 0}$ by:
       \begin{equation}
       \label{X4}
       X_t = x \, \exp \Big( \big( r - \delta - {\sigma^2}/{2} \big) \, t + \sigma \, B_t \Big)
       \end{equation}
       which solves the stochastic differential equation:
       \begin{equation}
       \label{dX4}
       dX_t = (r-\delta) \, X_{t} \, dt + \sigma \, X_{t} \, dB_t \quad (X_0=x)
       \end{equation}
       where $x > 0$ is fixed, and $r > 0$, $\delta > 0$, and $\sigma > 0$ are some given constants.
       Assume that $X$ describes the price of a risky asset in a financial market,
       where $r$ is the riskless interest rate, $\delta$ is the dividend rate paid to the asset holders,
       and $\sigma$ is the volatility rate.
       %and the expectations there are taken with respect to the risk-neutral probability measure $P$.
     We aim to present closed-form solutions to the discounted optimal stopping problems with the values:
%[The main purpose of the present paper
%is to compute the values of the optimal stopping problems:]
     \begin{align}
     \label{VU5a1}
     V_i &= \sup_{\tau \in \GG^1} \EE \big[ e^{- r \tau} \, G_i(X_{\tau}, S_{\tau}) \big]
     \quad \text{and} \quad
     U_i = \sup_{\zeta \in \GG^2} \EE \big[ e^{- r \zeta} \, F_i(X_{\zeta}, Q_{\zeta}) \big]
     \end{align}
     where $G_1(x, s) = L_1 - x$, $G_2(x, s) = s - L_2 x$, $G_3(x, s) = s - L_3$, and
     $F_1(x, q) = x - K_1$, $F_2(x, q) = K_2 x - q$, $F_3(x, q) = K_3 - q$,
     for some deterministic constants $L_i, K_i > 0$, for $i = 1, 2, 3$.
     The linear functions $G_i(x, s)$ and $F_i(x, q)$, for $i = 1, 2, 3$, represent the
     payoffs of {\it standard} and {\it lookback} options with {\it floating} and {\it fixed}
     strikes, respectively, which are widely used in financial practice.
     Here, the processes $S=(S_t)_{t \ge 0}$ and $Q=(Q_t)_{t \ge 0}$
     are the {\it running maximum} and {\it minimum} of $X$ defined by:
       %the associated with $X$ defined by:
       \begin{equation}
       \label{SQ4}
       S_t = s \vee \Big( \max_{0 \le u \le t} X_u \Big) \equiv \max \Big\{ s, \max_{0 \le u \le t} X_u \Big\}
       \quad \text{and} \quad
       Q_t = q \wedge \Big( \min_{0 \le u \le t} X_u \Big) \equiv \min \Big\{ q, \min_{0 \le u \le t} X_u \Big\}
       \end{equation}
       for some arbitrary $0 < x \le s$ and $0 < q \le x$, respectively.


     Suppose that the suprema in (\ref{VU5a1}) are taken over all stopping times
     $\tau$ and $\zeta$ with respect to the filtrations $\GG^k = ({\cal G}^k_t)_{t \ge 0}$,
     for $k = 1, 2$, which coincide with the (right-continuous) reference filtration
     $\FF = ({\cal F}_t)_{t \ge 0}$ progressively enlarged by the random times $\theta$ and $\eta$,
     which are given by:
       \begin{equation}
       \label{theta}
       \theta = \sup \{ t \ge 0 \, | \, X_t = S_t \}
       \quad \text{and} \quad
       \eta = \sup \{ t \ge 0 \, | \, X_t = Q_t \}
       \end{equation}
       respectively. More precisely, the filtrations $\GG^k$, for $k = 1, 2$,
       are defined as the the right-continuous versions of $\GG^{*,k}$, for $k = 1, 2$, given by:
\begin{equation}
\label{gg}
\GG^{*,1}_t = \bigcap_{u > t} \big( {\cal F}_u \vee \sigma (\theta \wedge u) \big)
\quad \text{and} \quad
\GG^{*,2}_t = \bigcap_{u > t} \big( {\cal F}_u \vee \sigma (\eta \wedge u) \big)
%\, \forall t \ge 0\,.
\end{equation}
for all $t \ge 0$.
       Note that the random times $\theta$ and $\eta$ from (\ref{theta})
       are not stopping times with respect to the natural filtration $\FF$
       of the process $X$, but they are honest times with respect to $\FF$
       in the sense of Barlow \cite{B} and Nikeghbali and Yor \cite{NY}.
       In this view, the values $V_i$ and $U_i$, for $i = 1, 2, 3$, in (\ref{VU5a1}) can be
       interpreted as the rational (or no-arbitrage) prices of the perpetual American options
       in the appropriate extension of the Black-Merton-Scholes model with enlarged information
       flows (see, e.g. \cite[Chapter~VII, Section~3g]{FM}).
       Some extensive overviews of the perpetual American options in diffusion models of financial
       markets and other related results in the area are provided in Shiryaev \cite[Chapter~VIII; Section~2a]{FM},
       Peskir and Shiryaev \cite[Chapter~VII; Section~25]{PSbook}, and Detemple \cite{Det} among others.
       %&({\cal F}_t)_{t \ge 0}$

