\, I(\theta \le u) - \alpha \sigma \, I(\theta > u) \bigg) \, du
\end{equation}
when $\alpha < 0$, and
\begin{equation}
\label{Btil2}
{\tilde B}^2_t = B_t - \int_0^t \bigg( \alpha \sigma \, \frac{Y_u}{1-Y_u}
%\frac{(Q_u/X_u)^{\alpha}}{1-(Q_u/X_u)^{\alpha}}
\, I(\eta \le u) - \alpha \sigma \, I(\eta > u) \bigg) \, du
\end{equation}
when $\alpha > 0$, which are standard Brownian motions
under $(\GG^1, \PP)$ and $(\GG^2, \PP)$, for all $t \ge 0$, respectively, according to the results of \cite{JLC}.
In this case, using the expressions in (\ref{Pi1b3}), we obtain that the process $X$ from (\ref{X4})-(\ref{dX4})
admits the representations:
       \begin{equation}
       \label{X4a}
       X_t = x \, \exp \bigg( \int_0^t
       \Big( r - \delta + \Psi \big( (S_u/X_u)^{\alpha}, \Xi^1_u \big)
       - \frac{\sigma^2}{2} \Big) \, du + \sigma \, {\tilde B}^1_t \Big)
       \end{equation}
       and
       \begin{equation}
       \label{X4b}
       X_t = x \, \exp \bigg( \int_0^t
       \Big( r - \delta + \Phi \big( (Q_u/X_u)^{\alpha}, \Xi^2_u \big)
       - \frac{\sigma^2}{2} \Big) \, du + \sigma \, {\tilde B}^2_t \Big)
       \end{equation}
       %for all $t \ge 0$,
       which solve the stochastic differential equations:
       \begin{equation}
       \label{dX4a}
       dX_t = \big( r - \delta + \Psi \big( (S_t/X_t)^{\alpha}, \Xi^1_t \big) \big)
       \, X_{t} \, dt + \sigma \, X_{t} \, d{\tilde B}^1_t \quad (X_0=x)
       \end{equation}
       and
       \begin{equation}
       \label{dX4b}
       dX_t = \big( r - \delta + \Phi \big( (Q_t/X_t)^{\alpha}, \Xi^2_t \big) \big)
       \, X_{t} \, dt + \sigma \, X_{t} \, d{\tilde B}^2_t \quad (X_0=x)
       \end{equation}
       for all $t \ge 0$ and each $x > 0$ fixed. Here, we set:
