       %[maybe $\psi(z, h^1)$ and $\xi(y, h^2)$]
       \begin{equation}
       \label{psi4}
       \Psi \big( (s/x)^{\alpha}, j \big) = \alpha \sigma \, \frac{(s/x)^{\alpha}}
       {1-(s/x)^{\alpha}} \, I(j = 1) - \alpha \sigma \, I(j = 0)
       \end{equation}
       for all $0 < x \le s$ and $j = 0, 1$, when $\alpha < 0$, and
       \begin{equation}
       \label{xi4}
       \Phi \big( (q/x)^{\alpha}, j \big) = \alpha \sigma \, \frac{(q/x)^{\alpha}}
       {1-(q/x)^{\alpha}} \, I(j = 1) - \alpha \sigma \, I(j = 0)
       \end{equation}
       for all $0 < q \le x$ and $j = 0, 1$, when $\alpha > 0$.





