\section{Technical Proofs}\label{sec:proofs}


\subsection{Proof of Theorem \ref{thm:testable_implication}}\label{proof:thm:testable_implication}

 Since $T|h \sim N(h,1)$, we have $f_T(t) = \int_{-\infty}^\infty \varphi(t-h)d\Pi_0(h) $. First we prove the $\implies$ direction. Under $\mathbf{H}_0$, $f_{T|R} = \int_{-\infty}^\infty \varphi(t-h)d\Pi(h)$. We can always construct a sequence of continuous random variables with pdfs $\pi_n$ that converge weakly to  $\Pi$. By Portmantau, $\left|\left|f_{T|R}- \int_{-\infty}^\infty \varphi(t-h)\pi_n(h)dh \right|\right|_Y \to 0$. This proves the right-hand-side. 

   % statement of the converse: $\mathbf{H}_0 \text{ false} \implies \inf_{\pi \in \mathcal{F}_\infty } \left|\left|f_{T|R}- \int_{-\infty}^\infty \varphi(t-h)\pi(h)dh \right|\right|_Y >0 $. 
   Now we prove the converse. If $\mathbf{H}_0$ is false, there is no distribution $\Pi\in \mathcal{P}$ such that $T|R \sim h_1+Z$ where $h_1\sim\Pi$ and $Z\sim N(0,1)$. This means that there is no $\Pi$ such that $f_{T|R}(t) = \int_{-\infty}^\infty \varphi(t-h)d\Pi(h)$ almost everywhere. So for each $\Pi \in \mathcal{P}$, $ \left|\left|f_{T|R}- \int_{-\infty}^\infty \varphi(t-h)d\Pi(h) \right|\right|_Y>0$. Since $\mathcal{P}$ is closed, $ \inf_{\Pi \in \mathcal{P}}\left|\left|f_{T|R}- \int_{-\infty}^\infty \varphi(t-h)d\Pi(h) \right|\right|_Y>0$. Since the set of continuous random variables is a subset, $ \inf_{\pi \in \mathcal{F}_{\infty}}\left|\left|f_{T|R}- \int_{-\infty}^\infty \varphi(t-h)\pi(h)dh \right|\right|_Y>0$. So the converse is proven.



\subsection{Proof of Lemma \ref{lem:pdf_spectral}}\label{proof:lem:pdf_spectral}

Define the following two inner products: $ \langle \phi,g\rangle_X \equiv \int_{-\infty}^{\infty} \phi(t)g(t)\varphi_{1+\sigma_Y^2}(t)dt$ and 
    $\langle \phi,g\rangle_Y \equiv \int_{-\infty}^{\infty} \phi(t)g(t)\varphi_{\sigma_Y^2}(t)dt$. Since the scaled Hermite polynomials $\chi_j$ are orthonormal in $\langle \rangle_{X}$ and $\psi_j$ are orthonormal in $\langle \rangle_{Y}$, we can characterize the difference between any two $f\in \mathcal{F}_\infty$ and $g=\int_{-\infty}^\infty \varphi(t-h)\pi(h)dh$:
\begin{align*}
||f-g||_Y^2 &= \langle f-g,f-g\rangle_Y^2 = \sum_{j=0}^\infty  \langle \psi_j,f-g \rangle_Y^2\\
   &=  \sum_{j=0}^\infty    \left(\mathbb{E}\left[\psi_j(T)\varphi_{\sigma_Y^2}(T)\right] - \langle \psi_j,g \rangle_Y\right)^2=  \sum_{j=0}^\infty    \left(\mathbb{E}\left[\psi_j(T)\varphi_{\sigma_Y^2}(T)\right] - \eta_j\langle \chi_j,\pi \rangle_Y\right)^2\\
  &=  \sum_{j=0}^\infty    \left(\mathbb{E}\left[\psi_j(T)\varphi_{\sigma_Y^2}(T)\right] - \eta_j\mathbb{E}_\pi\left[\chi_j(h)\varphi_{\sigma_Y^2+1}(h)\right] \right)^2
\end{align*}

\subsection{Proof of Theorem \ref{thm:validity_dj}}\label{proof:thm:validity_dj}
 The inequality is trivial. To show the equality, we must show that for any $\pi \in \mathcal{F}_{\infty}$ there is a sequence of $\{\mathbf{u}_k\}_{k=1}^\infty\subset U$ such that $\lim_{k\to \infty}\sum_{j=1}^\infty (\eta_j\mathbb{E}_\pi\left[\chi_j(h)\varphi_{\sigma_Y^2+1}(h)\right]-u_{k,j})^2=0$. Since any $\mathbf{u}_k$ can be converted to a discrete probability distribution $G_k$, this is equivalent to showing that there is a sequence of discrete distributions with finite support such that $\lim_{k\to \infty}||f_T-\int_{-\infty}^\infty \varphi(h-t)dG_k(h)||_Y=0$ which is possible with any sequence of discrete distributions with finite support $G_k$ that converge weakly to $\pi$ which is always possible.

 \subsection{Proof of Theorem \ref{thm:consistency_dj_large}}\label{proof:thm:consistency_dj_large}

If Equation \ref{eq:testable_restriction} holds, then by Theorem \ref{thm:validity_dj}, $d_\infty(U,\theta)>0$. By Lemma \ref{lem:bound_coeffs} each basis vector $\mathbf{u}$ satisfies $|u_j|< \eta_j \frac{1}{\sqrt{2\pi}}$. Now consider two cases. In case 1 there is some $J$ for which $|\theta_{J}| > \eta_{J} \frac{1}{\sqrt{2\pi}}$. In this case, setting this $J$ is sufficient to guarantee that $d_J(U,\theta)>0$. Now consider case 2 where  $|\theta^*_{j}| \leq \eta_{j} \frac{1}{\sqrt{2\pi}}$ for all $j$. Then there is some $J$ after which  $\sqrt{\sum_{j=J}^\infty u_j^2}<d_J(U,\theta)/3$ for all $u$ and $\sqrt{\sum_{j=J}^\infty \theta_j^2}<d_J(U,\theta)/3$. So for this $J$, it must be that $d_J(U,\theta)>0$. So in either case, when selective reporting is detectable,  $d_J(U,\theta)>0$.

\subsection{Proof of Lemma \ref{lem:max_grid_approx_error}}\label{proof:lem:max_grid_approx_error}



The approximation error is upper bounded by:

\begin{align*}
    \left|d_J({U},\mathbf{v})-d_J(\widetilde{U},\mathbf{v})\right| &= \left|  \inf_{\mathbf{u}\in U} ||\mathbf{v}-\mathbf{u}||_2-\inf_{\widetilde{\mathbf{u}}\in \widetilde{U}} ||\mathbf{v}-\widetilde{\mathbf{u}}||_2\right|\leq  \sup_{y\in\mathbb{R}} \min_{x\in\mathcal{X}} || \mathbf{u}_x-\mathbf{u}_y ||_2\\&\leq  \sup_{y\in\mathbb{R}} \min_{x\in\mathcal{X}} \sqrt{\int_{-\infty}^\infty \varphi_{\sigma_Y^2}(t)\left(\varphi(t-x)-\varphi(t-y)\right)^2dt }\\
    &\leq \max\left\{\sqrt{\int_{-\infty}^\infty \varphi_{\sigma_Y^2}(t)\varphi(t-L)^2dt }, \max_{y\in [-L,L]}\min_{x\in\mathcal{X}}\sqrt{\int_{-\infty}^\infty \varphi_{\sigma_Y^2}(t)\left(\varphi(t-x)-\varphi(t-y)\right)^2dt }  \right\}
\end{align*}

\begin{align*}
\max_{y\in [-L,L]}\min_{x\in\mathcal{X}}\sqrt{\int_{-\infty}^\infty \varphi_{\sigma_Y^2}(t)\left(\varphi(t-x)-\varphi(t-y)\right)^2dt } &\leq \max_{|x-y|<\delta/2}\sqrt{\int_{-\infty}^\infty \varphi_{\sigma_Y^2}(t)\left(\varphi(t-x)-\varphi(t-y)\right)^2dt } \\
&\leq\sqrt{\int_{-\infty}^\infty \varphi_{\sigma_Y^2}(t)\left(\varphi(t-1)-\varphi(t-1+\delta/2)\right)^2dt } 
\end{align*}

Let $\epsilon >0$. To force the right-hand-side below $\epsilon$, let $\widetilde{U}(\epsilon)$ consist of a grid of $h$ extending from $[-L,L]$ plus $h=\infty$ (i.e. $\mathbf{u}=\mathbf{0}$). Let $L$ satisfy $\sqrt{\int_{-\infty}^\infty \varphi_{\sigma_Y^2}(t)\varphi(t-L)^2dt }<\epsilon$. Let the spacing of the grid be $\delta$ where $\delta$ satisfies: $\sqrt{\int_{-\infty}^\infty \varphi_{\sigma_Y^2}(t)\left(\varphi(t-1)-\varphi(t-1+\delta/2)\right)^2dt } <\epsilon$. Thus: $d_J(\widetilde{U},\theta)<d_J({U},\theta)+\epsilon$

\subsection{Proof of Lemma \ref{thm:Ru_thetahat}}\label{proof:thm:Ru_thetahat}

The first step is to show that projection onto $\widetilde{U}$ is a piecewise linear. Since $\widetilde{U}$ is a convex hull of vectors in $\mathbb{R}^J$, it can be written as an intersection of half-planes. In other words, there exists a $J\times m$ matrix ${A}$ and an $m\times 1$ vector $\mathbf{b}$ such that:
\begin{equation}
    \widetilde{U} = \left\{\mathbf{x} \in \mathbb{R}^J \: : \: A\mathbf{x}\leq \mathbf{b}\right\}
\end{equation}

This means that we can rewrite $\mathbf{R}_{\widetilde{U}}$ as the solution to the following program:
\begin{align*}
    d_J(\widetilde{U},\mathbf{v}) = \min_{\mathbf{u}\in \mathbb{R}^J} &||\mathbf{v}-\mathbf{u}||_2\\
    \text{such that: } &A\mathbf{u}\leq \mathbf{b}
\end{align*}

Suppose that for a given $\mathbf{v}$, the constraints in a subset of rows $K$ of $A$ are binding and the rest are nonbinding. Then (for that $\mathbf{v}$) the solution can be written as:
\begin{align*}
    d_J(\widetilde{U},\mathbf{v}) = \min_{\mathbf{u}\in \mathbb{R}^J} &||\mathbf{v}-\mathbf{u}||_2\\
    \text{such that: } &A_i\mathbf{u}= {b}_i,\quad \forall \quad i\in K
\end{align*}

\noindent This is simply the  projection of $\mathbf{v}$ onto a linear subspace and is therefore a linear operator. Define $\mathbf{P}_{K,\widetilde{U}}$ as the linear projection operator onto this subspace.
$$ d_J(\widetilde{U},\mathbf{v}) = \left|\left|\left(\mathbf{P}_{K,\widetilde{U}}-\mathbf{I}\right)\mathbf{v}\right|\right|_2 $$

\noindent Consider $\widehat{\theta} \in \mathbb{R}$. If $\widehat{\theta} $ is sufficiently close to ${\theta}$, then by the continuity of the constraints and KKT conditions, the projections of to $\widehat{\theta} $ and $\theta $ will have the same set of binding constraints $K$. Therefore, \begin{align*}
   d_J(\widetilde{U},\widehat{\theta} )&= \left|\left|\left(\mathbf{P}_{K,\widetilde{U}}-\mathbf{I}\right)\left(\theta+\widehat{\theta}-\theta\right)\right|\right|_2\\
    \left|d_J(\widetilde{U},\widehat{\theta} )- \left|\left|\left(\mathbf{P}_{K,\widetilde{U}}-\mathbf{I}\right)\left(\widehat{\theta}-\theta\right)\right|\right|_2\right|&\leq d_J(\widetilde{U},\theta)
\end{align*}

Now let $\theta_2 \equiv \argmin_{\mathbf{u}\in\widetilde{U}} ||\mathbf{u}-\widehat{\theta}||$.  Notice that $d_J(\widetilde{U},\widehat{\theta}_2)=0$.  Let $\widehat{\theta}_2 \equiv \theta_2+\mathbf{e}$ where $\mathbf{e}$ has the same distribution as $\left(\widehat{\theta}-\theta\right)$.  For large enough $n$, $\widehat{\theta}_2,\theta$ are both close enough to $\theta$ so that they can be represented with the same linear projection $\mathbf{P}_{K,\widetilde{U}}$. 
\begin{align*}
       d_J(\widetilde{U},\widehat{\theta}+\mathbf{P}_{\widetilde{U}}\mathbf{e}) = \left|\left|\left(\mathbf{P}_{K,\widetilde{U}}-\mathbf{I}\right)\mathbf{e}\right|\right|_2
\end{align*}

Since $\mathbf{e}$ has the same distribution as $\left(\widehat{\theta}-\theta\right)$: $
    \mathbb{P}\left[ d_J(\widetilde{U},\widehat{\theta}_2) > x+\epsilon\right] \leq \mathbb{P}\left[d_J(\widetilde{U},\widehat{\theta} )> x\right]$ $ \forall x\in \mathbb{R} $


\subsection{Lemma \ref{lem:bound_coeffs} and Proof}\label{proof:lem:bound_coeffs}
\begin{lemma}\label{lem:bound_coeffs}
    $$| \langle \chi_j,\pi\rangle_X|\leq \frac{1}{\sqrt{2\pi}}\qquad \forall {j\in\mathbb{N},\pi \in \mathcal{F}_{\infty},||\pi||_1=1} $$

   % Proof: Section \ref{proof:lem:bound_coeffs}
\end{lemma}


\noindent Proof: Converting from probabalist's Hermite polynomials $He_j$ to  physicist's polynomials $H_j$: \begin{align*}
    \langle \chi_j,\pi_0\rangle_W&\leq |||\chi_j\varphi||_\infty||\pi_0||_1 \leq \sup_{t\in\mathbb{R}}\left|\chi_j(t)\varphi(t)\right| =\sup_{t\in\mathbb{R}}He_j(t)e^{-t^2/2}/(\sqrt{2\pi j!})\\
     &=\sup_{t\in\mathbb{R}} H_j(t/\sqrt{2})2^{-j/2}e^{-t^2/2}/\sqrt{2\pi j!}
\end{align*}

\noindent From \cite{HermiteBound}, the physicist's Hermite polynomials are bounded by:
    $|H_j(t/\sqrt{2})| \leq (2^j j!)^{1/2}e^{t^2/4}$. 
\begin{align*}
    \left|H_j(t/\sqrt{2})\right|2^{-j/2}e^{-t^2/2}/\sqrt{2\pi j!} &\leq (2^j j!)^{1/2}e^{t^2/4}2^{-j/2}e^{-t^2/2}/\sqrt{2\pi j!}=e^{-t^2/4}/\sqrt{2\pi}\leq \frac{1}{\sqrt{2\pi}}
\end{align*}

\subsection{Proof of Detectability of Example \ref{ex:minimiztion}}\label{proof:ex:minimization}

 First we compute the characteristic function of $T|R$. Here $T|R$ is equal to $h$ plus the maximum of two correlated standard normals with covariance $\rho$. The max of two correlated standard normals is equivalent in distribution to the sum of a normal with variance $\rho$ and the maximum of two independent normals each with variance $1-\rho$. Furthermore, the identity with the identity $\max\{A,B\}=\frac{A+B + |A-B|}{2}$ guarantees that maximum of two independent normals of variance $1-\rho$ is equal in distribution to the sum of a normal with variance $\frac{1-\rho}{2}$ and the absolute value of a normal of the same variance. So by the convolution theorem, the characteristic function of $T|R$ is: 
\begin{align*}
     \phi_{T|R}(t) &=\phi_h(t)\phi_{\sqrt{\rho} Z}(t)\phi_{\sqrt{1-\rho}\max\{Z_1,Z_2\}}(t)\\
     &= \phi_h(t)\phi_{\sqrt{\rho} Z}(t)\phi_{\sqrt{1-\rho}/2(Z_1+Z_2)}(t)\phi_{\sqrt{1-\rho}/2|Z_1-Z_2|}(t)\\
     &= \phi_h(t)e^{-\rho t^2/2}e^{-\frac{1-\rho}{2}t^2/2}e^{-\frac{1-\rho}{2}t^2/2}2\Phi\left(i(1-\rho)t\right)\\
     &=\phi_h(t)e^{- t^2/2}2\Phi\left(i(1-\rho)t\right) 
\end{align*}

  %\phi_{M}(t)$$

 %   where $\phi_M(t)$ is the characteristic function of the maximum of two independent normals with mean zero and variance $1-\rho$. The expression for $\phi_M(t)$  can be computed with the identity $\max\{A,B\}=\frac{A+B + |A-B|}{2}$ and the convolution theorem: $$\phi_M(t)=\exp\left(-\frac{(1-\rho) t^2}{2}\right)2\Phi\left(it\sqrt{\frac{1-\rho}{2}}\right)$$
%\left[1 + \operatorname{erf}\left(i t \sqrt{\frac{(1-\rho)}{4}}\right)\right]$$

$p$-hacking is detectable if and only if $e^{t^2/2}\phi_{T|R}$ is a valid characteristic function:
\begin{align*}
    e^{t^2/2}\phi_{T|R}(t) &= 
 2\phi_h(t)\Phi\left(it\sqrt{\frac{1-\rho}{2}}\right)
\end{align*}
When will this be a valid CF? If $\phi_h(t)$ is a convolution of any distribution $D$ with a normal of variance at least $2(1-\rho)$, then $ e^{t^2/2}\phi_{T|R}(t)$ is the characteristic function of the convolution of $D$ with a folded normal of variance $\frac{1-\rho}{2}$ and $p$-hacking is undetectable.  If instead $\phi_h$ decays slower than the modulus of $\Phi\left(it\sqrt{\frac{1-\rho}{2}}\right)$ grows, then $ e^{t^2/2}\phi_{T|R}(t)$  is not a valid characteristic function and $p$-hacking is detectable. Since the modulus of $\Phi\left(it\sqrt{\frac{1-\rho}{2}}\right)$ grows faster than $e^{t^2/2}$, if $\phi_h$ decays slowly (e.g. if it places any probability mass at any point including zero), then $p$-hacking is detectable.


