    \centering
    \caption{The $\mathcal{O}(p^4)$ ChPT predictions of the slope $\dot{\Theta}^\pi(0)$ at various pion masses.}
    \begin{tabular}{l | cccc}
    \hline\hline
        $m_\pi$ & 140~MeV & 239~MeV & 283~MeV & 391~MeV \\ \hline
        $\dot{\Theta}^\pi(0)$ & $0.98(2)$ & $0.96(3)$ & $0.96(4)$ & $0.97(7)$ \\
    \hline\hline
