where
\begin{align}
    A(\vb{r})=&\Delta_a^{~\mu}\sigma^a(-i\sigma^2)(-i\partial_\mu)\notag\\
    =&(\cos n\theta~\sigma^3+i\sin n\theta)(-i\partial_1)\notag\\
    &+(\sin n\theta~\sigma^3-i\cos n\theta)(-i\partial_2)\notag\\
    \equiv&A_1(\vb{r})+A_2(\vb{r})
