    &-i\frac{n\partial_2\theta}{2}(\cos n\theta~\sigma^3+i\sin n\theta)\notag\\
    \equiv&B_1(\vb{r})+B_2(\vb{r}).
\end{align}
From $\Delta^\dagger=-\Delta^*$, we have the following equalities,
\begin{align}
    \begin{pmatrix}
