    \begin{pmatrix}
        0 & A_2(\vb{r})\\
        -A_2^*(\vb{r}) & 0
    \end{pmatrix}
    &=\gamma^0\gamma^a\Delta_a^{~2}(-i\partial_2),\\
    \begin{pmatrix}
        0 & B_1(\vb{r})\\
        -B_1^*(\vb{r}) & 0
    \end{pmatrix}
