\section{Useful lemmas}

\begin{lemma}\label{lemma:extended_real_eff_incres}
\rm Consider any $n \geq 1$, $\bs{z} \in \{ 0, 1 \}^{n}$ and $\bs{y}, \bs{y'} \in \overline{\mathbb{R}}^{n}$ such that:
\begin{align*}
\begin{cases*}
    y_i \leq y_i', \quad \text{if $z_i = 1$}, \\
    y_i \geq y_i', \quad \text{if $z_i = 0$},
\end{cases*}
\end{align*}
where $\overline{\mathbb{R}} \coloneqq \mathbb{R}\cup \{\pm \infty\}$ denotes the extended real line. Then, for any test statistic defined in \eqref{eq:test_stat_R_phi} and \eqref{eq:test_stat_mann_whitney}: $t_{\R, \phi}\left( \bs{z}, \bs{y} \right) \leq t_{\R, \phi}\left( \bs{z}, \bs{y'} \right)$.
\end{lemma}

\begin{lemma}\label{lemma:rand_inf_valid_composite}
\rm Under the CRE and Assumption \ref{asmp:general}, 
the following $p$-values are valid for testing the sharp null hypothesis $H_{\bs{\delta}}$ in \eqref{eq:null_fisher_sharp} is 
\begin{align*}
    p_{\bs{Z}, \bs{\delta}} = G_{\R, \phi}\left(t_{\R, \phi}(\bs{Z}, \bs{Y}^{\sta}(0)) \right), \quad p_{\bs{Z}, \bs{\delta}, b}^{\star} = G_{\R, \phi}\left( t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}_b^{\sta}(0) \right) \right),
\end{align*}
where $t_{\R, \phi}$ is defined in either \eqref{eq:test_stat_R_phi} or \eqref{eq:test_stat_mann_whitney}, 
$G_{\R, \phi}$ is defined in
\eqref{eq:G_R_phi}, 
$\bs{Y}^{\sta}(0)$ is defined in \eqref{eq:imputation}, and $\tilde{\bs{Y}}_b^{\sta}(0)$ is defined in Example~\ref{eg:test_outcome_miss}. That is, under $H_{\bs{\delta}}$,
\begin{align*}
    \mathbb{P}\left( p_{\bs{Z}, \bs{\delta}} \leq \alpha \right) \leq \alpha, \quad \mathbb{P}\left( p_{\bs{Z}, \bs{\delta}, b}^{\star} \leq \alpha \right) \leq \alpha,
\end{align*}
for any $\alpha \in (0, 1)$ and for any $b \in \mathbb{R}$.
\end{lemma}

\begin{lemma}\label{lemma:inf_quan_m}
\rm    Consider any $\bs{z}, \bs{m} \in \{0,1\} ^n$ and $\bs{y}\in \overline{\mathbb{R}}^n$ such that 
    \begin{align*}
        y_i  \in 
        \begin{cases}
           \mathbb{R}, & \text{if } m_i = 1, \\
            \{\pm \infty \}, & \text{if } m_i = 0. 
        \end{cases}
    \end{align*}    
    Let 
    $\mathcal{N}_{11} := \{j:z_j=m_j=1\}$, and $n_{11} = |\mathcal{N}_{11}|$. 
    Sort the elements in $\mathcal{N}_{11}$ and denote it by $\mathcal{N}_{11} = \{ j_1, j_2, \ldots, j_{n_{11}} \}$, such that 
    $\rank_{j_1}(\bs{y}) < \rank_{j_2}(\bs{y}) < \ldots < \rank_{j_{n_{11}}}(\bs{y})$. 
    For any integer $0\le L \le n_{11}$, $c\in \mathbb{R}$, and $\kappa >0$, let 
    \begin{align*}
        \mathcal{H}_{L} & := \left\{ \bs{\delta} \in \mathbb{R}^n: \sum_{i\in \mathcal{N}_{11}} \I(\delta_i > c) \le L \right\}, 
        \\
        \mathcal{A}_L & :=
        \begin{cases}
            \{j_{n_{11}-L+1}, j_{n_{11}-L+2}, \ldots, j_{n_{11}}\}, & \text{if } L \ge 1, \\
            \emptyset, & \text{otherwise}, 
        \end{cases}
        \\
        \gamma & = \max\{y_i: z_i=m_i=1, 1\le i \le n\} - \min\{y_i: z_i = 0, m_i=1, 1\le i \le n\} + \kappa, 
    \end{align*}
    and 
    \begin{align*}
        \bs{\eta}_L = (\eta_{L,1}, \eta_{L,2}, \ldots, \eta_{L,n})^\top 
        \ \ \text{ with } \ \ 
         \eta_{L, i} = 
        \begin{cases}
            \gamma, & \text{if } i \in \mathcal{A}_L, \\
            c, & \text{otherwise}. 
        \end{cases}
    \end{align*}
    We then have, for any integer $0\le L \le n_{11}$ and $c\in \mathbb{R}$, 
    \begin{align*}
        \inf_{\bs{\delta} \in \mathcal{H}_{L}} 
        t_{\R, \phi}(\bs{z}, \bs{y} - \bs{z}\circ\bs{m}\circ \bs{\delta})
        = 
        t_{\R, \phi}\left( \bs{z}, \bs{y} - \bs{z}\circ\bs{m}\circ \bs{\eta}_L \right). 
    \end{align*}
\end{lemma}

\section{Proofs}\label{appx_sec:proof}

\begin{proof}[Proof of Theorem \ref{thm:sharp_null_gen}] Under CRE and $H_{\bs{\delta}}$ in \eqref{eq:null_fisher_sharp}, for $Y_i^{\sta}(0)$ and $Y_{\bs{Z}, \bs{\delta}, i}^{\gen}(0)$, where $1 \leq i \leq n$:
\begin{align*}
Y_i^{\sta}(0) = \begin{cases}
    Y_i - \delta_i \quad &\text{if $Z_i = 1$, $M_i = 1$} \\
    Y_i^{\sta} - \delta_i \quad &\text{if $Z_i = 1$, $M_i = 0$} \\
    Y_i \quad &\text{if $Z_i = 0$, $M_i = 1$} \\
    Y_i^{\sta} \quad &\text{if $Z_i = 0$, $M_i = 0$},
\end{cases} \quad 
Y_{\bs{Z}, \bs{\delta}, i}^{\gen}(0) = \begin{cases}
        Y_{i} - \delta_{i} &\quad \text{if $Z_{i} = 1$, $M_{i} = 1$} \\
        -\infty &\quad \text{if $Z_{i} = 1$, $M_{i} = 0$} \\
        Y_{i} &\quad \text{if $Z_{i} = 0$, $M_{i} = 1$} \\
        \infty &\quad \text{if $Z_{i} = 0$, $M_{i} = 0$}, \\
    \end{cases}
\end{align*}

Therefore, under CRE and the $H_{\bs{\delta}}$ in \eqref{eq:null_fisher_sharp}, for $Y_{\bs{Z}, \bs{\delta}, i}^{\gen}(0)$ and $Y_i^{\sta}(0)$, where $1 \leq i \leq n$:
\begin{align*}
\begin{cases*}
    Y_{\bs{Z}, \bs{\delta}, i}^{\gen}(0) \leq Y_i^{\sta}(0), \quad \text{if $Z_i = 1$}, \\
    Y_{\bs{Z}, \bs{\delta}, i}^{\gen}(0) \geq Y_i^{\sta}(0), \quad \text{if $Z_i = 0$}.
\end{cases*}
\end{align*}
Lemma \ref{lemma:extended_real_eff_incres} then implies that $t_{\R, \phi}\left(\bs{Z}, \bs{Y}_{\bs{Z}, \bs{\delta}}^{\gen}(0) \right) \leq t_{\R, \phi}\left(\bs{Z}, \bs{Y}^{\sta}(0) \right)$.

Because tail probability is nonincreasing, we have 
\begin{align*}
    p_{\bs{Z}, \bs{\delta}} = G_{\R, \phi}(t_{\R, \phi}\left(\bs{Z}, \bs{Y}^{\sta}(0) \right)) \leq G_{\R, \phi}\left( t_{\R, \phi}\left(\bs{Z}, \bs{Y}_{\bs{Z}, \bs{\delta}}^{\gen}(0) \right) \right) = p_{\bs{Z}, \bs{\delta}}^\gen,
\end{align*}
where $p_{\bs{Z}, \bs{\delta}}$ is a valid p-value for testing against the sharp null hypothesis $H_{\bs{\delta}}$ in \eqref{eq:null_fisher_sharp} by Lemma~\ref{lemma:rand_inf_valid_composite}. Now, the desired result follows immediately.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:sharp_null_gen_comp}] Under CRE, when $Z_i = 0$, for $\tilde{Y}_{\bs{Z},\bs{\delta}, b, i}^{\gen}(0)$ and $\tilde{Y}_{b, i}^\sta(0)$:
\begin{align*}
\tilde{Y}_{b, i}^\sta(0) &= \begin{cases}
    Y_i \times 1 + b \times (1 - 1) \quad &\text{if $Z_i = 0$ and $M_i = 1$} \\
    Y_i^{\sta} \times 0 + b \times (1 - 0) \quad &\text{if $Z_i = 0$ and $M_i = 0$}
\end{cases} = \begin{cases}
    Y_i \quad &\text{if $Z_i = 0$ and $M_i = 1$} \\
    b \quad &\text{if $Z_i = 0$ and $M_i = 0$}
\end{cases} \\
&= \tilde{Y}_{\bs{Z},\bs{\delta}, b, i}^{\gen}(0).
\end{align*}

Under the sharp null hypothesis $H_{\bs{\delta}}$ in \eqref{eq:null_fisher_sharp}, when $Z_i = 1, M_i = 0$, for $\tilde{Y}_{\bs{Z},\bs{\delta}, b, i}^{\gen}(0)$ and $\tilde{Y}_{b, i}^\sta(0)$:
\begin{align*}
    -\infty = \tilde{Y}_{\bs{Z},\bs{\delta}, b, i}^{\gen}(0) \leq \tilde{Y}_{b, i}^\sta(0).
\end{align*}

Under the sharp null hypothesis $H_{\bs{\delta}}$ in \eqref{eq:null_fisher_sharp}, when $Z_i = 1, M_i = 1$, for $\tilde{Y}_{b, i}^\sta(0)$:
\begin{align*}
\tilde{Y}_{b, i}^\sta(0) &= \begin{cases}
    (Y_i - \delta_{i}) \times 1 + b \times (1 - 1) \quad &\text{if $Z_i = 1$, $M_i = 1$, and $M_i(0) = 1$} \\
    (Y_i - \delta_{i}) \times 0 + b \times (1 - 0) \quad &\text{if $Z_i = 1$, $M_i = 1$, and $M_i(0) = 0$}
\end{cases} \\
&= \begin{cases}
    Y_i - \delta_{i} \quad &\text{if $Z_i = 1$, $M_i = 1$, and $M_i(0) = 1$} \\
    b \quad &\text{if $Z_i = 1$, $M_i = 1$, and $M_i(0) = 0$},
\end{cases} \\
&\geq \min\{ Y_i - \delta_i, b \} = \tilde{Y}_{\bs{Z},\bs{\delta}, b, i}^{\gen}(0).
\end{align*}

Therefore, under the sharp null hypothesis $H_{\bs{\delta}}$ in \eqref{eq:null_fisher_sharp}, for $\tilde{\bs{Y}}_{\bs{Z},\bs{\delta}, b}^{\gen}(0), \tilde{\bs{Y}}_b^{\sta}(0)$:
\begin{align*}
\begin{cases*}
    \tilde{Y}_{\bs{Z},\bs{\delta}, b, i}^{\gen}(0) \leq \tilde{Y}_{b, i}^\sta(0), \quad \text{if $Z_i = 1$}, \\
    \tilde{Y}_{\bs{Z},\bs{\delta}, b, i}^{\gen}(0) \geq \tilde{Y}_{b, i}^\sta(0), \quad \text{if $Z_i = 0$}.
\end{cases*}
\end{align*}
Lemma \ref{lemma:extended_real_eff_incres} then implies that $t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}_{\bs{Z},\bs{\delta}, b}^{\gen}(0) \right) \leq t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}_b^{\sta}(0) \right)$. Because the tail probability is nonincreasing:
\begin{align*}
    p_{\bs{Z}, \bs{\delta}, b}^{\star} = G_{\R, \phi}\left(t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}_b^{\sta}(0) \right)\right) \leq G_{\R, \phi}\left( t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}_{\bs{Z},\bs{\delta}, b}^{\gen}(0) \right) \right) = \tilde{p}_{\bs{Z}, \bs{\delta}, b}^\gen,
\end{align*}
where $p_{\bs{Z}, \bs{\delta}, b}^{\star}$ is a valid p-value for testing against the sharp null hypothesis $H_{\bs{\delta}}$ in \eqref{eq:null_fisher_sharp} by Lemma~\ref{lemma:rand_inf_valid_composite}. Now, the desired result follows immediately.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:sharp_null_mon}] Following an identical argument in Theorem \ref{thm:sharp_null_gen_comp}, under the CRE and Assumption \ref{asmp:mo_miss_M1_ge_M0} or \ref{asmp:mo_miss_M1_le_M0}, when $Z_i = 0$:
\begin{align*}
    \tilde{Y}^{\monp}_{\bs{Z}, \bs{\delta}, b, i}(0) = \tilde{Y}^{\monn}_{\bs{Z}, \bs{\delta}, b, i}(0) = \tilde{Y}_{b, i}^\sta(0) = \begin{cases}
    Y_i \quad &\text{if $Z_i = 0$ and $M_i = 1$} \\
    b \quad &\text{if $Z_i = 0$ and $M_i = 0$.}
\end{cases}
\end{align*}

Under the sharp null hypothesis $H_{\bs{\delta}}$ in \eqref{eq:null_fisher_sharp} and Assumption \ref{asmp:mo_miss_M1_ge_M0}, when $Z_i = 1$ and $M_i = 1$, because $M_{i}(1) = 1$ does not provide information about $M_{i}(0)$, by an identical argument in Theorem \ref{thm:sharp_null_gen_comp}, we conclude that
\begin{align*}
    \tilde{Y}^{\monp}_{\bs{Z}, \bs{\delta}, b, i}(0) = \min\{ Y_i - \delta_i, b \} \leq \tilde{Y}_{b, i}^\sta(0).
\end{align*}

Under the sharp null hypothesis $H_{\bs{\delta}}$ and Assumption \ref{asmp:mo_miss_M1_ge_M0}, $Z_i = 1$ and $M_i = 0$ (i.e., $M_{i}(1) = 0$) implies that $M_{i}(0) = 0$, which further implies:
\begin{align*}
    \tilde{Y}_{b, i}^\sta(0) = Y_i^{\sta}(0) \times 0 + b \times (1 - 0) = b = \tilde{Y}^{\monp}_{\bs{Z}, \bs{\delta}, b, i}(0).
\end{align*}

Under the sharp null hypothesis $H_{\bs{\delta}}$ and Assumption \ref{asmp:mo_miss_M1_le_M0}, $Z_i = 1$ and $M_i = 1$ (i.e., $M_{i}(1) = 1$) implies that $M_{i}(0) = 1$. Combined with the sharp null hypothesis  $H_{\bs{\delta}}$ in \eqref{eq:null_fisher_sharp} this further implies:
\begin{align*}
    \tilde{Y}_{b, i}^\sta(0) = (Y_i - \delta_i) \times 1 + b \times (1 - 1) = Y_i - \delta_i = \tilde{Y}^{\monn}_{\bs{Z}, \bs{\delta}, b, i}(0).
\end{align*}

Under the sharp null hypothesis $H_{\bs{\delta}}$ and Assumption \ref{asmp:mo_miss_M1_le_M0}, when $Z_i = 1$ and $M_i = 0$, it is easy to see that
\begin{align*}
    \tilde{Y}^{\monn}_{\bs{Z}, \bs{\delta}, b, i}(0) = - \infty \leq \tilde{Y}_{b, i}^\sta(0).
\end{align*}

Therefore, under CRE and the sharp null hypothesis $H_{\bs{\delta}}$ in \eqref{eq:null_fisher_sharp}:
\begin{align*}
\begin{cases*}
    \tilde{Y}^{\mon \square}_{\bs{Z}, \bs{\delta}, b, i}(0) \leq \tilde{Y}_{b, i}^\sta(0), \quad \text{if $Z_i = 1$}, \\
    \tilde{Y}^{\mon \square}_{\bs{Z}, \bs{\delta}, b, i}(0) \geq \tilde{Y}_{b, i}^\sta(0), \quad \text{if $Z_i = 0$},
\end{cases*}
\end{align*}
where $\square = $ p under Assumption \ref{asmp:mo_miss_M1_ge_M0} and $\square =$ n under Assumption \ref{asmp:mo_miss_M1_le_M0}.

Lemma \ref{lemma:extended_real_eff_incres} then implies that $t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}_{\bs{Z},\bs{\delta}, b}^{\mon \square}(0) \right) \leq t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}_b^{\sta}(0) \right)$. Because the tail probability is nonincreasing,
\begin{align*}
    p_{\bs{Z}, \bs{\delta}, b}^{\star} = G_{\R, \phi}\left(t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}_b^{\sta}(0) \right)\right) \leq G_{\R, \phi}\left( t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}_{\bs{Z},\bs{\delta}, b}^{\mon \square}(0) \right) \right) = \tilde{p}_{\bs{Z}, \bs{\delta}, b}^{\mon \square},
\end{align*}
where $p_{\bs{Z}, \bs{\delta}, b}^{\star}$ is a valid p-value for testing against the sharp null hypothesis $H_{\bs{\delta}}$ in \eqref{eq:null_fisher_sharp} by Lemma~\ref{lemma:rand_inf_valid_composite}. Now, the desired result follows immediately.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:sharp_null_mon_two_step}] First, note that 
if $\sum_{i=1}^n M_i(0)\le \hat{M}$, then 
\begin{align*}
    \sum_{i=1}^n Z_iM_i\{1-M_i(0)\}
    & = n_{11} - \sum_{i:Z_i=1, M_i = 1} M_i(0) = n_{11} + n_{01} - \sum_{i=1}^n M_i(0) \\
    & \ge n_{11} + n_{01} - \hat{M} \coloneqq \underline{m},
\end{align*}
where the second equality uses Assumption \ref{asmp:mo_miss_M1_ge_M0} and the fact that $n_{01} = \sum_{i = 1}^{n}(1 - Z_{i}) M_{i}(0)$. 

We now minimize the test statistic of the form in \eqref{eq:test_stat_mann_whitney} under $H_{\bs{\delta}}$ and Assumption \ref{asmp:mo_miss_M1_ge_M0}. Consider a treated unit $i$ and a control unit $j$, we have:
\begin{align*}
    \psi_{i,j}( \tilde{Y}^\sta_{\infty,i}(0), \tilde{Y}^\sta_{\infty,j}(0) ) &= \psi_{i,j}( Y_i^\sta(0) M_i(0) +  \infty \{1-M_i(0)\}, Y_j M_j +  \infty (1-M_j) ) \\
    & = 
    (1-M_i) \cdot \psi_{i,j}( \infty, Y_j M_j +  \infty (1-M_j) ) \\ 
    & \quad + 
    M_i \{1-M_i(0)\} \psi_{i,j}( \infty, Y_j M_j +  \infty (1-M_j) ) \\
    & \quad \ + 
    M_i M_i(0) \cdot \psi_{i,j}( Y_i - \delta_i, Y_j M_j +  \infty (1-M_j) ) \\
    &= M_i \{1-M_i(0)\} \cdot \Delta_{ij} + (1-M_i) A_{ij} + M_i B_{ij},
\end{align*}
where the second equality uses Assumption \ref{asmp:mo_miss_M1_ge_M0} and $H_{\bs{\delta}}$, and the third equality uses the facts that $A_{ij} \coloneqq  \psi_{i,j}( \infty, Y_j M_j +  \infty (1-M_j) )$, $B_{ij} \coloneqq \psi_{i,j}( Y_i - \delta_i, Y_j M_j +  \infty (1-M_j) )$, and $\Delta_{ij} \coloneqq A_{ij} - B_{ij} \ge 0$.

After some algebraic manipulation, we can verify that:
\begin{align*}
    t_{\R, \phi}\left( \bs{Z}, \tilde{\bs{Y}}^\sta_{\infty}(0) \right)  & = \sum_{i:Z_i=1}\phi\left( \sum_{j:Z_j=0} \psi_{i, j}( \tilde{Y}^\sta_{\infty,i}(0), \tilde{Y}^\sta_{\infty,j}(0) ) \right) 
    \\
    & = \sum_{i:Z_i=1,M_i=0}\phi(A_i) + 
    \sum_{i:Z_i=1, M_i = 1} \phi(B_i) + 
    \sum_{i:Z_i=1, M_i = 1} \{1-M_i(0)\} D_i, 
\end{align*}
where $A_{i}$, $B_{i}$, and $D_{i}$ are defined in Algorithm \ref{alg:mp_two_step_sharp}.

Then, it follows immediately that under the constraint that $\sum_{i=1}^n Z_i M_i \{1-M_i(0)\} \ge \underline{m}$:
\begin{align*}
    t_{\R, \phi}\left( \bs{Z}, \tilde{\bs{Y}}^\sta_{\infty}(0) \right)  
    & = \sum_{i:Z_i=1,M_i=0}\phi(A_i) + 
    \sum_{i:Z_i=1, M_i = 1} \phi(B_i) + 
    \sum_{i:Z_i=1, M_i = 1} \{1-M_i(0)\} D_i
    \\
    & \ge 
    \sum_{i:Z_i=1,M_i=0}\phi(A_i) + 
    \sum_{i:Z_i=1, M_i = 1} \phi(B_i) + 
    \sum_{i=1}^{\underline{m}} D_{l_i} \\
    &= t_{\R, \phi}\left( \bs{Z}, \tilde{\bs{Y}}_{\bs{Z}, \bs{\delta}, \infty}^{\monp, \underline{m}}(0) \right).
\end{align*}

We now show that $\tilde{p}_{\bs{Z}, \bs{\delta}, +\infty}^{\monp, \text{two-step}}$ is a valid p-value. To see this:
\begin{align*}
    & \quad \ \Pr\left( \tilde{p}_{\bs{Z}, \bs{\delta}, +\infty}^{\monp, \text{two-step}} \le \alpha \right)
    \\
    &\quad = 
    \Pr\left( \tilde{p}_{\bs{Z}, \bs{\delta}, +\infty}^{\monp, \text{two-step}} \le \alpha, \sum_{i=1}^n M_i(0) \le \hat{M} \right) + \Pr\left( \tilde{p}_{\bs{Z}, \bs{\delta}, +\infty}^{\monp, \text{two-step}} \le \alpha, \sum_{i=1}^n M_i(0) > \hat{M} \right) \\
    &\quad \le \Pr\left( G_{\R, \phi}\left( t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}^{\monp, \underline{m}}_{\bs{Z}, \bs{\delta},\infty}(0) \right) \right) \le \alpha - \beta, \sum_{i=1}^n M_i(0) \le \hat{M} \right)  + 
    \Pr\left( \sum_{i=1}^n M_i(0) > \hat{M} \right) \\
    &\quad \le 
    \Pr\left( G_{\R, \phi}\left( t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}^\sta_{\infty}(0) \right) \right) \le \alpha - \beta \right) + 
    \Pr\left( \sum_{i=1}^n M_i(0) > \hat{M} \right) \\
    &\quad \le \alpha - \beta + \beta = \alpha, 
\end{align*}
where the first inequality holds by the construction of Algorithm \ref{alg:mp_two_step_sharp}, the second inequality follows the fact that $G_{\R, \phi}\left( t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}^\sta_{\infty}(0) \right) \right) \leq G_{\R, \phi}\left( t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}^{\monp, \underline{m}}_{\bs{Z}, \bs{\delta},\infty}(0) \right) \right)$.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:p_t_kc_genmon}] Define $\check{\bs{Y}}^{\square} = (\check{Y}_1^{\square}, \check{Y}_2^{\square}, \ldots, \check{Y}_n^{\square} )$ for $\square = \gen, \monp, \monn$ in the following way: 
\begin{align*}
    \check{Y}_i^{\gen} 
    = 
    \begin{cases}
        Y_i, & \text{if } Z_i = 1, M_i=1, \\
        -\infty,  & \text{if } Z_i = 1, M_i=0,  \\
        Y_i,   & \text{if } Z_i = 0, M_i=1, \\
        \infty  & \text{if } Z_i = 0, M_i=0, 
    \end{cases}
    \quad 
    \check{Y}_i^{\monp} 
    = 
    \begin{cases}
        Y_i, & \text{if } Z_i = 1, M_i=1, \\
        \infty,  & \text{if } Z_i = 1, M_i=0,  \\
        Y_i,   & \text{if } Z_i = 0, M_i=1, \\
        \infty  & \text{if } Z_i = 0, M_i=0, 
    \end{cases}
\end{align*}
and 
\begin{align*}
    \check{Y}_i^{\monn} 
    = 
    \begin{cases}
        Y_i, & \text{if } Z_i = 1, M_i=1, \\
        -\infty,  & \text{if } Z_i = 1, M_i=0,  \\
        Y_i,   & \text{if } Z_i = 0, M_i=1, \\
        -\infty  & \text{if } Z_i = 0, M_i=0, 
    \end{cases}
    \qquad (1\le i \le n).  
\end{align*}
If the null hypothesis $H_{k,c}^\texttt{t}$ holds (i.e., $\bs{\tau} \in \mathcal{H}_{k,c}^\texttt{t}$), then:
\begin{equation}\label{eq:p_val_gen_mon}
 \check{p}^{\square} \coloneqq G_{\R, \phi}\left( \inf_{\bs{\delta}\in \mathcal{H}^{\texttt{t}}_{k,c} }t_{\R, \phi}\left(\bs{Z}, \check{\bs{Y}}^\square - \bs{Z}\circ\bs{M}\circ\bs{\delta} \right) \right) 
 \ge 
     G_{\R, \phi}\left( t_{\R, \phi}\left(\bs{Z}, \check{\bs{Y}}^\square - \bs{Z}\circ\bs{M}\circ\bs{\tau} \right)\right).
\end{equation}
By definition and from Theorems \ref{thm:sharp_null_gen_comp} and \ref{thm:sharp_null_mon}, 
$
    G_{\R, \phi}\left( t_{\R, \phi}\left(\bs{Z}, \check{\bs{Y}}^\square - \bs{Z}\circ\bs{M}\circ\bs{\tau} \right)\right)
$
is stochastically larger than or equal to the uniform distribution on $(0,1)$. This implies that $\check{p}$ is a valid p-value for testing  $H_{k,c}^\texttt{t}$. 

Note that the value of $\bs{\delta}$ in \eqref{eq:p_val_gen_mon} only matters for units in $\{i:M_i=Z_i=1\}$. 
Recall that $n_{11} = |\{i:M_i=Z_i=1\}|$. 
We can verify that 
\begin{align*}
    \inf_{\bs{\delta}\in \mathcal{H}^{\texttt{t}}_{k,c} }t_{\R, \phi}\left( \bs{Z}, \check{\bs{Y}}^\square - \bs{Z}\circ\bs{M}\circ\bs{\delta} \right)
    = \inf_{\bs{\delta}\in \mathcal{H}_L} t_{\R, \phi}\left( \bs{Z}, \check{\bs{Y}}^\square - \bs{Z}\circ\bs{M}\circ\bs{\delta} \right),
\end{align*}
where $L = \min\{ n_1 - k, n_{11}\}$ and $\mathcal{H}_L \coloneqq \{\bs{\delta} \in \mathbb{R}^n: \sum_{i=1}^n \I(Z_i=M_i=1)\I(\delta_i > c) \le L \}$. 
We can then use Lemma \ref{lemma:inf_quan_m} to solve this optimization. 
Specifically, from Lemma  \ref{lemma:inf_quan_m}, we have 
\begin{align*}
    \inf_{\bs{\delta}\in \mathcal{H}_L }t_{\R, \phi}\left(\bs{Z}, \check{\bs{Y}}^\square - \bs{Z}\circ\bs{M}\circ\bs{\delta} \right)
    = t_{\R, \phi}\left(\bs{Z}, \check{\bs{Y}}^\square - \bs{Z}\circ\bs{M}\circ\bs{\xi}_{k,c} \right), 
\end{align*}
where $\bs{\xi}_{k,c}$ is defined as in \eqref{eq:xi_kc}. 

From the above and by definition, we can verify that 
\begin{align*}
    \tilde{p}_{\texttt{t}, k, c}^{\square} & = 
    G_{\R, \phi}\left( t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}^{\square}_{\texttt{t}, k, c}(0)  \right)\right)
    =
    G_{\R, \phi}\left( t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}_{\bs{Z},\bs{\xi}_{k,c}}^{\square}(0)  \right)\right) \\
    & = 
    G_{\R, \phi}\left( t_{\R, \phi}\left(\bs{Z}, \check{\bs{Y}}^\square - \bs{Z}\circ\bs{M}\circ\bs{\xi}_{k,c} \right) \right)\\
    & = G_{\R, \phi}\left( \inf_{\bs{\delta}\in \mathcal{H}^{\texttt{t}}_{k,c} }t_{\R, \phi}\left(\bs{Z}, \check{\bs{Y}}^\square - \bs{Z}\circ\bs{M}\circ\bs{\delta} \right) \right) 
    = \check{p}^{\square}.
\end{align*}
Therefore, $\tilde{p}_{\texttt{t}, k, c}^{\square}$ a valid p-value for testing  $H_{k,c}^\texttt{t}$.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:ci_genmon_treat}] From the proof of Theorem \ref{thm:p_t_kc_genmon}, 
for $\square = \gen, \monp$ or $\monn$, 
\begin{align}\label{eq:p_kc_square_equiv}
    \tilde{p}_{\texttt{t}, k, c}^{\square}  =
    G_{\R, \phi}\left( 
    \inf_{\bs{\delta} \in \mathcal{H}^{\texttt{t}}_{k,c}}
    t_{\R, \phi}\left(\bs{Z}, \check{\bs{Y}}^\square - \bs{Z}\circ\bs{M}\circ\bs{\delta}  \right)
    \right). 
\end{align}
Because the set $\mathcal{H}^{\texttt{t}}_{k,c}$ increases with $c$, we can know that the p-value $\tilde{p}_{\texttt{t}, k, c}^{\square}$ is nondecreasing in $c$. Thus, the interval $\mathcal{I}^{\alpha}_{\texttt{t}, k}$ must be a one-sided interval for form $[\hat{\tau}_{\texttt{t}(k)}, \infty)$ or $(\hat{\tau}_{\texttt{t}(k)}, \infty)$, with $\hat{\tau}_{\texttt{t}(k)} = \inf \mathcal{I}^{\alpha}_{\texttt{t}, k}$.  

Below we prove the simultaneous validity of the prediction intervals $\mathcal{I}^{\alpha}_{\texttt{t}, k}$s, for $1\le k \le n_1$. Suppose that $\tau_{\texttt{t}(k)} \notin \mathcal{I}^{\alpha}_{\texttt{t}, k}$ for some $1\le k \le n_1$. By definition, this implies that $\tilde{p}_{\texttt{t}, k, c}^{\square} \le \alpha$ when $c = \tau_{\texttt{t}(k)}$. By definition, $\bs{\tau} \in \mathcal{H}^{\texttt{t}}_{k,c}$ when $c = \tau_{\texttt{t}(k)}$. From \eqref{eq:p_kc_square_equiv}, we then have, for $c = \tau_{\texttt{t}(k)}$,
\begin{align*}
    \alpha &\ge \tilde{p}_{\texttt{t}, k, c}^{\square} 
    = G_{\R, \phi}\left( 
    \inf_{\bs{\delta} \in \mathcal{H}^{\texttt{t}}_{k,c}}
    t_{\R, \phi}\left(\bs{Z}, \check{\bs{Y}}^\square - \bs{Z}\circ\bs{M}\circ\bs{\delta}  \right)
    \right) \\
    &\ge 
    G_{\R, \phi}\left( 
    t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}^{\square}_{\bs{Z}, \bs{\tau}}(0)  \right)
    \right)
    \ge 
    G_{\R, \phi}\left( 
    t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}^{\sta}_{b}(0)  \right)
    \right), 
\end{align*}
where the last inequality follows from the proof of Theorems \ref{thm:sharp_null_gen_comp} and \ref{thm:sharp_null_mon}, 
and $b$ equals $\infty$ when $\square = \gen, \monp$ and $-\infty$ when $\square = \monn$. 
Thus, we have 
\begin{align*}
    \mathbb{P}\left( \tau_{\texttt{t}(k)} \notin \mathcal{I}^{\alpha}_{\texttt{t}, k} \text{ for some } 1\le k \le n_1 \right) 
    \le 
    \Pr \left( 
    G_{\R, \phi}\left( 
    t_{\R, \phi}\left(\bs{Z}, \tilde{\bs{Y}}^{\sta}_{b}(0)  \right)
    \right) \le \alpha \right)
    \le \alpha,
\end{align*}
where the last inequality follows from Lemma \ref{lemma:rand_inf_valid_composite}. 
\end{proof} 

