\subsection{Reaction-diffusion dynamics of labeled molecules in a ternary mixture}
Combining Eq.\eqref{eq:rr*} and \eqref{eq:j_multiAB}, we obtain the equations governing the reaction-diffusion dynamics for the labeled molecules of the two species
 \begin{subequations}\label{eq:effective_rate_AB}
\begin{align}\label{eq:effective_rate_A}
\partial_\mathrm{t}\phi_A^*
=&%k_\mathrm{B}T \,
\nabla\cdot\left[D_{A}\left(\nabla \phi_A^*-\phi_A^*\frac{\nabla\phi_A}{\phi_A}\right)-\phi_A^*\frac{\boldsymbol{j}_A}{\phi_A}\right]\\\nonumber
&-r_+\frac{\phi_A^*}{\phi_A}+r_-\frac{\phi_B^*}{\phi_B}\, ,\\\label{eq:effective_rate_B}
% \phi_A^*\frac{\boldsymbol{j}_A}{\phi_A}\right]-\frac{r^_{A\to B}}{\phi_A}\phi_A^*+\frac{r^-_{A\to B}}{\phi_B}\phi_B^*\, ,
\partial_\mathrm{t}\phi_B^*
=&%k_{B}T \,
\nabla\cdot\left[D_{B}\left(\nabla \phi_B^*-\phi_B^*\frac{\nabla\phi_B}{\phi_B}\right)-\phi_B^*\frac{\boldsymbol{j}_B}{\phi_B}\right]\\\nonumber
&-r_-\frac{\phi_B^*}{\phi_B}+r_+\frac{\phi_A^*}{\phi_A}\, ,
% \phi_B^*\frac{\boldsymbol{j}_B}{\phi_B}\right]-\frac{r^-_{A\to B}}{\phi_B}\phi_B^*+\frac{r^+_{A\to B}}{\phi_A}\phi_A^*\, .
%\label{eq:effective_rate_B}
\end{align}
\end{subequations}
where the dynamics of $\phi_A$ and $\phi_B$ is described by \eqref{eq:cont_AB}.
These expressions are the first main results of the paper.


 \section{Stochastic description of single molecules}
  Equations~\eqref{eq:effective_rate_AB} describe the reaction-diffusion dynamics of the labeled molecules. Taking the limit where only a small number of molecules are labeled, we can interpret Eqs.~\eqref{eq:effective_rate_AB} as describing the evolution of the probability density of having a single labeled molecule of species $A$ ($B$) in position $x$ at time $t$: $P_\alpha(x,t)=\phi_\alpha^*/\int \phi_\alpha^*dx$ where $\alpha$ is either $A$ or $B$.
% \begin{align}
%     P_A(x,t)=\frac{\phi_A^*}{\int \phi_A^*dx}\qquad P_B(x,t)=\frac{\phi_B^*}{\int \phi_B^*dx}\,.
% \end{align}
The probabilities $P_A(x,t)$ and $P_B(x,t)$ obey the Fokker-Planck equations 
\begin{subequations}\label{eq:FPAB}
\begin{align}\label{eq:FPA}
\partial_t P_A &= -\nabla\cdot\left( \VEC{v}_A P_A- D_A\nabla P_A\right) +K_-P_B-K_+P_A \\\label{eq:FPB}
\partial_t P_B &= -\nabla\cdot \left(\VEC{v}_B P_B- D_B\nabla P_B\right)+K_+P_A-K_-P_B\,.
\end{align} 
\end{subequations}
Here, $\VEC{v}_A$ and $\VEC{v}_B$ are the single-molecule deterministic drift velocities if the tracked molecule has the chemical identity $\alpha=A,\,B$,
\begin{align}\label{eq:vAB}
    \VEC{v}_\alpha(x,t)=&-\frac{D_\alpha}{k_BT} \nabla W_\alpha + \frac{\VEC{j}_\alpha}{\phi_\alpha}\,,
%    \\\nonumber
%    \VEC{v}_B=&-\frac{D_B}{k_BT} \nabla W_B + \frac{\VEC{j}_B}{\phi_B}
\end{align}
where the first term is driven by the gradient of the corresponding effective potential $ W_\alpha(x,t)=-k_BT\ln\phi_\alpha$,
% \begin{align}\label{eq:W}
%   W_\alpha(x,t)=-k_BT\ln\phi_\alpha \,,
% \end{align}
which takes into account the overall effect of the intermolecular forces that can lead to phase separation~\cite{Bo2021a}.
The second term in Eq.~(\ref{eq:vAB}) is due to the non-equilibrium volume-fraction flux $\VEC{j}_\alpha$ defined in Eq.~(\ref{eq:j}).
$D_\alpha$ is the single-molecule diffusion coefficient of species $\alpha$, given in Eq.~(\ref{eq:DAB}), which can depend on composition.
Finally,
\begin{align}\label{eq:K}
    K_+(x,t)=\frac{r_+}{\phi_A}\qquad \qquad  K_-(x,t)=\frac{r_-}{\phi_B}
\end{align}
are the single-molecule reaction rates transforming species $A$ into $B$ and $B$ into $A$, respectively (see Ref. \cite{gillespie1992rigorous}). These rates depend on composition as they are influenced by intermolecular interactions.
Importantly, and at variance with the dilute case,  the ratio of the rates $K^{eq}_+/K^{eq}_-=\phi_B^{eq}/\phi_A^{eq}$ satisfies the equilibrium condition only at equilibrium concentrations. %, which is, in that case, independent of composition.
The stochastic process described by the Fokker-Planck equation~(\ref{eq:FPAB}) can also be described by the coupled (Ito) Langevin equations for molecular trajectories
\begin{subequations}\label{eq:langevin}
\begin{align}\label{eq:langevin_x}
    d\VEC{x}&=\VEC{v}(\sigma,\,\VEC{x})dt+\nabla D(\sigma,\,\VEC{x})dt+\sqrt{2D(\sigma,\VEC{x})}\;d\VEC{w}\,\\\label{eq:langevin_sigma}
    d\sigma&=d\eta_+(\sigma,x)-d\eta_-(\sigma,x)
\end{align}
\end{subequations}
where $\VEC{x}(t)$ is the stochastic time-dependent position of a tracked molecule. The stochastic variable $\sigma(t)$, which only takes discrete values $\sigma=0,\,1$, describes the instantaneous chemical state of the molecule. Here $0$ and $1$ represent chemical species $A$ and $B$, respectively.
The drift velocity  $\VEC{v}(\sigma_t,x_t)=\VEC{v}_A\delta_{\sigma_t,0}+\VEC{v}_B\delta_{\sigma_t,1}$ and the diffusion coefficient $D(\sigma_t,x_t)=D_A\delta_{\sigma_t,0}+D_B\delta_{\sigma_t,1}$ depend on position $x$ and on the chemical state $\sigma$.
Molecular noise is described by the stochastic variables $\VEC{w}$, $\eta_+$ and $\eta_-$.  The Gaussian white noise $\VEC{w}$ vanishes on average ($ \langle d\VEC{w}_t\rangle=0$), its fluctuations during a time increment $dt$  
satisfy $\langle dw^i dw^j\rangle=dt\delta_{ij}$ %$\langle\xi_\alpha(t)\xi_\beta(t')\rangle=\delta(t-t')\delta_{\alpha\beta}$ ().
% \begin{align}
%     \langle dw^\alpha dw^\beta\rangle=dt\delta_{\alpha\beta}\,,
% \end{align}
and $d\VEC{w}$ at different times are uncorrelated. The indices
$i,\,j$ correspond to the spatial coordinates \cite{Gardiner1985}.
The chemical noise is a Poisson process that only takes increments $d\eta^\pm=0,\,1$ with average $ \langle d\eta^+\rangle=K_+\delta_{\sigma_t,0}dt$, $\langle d\eta^-\rangle=K_-\delta_{\sigma_t,1}dt$
% \begin{align}
%     \langle d\eta^+\rangle=K_+\delta_{\sigma_t,0}dt\qquad \langle d\eta^-\rangle=K_-\delta_{\sigma_t,1}dt
% \end{align}
during a time increment $dt$, set by the rates rates $K_+$ and $K_-$.
% It describes the increments of the point process obeyed by the chemical reactions, which occur with rates $K_+$ and $K_-$.
The coupled Langevin equations describe the particle dynamics as it diffuses, subject to the deterministic drift and as it switches between chemical states $A$ and $B$. An example of these trajectories is shown in Fig.~\ref{fig:intro}c.
 The multiplicative noise is taken in the Ito discretization and $\nabla D$ is the associated noise-induced drift.
