\section{Free energy, exchange chemical potentials and reaction rates for a ternary mixture}%: explicit expressions}
The free energy density for a ternary mixture reads
% \begin{align}\label{eq:free_energy_compactAB}
% f =&\frac{k_BT}{\nu}(\phi_A\ln\phi_A  + 
% \phi_B\ln\phi_B+
% \frac{\nu}{\nu_0}\phi_0\ln\phi_0)\\\nonumber
% &+\chi_{AB}\phi_A\phi_B +
% \chi_{A0}\phi_A\phi_0 +
% \chi_{B0}\phi_B\phi_0 \\\nonumber
% &+\omega^0_A\phi_A\,+
% \omega^0_B\phi_B\,+
% \omega^0_0\phi_0\, ,
% \end{align}
\begin{align}\label{eq:free_energy_compactAB}
f =\frac{k_BT}{\nu}(\phi_A\ln\phi_A  + 
\phi_B\ln\phi_B+
\frac{\nu}{\nu_0}\phi_0\ln\phi_0)+\chi_{AB}\phi_A\phi_B +
\chi_{A0}\phi_A\phi_0 +
\chi_{B0}\phi_B\phi_0 +\omega^0_A\phi_A\,+
\omega^0_B\phi_B\,+
\omega^0_0\phi_0\, ,
\end{align}
where $\phi_0=1-\phi_A-\phi_B$ is implied, $\chi_{\alpha\beta}$ denotes the interaction parameter, $\nu_0$ is the molecular volume of the solvent and $\omega^0_\alpha$ are the internal free energy densities for the components. 
The exchange chemical potential $\mu_\alpha=\nu_\alpha \delta F/\delta \phi_\alpha$ is computed from the free energy of the ternary mixture which is defined in  Eqs.~\eqref{eq:free_energyAB}, \eqref{eq:free_energy_compactAB}, and reads
\begin{align}\label{eq:chem_potAB}
\mu_A&=k_BT\ln  \left( \phi_0^{-\frac{\nu}{\nu_0}} \phi_A \right)+\nu \left[
-2\chi_{A0}\phi_A +
(\chi_{AB}-\chi_{A0}-\chi_{B0}) \phi_B 
\right] + \omega_A - \kappa_A \nabla^2 \phi_A \\\nonumber
\mu_B&=k_BT \ln  \left( \phi_0^{-\frac{\nu}{\nu_0}} \phi_B \right)+\nu \left[
-2\chi_{B0}\phi_B +
(\chi_{AB}-\chi_{A0}-\chi_{B0}) \phi_A 
\right] + \omega_B - \kappa_B \nabla^2 \phi_B
\, ,
\end{align}
where  $\omega_\alpha$ are composition-independent reference chemical potentials:
% given in Eq.~\eqref{eq:reference_muAB}.

% The composition-independent reference chemical potentials follow from taking the derivative of the free energy given in Eq.~\eqref{eq:free_energyAB} and read
\begin{align}\label{eq:reference_muAB}
\omega_A =& k_BT\left(1- \frac{\nu}{\nu_0}\right) + \nu\chi_{A0} + \nu\left( \omega_A^0-  \omega_0^0 \right)\\\nonumber
\omega_B =& k_BT\left(1- \frac{\nu}{\nu_0}\right) + \nu\chi_{B0} + \nu\left( \omega_B^0-  \omega_0^0 \right)\,,
\end{align}
which we assume to be constant in space.
We consider systems obeying detailed balance so that the ratio of the reaction rates is set by the differences in chemical potentials between reagent and product species, as defined in Eq.~\eqref{eq:detailed_balance} in the main text. The reaction ratio then reads
\begin{align}\label{eq:r_ratio}
    \frac{r_+}{r_-}=e^{\frac{\mu_A-\mu_B}{k_B T}}=\frac{\phi_A}{\phi_B}\exp{\left[\frac{1}{k_BT}\left(\nu\lambda_\chi(\phi_A,\phi_B)+\omega_A-\omega_B
    +\lambda_\kappa
    \right)
    \right]}
\end{align}
where we have defined
\begin{align}\label{eq:lambda_chi}
    \lambda_\chi (\phi_A,\phi_B)=\chi_{AB}(\phi_B-\phi_A)+\left(\chi_{B0}-\chi_{A0}\right)(\phi_A+\phi_B)\,,
\end{align}
as the difference in chemical potentials due to the interactions $\chi$ and
\begin{align}\label{eq:lambda_kappa}
    \lambda_\kappa (\phi_A,\phi_B)=
    - \kappa_A \nabla^2 \phi_A+ \kappa_B \nabla^2 \phi_B\,.
\end{align}
The individual rates can be obtained from the definitions of Eq.~\eqref{eq:reaction_ratesAB}, and that of the chemical potentials \eqref{eq:chem_potAB}
\begin{align}\label{eq:r_explicit}
   r_+&=k\frac{\phi_A}{\phi_0}\exp{\left[\frac{1}{k_BT}\left(\nu \left(
-2\chi_{A0}\phi_A +
\tilde{\chi} \phi_B 
\right)+\omega_A
    - \kappa_A \nabla^2 \phi_A
    \right)
    \right]}\\\nonumber
    r_-&=k\frac{\phi_B}{\phi_0}\exp{\left[\frac{1}{k_BT}\left(\nu \left(
-2\chi_{B0}\phi_B +\tilde{\chi}\phi_A 
\right)+\omega_B
    - \kappa_B \nabla^2 \phi_B
    \right)
    \right]}\,.
\end{align}
where we have defined
\begin{align}\label{eq:chitilde}
    \tilde{\chi}\equiv\chi_{AB}-\chi_{B0}-\chi_{A0}\,.
\end{align}


The fluxes of volume fractions are driven by gradients in the chemical potential [See Eq.~(\ref{eq:j})]. Using the explicit expression for the mobility provided in Eq.~(\ref{eq:MAB}), the fluxes read
\begin{align}\label{eq:jAB_app}
    \boldsymbol{j}_A=&-\left[m_{A0}\phi_A\phi_0\nabla\mu_A+m_{AB}\phi_A\phi_B\nabla(\mu_A-\mu_B)
    \right]\\\nonumber
    \boldsymbol{j}_B=&-\left[m_{B0}\phi_B\phi_0\nabla\mu_B+m_{AB}\phi_A\phi_B\nabla(\mu_B-\mu_A)\right]\,.
\end{align}
These expressions for the fluxes can be used to define the collective diffusion matrix $D^{\text{col}}$ via
\begin{align}\label{eq:D_col}
     \boldsymbol{j}_\alpha=-\sum_\beta D^{\text{col}}_{\alpha\beta}\nabla \phi_\beta\,.
\end{align}
\section{Labeled molecules}\label{app:labeled}
Labeling molecules changes the entropy of the mixtures since our ability to distinguish them increases the number of possible configurations. We assume that labeling does not modify the interactions between molecules or their internal energy. With these assumptions, the free energy density reads:
\begin{align}\label{eq:free_energy_compactAB_labeled}
\tilde{f} =&\frac{k_BT}{\nu}(\phi_A^*\ln\phi_A^*  +
\overline{\phi}_A\ln\overline{\phi}_A+
\phi_B^*\ln\phi_B^*+
\overline{\phi}_B\ln\overline{\phi}_B+
\frac{\nu}{\nu_0}\phi_0\ln\phi_0)\\\nonumber
&+\chi_{AB}\phi_A\phi_B +
\chi_{A0}\phi_A\phi_0 +
\chi_{B0}\phi_B\phi_0 +\omega^0_A\phi_A\,+
\omega^0_B\phi_B\,+
\omega^0_0\phi_0\, .
\end{align}

