\section{Reference chemical potential and exchange activity coefficient}\label{app:mu}
Making explicit the definition of $\phi_0$ we get
\begin{align}\label{eq:free_energy_expanded}
%f =k_BT\sum_{i=0}^n\frac{\phi_\alpha}{\nu_\alpha}\ln\phi_\alpha  + 
f =k_BT\sum_{i=1}^n\frac{\phi_\alpha}{\nu_\alpha}\ln\phi_\alpha  + \frac{k_BT}{\nu_0}\left(1-\sum_{i=1}^n\phi_\alpha\right)\ln\left(1-\sum_{i=1}^n\phi_\alpha\right)+
\sum_{i=1}^n\sum_{j=1}^n\frac{\chi_{\alpha\beta}}{2}\phi_\alpha\phi_\beta+\left(1-\sum_{i=1}^n\phi_\alpha\right)\sum_{i=1}^n\chi_{i0}\phi_\alpha +\sum_{i=0}^n\omega^0_\alpha\phi_\alpha\, .
\end{align}
The chemical potential $\mu_\alpha=\nu_\alpha \delta F/\delta \phi_\alpha$ reads
\begin{align}
\mu_\alpha = k_B T \ln  \left( \phi_\alpha \phi_0^{-\nu_\alpha/\nu_0} \right) + 1-\frac{\nu_\alpha}{\nu_0}  - \kappa_\alpha \nabla^2 \phi_\alpha  
+ \nu_\alpha \sum_{j=1}^n  (\chi_{\alpha\beta}-\chi_{i0}-\chi_{j0}) \phi_\beta
+ \nu_\alpha\chi_{i0} + \nu_\alpha\left( \omega_\alpha^0-  \omega_0^0 \right) 
\end{align}
and the composition independent terms define the reference chemical potential (see {\it e.g.}, \cite{Bauermann2022a})
\begin{align}\label{eq:reference_mu}
\omega_\alpha = 1- \frac{\nu_\alpha}{\nu_0} + \nu_\alpha\chi_{i0} + \nu_\alpha\left( \omega_\alpha^0-  \omega_0^0 \right)\,.
\end{align}
