    \lambda= 1: & \Psi(e_1)=e_1+\alpha_{1} e_2+\alpha_{2} e_3,& \Psi(e_2)=\alpha_{3} e_2+\alpha_{5} e_3,& \Psi(e_3)=\alpha_{4} e_3 + \alpha_{6} e_2.\\[1mm]
\end{array}$$

\textbf{Case {$\lambda \neq1$}.}
 Considering $f-ad_a$ for $a = \beta_4e_1 -\beta_2e_2 - \frac{\beta_3}{\lambda} e_3,$ instead of $f$, we can easily conclude that Lie affgebra over $\mathbf{r}_3(1)$ is isomorphic to one with
\begin{equation}\label{eqfg8}
 \begin{array}{lll}
  f(e_1)=\beta_{1} e_1, &   f(e_2)=0, & f(e_3)=\beta_{5} e_3,\\[1mm]
    g(e_1)=\beta_{1} e_1, & g(e_2)=\beta_{1} e_2, & g(e_3)=\beta_{1} e_3.
\end{array}
\end{equation}

Thus, for any elements $x=\xi_1e_1 + \xi_2e_2 + \xi_3e_3$ and
$y=\eta_1e_1 + \eta_2 e_2 + \eta_3e_3,$ we obtain an affine Lie bracket
$$\{x, y\} = [x, y] + \beta_1 \eta_1e_1 + \beta_1 \xi_2e_2 +(\beta_1 \xi_3 + \beta_5 \eta_3 - \beta_5 \xi_3)e_3 + s,$$
where $s = N_1e_1+ N_2e_2+N_3e_3.$
Denote the Lie affgebra on the algebra $\mathbf{r}_3(\lambda)$ with this affine Lie bracket by $H(\beta_{1}, \beta_{5}, N_1, N_2, N_3).$



\begin{prop}\label{prop3.22}
     Two Lie affgebras $H(\beta_{1}, \beta_{5}, N_1, N_2, N_3)$ and
$H(\beta_{1}', \beta_{5}', N_1', N_2', N_3')$ are isomorphic if and only if there exist $\alpha_{1}, \alpha_{2}\in \mathbb{C},$ $\alpha_{3}, \alpha_{4} \in \mathbb{C}^*,$ such that
