\begin{prop} Any Lie affgebra structure on the algebra  $\mathbf{r}_3(\lambda)$ with $\lambda\neq 1,$ is isomorphic to one of the following pairwise non-isomorphic Lie affgebras:
$$\begin{array}{lll}
    H_1(\beta_{1},\beta_{5},N_1,0,0), &H_2(\beta_{1},\beta_{5},\beta_{1}(1-\beta_{1}),1,0),\\[1mm]
    H_3(\beta_{1},\beta_{5},\frac{(\beta_{1}-\beta_{5})(1-\beta_{1})} {\lambda},0,1), &
H_4(1,\beta_{5},0,1,1), \ \beta_5 \neq 1-\lambda,\\[1mm]
    H_5(\beta_{1},\beta_{1}(1-\lambda),\beta_{1}(1-\beta_{1}),1,1 ).
\end{array}$$
\end{prop}

\begin{proof} Using Proposition \ref{prop3.22}, we consider the following cases.
\begin{itemize}
    \item  $N_1\neq \beta_{1}(1-\beta_{1})$ and $N_1 \neq \frac{(\beta_{1}-\beta_{5})(1-\beta_{1})} {\lambda},$ then taking
    $\alpha_{1}=\frac{\alpha_{3} N_2}{\beta_{1}(1-\beta_{1}) - N_1},$ $\alpha_{2}=\frac{\alpha_{4} \lambda N_3}{(\beta_{1}-\beta_{5})(1-\beta_{1})-\lambda N_1},$ we get $N_2'=N_3'=0$ and obtain  the Lie affgebra    $H_1(\beta_{1},\beta_{5},N_1,0,0).$
    \item  $N_1= \beta_{1}(1-\beta_{1})$ and $N_1 \neq \frac{(\beta_{1}-\beta_{5})(1-\beta_{1})} {\lambda},$ then we have $\beta_1 \neq 1,$ $\beta_5 \neq \beta_1(1-\lambda)$ and taking
    $\alpha_{2}=\frac{\alpha_{4} \lambda N_3}{(\beta_{1}-\beta_{5})(1-\beta_{1})-\lambda N_1},$ we obtain $N_3'=0$ and $N_2'=\alpha_{3} N_2.$
    Thus, in the case of $N_2 =0,$ we obtain the Lie affgebra $H_1$ with $N_1= \beta_{1}(1-\beta_{1}).$ In the case of $N_2 \neq 0,$ we can get $N_2'=1$  and obtain the Lie affgebra $H_2(\beta_{1},\beta_{5},\beta_{1}(1-\beta_{1}),1,0).$

    \item  $N_1\neq \beta_{1}(1-\beta_{1})$ and $N_1 = \frac{(\beta_{1}-\beta_{5})(1-\beta_{1})} {\lambda},$ then taking
    $\alpha_{1}=\frac{\alpha_{3} N_2}{\beta_{1}(1-\beta_{1}) - N_1},$ we obtain $N_2'=0$ and $N_3'=\alpha_{4} N_3.$
    Thus, in the case of $N_3 =0,$ we obtain the affgebra $H_2$ with $N_1= \frac{(\beta_{1}-\beta_{5})(1-\beta_{1})} {\lambda}.$ In the case of $N_3 \neq 0,$ we can suppose $N_3'=1$  and obtain the affgebra $H_3(\beta_{1},\beta_{5},\frac{(\beta_{1}-\beta_{5})(1-\beta_{1})} {\lambda},0,1).$

    \item  $N_1= \beta_{1}(1-\beta_{1})$ and $N_1 = \frac{(\beta_{1}-\beta_{5})(1-\beta_{1})} {\lambda}.$ Then we have $\beta_1=1$ or $\beta_5 = \beta_1 (1-\lambda)$ and
$N_2'=\alpha_{3} N_2,$ $N_3'=\alpha_{4} N_3.$ If $N_2N_3=0,$ then we obtain one of the affgebras from $H_1, H_2, H_3.$ In the case of $N_2N_3\neq0,$ we can suppose $N_2'=N_3'=1$ and obtain the affgebras  $H_4(1,\beta_{5},0,1,1)$ and $H_5(\beta_{1},\beta_{1}(1-\lambda),\beta_{1}(1-\beta_{1}),1,1 ).$
\end{itemize}

\end{proof}


\textbf{Case {$\lambda =1$}.}
 Considering $f-ad_a$ for $a = \mu e_1 -\beta_2e_2 - \beta_3e_3,$ instead of $f$, we can easily conclude that Lie affgebra over $\mathbf{r}_3(\lambda)$ is isomorphic to one with
\begin{equation*}\label{eqfg8.1}
 \begin{array}{lll}
  f(e_1)=\beta_{1} e_1, &   f(e_2)=(\beta_{4} - \mu) e_2 + \beta_{6} e_3, & f(e_3)=\beta_{7} e_2+(\beta_{5}-\mu) e_3,\\[1mm]
    g(e_1)=\beta_{1} e_1, & g(e_2)=\beta_{1} e_2, & g(e_3)=\beta_{1} e_3.
\end{array}
\end{equation*}

By selecting $\mu$ as one of the eigenvalues of the matrix $\left(\begin{matrix} \beta_{4} & \beta_{6} \\ \beta_{7} & \beta_{5}\end{matrix}\right),$ without loss of generality we can assume that the matrix has a zero eigenvalue.

From the formulas $f' = \Psi (f - \operatorname{ad}_a) \Psi^{-1},$ and the general form of the automorphism $\Psi,$ it follows that the matrix of the operator $f'$ can be reduced to one of the following Jordan forms:
$$\left(\begin{matrix}\beta_1 & 0& 0 \\ 0&  0 & 0 \\ 0& 0 & \beta_{5}\end{matrix}\right), \quad \left(\begin{matrix}\beta_1 & 0& 0 \\ 0&  0 & \beta_6 \\ 0& 0 & 0\end{matrix}\right), \ \beta_6\neq0.$$

If the Jordan form of the matrix corresponds to the first case, then the situation is analogous to that of $\lambda \neq 1$ and we obtain the affgebras $H_1, H_2, H_3, H_4$ and $H_5$ with $\lambda=1.$


If the Jordan form of the matrix corresponds to the second case, then we get
\begin{equation}
 \begin{array}{lll}
  f(e_1)=\beta_{1} e_1, &   f(e_2)= \beta_{6} e_3, & f(e_3)=0,\\[1mm]
    g(e_1)=\beta_{1} e_1, & g(e_2)=\beta_{1} e_2, & g(e_3)=\beta_{1} e_3,
\end{array}
\end{equation}
and for any elements $x=\xi_1e_1 + \xi_2e_2 + \xi_3e_3,$
$y=\eta_1e_1 + \eta_2 e_2 + \eta_3e_3,$ we obtain an affine Lie bracket
$$\{x, y\} = [x, y] + \beta_1 \eta_1e_1 + \beta_1 \xi_2e_2 +(\beta_1 \xi_3 + \beta_6 \eta_2 - \beta_6 \xi_2)e_3 + s,$$
where $s = N_1e_1+ N_2e_2+N_3e_3.$
Denote the Lie affgebra on the algebra $\mathbf{r}_3(\lambda)$ with this affine Lie bracket by $K(\beta_{1}, \beta_{6}, N_1, N_2, N_3).$


\begin{prop}\label{prop3.222}
     Two Lie affgebras $K(\beta_{1}, \beta_{6}, N_1, N_2, N_3)$ and
$K(\beta_{1}', \beta_{6}', N_1', N_2', N_3')$ are isomorphic if and only if there exist $\alpha_{1}, \alpha_{2}\in \mathbb{C},$ $\alpha_{3}, \alpha_{4} \in \mathbb{C}^*,$  such that
$$\begin{array}{lllll}
    \beta_{1}'=\beta_{1} , & \beta_{6}'=\frac{\alpha_4 \beta_6}{\alpha_3}, & N_2'=\alpha_{3} N_2 + \alpha_{1}\big(N_1 -  \beta_{1}(1-\beta_{1})\big), \\
    N_1'= N_1, & & N_3'=\alpha_{4} N_3 + \alpha_{2}\big(N_1 -  \beta_{1}(1-\beta_{1})\big) + \alpha_5N_2
+\frac{\alpha_1 \alpha_4 \beta_6 (1-\beta_1)}{\alpha_3}.
\end{array}$$
\end{prop}



\begin{proof} The proof is straightforward and follows similarly to the proof of Proposition \ref{prop3.2}.
\end{proof}

\begin{prop} Any Lie affgebra from the class $K(\beta_{1}, \beta_{6}, N_1, N_2, N_3)$ is isomorphic to one of the following pairwise non-isomorphic Lie affgebras:
$$\begin{array}{lll}
    K_1(\beta_{1},1,N_1,0,0), &K_2(\beta_{1},1,\beta_{1}(1-\beta_{1}),1,0),& K_3(1,1,0,0,1).
\end{array}$$
\end{prop}

\begin{proof} By taking $\alpha_3= \alpha_4\beta_6,$ in Proposition \ref{prop3.222}, without loss of generality we may assume
$\beta_6=1$ and $\alpha_3=\alpha_4.$ We now consider the following cases:
\begin{itemize}
    \item  $N_1\neq \beta_{1}(1-\beta_{1}),$ then taking
    $\alpha_{1}=\frac{\alpha_{3} N_2}{\beta_{1}(1-\beta_{1}) - N_1},$ $\alpha_{2}=\frac{\alpha_{4} N_3 + \alpha_{5} N_2+ \alpha_1(1-\beta_1)}{\beta_{1}(1-\beta_{1}) - N_1},$ we get $N_2'=N_3'=0$ and obtain the affgebra
    $K_1(\beta_{1},1,N_1,0,0).$
    \item  $N_1= \beta_{1}(1-\beta_{1}),$ then $N_2'=\alpha_{4} N_2,$ $N_3'=\alpha_{4} N_3 + \alpha_5N_2
+\alpha_1 (1-\beta_1).$
    \begin{itemize}
    \item  If $N_2\neq 0,$ then choosing $\alpha_{4}=\frac{1} {N_2},$ $\alpha_{5}=-\frac{\alpha_{4} N_3
+\alpha_1 (1-\beta_1)} {N_2},$ we have $N_2'=1,$ $N_3'=0$ and obtain the affgebra $K_2(\beta_{1},1,\beta_{1}(1-\beta_{1}),1,0).$
    \item  If $N_2= 0,$ then $N_3'=\alpha_{4} N_3 +\alpha_1 (1-\beta_1).$ If $\beta_1\neq 1$ or $N_3=0,$ then by choosing appropriate values for $\alpha_1$ and $\alpha_4,$ we have $N_3'=0$ and obtain the affgebra $K_1$ with $N_1= \beta_{1}(1-\beta_{1}).$ If
 $\beta_1=1$ and $N_3\neq 0,$ then taking $\alpha_{4}=\frac{1} {N_3},$  we have $N_3'=1$ and obtain the affgebra $K_3(1,1,0,0,1).$
    \end{itemize}
\end{itemize}

\end{proof}

Summarizing the results for the cases $\lambda\neq 1$ and $\lambda=1,$ we obtain the following theorem.

\begin{thm} Any Lie affgebra structure on the algebra  $\mathbf{r}_3(\lambda)$ is isomorphic to one of the following pairwise non-isomorphic Lie affgebras:
$$\begin{array}{lll}
    H_1(\beta_{1},\beta_{5},N_1,0,0), &H_2(\beta_{1},\beta_{5},\beta_{1}(1-\beta_{1}),1,0),\\[1mm]
    H_3(\beta_{1},\beta_{5},\frac{(\beta_{1}-\beta_{5})(1-\beta_{1})} {\lambda},0,1), &
H_4(1,\beta_{5},0,1,1), \ \beta_5 \neq 1-\lambda,\\[1mm]
    H_5(\beta_{1},\beta_{1}(1-\lambda),\beta_{1}(1-\beta_{1}),1,1 ),
\end{array}$$
and
$$\begin{array}{lll}
    K_1(\beta_{1},1,N_1,0,0), &K_2(\beta_{1},1,\beta_{1}(1-\beta_{1}),1,0),& K_3(1,1,0,0,1).
\end{array}$$
\end{thm}

Note that in the case of $\lambda=1$, we have $H_2(\beta_{1},0,\beta_{1}(1-\beta_{1}),1,0) \simeq H_3(\beta_{1},0,\beta_{1}(1-\beta_{1}),0,1).$



\subsection{Lie affgebra structures on the algebra $\mathbf{r}_2 \oplus \mathbb{C}$}

First, we present the description of the pair of linear transformations
$(f,g),$ that satisfy condition \eqref{eqfg1}.

\begin{prop}
    Any linear transformations $f$ and $g$ of the algebra $\mathbf{r}_2 \oplus \mathbb{C},$ that satisfy condition \eqref{eqfg1} have the following form:
 $$\begin{array}{lll}
  f(e_1)=\beta_{1} e_1+\beta_{2} e_2+\beta_{3} e_3, &   f(e_2)=\beta_{4} e_2, & f(e_3)=\beta_{5} e_3,\\[1mm]
    g(e_1)=\beta_{1} e_1+\gamma_{1} e_3, & g(e_2)=\beta_{1} e_2+\gamma_{2} e_3, & g(e_3)=\gamma_{3} e_3.
\end{array}$$
\end{prop}

\begin{proof} The proof of the proposition follows directly from the straightforward verification.
\end{proof}

For any element $s= N_1e_1+N_2e_2+N_3e_3\in \mathbf{r}_2 \oplus \mathbb{C},$ a Lie affgebra structure is defined by the binary operation $$ \{x, y\} = [x, y] + g(x) + f(y-x) + s,$$
which is denoted by $X(\mathbf{r}_2 \oplus \mathbb{C}; g, f, s).$

Since any automorphism of the algebra $\mathbf{r}_2 \oplus \mathbb{C}$ has the form
\begin{center}
    $\Psi(e_1)=e_1+\alpha_{1} e_2+\alpha_{2} e_3,$ \quad
$\Psi(e_2)=\alpha_{3} e_2,$ \quad
$\Psi(e_1)=\alpha_{4} e_3,$
\end{center}
we obtain the following proposition.

\begin{prop}\label{pr3.5} Two Lie affgebras $X(\mathbf{r}_2 \oplus \mathbb{C}; g, f, s)$ and
$X\mathbf{r}_2 \oplus \mathbb{C}; g', f', s')$ are isomorphic if and only if there exist $\alpha_{1}, \alpha_{2}, C_1, C_2, C_3\in \mathbb{C}$ and  $\alpha_{3}, \alpha_{4} \in \mathbb{C}^*,$ such that
$$\begin{array}{lll}
    \beta_{1}'=\beta_{1}, &  \beta_{2}'=\alpha_{1}(\beta_{1}+\beta_{4}-C_1)+\alpha_{3} (\beta_{2} +C_2), & \beta_{3}'=\alpha_{2} (\beta_{1}-\beta_{5})+\alpha_{4}
 \beta_{3}, \\
 \beta_{5}'=\beta_{5}, & \beta_{4}'= \beta_{4} -C_1 , & \\
 \gamma_{3}'=\gamma_{3}, & \gamma_{1}'=\alpha_{2} (\beta_{1}-\gamma_{3})+\alpha_{4} (\gamma_{1}-\frac{\alpha_{1} \gamma_{2}}{\alpha_{3}}), & \gamma_{2}'=\frac{\alpha_{4} \gamma_{2}}{\alpha_{3}},
\end{array}$$
and
 $$\begin{array}{lll} N_1'= C_1 (1-\beta_{1}) +N_1, \\
 N_2'=\alpha_{1} (C_1 (1-\beta_{1}) +N_1) +\alpha_{3} (C_2 (1-\beta_{1}) +N_2), \\
 N_3'=\alpha_{2} (C_1 (1-\beta_{1}) +N_1) +\alpha_{4} (C_3 (1-\gamma_{3})+C_1 \gamma_{1} + C_2 \gamma_{2} +N_3).
 \end{array}$$
\end{prop}

\begin{proof} The proof is obtained by straightforward computation using Theorem\ref{thm_Aff2}.

\end{proof}

Choosing $C_1=\beta_{4}$ and
$C_2=-\frac{\alpha_{3} \beta_{2}+\alpha_{1} \beta_{1}}{\alpha_{3}}$ in Proposition \ref{pr3.5}, we obtain $\beta_{2}'= \beta_{4}'=0.$ Therefore, without loss of generality, we may assume $\beta_{2}= \beta_{4}=0,$ $C_1=0,$ $C_2=-\frac{\alpha_{1} \beta_{1}}{\alpha_{3}}.$ Hence, we derive the following restrictions:
\begin{equation}\label{eq3.1}\begin{array}{lll}
    \beta_{3}'=\alpha_{2} (\beta_{1}-\beta_{5})+\alpha_{4}
 \beta_{3}, &
 \gamma_{1}'=\alpha_{2} (\beta_{1}-\gamma_{3})+\alpha_{4} (\gamma_{1}-\frac{\alpha_{1} \gamma_{2}}{\alpha_{3}}), & \gamma_{2}'=\frac{\alpha_{4} \gamma_{2}}{\alpha_{3}},
\end{array}\end{equation}
and
 \begin{equation}\label{eq3.2}\begin{array}{lll} N_1'= N_1, \\
 N_2'=\alpha_{3} N_2 +\alpha_{1} \big( N_1 - \beta_1(1-\beta_{1})\big), \\
 N_3'=\alpha_{4}N_3 + \alpha_{2} N_1 +\alpha_{4} \big(C_3 (1-\gamma_{3})-\frac{\alpha_{1} \beta_{1}}{\alpha_{3}} \gamma_{2}\big).
 \end{array}\end{equation}

Hence, Lie affgebra structures on the algebra $\mathbf{r}_2 \oplus \mathbb{C}$  depend on the parameters $\beta_{1},\beta_{3}, \beta_{5}, \gamma_{1}, \gamma_{2}, \gamma_{3}, N_1, N_2, N_3.$
We denote this class of Lie affgebras by $$L(\beta_{1},\beta_{3}, \beta_{5}, \gamma_{1}, \gamma_{2}, \gamma_{3}, N_1, N_2, N_3).$$

\begin{thm} Any Lie affgebra structure on the algebra $\mathbf{r}_2 \oplus \mathbb{C}$ is isomorphic to one of the following
pairwise non-isomorphic Lie affgebras:
$$\begin{array}{lll}
L_1(\beta_{1},0,\beta_{5},0,1,\gamma_{3},N_1,0,0), &
L_2(\beta_{1},0,\beta_{5},0,1,\gamma_{3},N_1,1,0),\\[1mm]
L_3(\beta_{1},0,\beta_{5},0,1,1,N_1,N_2,1),&
L_4(\beta_{1},0,\beta_{5},0,0,\gamma_{3},N_1,0,0),\\[1mm]
L_5(\beta_{1},0,\beta_{5},1,0,\gamma_{3},N_1,0,0),&
L_6(\beta_{1},0,\beta_{5},\gamma_{1},0,1,N_1,0,1),\\[1mm]
L_7(\beta_{1},0,\beta_{5},0,0,\gamma_{3}, \beta_{1} (1-\beta_{1}),1,0),&
L_8(\beta_{1},0,\beta_{5},1,0,\gamma_{3}, \beta_{1} (1-\beta_{1}),1,0), \\[1mm]
L_9(\beta_{1},0,\beta_{5},\gamma_{1},0,1, \beta_{1} (1-\beta_{1}),1,1),&
L_{10}(\beta_{1},1,\beta_{1},0,1,\gamma_{3},N_1,0,0), \\[1mm]
L_{11}(\beta_{1},1,\beta_{1},0,1,\beta_{1},N_1,N_2,0), \beta_1\neq 1,&
L_{12}(\beta_{1},1,\beta_{1},0,1,\gamma_{3},\beta_{1}(1-\beta_{1}),N_2,0), \ \gamma_3 \neq 1,\\[1mm]
L_{13}(\beta_{1},1,\beta_{1},0,1,1,N_1,N_2,0),& L_{14}(\beta_{1},\beta_{3},\beta_{1},0,1,1,\beta_{1}(1-\beta_{1}),N_2,1),\\[1mm]
L_{15}(\beta_{1},1,\beta_{1},0,0,\gamma_{3},N_1,0,0),&
L_{16}(\beta_{1},\beta_{3},\beta_{1},1,0,\beta_{1},N_1,0,0), \ \beta_1 \neq 1,\\[1mm]
L_{17}(\beta_{1},\beta_{3},\beta_{1},1,0,1,N_1,0,0), &
L_{18}(\beta_{1},\beta_{3},\beta_{1},0,0,1,0,0,1), \\[1mm]
L_{19}(\beta_{1},1,\beta_{1},0,0,\gamma_{3},\beta_{1} (1-\beta_{1}),1,0),&
L_{20}(\beta_{1},\beta_{3},\beta_{1},1,0,\beta_{1},\beta_{1} (1-\beta_{1}),1,0), \ \beta_1\neq 1,\\[1mm]
L_{21}(\beta_{1},\beta_{3},\beta_{1},0,0,1,\beta_{1} (1-\beta_{1}),0,1),&
L_{22}(\beta_{1},\beta_{3},\beta_{1},0,0,1,\beta_{1} (1-\beta_{1}),1,1),\\[1mm]
L_{23}(1,\beta_{3},1,1,0,1,0,0,N_3),&
L_{24}(1,\beta_{3},1,1,0,1,0,1,N_3)
\end{array}$$
\end{thm}


\begin{proof}
Consider the following cases.
\begin{itemize}
    \item Let $\beta_{1} \neq \beta_{5}$ and $\gamma_{2} \neq 0,$ then taking $\alpha_{2} =\frac{\alpha_{4} \beta_{3}}{\beta_{5}-\beta_{1}},$ $\alpha_{4}=\frac{\alpha_{3}}{\gamma_{2}}$ and $\alpha_{1}=\alpha_{2}(\beta_{1}-\gamma_{3})+ \alpha_{4} \gamma_{1},$ we obtain $\beta_{3}'=0,$ $\gamma_{1}'=0,$  $\gamma_{2}'=1.$ Thus, we get that
    $N_2'=\alpha_{3} N_2,$ $ N_3'=\alpha_{3} (C_3 (1-\gamma_{3}) + N_3).$
        \begin{itemize}
            \item Let $\gamma_{3} \neq 1,$ then taking
            $C_3=\frac{N_3}{\gamma_{3}-1},$ we obtain  $N_3'=0.$
            Hence, we get the Lie affgebras $L_1(\beta_{1},0,\beta_{5},0,1,\gamma_{3},N_1,0,0)$ and $L_2(\beta_{1},0,\beta_{5},0,1,\gamma_{3},N_1,1,0)$ depending on whether $N_2 = 0$ or not.
            \item Let $\gamma_{3} = 1,$ then we get $N_2'=\alpha_{3} N_2,$ $N_3'=\alpha_{3} N_3.$
            \begin{itemize}
            \item If $N_3 \neq 0,$ then taking $\alpha_{3}=\frac{1}{N_3},$ we get $N_3'=1,$ and obtain the affgebra $L_3(\beta_{1},0,\beta_{5},0,1,1,N_1,N_2,1).$
            \item If $N_3 = 0,$ then we obtain the
            affgebras $L_1(\beta_{1},0,\beta_{5},0,1,1,N_1,0,0)$ and $L_2(\beta_{1},0,\beta_{5},0,1,1,N_1,1,0)$ depending on whether $N_2 = 0$ or not.
            \end{itemize}



        \end{itemize}


\item Let $\beta_{1} \neq \beta_{5}$ and $\gamma_{2} = 0,$ then $\gamma_{2}'=0$ and taking $\alpha_{2} =\frac{\alpha_{4} \beta_{3}}{\beta_{5}-\beta_{1}},$   we obtain $\beta_{3}'=0.$ Thus, we get that
    $$\gamma_{1}'=\alpha_{4} \gamma_{1}, \quad N_2'=\alpha_{1} (N_1 - \beta_{1} (1-\beta_{1}))+\alpha_{3} N_2, \quad N_3'=\alpha_{4} (C_3 (1-\gamma_{3})+N_3).$$

\begin{itemize}
        \item Let $N_1 \neq \beta_{1} (1-\beta_{1})$ and $\gamma_{3} \neq 1,$ then taking
            $\alpha_{1}=\frac{\alpha_{3} N_2}{\beta_{1} (1-\beta_{1}) -N_1},$ $C_3=\frac{N_3}{\gamma_{3}-1},$ we obtain     $N_2'=0,$ $N_3'=0$ and $\gamma_{1}'=\alpha_{4} \gamma_{1}.$ Thus, in this case we get the affgebras
             $L_4(\beta_{1},0,\beta_{5},0,0,\gamma_{3},N_1,0,0)$ and
              $L_5(\beta_{1},0,\beta_{5},1,0,\gamma_{3},N_1,0,0)$ depending on whether $\gamma_{1} = 0$ or not.
 \item Let $N_1 \neq \beta_{1} (1-\beta_{1})$ and $\gamma_{3} =1,$ then taking
            $\alpha_{1}=\frac{\alpha_{3} N_2}{\beta_{1} (1-\beta_{1})-N_1},$ we obtain  $N_2'=0,$ and $N_3'=\alpha_{4} N_3,$ $\gamma_{1}'=\alpha_{4} \gamma_{1}.$
            \begin{itemize}
               \item If $N_3=0,$ then $N'_3=0,$ and we get the affgebras
             $L_4(\beta_{1},0,\beta_{5},0,0,1,N_1,0,0)$ and
              $L_5(\beta_{1},0,\beta_{5},1,0,1,N_1,0,0)$ depending on whether $\gamma_{1} = 0$ or not.
              \item If $N_3\neq 0,$ then taking $\alpha_{4} = \frac 1{N_3},$ we get $N_3'=1$ and obtain the affgebra
              $L_6(\beta_{1},0,\beta_{5},\gamma_{1},0,1,N_1,0,1).$

            \end{itemize}
\item Let $N_1 = \beta_{1} (1-\beta_{1})$ and $\gamma_{3} \neq 1,$ then taking
            $C_3=\frac{N_3}{\gamma_{3}-1},$ we obtain $N_3'=0$ and $N_2'=\alpha_{3}N_2,$ $\gamma_{1}'=\alpha_{4} \gamma_{1}.$
           \begin{itemize}
               \item If $N_2=0,$ then $N'_2=0,$ and we get the affgebras
             $L_4(\beta_{1},0,\beta_{5},0,0,1,\beta_{1} (1-\beta_{1}),0,0)$ and
              $L_5(\beta_{1},0,\beta_{5},1,0,1,\beta_{1} (1-\beta_{1}),0,0)$ depending on whether $\gamma_{1} = 0$ or not.
              \item If $N_2\neq 0,$ then taking $\alpha_{3} = \frac 1{N_2},$ we get $N_2'=1$ and obtain the affgebras
              $L_7(\beta_{1},0,\beta_{5},0,0,\gamma_{3}, \beta_{1} (1-\beta_{1}),1,0)$ and $L_8(\beta_{1},0,\beta_{5},1,0,\gamma_{3}, \beta_{1} (1-\beta_{1}),1,0)$ depending on whether $\gamma_{1} = 0$ or not.
            \end{itemize}
\item Let $N_1 = \beta_{1} (1-\beta_{1})$ and $\gamma_{3} = 1,$ then we get $N_2'=\alpha_{3}N_2,$ $N_3'=\alpha_{4}N_3,$   $\gamma_{1}'=\alpha_{4} \gamma_{1}.$
        \begin{itemize}
               \item If $N_2=0,$ $N_3=0,$ then $N_2'=0,$ $N_3'=0,$ and we obtain the affgebras
               $L_4(\beta_{1},0,\beta_{5},0,0,1,\beta_{1} (1-\beta_{1}),0,0)$ and
              $L_5(\beta_{1},0,\beta_{5},1,0,1,\beta_{1} (1-\beta_{1}),0,0)$ depending on whether $\gamma_{1} = 0$ or not.
        \item If $N_2=0,$ $N_3\neq0,$ then $N_2'=0,$ and taking $\alpha_{4} = \frac 1{N_3},$ we get $N_3'=1.$ Thus, in this case we obtain the affgebra $L_6(\beta_{1},0,\beta_{5},\gamma_{1},0,1,\beta_{1} (1-\beta_{1}),0,1).$
        \item If $N_2\neq 0,$ $N_3=0,$ then $N_3'=0,$ and taking $\alpha_{3} = \frac 1{N_2},$ we get $N_2'=1.$ Thus, in this case, we obtain the affgebras $L_7(\beta_{1},0,\beta_{5},0,0,1, \beta_{1} (1-\beta_{1}),1,0),$ and
$L_8(\beta_{1},0,\beta_{5},1,0,1, \beta_{1} (1-\beta_{1}),1,0)$
depending on whether $\gamma_{1} = 0$ or not.
       \item If $N_2\neq 0,$ $N_3\neq0,$  taking $\alpha_{3} = \frac 1{N_2},$  $\alpha_{4} = \frac 1{N_3},$ we get $N_2'=N_3'=1.$  Hence, we get the affgebra $L_9(\beta_{1},0,\beta_{5},\gamma_{1},0,1, \beta_{1} (1-\beta_{1}),1,1).$
            \end{itemize}


\end{itemize}


    \item Let  $\beta_{1} = \beta_{5}$  and $\gamma_{2} \neq 0,$ then taking $\alpha_{1} =\alpha_{4} \gamma_{1} + \alpha_{2}( \beta_{1}-\gamma_{3})$ and
    $\alpha_{4} = \frac{\alpha_{3}}{\gamma_{2}},$
 we obtain   $\gamma_{1}'=0,$  $\gamma_{2}'=1.$
        Thus, without loss of generality, we may assume $\gamma_1=0,$ $\gamma_2=1,$ then $\alpha_{1} =\alpha_{2}( \beta_{1}-\gamma_{3}),$ $\alpha_{4} = \alpha_{3},$ and we have
    $$\beta_{3}'=\alpha_{3}\beta_{3},\quad N_2'=\alpha_{3} N_2+\alpha_{2} (\beta_{1}-\gamma_{3}) (N_1-\beta_{1}(1-\beta_{1})),$$ $$N_3'=\alpha_{3} (C_3 (1-\gamma_{3}) + N_3) + \alpha_{2} (N_1-\beta_{1}(\gamma_{3}-\beta_{1})) .$$

    \begin{itemize}
        \item Let $\gamma_{3} \neq 1$ and $(\beta_{1}-\gamma_{3})(N_1-\beta_{1}(1-\beta_{1}))\neq 0,$ then taking  $$C_3=\frac{ \alpha_{3}N_3+\alpha_{2} (N_1-\beta_{1}(\gamma_{3}-\beta_{1}))}{\alpha_{3}  (\gamma_{3}-1)},\quad \alpha_{2}=\frac{\alpha_{3} N_2}{(\gamma_{3}-\beta_{1}) (N_1-\beta_{1}(1-\beta_{1}))},$$ we obtain $N_2'=0,$ $N_3'=0$.
        \begin{itemize}
        \item If $\beta_{3}=0,$ then we get the affgebra
$L_1(\beta_{1},0,\beta_{1},0,1,\gamma_{3},N_1,0,0).$
\item If $\beta_{3}\neq 0,$ we get the affgebra
$L_{10}(\beta_{1},1,\beta_{1},0,1,\gamma_{3},N_1,0,0).$
\end{itemize}

\item Let $\gamma_{3} \neq 1$ and $(\beta_{1}-\gamma_{3})(N_1-\beta_{1}(1-\beta_{1}))= 0,$ then taking  $C_3=\frac{\alpha_{3}N_3+\alpha_{2} (N_1-\beta_{1}(\gamma_{3}-\beta_{1})}{\alpha_{3}  (\gamma_{3}-1)},$ we obtain $N_3'=0$. Thus,
we have  $\beta_{3}'=\alpha_{3} \beta_{3},$ and $N_2'=\alpha_{3} N_2.$

\begin{itemize}
        \item If $\beta_{3}=0,$ then we get the affgebras
$L_1(\beta_{1},0,\beta_{1},0,1,\gamma_{3},N_1,0,0)$
and $L_2(\beta_{1},0,\beta_{1},0,1,\gamma_{3},N_1,1,0)$
depending on whether $N_2=0$ or not.
\item If $\beta_{3}\neq 0,$ then we can suppose  $\beta_{3}'=1,$ and obtain the affgebras
$L_{11}(\beta_{1},1,\beta_{1},0,1,\beta_{1},N_1,N_2,0)$ and
$L_{12}(\beta_{1},1,\beta_{1},0,1,\gamma_{3},\beta_{1}(1-\beta_{1}),N_2,0).$
    \end{itemize}

 \item Let $\gamma_{3} = 1$ and $N_1\neq \beta_{1}(1-\beta_{1}),$  then taking  $\alpha_{2}=\frac{\alpha_{3} N_3}{\beta_{1}(1-\beta_{1}) - N_1},$ we have $N_3'=0$ and obtain $\beta_{3}'=\alpha_{3}\beta_{3},$ $N_2'=\alpha_{3} N_2.$

\begin{itemize}
        \item If $\beta_{3}=0,$ then we get the affgebras
$L_1(\beta_{1},0,\beta_{1},0,1,1,N_1,0,0)$
and $L_2(\beta_{1},0,\beta_{1},0,1,1,N_1,1,0)$
depending on whether $N_2=0$ or not.
\item If $\beta_{3}\neq 0,$ then we can suppose  $\beta_{3}'=1,$ and obtain the affgebra
$L_{13}(\beta_{1},1,\beta_{1},0,1,1,N_1,N_2,0).$
    \end{itemize}
 \item Let $\gamma_{3} = 1$ and $N_1= \beta_{1}(1-\beta_{1}),$ then we get $\beta_{3}'=\alpha_{3}\beta_{3},$ $N_2'=\alpha_{3} N_2$ and
 $N_3'=\alpha_{3} N_3.$
 \begin{itemize}
        \item If $N_3=0,$ then we get the affgebras
$L_1,$ $L_2$ and $L_{13},$ with $\beta_3=\beta_1,$ $\gamma_3=1,$ $N_1 = \beta_1(1-\beta_1).$
\item If $N_3\neq0,$ then we may assume $N_3'=1$ and obtain the affgebra
$L_{14}(\beta_{1},\beta_{3},\beta_{1},0,1,1,\beta_{1}(1-\beta_{1}),N_2,1).$
    \end{itemize}

  \end{itemize}

\item  Let $\beta_{1} = \beta_{5}$ and $\gamma_{2} = 0,$ then $\gamma_{2}'=0.$ Thus, we get that $$\beta_{3}'=\alpha_{4}\beta_{3}, \quad \gamma_{1}'=\alpha_{2} (\beta_{1}-\gamma_{3})+\alpha_{4} \gamma_{1},$$ $$N_2'=\alpha_{3} N_2+\alpha_{1} (N_1 - \beta_{1} (1-\beta_{1})), \quad N_3'=\alpha_{2} N_1 + \alpha_{4}N_3+ \alpha_{4} C_3 (1-\gamma_{3})$$

\begin{itemize}
        \item Let $N_1 \neq \beta_{1} (1-\beta_{1})$ and $\gamma_{3} \neq 1,$ then taking
            $\alpha_{1}=\frac{\alpha_{3} N_2}{\beta_{1} (1-\beta_{1})-N_1},$ $C_3=\frac{\alpha_{2} N_1 + \alpha_{4}N_3}{\alpha_{4}(\gamma_{3}-1)},$ we obtain $N_2'=0,$ $N_3'=0.$
            \begin{itemize}
        \item If $\gamma_{3} \neq \beta_{1},$ then taking $\alpha_{2}=\frac{\alpha_{4} \gamma_{1}}{\gamma_{3}-\beta_{1}},$ we get $\gamma_{1}'=0$ and obtain the  affgebras
             $L_4(\beta_{1},0,\beta_{1},0,0,\gamma_{3},N_1,0,0)$ and
              $L_{15}(\beta_{1},1,\beta_{1},0,0,\gamma_{3},N_1,0,0),$ depending on whether $\beta_{3} = 0$ or not.
              \item If $\gamma_{3} = \beta_{1},$ then in case of $\gamma_{1}=0,$ we obtain the  affgebras $L_4$ and $L_{15}$ with $\gamma_3=\beta_3=\beta_1.$
              In the case of $\gamma_{1}\neq 0,$ we obtain the affgebra $L_{16}(\beta_{1},\beta_{3},\beta_{1},1,0,\beta_{1},N_1,0,0).$
     \end{itemize}
     \item Let $N_1 \neq \beta_{1} (1-\beta_{1})$ and $\gamma_{3} = 1,$ then taking
            $\alpha_{1}=\frac{\alpha_{3} N_2}{\beta_{1} (1-\beta_{1})-N_1},$ we obtain $N_2'=0.$
             \begin{itemize}
        \item If $N_1 \neq 0,$ then taking $\alpha_{2} =- \frac{\alpha_{4}N_3}{N_1},$ we have $N_3'=0$ and $\beta_{3}'=\alpha_{4}\beta_{3}, $ $\gamma_{1}'=\alpha_{4} \gamma_{1}.$
        \begin{itemize}
        \item If $\gamma_{1}=0,$ then we get the affgebras $L_4$ and $L_{15}$ with $\gamma_3=1,$ $\beta_3=\beta_1.$
        \item If $\gamma_{1}\neq 0,$ then we may assume $\gamma_{1}'=1,$
        and obtain the affgebra $L_{17}(\beta_{1},\beta_{3},\beta_{1},1,0,1,N_1,0,0).$
\end{itemize}
\item If $N_1 = 0,$ then $\beta_{1} (1-\beta_{1})\neq 0.$ Taking $\alpha_{2}  = \frac{\alpha_{4} \gamma_{1}}{1-\beta_{1}},$ we have $\gamma_{1}'=0$ and
$\beta_{3}'=\alpha_{4}\beta_{3},$ $N_3'=\alpha_{4}N_3.$
\begin{itemize}
        \item If $N_3=0,$ then we get the affgebras $L_4$ and $L_{15}$ with $\beta_3=\beta_1,$ $N_1=0$.
        \item  $N_3\neq 0,$ then we may assume $N_3'=1,$ and obtain the affgebra $L_{18}(\beta_{1},\beta_{3},\beta_{1},0,0,1,0,0,1).$

\end{itemize}
\end{itemize}
\item Let $N_1 = \beta_{1} (1-\beta_{1})$ and $\gamma_{3} \neq 1,$ then taking
            $C_3=\frac{\alpha_{2} N_1 + \alpha_{4}N_3}{\alpha_{4}(\gamma_{3}-1)},$ we obtain  $N_3'=0.$
            \begin{itemize}
        \item If $\gamma_{3} \neq \beta_{1},$ then taking $\alpha_{2}=\frac{\alpha_{4} \gamma_{1}}{\gamma_{3}-\beta_{1}},$ we may suppose $\gamma_{1}'=0.$
        \begin{itemize}
        \item If $\beta_{3}=0,$ $N_2 =0,$ then we obtain the affgebra
$L_4$ with $N_1=\beta_{1} (1-\beta_{1}).$
%$L_4(\beta_{1},0,\beta_{1},0,0,\gamma_{3},\beta_{1} (1-\beta_{1}),0,0).$
\item If $\beta_{3}=0,$ $N_2 \neq 0,$ then we obtain the affgebra
$L_7$ with $N_1=\beta_{1} (1-\beta_{1}).$
\item If $\beta_{3}\neq 0,$ $N_2 =0,$ then we obtain the affgebra
$L_{15}$ with $N_1=\beta_{1} (1-\beta_{1}).$

\item If $\beta_{3}\neq 0,$ $N_2 \neq 0,$ then we obtain the affgebra
$L_{19}(\beta_{1},1,\beta_{1},0,0,\gamma_{3},\beta_{1} (1-\beta_{1}),1,0).$
        \end{itemize}
 \item If $\gamma_{3}= \beta_{1},$ then we have
$\beta_{3}'=\alpha_{4}\beta_{3},$ $\gamma_{1}'=\alpha_{4} \gamma_{1},$ $N_2'=\alpha_{3} N_2.$

\begin{itemize}
        \item If $\gamma_{1}=0,$ then similarly to the previous case we obtain the affgebras $L_4,$ $L_{7},$ $L_{15}$ and $L_{19}$ with $\gamma_3=\beta_3=\beta_1$ and $N_1 = \beta_1(1-\beta_1).$

        \item If $\gamma_{1}\neq 0,$ then we can suppose $\gamma_{1}'=1,$ and obtain the affgebras $L_{16}(\beta_{1},\beta_{3},\beta_{1},1,0,\beta_{1},\beta_{1} (1-\beta_{1}),0,0)$ and $L_{20}(\beta_{1},\beta_{3},\beta_{1},1,0,\beta_{1},\beta_{1} (1-\beta_{1}),1,0)$ depending on whether $N_2=0$ or not.
   \end{itemize}
   \end{itemize}
  \item Let $N_1 = \beta_{1} (1-\beta_{1})$ and $\gamma_{3} = 1.$
  %Then $$\beta_{3}'=\alpha_{4}\beta_{3}, \quad \gamma_{1}'=\alpha_{2} (\beta_{1}-1)+\alpha_{4} \gamma_{1}, \quad N_2'=\alpha_{3} N_2, \quad N_3'=\alpha_{2} \beta_{1} (1-\beta_{1}) + \alpha_{4}N_3.$$
  \begin{itemize}
        \item Let $\beta_{1}\neq 1,$ then taking $\alpha_{2} = \frac{\alpha_{4}\gamma_{1}}{1-\beta_{1}},$ we get that $\gamma_{1}'=0.$
\begin{itemize}
        \item If $N_3=0,$ then similarly to the previous case, we get the affgebras $L_4,$ $L_{7},$ $L_{15}$ and $L_{19}$ with $\gamma_3=1,$ $\beta_3=\beta_1$ and $N_1 = \beta_1(1-\beta_1).$

        \item If $N_3\neq0,$ then we may suppose $N_3'=1,$ and obtain the algebras
        $L_{21}(\beta_{1},\beta_{3},\beta_{1},0,0,1,\beta_{1} (1-\beta_{1}),0,1)$ and $L_{22}(\beta_{1},\beta_{3},\beta_{1},0,0,1,\beta_{1} (1-\beta_{1}),1,1)$ depending on whether $N_2=0$ or not.

        \end{itemize}
    \item Let $\beta_{1}= 1.$
\begin{itemize}
        \item If $\gamma_{1}=0,$ then we get the affgebras
        $L_4,$ $L_{7},$ $L_{15},$ $L_{19},$ $L_{21}$ and $L_{22},$ with $\gamma_3=\beta_3=\beta_1=1$ and $N_1 = 0.$
          \item If $\gamma_{1}\neq0,$ then we may suppose $\gamma_{1}'=1,$ and obtain the affgebras
        $L_{23}(1,\beta_{3},1,1,0,1,0,0,N_3)$ and $L_{24}(1,\beta_{3},1,1,0,1,0,1,N_3)$ depending on whether $N_2=0$ or not.

        \end{itemize}
        \end{itemize}
  \end{itemize}


\end{itemize}

\end{proof}





