\paragraph{Learning multi-norm prediction sets.}
Thus far, we have optimized prediction sets using a single global norm. While this provides flexibility, it fails to adapt to local variations in uncertainty. In many applications, uncertainty behaves asymmetrically—certain directions require tighter coverage, while others necessitate broader regions. To address this, we extend our framework to allow for region-dependent norms by partitioning the space into $m$ disjoint regions $\{\mathcal A_j\}_{j=1}^{m}$, each with its own norm~$p_j$. A natural way to define these partitions is through axis-aligned decomposition, where the space is split along coordinate axes. This approach ensures computational tractability and facilitates structured volume computations, allowing for at most $m = 2^k$ regions in dimension $k$. For example, when $k=2$, the space can be split into four quadrants, and when $k=3$, it can be divided into eight octants.

To construct these prediction sets, we introduce a global rotation matrix $R$ that aligns the space, followed by region-specific \emph{diagonal} scaling matrices $D_j$, for $j \in [m]$. The role of $R$ is to standardize the representation of data by aligning principal directions of variation with coordinate axes. Within each partition, the diagonal matrix $D_j$ then scales the axes independently, capturing anisotropic structure while preserving computational efficiency. Given a center $\mu$, we define the pseudo-distance 
\begin{align*}
    d(y, \mu; {R, \{D_j\}_{j=1}^m}) \coloneqq \sum_{j=1}^{m} \mathds{1}\{R(y - \mu) \in \mathcal A_j \} \left\|R D_j (y - \mu) \right\|_{p_j},
\end{align*}  
which induces a prediction set that takes the form
\begin{align*}
    \mathbb{M}\left( \{p_j\}_{j=1}^m, R, \{D_j\}_{j=1}^m, \mu \right) \coloneqq \left\{ y \in \mathbb{R}^k \mid d(y, \mu; {R, \{D_j\}_{j=1}^m}) \leq 1 \right\}.
\end{align*}
Using this decomposition, the multi-norm MVCS problem is formulated as
\begin{align}
\label{eq:min:vol:multi-p}
\begin{split}
\min \quad & \mathrm{Vol}\left(\mathbb{M}\left( \{p_j\}_{j=1}^m, R, \{D_j\}_{j=1}^m, \mu \right)\right)\\
\mathrm{s.t.} \quad & R \in \mathrm{SO}(k)
, \; \mu \in \mathbb{R}^k,\; D_j \in \mathrm{Diag}(k) \\
& D_j \geqm 0, \; p_j > 0, \quad \forall\, j \in [m] \\
& \mathrm{Card} \left\{ i \in [n] \mid d(y_i, \mu; {R, \{D_j\}_{j=1}^m}) \leq 1 \right\} \geq n - r + 1.
\end{split}
\end{align}
Here, the total volume of the multi-norm prediction set is given by the average of the region-specific volumes,
\begin{align}
\label{eq:vol:multi-p}
\mathrm{Vol}\left(\mathbb{M}\left( \{p_j\}_{j=1}^m, R, \{D_j\}_{j=1}^m, \mu \right)\right) = \frac{1}{m} \sum_{j=1}^{m} \mathrm{Vol}\left(\mathbb{B}(p_j,D_j,\mu)\right) = \frac{1}{m} \sum_{j=1}^{m}{\lambda(B_{\|\cdot \|_{p_j}}(1))}{\det(D_j)}^{-1},
\end{align}
where $\lambda(B_{\|\cdot \|_{p_j}}(1))$ represents Lebesgue measure of the unit $p_j$-norm ball, given explicitly in \eqref{eq:Lebesgue:p:norm}. The global rotation matrix $R$ does not affect the volume since it is an orthogonal transformation with $\det(R) = 1$, leaving the determinant term unchanged. Moreover, the uniform weighting of $1/m$ arises because the matrices $D_j$ are diagonal, so the total volume is taken as the average contribution across all regions. The following proposition provides a reformulation of \eqref{eq:min:vol:multi-p} that is amenable to iterative optimization algorithms.



\begin{proposition}[Multi-norm MVCS]
\label{prop:min:vol:multi}
The multi-norm MVCS problem~\eqref{eq:min:vol:multi-p} is equivalent to the following optimization problem
\begin{align}
\label{eq:min:vol:exact:multi-p}
\begin{split}
\min \quad & k \log \left(\sigma_r\left\{ d(y_i, \mu; {R, \{D_j\}_{j=1}^m}) \right\}\right) + \log \left(\sum_{j=1}^m {\lambda(B_{\|\cdot \|_{p_j}}(1))}{\det(D_j)}^{-1}\right) \\
\mathrm{s.t.} \quad & R \in \mathrm{SO}(k)
, \; \mu \in \mathbb{R}^k,\; D_j \in \mathrm{Diag}(k) \\
& D_j \geqm 0, \; p_j > 0, \quad \forall\, j \in [m].
\end{split}
\end{align}
\end{proposition}
\begin{proof}
Using the change of coordinates $D_j \to D_j/\nu$, for $\nu \geq 0$, problem~\eqref{eq:min:vol:multi-p} is equivalent to
\begin{align}
\label{eq:min:vol:exact:multi-p:temp:1}
\begin{split}
\min \quad & k \log \nu + \log \left(\sum_{j=1}^m {\lambda(B_{\|\cdot \|_{p_j}}(1))}{\det(D_j)}^{-1}\right) \\
\mathrm{s.t.} \quad & R \in \mathrm{SO}(k)
, \; \mu \in \mathbb{R}^k,\; D_j \in \mathrm{Diag}(k),\; \nu \geq 0 \\
& D_j \geqm 0, \; p_j > 0, \quad \forall\, j \in [m] \\
& \mathrm{Card} \left\{ i \in [n] \mid d(y_i, \mu; {R, \{D_j\}_{j=1}^m}) \leq \nu \right\} \geq n - r + 1,
\end{split}
\end{align}
where we have used the expression of the volume provided in \eqref{eq:vol:multi-p}. Now, due the cardinality constraint, for given $R, \mu, \{D_j\}_{j=1}^m$, and $\{p_j\}_{j=1}^m$, the optimal $\nu^\star(R, \mu, \{D_j\}_{j=1}^m, \{p_j\}_{j=1}^m)$ is equal to the $(n-r+1)$-th smallest value in the set $\left\{d(y_i,\mu; {R, \{D_j\}_{j=1}^m})\right\}_{i=1}^n$, or, equivalently, the $r$-th largest value, i.e., $\nu^\star = \sigma_r\left\{ d(y_i,\mu; {R, \{D_j\}_{j=1}^m}) \right\}$. Plugging this into \eqref{eq:min:vol:exact:multi-p:temp:1}, we obtain problem \eqref{eq:min:vol:exact:multi-p} in the statement of the proposition.
\end{proof}

