A^P_{ij}(t,p,J)  & = \delta_{ij} - \frac{wN_iN_j\partial_x h_i(t,J_i)K_i(t,t)}{\overline \bfp(p^0)\overline \bfp(p)}\overleftrightarrow{\nabla^2 G}^{\mu(p)}_{ij}(t,\mu(p)), \label{eqn:AP} \\
