    \begin{equation} \label{eqn:wealth_predictable}  
    \begin{aligned}
    W^Q(T) & = w + \int_0^T Q(t)^\top dS(t) + I(T)^\top Q(T)-I(0)^\top Q(0) - \sum_{i=1}^d \left(\frac{H_i(t,J_i(T))}{K_i(t,t)} - \frac{H_i(0,J_i(0))}{K_i(0,0)}\right) \\
