\end{equation}
\end{lem}
\begin{proof} Fix a $\psi \in C_c^\infty(0,\infty)$, which is a nonnegative function satisfying $\mathrm{supp}(\psi) = [0,1]$ and $\int_0^\infty \psi(x)dx = 1$. Put $\psi^n(t) = \frac{n\psi(nt)}{\int_0^{nt} \psi(s)ds}$ for $n \in \N$ and define $Q^n(t) = \int_0^t Q(s)\psi^n(t-s)ds$.
Clearly $Q^n$ is predictable, since it only depends on $Q(s)$ for $s \leq t$. Additionally it is absolutely continuous so that the wealth process corresponding to that strategy is unambiguously given by \eqref{eqn:wealth_smooth}. 
By basic properties of mollifiers we have almost surely that $Q^n(t) \to Q(t)$ pointwise and in $L^1_{\mathrm{Loc}}(\R_+;\R^d)$ as $n \to \infty$. Additionally from \eqref{eqn:J_dynamics} we see that almost surely $J^n(t) \to J(t)$ in $L^1_{\mathrm{Loc}}(\R_+;\R^d)$, where $J^n$ is the impact state process corresponding to $Q^n$. Finally note that since $|Q^n(T)| \leq \sup_{t \leq T}|Q(t)|$ we have by the stochastic dominated convergence theorem \cite[Theorem~IV.2.12]{revuz1999continuous} that $\int_0^T Q^n(t)^\top dS(t) \to \int_0^T Q(t)^\top dS(t)$. As such, we see that sending $n \to \infty$ in \eqref{eqn:wealth_smooth} yields precisely \eqref{eqn:wealth_predictable}.
\end{proof}
% By standard convention wealth processes are cadlag semimartingales, so we set $(W^Q(t))_{t\geq 0}$ to be the right continuous version of the process obtained in Lemma~\ref{lem:wealth_approx}. 
This process $W^Q$ is the investor's wealth process when using the trading strategy $Q$. 
We are now ready to prove Proposition~\ref{thm:wealth}.

\begin{proof}[Proof of Proposition~\ref{thm:wealth}] We will reformulate the right hand side of \eqref{eqn:wealth_predictable}. Using It\^o's formula on $H_i(t,J_i(t))/K_i(t,t)$ we get
\begin{align*}
	\frac{H_i(T,J_i(T))}{K_i(T,T)} - 	\frac{H_i(0,J_i(0))}{K_i(0,0)}  & = \int_{0}^T\frac{h_i(t,J_i(t))}{K_i(t,t)}dJ_i(t) + \int_0^T\frac{\partial_x h_i(t,J_i(t))}{2K_i(t,t)}d[J_i](t) \\
	& + \int_0^T\left(\frac{\partial_t H_i(t,J_i(t))}{K_i(t,t)} - \frac{(\partial_t K_i(t,t) + \partial_s K_i(t,t))H_i(t,J_i(t))}{K_i(t,t)^2}\right)dt 
	% & + \sum_{0 < t \leq T} \sum_{i=1}^d \left(\frac{\Delta H_i(t,J_i(t))}{K_i(t,t)} - \frac{h_i(t,J(t-))}{K_i(t,t)}\Delta J _i(t)\right).
\end{align*}
    Plugging this into \eqref{eqn:wealth_predictable} yields
\begin{equation} \label{eqn:wealth_intermediate}
\begin{aligned} 
	W^Q(T) - w & = \int_0^T Q(t)^\top dS(t) + I(T)Q(T) - I(0)Q(0) + \sum_{i=1}^d\int_0^T\frac{h_i(t,J_i(t))}{K_i(t,t)}b^J_i(t,Q_{[0,t]})dt \\
    & \hspace{0.5cm}    -\sum_{i=1}^d \int_{0}^T \frac{h_i(t,J_i(t))}{K_i(t,t)}dJ_i(t) -\sum_{i=1}^d\int_0^T \frac{\partial_x h_i(t,J_i(t))}{2K_i(t,t)}d[J_i](t). 
    % & \hspace{0.5cm}
	   % - \sum_{0 < t \leq T} \sum_{i=1}^d \left(\frac{\Delta H_i(t,J_i(t))}{K_i(t,t)} - \frac{h_i(t,J(t-))}{K_i(t,t)}\Delta J _i(t)\right).
\end{aligned}
\end{equation}
Now recalling the relationship \eqref{eqn:dQ} and that $I_i(t) = h_i(t,J_i(t))$ we get that 
\[\sum_{i=1}^d\int_0^T\frac{h_i(t,J_i(t))}{K_i(t,t)}b^J_i(t,Q_{[0,t]})dt -\sum_{i=1}^d \int_{0}^T \frac{h_i(t,J_i(t))}{K_i(t,t)}dJ_i(t) = -\sum_{i=1}^d \int_{0}^T I_i(t)dQ_i(t) .\]
Moreover, we have that 
\[\int_0^T\frac{\partial_x h_i(t,J_i(t))}{2K_i(t,t)}d[J_i](t) = \frac{1}{2}\int_0^T\partial_x h_i(t,J_i(t))d[J_i,Q_i](t) = \frac{1}{2}[I_i,Q_i](T).\]
Hence, subbing these identities into \eqref{eqn:wealth_intermediate} and integrating $I(T)^\top Q(T)$ by parts gives
\begin{align*}
	W^Q(T) - w  = &  \int_0^T Q(t)^\top dS(t) + I(T)^\top Q(T)-I(0)^\top Q(0) -\sum_{i=1}^d \int_{0}^T I_i(t)dQ_i(t) - \frac{1}{2}\sum_{i=1}^d[I_i,Q_i](T)  \\
	 = & \int_0^T Q(t)^\top dS(t)  + \sum_{i=1}^d\int_{0}^TQ_i(t)^\top dI_i(t) + \sum_{i=1}^d [I_i,Q_i](T) - \frac{1}{2}\sum_{i=1}^d [I_i,Q_i](T)  \\
	 = & \int_{0}^T Q(t)^\top dP(t) + \frac{1}{2}\sum_{i=1}^d [I_i,Q_i](T).  \label{eqn:general_pnl} 
\end{align*}
This completes the proof.
