Next we establish the relative wealth equation \eqref{eqn:relative_wealth}.
\begin{proof}[Proof of Theorem~\ref{thm:relative_wealth}] We start by noting the following three relationships,
\begin{equation} \label{eqn:numeraire_identities}
\begin{aligned}
    \frac{dW^\mathcal{M}(t)}{W^\mathcal{M}(t)} & = \frac{d\overline \bfp(t)}{\overline \bfp(t)}, \\
    \frac{d\mu_i(t)}{\mu_i(t)} & = \frac{d\bfp_i(t)}{\bfp_i(t)} -  \frac{d\overline \bfp(t)}{\overline \bfp(t)} + \frac{d[\overline \bfp](t)}{\overline \bfp^2(t)} - \frac{d[\bfp_i,\overline \bfp](t)}{ \bfp_i(t)\overline \bfp(t)}, &    i=1,\dots,d, \\
    [W^Q,W^\mathcal{M}](T) & = \int_0^T\sum_{i=1}^d \frac{w}{N_i\overline \bfp(0)}Q_i(t)d[\bfp_i,\overline \bfp](t), &    i=1,\dots,d,
\end{aligned} 
\end{equation}
 These three identities follow directly from the wealth equations \eqref{eqn:wealth}, \eqref{eqn:market_wealth} and It\^o's quotient rule to compute the dynamics of $\mu$. We now apply It\^o's formula to the quotient $W^Q/W^{\mathcal{M}}$ to get
\begin{align*}
    dV^Q(t) & = V^Q(t)\left(\frac{dW^Q(t)}{W^Q(t)} - \frac{dW^\mathcal{M}(t)}{W^\mathcal{M}(t)} + \frac{d[W^\mathcal{M}](t)}{(W^\mathcal{M}(t))^2} - \frac{d[W^Q,W^\mathcal{M}](t)}{W^Q(t)W^\mathcal{M}(t)} \right) 
    \\
    & = \frac{1}{W^\mathcal{M}(t)}\left(dW^Q(t)- W^Q(t)\frac{dW^\mathcal{M}(t)}{W^\mathcal{M}(t)} + W^Q(t)\frac{d[W^\mathcal{M}](t)}{(W^\mathcal{M}(t))^2} - \frac{d[W^Q,W^\mathcal{M}](t)}{W^\mathcal{M}(t)}\right).
\end{align*}   
Next we use \eqref{eqn:numeraire_identities}, \eqref{eqn:wealth} and the fact that $W^Q(t) = Q(t)^\top P(t) = \sum_{i=1}^d \frac{Q_i(t)}{N_i}\bfp_i(t)$ to obtain
\begin{align*} 
V^Q(T) &= 1+ \int_0^T\frac{\overline \bfp(0)}{w\overline \bfp(t)}\left( \sum_{i=1}^d Q_i(t)dP_i(t) - \sum_{i=1}^d\frac{Q_i(t)}{N_i}\bfp_i(t)\left(\frac{d\overline \bfp(t)}{\overline \bfp(t)} -\frac{d[\overline \bfp](t)}{\overline \bfp^2(t)}\right)\right.\\
& \hspace{1.9cm}\left.- \sum_{i=1}^d \frac{Q_i(t)}{N_i}\frac{d[\bfp_i,\overline \bfp](t)}{\overline \bfp(t)}\right)dt + \frac{1}{2}\sum_{i=1}^d\int_0^T\frac{\overline \bfp(0)}{w\overline \bfp(t)}d[I_i,Q_i](t) \\
% & \hspace{2.5cm}+\sum_{0\leq t \leq T}\frac{\overline \bfp(0-)}{w\overline \bfp(t-)}\left(\mathcal{J}^Q(t) - \frac{\mathcal{J}^Q(t)\Delta \overline\bfp(t))}{\overline \bfp(t-)}\right) \\
& = 1 + \int_0^T \sum_{i=1}^d \frac{\bfp_i(t)}{\overline \bfp(t)}\frac{\overline \bfp(0)Q_i(t)}{wN_i}\left(\frac{d\bfp_i(t)}{\bfp_i(t)} -  \frac{d\overline \bfp(t)}{\overline \bfp(t)} + \frac{d[\overline \bfp](t)}{\overline \bfp^2(t)} - \frac{d[\bfp_i,\overline \bfp](t)}{ \bfp_i(t)\overline \bfp(t)}\right)dt \\
& \hspace{1.9cm} + \frac{1}{2}\sum_{i=1}^d\int_0^T\frac{\overline \bfp(0)}{w\overline \bfp(t)}d[I_i,Q_i](t)\\
& = 1 + \int_0^T\sum_{i=1}^d\mu_i(t)\frac{\overline \bfp(0)Q_i(t)}{wN_i}\left(\frac{d\mu_i(t)}{\mu_i(t)}\right) + \frac{1}{2}\sum_{i=1}^d\int_0^T\frac{\overline \bfp(0)}{w\overline \bfp(t)}d[I_i,Q_i](t) \\
% & \hspace{1.9cm} +  \sum_{0 \leq t \leq T}\frac{\overline \bfp(0-)}{w\overline \bfp(t-)}\mathcal{J}^Q(t)\left(1 - \frac{\Delta \overline \bfp(t)}{\overline \bfp(t-)}\right) \\
& = 1 +\int_0^T \sum_{i=1}^d \frac{\overline \bfp(0)Q_i(t)}{wN_i}d\mu_i(t) +  \frac{1}{2}\sum_{i=1}^d\int_0^T\frac{\overline \bfp(0)}{w\overline \bfp(t)}d[I_i,Q_i](t).
\end{align*} 
In the second equality we factored $\bfp_i(t) Q_i(t)/N_i$ and in third we used that $\mu_i = \bfp_i/\overline \bfp$ and subbed in the returns dynamics \eqref{eqn:numeraire_identities} for the market weights $\mu_i$. This is precisely \eqref{eqn:relative_wealth}.
\end{proof}



\section{Proofs for Section~\ref{sec:functionally_generated}}
\subsection{Proof of Proposition~\ref{prop:AP}} \label{sec:proof_AP}
\begin{proof}
To simplify the exposition we set for $t \geq 0$, $\mu \in \Delta^{d-1}_+$,
\[\Xi(t,\mu) =-\mathrm{diag}(N)\overleftrightarrow{\nabla^2 G}^{\mu}_{ij}(t,\mu)\mathrm{diag}(N), \quad  C(t,\mu,J) = \frac{w}{\overline \bfp(p^0)} \mathrm{diag}\Big(\partial_x h(t,J) \circ K(t,t)\Big)\Xi(t,\mu)\]
so that $A^P(t,p,J) = I_{d \times d} + \overline \bfp^{-1}(p)C(t,\mu(p),J)$. It also follows from the representation \eqref{eqn:arrowM} that
for any $\varphi\in \R^d$,
    \begin{equation} \label{eqn:arrowM_PSD}
        \varphi^\top \overleftrightarrow{\nabla^2 G}^{\mu}(t,\mu)\varphi =  (\varphi - \overline \varphi\mu)^\top \nabla^2 G(t,\mu)(\varphi - \overline\varphi\mu),
    \end{equation}
    where $\overline \varphi = \varphi^\top {\bf 1}_d$.

    Now let $(t,p,J) \in [0,\infty) \times (0,\infty)^d \times \R^d$ be given and assume that $G(t,\mu(p))$ satisfies \eqref{eqn:quadratic_form}. From \eqref{eqn:arrowM_PSD} we deduce that $\overleftrightarrow{\nabla^2 G}^{\mu(p)}(t,\mu(p))$ is a negative semidefinite matrix since $(\varphi - \overline \varphi \mu)^\top {\bf 1}_d = 0$ for any $\varphi \in \R^d$. It then follows that $\Xi(t,\mu(p))$ is a positive semidefinite matrix. Since the product of two positive semidefinite matrices has nonnegative eigenvalues \cite[Corollary~7.6.2]{horn2013matrix} we have that $C(t,\mu(p),J)$ has nonnegative eigenvalues. From here it follows that all of the eigenvalues of $A^P(t,p,J)$ are real and not smaller than one. Indeed $(\lambda,u)$ are an eigenvalue, eigenvector pair for $A^P(t,p,J)$ if and only if 
    \[A^P(t,p,J) u = \lambda u \iff C(t,\mu(p),J)u = \overline \bfp(p)(\lambda - 1)u,\]
    establishing the claim. 

    For the converse we assume that $G(t^*,\mu^*)$ does not satisfy \eqref{eqn:quadratic_form} for some $t^* \geq 0$ and $\mu^* \in \Delta^{d-1}_+$. Then there exits $x \in \R^d$ with $x^\top {\bf 1}_d = 0$ satisfying $x^\top \nabla^2 G(t^*,\mu^*)x > 0$. Setting $\varphi = x$ in \eqref{eqn:arrowM_PSD} we see that $\overleftrightarrow{\nabla^2 G}^{\mu^*}(t^*,\mu^*)$ fails to be negative semidefinite. We now establish that  $C(t^*,\mu^*,J^*)$ has a negative eigenvalue. Let $D = \mathrm{diag}(\partial_x h(t^*,J^*) \circ K(t^*,t^*))$ and note that $D$ is a diagonal matrix with strictly positive entries by our assumption regarding $J^*$. Hence $C(t^*,\mu^*,J^*) = D^{1/2}(D^{1/2}\frac{w}{\overline \bfp(p^0)}\Xi(t^*,\mu^*)D^{1/2})D^{-1/2}$ is similar to the matrix $\widetilde \Xi(t^*,\mu^*) := D^{1/2}\Xi(t^*,\mu^*) D^{1/2}$ and, as such, has the same eigenvalues as it. But $\widetilde \Xi(t^*,\mu^*)$ is not positive semidefinite because $\Xi(t^*,\mu^*)$ is not. Indeed, taking $x \in \R^d$ such that $x^\top \Xi(t^*,\mu^*)x < 0$ and setting $y = D^{-1/2}x$ we have that $y^\top \widetilde \Xi(t^*,\mu^*) y < 0$. Hence,  $\widetilde \Xi(t^*,\mu^*)$ and, consequently, $C(t^*,\mu^*,J^*)$ must have a negative eigenvalue $\lambda^* < 0$. We denote by $u^*$ the corresponding eigenvector. 

    We are now ready to establish non-invertibility of $A^P$. To this end set $p^*_i = -\lambda^*\mu^*_i/N_i > 0$ so that $\overline \bfp(p^*) = -\lambda^*>0$ and $\mu(p^*) = \mu^*$. We have that
    \[A^P(t^*,p^*,J^*)u^* = u^* + \frac{1}{-\lambda^*} C(t^*,\mu^*,J^*)u^* = u^*-\frac{1}{\lambda^*}(\lambda^*u^*) = 0 \]
    proving the claim.
\end{proof}
\subsection{Deriving the SDE \eqref{eqn:SDE}}  \label{app:SDE_derivation}
We start by formally deriving \eqref{eqn:SDE}. To carry this out we, for the moment, suppose that that $P, Q$ and $\mu$ are semimartingales so that the equation \eqref{eqn:additive_Q_explicit} derived in Section~\ref{sec:heuristic} for $Q$ holds. To simplify the exposition, in this section for any semimartingale $X$ we will write $X = X(0) + X^{FV} + X^M$ for its canonical semimartingale decomposition, where $X^{FV}$ is the finite variation part and $X^M$ is the local martingale part. 

We start by deriving $Q^M$. Applying It\^o's formula to the function $\partial_i G(t,\mu) + G(t,\mu)- \nabla G(t,\mu)^\top \mu$ appearing in the right hand side of \eqref{eqn:additive_Q_explicit} and collecting the local martingale terms gives
\[dQ_i^M(t) = \frac{wN_i}{\overline \bfp(0)}\sum_{k=1}^d \Big(\partial_{ik}G(t,\mu(t))-\sum_{\ell=1}^d \partial_{kl} G(t,\mu(t))\mu_\ell(t)\Big)d\mu_k^M(t).\]
    Recalling the dynamics for $\mu$ \eqref{eqn:numeraire_identities} in terms of $P$  then gives
\begin{align} dQ^M_i(t)  & = \sum_{j=1}^d\frac{wN_iN_j}{\overline \bfp(0)\overline \bfp(t)}\sum_{k=1}^d\Big(\partial_{ik}G(t,\mu(t))-\sum_{\ell=1}^d \partial_{kl}G(t,\mu(t))\mu_\ell(t)\Big)(\delta_{jk}-\mu_k(t))dP^M_j(t) \nonumber \\
& = \sum_{j=1}^d A^Q_{ij}(t,P(t),J(t))dP^M_j(t), \label{eqn:Q^M}
\end{align}
where we recall that $A^Q$ is given by \eqref{eqn:AQ}.
Next, recalling \eqref{eqn:price} and \eqref{eqn:dJ} we have that
\[dP^M_i(t) = dS^M_i(t) + dI^M_i(t) = dS_i^M(t) + \partial_x h_i(t,J_i(t))dJ_i^M(t) = dS_i^M + \partial_x h_i(t,J_i(t))K_i(t,t)dQ_i^M(t). \] Substituting in \eqref{eqn:Q^M}, writing in vector form and collecting the $dP^M(t)$ terms on the left hand side yields $A^P(t,P(t),J(t))dP^M(t) = dS^M(t)$ or that
\begin{equation} \label{eqn:P^M}
    dP^M(t) = \beta^P(t,P(t),J(t))dS^M(t),
\end{equation}
where $\beta^P = (A^P)^{-1}$. In particular, by substituting into \eqref{eqn:Q^M} we obtain the SDE coefficient $\beta^Q$ and by computing the quadratic variation from \eqref{eqn:P^M} we get
\begin{equation} \label{eqn:[P]}
d[P](t) = \beta^P(t,P(t),J(t))d[S](t)\beta^P(t,P(t),J(t))^\top.
\end{equation}

Next we compute $Q^{FV}$ by appling It\^o's formula to the right hand side of \eqref{eqn:additive_Q_explicit}. In the following we omit the function evaluations for brevity,
\begin{align*}dQ_i^{FV} & = \frac{wN_i}{\overline \bfp(0)}\Bigg(\partial_{it}G dt + \sum_{j=1}^d \partial_{ij}Gd\mu_j^{FV} + \frac{1}{2}\sum_{j,k=1}^d \partial_{ijk}Gd[\mu_j,\mu_k] + \partial_t G dt + \sum_{j=1}^d \partial_{j}Gd\mu_j^{FV} \\
& \qquad + \frac{1}{2}\sum_{j,k=1}^d \partial_{jk}Gd[\mu_j,\mu_k] -\sum_{\ell=1}^d \partial_{\ell t}G\mu_\ell dt - \sum_{j=1}^d\left(\sum_{\ell=1}^d \partial_{j\ell}G\mu_\ell +\partial_j G\right)d\mu_j^{FV}\\
& \qquad - \frac{1}{2}\sum_{j,k=1}^d\left(\sum_{\ell=1}^d\partial_{jk\ell}G\mu_\ell + 2 \partial_{jk}G\right)d[\mu_j,\mu_k] -\partial_tGdt -\frac{1}{2}\sum_{j,k=1}^d\partial_{jk}Gd[\mu_j,\mu_k] \\
% & \qquad+ \frac{1}{2}\sum_{\ell=1}^d \frac{wN_\ell^2}{\overline \bfp(0)\overline \bfp(t)}\partial_xh_\ell K_\ell\sum_{j,k=1}^d (\partial_{j\ell}G - \sum_{m=1}^d \partial_{\ell m}G\mu_m)(\partial_{k\ell}G - \sum_{m=1}^d \partial_{\ell m}G\mu_m)d[\mu_j,\mu_k]\Bigg) \\
& \qquad+ \frac{1}{2}\sum_{\ell=1}^d \frac{wN_\ell^2}{\overline \bfp(0)\overline \bfp}\partial_xh_\ell K_\ell\sum_{j,k=1}^d (\partial_{j\ell}G - \sum_{m=1}^d \partial_{j m}G\mu_m)(\partial_{k\ell}G - \sum_{m=1}^d \partial_{km}G\mu_m)d[\mu_j,\mu_k]\Bigg) \\
& = \frac{wN_i}{\overline \bfp(0)}\Bigg((\partial_{it}G  - \sum_{\ell=1}^d \partial_{\ell t}G\mu_\ell)dt + \sum_{k=1}^d (\partial_{ik}G - \sum_{\ell=1}^d \partial_{kl}G\mu_\ell)d\mu_k^{FV} \\
 &\qquad \qquad + \frac{1}{2}\sum_{j,k=1}^d \Big(\partial_{ijk}G - 2\partial_{jk}G- \sum_{\ell=1}^d \partial_{jkl}G \mu_\ell  \\
 & \qquad \qquad \qquad   + \sum_{\ell=1}^d \frac{wN_\ell^2}{\overline \bfp(0) \overline \bfp}\partial_xh_\ell K_\ell (\partial_{j\ell}G - \sum_{m=1}^d \partial_{j m}G\mu_m)(\partial_{k\ell}G - \sum_{m=1}^d \partial_{k m}G\mu_m)\Big)d[\mu_j,\mu_k]\Bigg. \\
 & = \frac{wN_i}{\overline \bfp(0)}\Bigg((\overrightarrow{\nabla \partial_tG})^{\mu}_idt + \sum_{k=1}^d (\overrightarrow{\nabla \partial_kG})^{\mu}_id\mu_k^{FV} + \frac{1}{2}\sum_{j,k=1}^d(\overrightarrow{\nabla \partial_{jk}G})^{\mu}_id[\mu_j,\mu_k]\\
 & \qquad \qquad - \frac{1}{2}\sum_{j,k=1}^d\Big(2\partial_{jk}G -\sum_{\ell=1}^d \frac{wN_\ell^2}{\overline \bfp(0)\overline \bfp}\partial_x h_\ell K_\ell(\overrightarrow{\nabla \partial_jG})^{\mu}_\ell(\overrightarrow{\nabla \partial_kG})^{\mu}_\ell\Big)d[\mu_j,\mu_k]\Bigg).
 \end{align*}
Using the identities
 \begin{align*}
     d\mu_k^{FV} & = \frac{N_kdP_k^{FV}}{\overline \bfp} -\mu_k\sum_{j=1}^d\frac{N_jdP^{FV}_j}{\overline \bfp} + \mu_k \frac{d[\overline \bfp]}{\overline \bfp^2} -\frac{d[\bfp_k,\overline \bfp]}{\overline \bfp^2}, \\
     d[\mu_j,\mu_k] & = \frac{1}{\overline \bfp^2}(d[\bfp_j,\bfp_k] - \mu_jd[\bfp_k,\overline \bfp]-\mu_kd[\bfp_j,\overline \bfp]+\mu_j\mu_kd[\overline \bfp])
 \end{align*} we obtain
 \begin{align}
     dQ_i^{FV} & =  \frac{wN_i}{\overline \bfp(0)}(\overrightarrow{\nabla \partial_tG})^{\mu}_idt + \sum_{j=1}^d\frac{wN_iN_j}{\overline \bfp(0)\overline \bfp}\sum_{k=1}^d(\overrightarrow{\nabla \partial_kG})^{\mu}_i(\delta_{jk}-\mu_k)dP^{FV}_j   \nonumber \\
     & \quad  +\frac{wN_i}{\overline \bfp(0)} \sum_{k=1}^d\Big(\mu_k (\overrightarrow{\nabla \partial_kG})^{\mu}_i\sum_{\ell, m=1}^d\frac{N_\ell N_m}{\overline \bfp^2}d[P_\ell,P_m] - (\overrightarrow{\nabla \partial_kG})^\mu_i\sum_{\ell=1}^dN_kN_\ell\frac{d[P_k,P_\ell]}{\overline \bfp^2}\Big) \nonumber\\
     & \qquad \qquad  
     + \frac{wN_i}{2\overline \bfp(0)\overline \bfp^2}\sum_{j,k=1}^d \Big((\overrightarrow{\nabla \partial_{jk}G})^{\mu}_i - 2\partial_{jk}G + \sum_{\ell=1}^d \frac{wN_\ell^2}{\overline \bfp(0)\overline \bfp}\partial_x h_\ell K_\ell(\overrightarrow{\nabla \partial_jG})^{\mu}_\ell(\overrightarrow{\nabla \partial_kG})^{\mu}_\ell\Big) \nonumber\\
     & \qquad \qquad \qquad \qquad \quad  \times \bigg(N_jN_kd[P_j,P_k] - \sum_{m=1}^d\mu_jN_kN_md[P_k,P_m] \nonumber \\
     & \qquad \qquad \qquad \qquad \qquad  -\sum_{m=1}^d\mu_kN_jN_md[P_j,P_m]) + \sum_{m,n=1}^d\mu_j\mu_kN_mN_nd[P_m,P_n]\bigg) \nonumber\\
     &  =   \frac{wN_i}{\overline \bfp(0)}(\overrightarrow{\nabla \partial_tG})^{\mu}_idt + \sum_{j=1}^dA^Q_{ij}dP^{FV}_j  + \sum_{j,k=1}^d\Upsilon_{ijk}d[P_j,P_k], \label{eqn:Q^FV}
     \end{align}
     where in the last equality we group like terms and recall the notation \eqref{eqn:AQ} and \eqref{eqn:upsilon}.
     We are now able to obtain the full dynamics of $P$,
     \begin{align*}
     dP_i(t) & = dS_i(t) + dI_i(t) = dS_i(t) + \partial_t h_i(t,J_i(t))dt + \partial_x h_i(t,J_i(t))dJ_i(t) + \frac{1}{2}\partial_{xx}h_i(t,J_i(t))d[J_i](t) \\
     & = dS_i(t) + (\partial_t h_i(t,J_i(t)) +\partial_x h_i(t,J_i(t))b_i^J(t,Q_{[0,t]}))dt + \partial_x h_i(t,J_i(t))K_i(t,t)dQ_i(t) \\
     & \qquad \qquad \qquad \qquad \qquad\qquad \qquad \qquad \qquad \qquad + \frac{1}{2}\partial_{xx}h_i(t,J_i(t))K_i^2(t,t)d[Q_i](t),
     \end{align*}
     where we expanded out the dynamics of $J$ using \eqref{eqn:dJ}. 
     Now we substitute in for $dQ_i$ and $d[Q]_i$ using \eqref{eqn:Q^M} and \eqref{eqn:Q^FV} and collect $dP$ terms on the left hand side to get
\begin{align*}
         \sum_{j=1}^dA^P_{ij}(t,P(t),J(t))dP_j(t) & =  dS_i(t) + \partial_x h_i(t,J_i(t)) K_i(t,t) \sum_{j,k=1}^d  \Upsilon_{ijk}(t,P(t),J(t))d[P_j,P_k](t) \\
         & \hspace{-3.5cm}  + \Big(\partial_t h_i(t,J_i(t)) + \partial_x h_i(t,J_i(t))b^J_i(t,Q_{[0,t]}) + \frac{wN_i}{\overline \bfp(0)} \partial_x h_i(t,J_i(t)) K_i(t,t)  (\overrightarrow{\nabla \partial_tG})^{\mu(t)}_i(t,\mu(t))\Big)dt \\
         &  + \frac{1}{2}\partial_{xx}h_i(t,J_i(t))K_i^2(t,t)\Big(A^Q(t,P(t),J(t))d[P](t)A^Q(t,P(t),J(t))^\top\Big)_{ii}.
\end{align*}
Finally, subbing in for $d[P]$ using \eqref{eqn:[P]} and multiplying both sides by $\beta^P = (A^P)^{-1}$ yields \eqref{eqn:SDEP}. Plugging in the now deduced $dP^M$, $dP^{FV}$ and $d[P]$ terms into \eqref{eqn:Q^M} and \eqref{eqn:Q^FV} yields \eqref{eqn:SDEQ}. Finally, \eqref{eqn:SDEJ} is obtained by substituting the dynamics for $dQ$ into \eqref{eqn:dJ}.

\subsection{Proof of Theorem~\ref{thm:main}} \label{sec:main_proof}
Now that we have formally derived the SDE \eqref{eqn:SDE}, we are ready to establish Theorem~\ref{thm:main}.
\begin{proof}[Proof of Theorem~\ref{thm:main}]
We start by noting that the SDE \eqref{eqn:SDE} can be written in the standard form
\[dX(t) = \Phi(t,X_{[0,t]})dZ(t),\]
where $ X= (P,Q,J)$ is a $3d$-dimensional process, $Z = (t,S,[S])$ is the driving $(1+d+d^2)$-dimensional semimartingale and $\Phi:[0,\infty) \times C(\R^{3d}) \to  \R^{3d \times (1+d+d^2)}$ can be explicitly computed in terms of the SDE coefficients \eqref{eqn:SDE_coefficients}. 

Define the domains 
\[D_n = \{p \in (0,\infty)^d: p_i > 1/n \text{ and }\mu_i(p) > 1/n \text{ for every i}\} \times \{q \in \R^d: |q_i| < n \text{ for every } i\} \times \R^d ,\] and the corresponding exit times 
\[\xi_n = \inf\{t \geq 0: X(t) \not \in D_n\}\]
for every $n \in \N$. By inspecting the coefficients \eqref{eqn:SDE_coefficients}, recalling Assumption~\ref{ass:impact_inputs} ensuring boundedness of the derivatives of $h$ as well as the hypothesis on $G$ given in the statement of the theorem it is easily verified that $\Phi$ is bounded and Lipschitz continuous on $[0,T]\times \mathcal{D}_n$ for ever $T \geq 0$, where
\[\mathcal{D}_n = \{ \omega \in C(\R^{3d}): \omega(t)\in D_n \text{ for every }t \geq 0\}.\]It\^o's existence and uniqueness theorem (see e.g.\ \cite[Theorem~IX.2.1]{revuz1999continuous}) together with a standard localization argument yields a pathwise unique solution to \eqref{eqn:SDE} on $[0,T \land \xi_n)$. Sending $T$ and $n$ to infinity yields a pathwise unique solution on $[0,\xi)$, where $\xi = \lim_{n \to \infty} \xi_n$. To complete the proof of \ref{item:SDE} we just need to establish the claimed representation for $\xi$. We first establish \ref{item:right_process} and \ref{item:Q_additive} and then return to this step.

That $P,Q$ and $J$ are indeed the price, holdings and impact state processes from our financial model follows directly by reversing the calculations in Appendix~\ref{app:SDE_derivation} and Section~\ref{sec:heuristic} above. These are now rigorous on the lifetime $[0,\xi)$ as we start from the processes constructed in \ref{item:SDE} and by manipulations, mostly involving It\^o's formula, obtain the representations $P = S + I$, where $I$ is given by \eqref{eqn:impact} and $Q$ is given by \eqref{eqn:additive_Q_explicit}. It is clear that the solution to \eqref{eqn:SDE} is the unique such semimartingale process $(P,Q,J)$ since, again by the calculations in Section~\ref{sec:heuristic} and Appendix~\ref{app:SDE_derivation}, any processes $(P,Q,J)$ satisfying \eqref{eqn:price}, \eqref{eqn:impact} and \eqref{eqn:additive_Q_explicit} must also satisfy the SDE \eqref{eqn:SDE}, which by pathwise uniqueness must then coincide with the processes obtained in \ref{item:SDE}. This proves \ref{item:right_process}. 

Item \ref{item:Q_additive} follows from noting that the holdings process $Q$  given by \eqref{eqn:additive_Q_explicit} is of the form $Q_i(t) = \frac{wN_i}{\overline \bfp(0)}(\partial_i  G(t,\mu(t)) + C(t))$ for $t \in [0,\xi)$, where $C(t)$ is a scalar process common to all $i$. Plugging into the relative wealth equation \eqref{eqn:relative_wealth} and using the fact that $\sum_{i=1}^d d\mu_i(t) = 0$ yields
\[dV^Q(t) = \nabla G(t,\mu(t))^\top d\mu(t) + \frac{1}{2}\sum_{i=1}^d\frac{\bfp (0)}{w\bfp(t)}d[I_i,Q_i](t).\] The ensuing computations in Section~\ref{sec:heuristic} now rigorously lead to \eqref{eqn:additive_master_impact} establishing that $Q$ is additively functionally generated by $G$ on $[0,\xi)$.

We now return to establishing the representation for $\xi$ given by \eqref{eqn:xi}.
From the definition of $\xi_n$ and $D_n$ above it is clear that $\xi$ corresponds to the first time that $P_i(t) = 0$ or $\mu_i(t) = 0$ or $|Q_i(t)| = + \infty$. Since $\mu_i(t) = N_iP_i(t)/\overline{\bfp}(t)$ we see that if $P_i(t) = 0$ then either $\mu_i(t) = 0$ or, if not, then it must be because $\overline \bfp(t) = 0$ as well.
% Comment for me: we didn't need to ensure that $\overline \bfp(t) < n$ in the definite of $D_n$. What this means is that you cannot have $\overline \bfp(t) = \infty$ without $\mu_i(t) = 0$ for some $i$. Although it is possible theoretically with, say, all $P_i$'s being the same and going to infinity, none of the SDE coefficients blow up in this case so it wouldn't happen in finite time. 
 As such, to establish the representation of $\xi$ and complete the proof of \ref{item:SDE} we will show that if $|Q_i(\xi)| = \infty$ then $\mu_j(\xi) = 0$ for some $j$ or $\overline \bfp(\xi) = 0$.

We begin by expanding out only the quadratic variation terms 
 in \eqref{eqn:additive_Q_explicit}. Note that since the diffusion coefficient $\beta^P$ is a function of $t, P(t)$ and $J(t)$, but not of $Q_{[0,t]}$, it follows that $d[\mu](t) = \Psi(t,P(t),J(t))d[S](t)$ for some $\R^{d\times d}$ valued function $\Psi$. Then expanding the quadratic variations term in \eqref{eqn:additive_Q_explicit} establishes that $Q_i$ has the representation
 \begin{align*} 
 Q_i(t) = & \frac{wN_i}{\overline \bfp(0)}\Bigg(\partial_i G(t,\mu(t)) + 1 + G(t,\mu(t)) - G(0,\mu(0)) - \nabla G(t,\mu(t))^\top \mu(t) \\
 & \qquad - \int_0^t \partial_t G(s,\mu(s))ds + \sum_{j,k=1}^d\widetilde\Psi_{jk}(t,P(t),J(t))d[S_j,S_k](t)\Bigg), 
\end{align*} 
where $\widetilde \Psi$ is some $\R^{d \times d}$ valued function which aggregates all of the quadratic variation terms. Although $\widetilde \Psi$ can be explicitly computed in a similar fashion as in the derivation of \eqref{eqn:Q^FV}, we will not need its explicit form. We only note, by the boundedness of $G$ and it's derivatives on $[0,T] \times \{\mu: \mu_i \geq 1/n \text{ for every i}\}$, as well as the boundedness of $\overline \bfp^{-1}(p)$ on $\{p:p_i \geq 1/n\}$, that each element $\widetilde \Psi_{jk}$ is bounded on $[0,T] \times D_n$. Hence we obtain the estimate
\begin{align*}
 \sup_{t \leq T \land \xi_n}|Q_i(t)| & \leq \frac{wN_i}{\overline \bfp(0)}\Bigg(1+ \sup_{t \leq T \land \xi_n}|\partial_i G(t,\mu(t))| + 2\sup_{t \leq T \land \xi_n}|G(t,\mu(t))| + \sup_{t \leq T \land \xi_n}|\nabla G(t,\mu(t))^\top \mu(t)| \\
    & \qquad \quad + \sup_{t \leq T \land \xi_n}|\partial_t G(t,\mu(t)|T + \sum_{j,k=1}^d \sup_{t \leq T \land \xi_n}|\widetilde \Psi_{jk}(t,P(t),J(t))|\sqrt{[S_j](T)}\sqrt{[S_k](T)}\Bigg),
\end{align*}
where we used the Kunita--Watanabe Inequality \cite[Corollary~IV.1.16]{revuz1999continuous}  to handle the quadratic covariation of $S$ terms. The right hand side only (possibly) tends to $+\infty$ as $n \to \infty$ if $\mu_j(t) \to 0$ for some $j$ or $\overline \bfp(t) \to 0$. Hence $\lim_{n \to \infty} \sup_{t \leq T \land \xi_n} |Q_i(t)| = \infty \implies \mu_j(\xi) = 0$ for some $j$ or $\overline \bfp(\xi) = 0$. This completes the proof of \ref{item:SDE}. 

