The purpose of this section is to prove Lemma~\ref{lem:relarb},
% We start off with defining several constants, which will play important rolls in the ensuing computations,
% \begin{align}
% \underline \bfi & = \\
% \overline \bfi^T & =  \\
% \kappa_P & = \\
% \overline \nu & =
% \end{align}
which we break up into the proof of several smaller lemmas. We begin by introducing some notation, including the constant $\overline \nu$ appearing in Lemma~\ref{lem:relarb}. In this section $\|x\|_p$ denotes the $L^p$ norm of a vector $x \in \R^d$ for $p \in [1,\infty]$. When $p = 2$, we simply write $\|x\|$ without the subscript. Note that $\widehat h_i$ is nondecreasing and, as such, admits a pseudoinverse which we take to be \[\widehat h_i^{-1}(x) = \begin{cases}
    \inf\{y \geq 0: h_i(y) = x\}, & x \geq 0, \\
    \sup\{y \leq 0: h_i(y) = x\}, & x < 0. 
\end{cases}\] Additionally, Assumption~\ref{ass:impact_inputs} ensures that $\widehat h_i'$ is bounded which implies that $\overline {\widehat h'}_i := \sup_{ x \in \R} \widehat h_i'(x) < \infty$.
Set $\kappa_P  = \kappa_S\frac{1-\delta_S}{1-\delta_S/2}$ 
and define
\begin{equation} \label{eqn:bar_nu}
    \overline \nu = \min_{i \in \{1,\dots,d\}}\min\{\nu^0,\nu^1_i,\nu^2_i\},
\end{equation} 
% I included the bound by 1 to remove $\bar \nu$ from the definition of $C$.
where
\begin{align*}
 \nu^0 & = \frac{\overline \bfp(0)\kappa_S(1-\delta_S)}{3w\|N\|_\infty\|N\|_1\|\overline {\widehat h'}\|_\infty\|\overline K\|_\infty (1-\delta_S/4)}, \\
 \nu^1_i & = -\frac{2\overline \bfp(0)}{5wN_i\overline K_i}\widehat h^{-1}_i\left(\frac{-\kappa_S\ell_S}{2\overline \phi_iN_i}\frac{\delta_S}{1-\delta_S/2}\right), \\
 \nu^2_i & = \frac{\overline \bfp(0)}{wN_i\overline K_i}\frac{1}{2+CT^*}\widehat h^{-1}_i\left(\frac{\delta_S(1-\delta_S)\kappa_S}{4N_i(1-\delta_S/2)}\right)
\end{align*}
with 
\[
 C  = \left(\frac{1}{2} +\frac{(\min_{i\in \{1,\dots,d\}}\min\{\nu^0,\nu^1_i\})w\|N^2\|_\infty\|\overline \phi\|_\infty\|\overline{\widehat h'}\|_\infty\|\overline K\|_\infty}{2\overline \bfp(0)\kappa_P}\right) \frac{4d^2\sigma_S^2\|N^{-1}\|_1^2\|N\|^2 (\kappa_S)^2}{(\kappa_P)^2}.
\]

Next, we turn towards stating and proving a technical lemma, which is a crucial component in the proofs to come. To state this lemma we introduce the following notation
\begin{align*}
    \underline I_i & = -\overline \phi_i \widehat h_i\left(-\bar \nu\frac{5wN_i\overline K_i}{2\overline \bfp(0)}\right), && \underline \bfi  = \sum_{i=1}^d N_i\underline I_i, \\
\overline I_i(t)  & = \phi\widehat h_i\left(\overline \nu\frac{wN_i\overline K_i}{\overline \bfp(0)}(2+Ct)\right),
&& \overline \bfi(t) = \sum_{i=1}^d N_i\overline I_i(t).
\end{align*}
It should be noted that $\underline I_i$ is nonnegative because $\widehat h_i(x) \leq 0$ whenever $ x \leq 0$.
\begin{lem} \label{lem:impact_bound}
    Let the setup and assumptions of Lemma~\ref{lem:relarb} hold. Then we have the bound
    % \[-\frac{2wN_i\overline K_i}{\overline \bfp(0)}\nu \leq J_i(t) \leq \overline J_i + \nu\frac{wN_i\overline K_i}{\overline \bfp(0)}(2+Ct)\]
    \begin{equation} \label{eqn:impact_bound}
        -\underline I_i\leq I_i(t) \leq \overline I_i(t)
    \end{equation}
    for every $i=1,\dots,d$ and $t \in[0,\xi)$.
\end{lem}
\begin{proof}
We have from \eqref{eqn:additive_Q_explicit} that \begin{align*}
    Q_i(t) & = \frac{wN_i}{\overline \bfp(0)}\left(1 + \nu\psi(t)F_i(\mu(t))+\Gamma(t)\right),
    % \\
    % & = \frac{wN_i}{\overline \bfp(0)}(\Gamma(t) + 1 + \frac{\nu \psi(t)}{2}(\|\mu(t)\|^2 + \|\mu(0)\|^2 - 2\mu_i(t))), 
\end{align*}  
where $\Gamma$ is given by \eqref{eqn:Gamma} and $F_i(\mu) = 1+\frac{1}{2}\|\mu\|^2 - \mu_i$.
% As such, we have that
% \[Q_i(t) \geq \frac{wN_i}{\overline \bfp(0)}(1-\nu\int_0^{T_0}\psi'(t)(1-\frac{1}{2}\|\mu(t)\|^2)dt - \nu\psi(t)) \geq \frac{wN_i}{\overline \bfp(0)}(1-2\nu)\]
% so that $Q$ is long-only for $\nu \leq 1/2$. 
From \eqref{eqn:impact} and the assumption on $J_i^0$ we have 
\begin{align}
    J_i(t) & = \frac{wN_i}{\overline \bfp(0)}\int_0^t K_i(t,s)d\Gamma(s) + \frac{wN_i\nu}{\overline \bfp(0)}\int_0^t K_i(t,s)d(\psi F_i(\mu))(s),\nonumber \\
    &  = \frac{wN_i}{\overline \bfp(0)}\int_0^t K_i(t,s)d\Gamma(s) + \frac{wN_i\nu}{\overline \bfp(0)}\left(K_i(t,t)\psi(t)F_i(\mu(t)) - \int_0^t \partial_s K_i(t,s)\psi(s)F_i(\mu(s))ds\right), \label{eqn:J_relarb}
\end{align}
where we recalled that $\psi(0) = 0$ in the final step.

We now work towards bounding $J_i$ from above and below. First, we note that $0 \leq \psi(t) \leq 1$ and $1/2 \leq F_i(\mu) \leq 3/2$. Next, using that all of the terms making up $\Gamma$ in \eqref{eqn:Gamma} are increasing, by our assumptions on $G$ and $\psi$, with the exception of the term $t \mapsto- \int_0^{t\land T_0} \partial_t G(s,\mu(s))ds$ we get the lower bound
\[J_i(t) \geq -\frac{wN_i\nu}{\overline \bfp(0)}\int_0^{t \land T_0} K_i(t\land T_0,s)\psi'(s)(1-\frac{1}{2}\|\mu(s)\|^2)ds -\frac{3wN_i\nu\overline K_i}{2\overline \bfp(0)} \geq -\frac{5wN_i\overline K_i}{2\overline \bfp(0)}\overline \nu.\]
Applying $h_i$ to both sides and bounding $\phi_i(t)$ by $\overline \phi_i$ gives the lower bound in \eqref{eqn:impact_bound}.

As a consequence we see that 
$P_i(t) \geq S_i(t) -\underline I_i$. Since $\overline \nu \leq \nu^1_i$ we have that
$\underline I_i \leq \frac{\kappa_S\ell_S\delta_S}{2N_i(1-\delta_S/2)}$,
from which it follows that 
\[\underline \bfi \leq \frac{d\kappa_S\ell_S\delta_S}{2(1-\delta_S/2)} \leq \frac{\kappa_S\delta_S}{2(1-\delta_S/2)},\]
where we used the fact that $d\ell_S \leq 1$.
Hence, we see that
\begin{align}
    \overline \bfp(t) & \geq \overline \bfs(t) - \underline \bfi 
     \geq \kappa_S - \frac{\kappa_S\delta_S}{2(1-\delta_S/2)} = \kappa_P.
     \label{eqn:bfp_lower_bound_S} 
\end{align}
To obtain an upper bound for $J_i$ we start by bounding $\Gamma$ from above. For our choice of generating function we have from \eqref{eqn:Gamma} that
\begin{align} \Gamma(t) & = -\nu\int_0^t \psi'(t)(1-\frac{1}{2}\|\mu(s)\|^2)ds + \frac{\nu}{2}\int_0^t\sum_{i=1}^d \psi(s)d[\mu_i](s) \\
& \qquad + \frac{\nu^2}{2}\int_0^t \sum_{i=1}^d \frac{wN_i^2}{\overline \bfp(0) \overline \bfp(t)}\phi_i(t)\widehat h_i'(J_i(t))K_i(t,t)d\Big[\frac{1}{2}\|\mu\|^2 - \mu_i\Big](s) \nonumber  \\
& \leq \nu + \frac{\nu }{2}\sum_{i=1}^d [\mu_i](t) \\
& \qquad + \nu \frac{(\min_{i\in \{1,\dots,d\}}\min\{\nu^0,\nu^1_i\})w\|N^2\|_\infty\|\overline \phi\|_\infty\|\overline{\widehat h'}\|_\infty\|\overline K\|_\infty}{2\overline \bfp(0)\kappa_P}\sum_{i=1}^d\left([\|\mu\|^2](t) + 2[\mu_i](t)\right). \label{eqn:Gamma_QV_bound}
\end{align}
  It just remains to bound the quadratic variation terms. First notice by It\^o's formula and the Kunita--Watanabe inequality \cite[Corollary~IV.1.16]{revuz1999continuous} that 
\begin{align}
    [\|\mu\|^2](t) & = 4\sum_{i,j=1}^d\int_0^t\mu_i(s)\mu_j(s) d[\mu_i,\mu_j](s) \leq 4\sum_{i,j=1}^d\sqrt{\int_0^t\mu_i^2(s)d[\mu_i(s)]}\sqrt{\int_0^t\mu_j^2(s)d[\mu_j(s)]} \nonumber \\
    & \leq 4\left(\sum_{i=1}^d\sqrt{[\mu_i](t)}\right)^2 \leq 4d\sum_{i=1}^d [\mu_i](t) \label{eqn:QV_norm_bound},
\end{align}  
where the last inequality followed by Cauchy--Schwarz. Next we estimate that
\begin{equation} \label{eqn:QV_mu_bound}
    d[\mu_i]= d\left[\int_0^\cdot \frac{d\bfp_i}{\overline \bfp} - \int_0^\cdot \frac{\mu_i}{\overline \bfp}d\overline \bfp\right] \leq \frac{2}{\overline \bfp^2}(d[\bfp_i] + \mu_i^2d[\overline \bfp]) \leq \frac{2}{\overline \bfp^2}(N_i^2d[P_i] + \mu_i^2d\sum_{j=1}^d N_j^2d[P_j]).
\end{equation}
Recalling the dynamics of $P$ given by \eqref{eqn:SDEP} we see, omitting function evaluations for brevity, that
\begin{align*}
    d[ P_i]& \leq \sum_{j=1}^d d[P_j]=  \mathrm{Tr}(\beta^Pd[S](\beta^P)^\top) \\ 
    & = \mathrm{Tr}\left((\beta^P)^\top \beta^P\mathrm{diag}(N^{-1})\mathrm{diag}(\bfs (t))d[\log S](t)\mathrm{diag}(\bfs (t))\mathrm{diag}(N^{-1})\right)  \\
    & \leq \mathrm{Tr}((\beta^P)^\top\beta^P)\overline \bfs^2(\sum_{j=1}^d N_j^{-1})^2\sigma^2 dt  \leq d\sigma^2\|N^{-1}\|_1^2 \overline \bfs^2dt,
    \end{align*}
where in the second equality we used the cyclical property of trace and expanded out terms to obtain $d[\log S]$ in place of $d[S]$. In the final two inequalities we used the fact that the trace of a product of positive definite matrices is less than the product of the traces and that the eigenvalues of $(\beta^P)^\top\beta^P$ are bounded by one courtesy of Proposition~\ref{prop:AP}. Substituting this into \eqref{eqn:QV_mu_bound} and writing in integral form yields the bound
\begin{align}
[\mu_i](t) & \leq 2d\sigma^2\|N^{-1}\|_1^2\left(N_i^2\int_0^t \frac{\overline \bfs^2(s)}{\overline \bfp^2(s)}ds +\|N\|^2 \int_0^t \mu_i^2(s)\frac{\overline \bfs^2(s)}{\overline \bfp^2(s)}ds\right) \nonumber \\
& \leq 4d\sigma^2\|N^{-1}\|_1^2\|N\|^2\int_0^t \frac{\overline \bfs^2(s)}{\overline \bfp^2(s)}ds  
 \leq 4d\sigma^2\|N^{-1}\|_1^2\|N\|^2\int_0^t \frac{\overline \bfs^2(s)}{(\overline \bfs(s)-\underline \bfi)^2}ds \nonumber  \\
& \leq  4d\sigma^2\|N^{-1}\|_1^2\|N\|^2 \frac{(\kappa_S)^2}{(\kappa_S-\underline \bfi)^2}t \leq  4d\sigma^2\|N^{-1}\|_1^2\|N\|^2 \frac{(\kappa_S)^2}{(\kappa_P)^2}t \label{eqn:QV_mu_final_bound},
\end{align}    
where in the second to last inequality we used that the function $x \mapsto \frac{x}{x-c}$ for $c > 0$ is decreasing on $(c,\infty)$ and in the final one used \eqref{eqn:bfp_lower_bound_S}. From \eqref{eqn:Gamma_QV_bound}, \eqref{eqn:QV_norm_bound} and \eqref{eqn:QV_mu_final_bound} we obtain the bound
\[\Gamma(t) \leq \nu(1+Ct).\]
% \[C = \left(\frac{1}{2} +\frac{\overline \nu w(4d+2)\|N^2\|_\infty\|\overline \phi\|_\infty\|\overline{\widehat h'}\|_\infty\|\overline K\|_\infty}{2\overline \bfp(0)\kappa_P}\right) \frac{4d^2\sigma^2\|N^{-1}\|_1^2\|N\|^2 (\kappa_S)^2}{(\kappa_P)^2}. \]
Finally, as a consequence of this estimate using \eqref{eqn:J_relarb} we obtain the upper bound
\begin{equation} \label{eqn:J_bound}
    J_i(t) \leq  \nu\frac{wN_i\overline K_i}{\overline \bfp(0)}(2+Ct)\leq \overline  \nu\frac{wN_i\overline K_i}{\overline \bfp(0)}(2+Ct).
\end{equation}
Applying $\widehat h_i$ to both sides, multiplying by $\phi_i(t)$ and bounding it by $\overline \phi_i$ completes the proof. \end{proof}


As a consequence of Lemma~\ref{lem:impact_bound} we obtain nonexplosion of the SDE \eqref{eqn:SDE}.
% have that
% \begin{equation} \label{eqn:market_cap_bound}
% \overline \bfs(t) - \underline \bfi \leq \overline \bfp(t) \leq \overline \bfs(t) + \overline \bfi^T,    
% \end{equation}
