\begin{lem} \label{lem:nonexplosion}
    Let the setup and assumptions of Lemma~\ref{lem:relarb} hold. Then Assumption~\ref{ass:nonexplosion} holds.
    % $\P(\xi < \infty) =  0$, where $\xi$ is the explosion time of the SDE \eqref{eqn:SDE} as in Theorem~\ref{thm:main}.
\end{lem}
\begin{proof}
    From \eqref{eqn:bfp_lower_bound_S} we have that the total market capitalization $\overline \bfp(t)$ is strictly positive.
    Hence, from the representation \eqref{eqn:xi} the proof will be complete once we show that $\mu_i$ is positive almost surely for every $i$. To this end we use the market weight floor for the frictionless market to see that
    \begin{align*}
        \mu_i(t) = \frac{\bfs_i(t) + N_iI_i(t)}{\overline \bfp(t)} & = \frac{\overline \bfs_i(t) + N_iI_i(t)}{\overline \bfs(t)}\frac{\overline \bfs(t)}{\bfs(t) + \sum_{j=1}^d N_jI_j(t)} \\
        & \geq \left(\ell_S - \frac{N_i\underline I_i}{\kappa_S}\right)\left(\frac{\overline \bfs(t)}{\overline \bfs(t) + \overline \bfi(t)}\right)
        \geq \left(\ell_S - \frac{N_i\underline I_i}{\kappa_S}\right)\left(\frac{\kappa_S}{\kappa_S + \overline \bfi(t)}\right).
    \end{align*}
    In the second inequality we used the fact that the function $x \mapsto x/(x+c)$ is an increasing function for $c > 0$. Since $\overline \nu \leq \nu_i^1$ we have that that $N_i\underline I_i/\kappa_S \leq \frac{3}{4}\frac{\delta_S}{1-\delta_S/4}\ell_S < \ell_S$ so that $\ell_S - \frac{N_i\underline I_i}{\kappa_S} > 0$. This completes the proof. 
\end{proof}



\begin{lem} \label{lem:diversity}
    Let the setup and assumptions of Lemma~\ref{lem:relarb} hold. Then there exists $\theta > 0$ such that the observed market is diverse on $[0,T^*+\theta]$ with diversity constant $\delta_P = \delta_S/4$. 
\end{lem}
\begin{proof}
First we note that since $\nu < \overline \nu \leq \nu^2_i$ for every $i$, there exists a $\theta > 0$ such that 
\begin{equation}\label{eqn:nu2}
\nu \leq \widetilde \nu^2_i := \frac{\overline \bfp(0)}{wN_i\overline K_i}\frac{1}{2+C(T^*+\theta)}\widehat h^{-1}_i\left(\frac{\delta_S(1-\delta_S)\kappa_S}{4N_i(1-\delta_S/2)}\right).
\end{equation}
Using diversity of the frictionless market and Lemma~\ref{lem:relarb} we have that
\begin{align}
    \mu_i(t)  = \frac{\bfs_i(t) + N_iI_i(t)}{\overline \bfs(t) + \sum_{j=1}^d N_jI_j(t)} &  \leq \frac{(1-\delta_S)\overline \bfs(t) + N_i I_i(t)}{\overline \bfs(t)  - \underline \bfi} \leq \frac{(1-\delta_S)\kappa_S + N_i I_i(t)}{\kappa_S -\underline \bfi} \nonumber \\
    & \leq \frac{(1-\delta_S)\kappa_S + N_i I_i(t)}{\kappa_P} = 1- \frac{\delta_S}{2} + \frac{N_iI_i(t)}{\kappa_P}, \label{eqn:mu_bound}
\end{align}
where in the second to last inequality we used he fact that $x \mapsto (ax+b)/(x-c)$ is a decreasing function on $(c,\infty)$ whenever $a,b,c > 0$ and in the final one we used \eqref{eqn:bfp_lower_bound_S}. Next, from the first inequality in \eqref{eqn:J_bound} and the fact that $\nu$ satisfies \eqref{eqn:nu2} we readily see that for $t \in [0,T^*+\theta]$,
\[\frac{N_iI_i(t)}{\kappa_P} \leq \frac{N_i}{\kappa_P}\widehat h\left(\widetilde \nu^2_i\frac{wN_i\overline K_i}{\overline \bfp(0)}(2+C(T^*+\theta))\right) = \frac{\delta_S}{4}.\] 
Together with \eqref{eqn:mu_bound} this shows that $\mu_i(t) \leq 1-\delta_S/4$ for all $i$ and $t \in [0,T^*+\theta]$ completing the proof.
\end{proof}
