As a next step we estimate the largest eigenvalue of $A^P$ given by \eqref{eqn:AP}. To facilitate this computation set
\[X_{ij}(t) = \frac{wN_iN_j\phi_i(t)\widehat h_i'(J_i(t))K_i(t,t)}{\overline \bfp(0)\overline \bfp(t)}\] and note that with our choice of $G$ we have 
\[A^P_{ij}(t,P(t),J(t)) = \begin{cases}
    1 + \nu \psi(t) X_{ii}(t)(1-2\mu_i(t) + \|\mu(t)\|^2), & \text{if } i = j, \\
    \nu \psi(t) X_{ij}(t)(\|\mu(t)\|^2 - \mu_i(t) - \mu_j(t)), & \text{if } i \ne j,
\end{cases}\]
where we omitted function evaluations for brevity.
Looking at the sum of the off-diagonal entries we have that
\begin{equation} \label{eqn:R_bound}
    R_i(t) := \sum_{j\ne i} |A^P_{ij}(t,P(t),J(t))| \leq \nu \frac{wN_i\|N\|_1\overline{\widehat h'_i}\overline K_i}{\overline \bfp(0) \kappa_P}.
\end{equation}
By the Ger\v{s}gorin circle theorem \cite[Theorem~6.1.1]{horn2013matrix} we have that the eigenvalues of $A^P(t,P(t),J(t))$ are within radius $R_i(t)$ of one of the diagonal entries of $A^P_{ii}(t,P(t),J(t))$.
This leads to the estimate
\[\lambda_{\max}(A^P(t,P(t),J(t))) \leq \max_{i=1,\dots,d}(A^P_{ii}(t,P(t),J(t)) + R_i(t)) \leq  1 + 3\nu \frac{w\|N_\infty\|\|N\|_1\|\overline {\widehat h'}\|_\infty\|\overline K\|_\infty}{\overline \bfp(0)\kappa_P} \leq 2,\]where the last line followed since $\nu < \overline \nu \leq \nu^0$.
% and note that $X_{11}X_{22} = X_{12}X_{21}$, where we omit functional evaluations for brevity.
%  With this in hand we have
% \begin{align*}
%    \det(A^P) & = (1 - X_{11}\overleftrightarrow{\nabla^2 G}^\mu_{11})(1-X_{22}\overleftrightarrow{\nabla^2 G}^\mu_{22}) -X_{12}\overleftrightarrow{\nabla^2 G}^\mu_{12}X_{21}\overleftrightarrow{\nabla^2 G}^\mu_{21} \\
%    & = 1 - X_{11}\overleftrightarrow{\nabla^2 G}^\mu_{11} - X_{22}\overleftrightarrow{\nabla^2 G}^\mu_{22} +X_{11}X_{22}\det(\overleftrightarrow{\nabla^2 G}^\mu) 
%    = 1 - X_{11}\overleftrightarrow{\nabla^2 G}^\mu_{11} - X_{22}\overleftrightarrow{\nabla^2 G}^\mu_{22} 
% \end{align*}
% where in the last step we used the fact that $\det(\overleftrightarrow{\nabla^2 G}^\mu) = 0$, which follows from \eqref{eqn:arrowM_PSD}. Evaluating using our choice of $G$ yields
% \[\det(A^P) = 1 + (X_{11}+X_{22})(1-2\mu_1(1-\mu_1)) \leq 1 + \overline \nu\frac{w\|N\|^2\|\overline\phi\|_\infty\|\overline {\widehat h'}\|_\infty \|\overline K\|_\infty}{\overline \bfp(0)\overline \bfp(t)}.\]
% Since both eigenvalues of $A^P$ are at least one by Proposition~\ref{prop:AP} and $\det(A^P) = \lambda_{\max}(A^P)\lambda_{\min}(A^P)$, it follows that $\lambda_{\max}(A^P) \leq 1+C$.
As such,
\[\lambda_{\min}(\beta^P(t,P(t),J(t))) = \lambda_{\max}^{-1}(A^P(t,P(t),J(t))) \geq \frac{1}{2}.\]
With this estimate in hand, we are ready to obtain a lower bound on the the smallest eigenvalue of $a^P(t)$. Indeed taking any vector $x \in \R^d$, we see from \eqref{eqn:ap} that
\begin{align*}
    x^\top a^P(t)x & \geq \frac{\lambda_{\min}(a^S(t))}{\|N\|_\infty\|N^{-1}\|_\infty} \left(\min_{i \in \{1,\dots,d\}}S_i^2(t)\right)\lambda_{\min}(\beta^P(t,P(t),J(t)))^2\left(\min_{i \in \{1,\dots,d\}}\frac{1}{P_i^2}\right)\|x\|^2 \\
    & \geq \frac{\epsilon_S}{4\|N\|_\infty\|N^{-1}\|_\infty} \left(\min_{i \in \{1,\dots,d\}}\mu_i^S(t)\right)^2\left(\min_{i \in \{1,\dots,d\}}\frac{1}{\mu_i(t)}\right)^2 \frac{\overline \bfs^d(t)}{\overline \bfp^d(t)} \|x\|^2\\
    & \geq \epsilon_S \frac{\ell_S^2\kappa_S^d}{4\|N\|_\infty\|N^{-1}\|_\infty(\kappa_S-\underline \bfi)^d}\|x\|^2 \geq \epsilon_P\|x\|^2,
\end{align*}
where in the last line we used \eqref{eqn:bfp_lower_bound_S} to obtain $\epsilon_P$.
This completes the proof.
\end{proof}
