\section{Experiments \& Discussion}

\subsection{RNA Inverse Folding}
\label{sec:rna_if}
\subsubsection{Setup}
\paragraph{Dataset.} This study leverages two datasets for RNA inverse folding, namely, \textbf{RNAsolo} \citep{rnasolo} and \textbf{RNA-Puzzles} \citep{puzzle}, following the precedent set by previous research \citep{rdesign}. These datasets encompass the RNA tertiary structure and sequence. The data splitting pursued parallels the methodology adopted by Tan et al. \citep{rdesign}.

\paragraph{Evaluation metrics.} Our principal assessment tools for RNA inverse folding include structure recovery metrics such as \textbf{TM-score} and \textbf{RMSD}, and sequence recovery metrics comprising native structure recovery (\textbf{NSR}) and Macro-F1 (\textbf{M-F1}) score, following the approach utilized in \citep{rdesign}. The NSR is described as Eq.~\ref{eq:nsr} and Macro-F1 score is computed as described in \citep{rdesign}:
\begin{equation*}
    \text{M-F1} = \frac{1}{|T|} \sum_{t\in\{{\rm A, U, C, G}\}}^{T} 2\times \frac{P_t \times R_t}{P_t + R_t},
\end{equation*}
where $P_t$ and $R_t$ are the precision and recall of token $c$ respectively.
\paragraph{Compared approaches.} Following Tan et al. \citep{rdesign}, we compare our RiFold with sequence-based models (\textit{SeqRNN} and \textit{SeqLSTM}), tertiary structure-based models (\textit{RDesign} \citep{rdesign}, \textit{StructMLP}, \textit{StructGNN}, \textit{GraphTrans} \citep{StructGNN}, and \textit{PiFold} \citep{pifold}), and secondary structure-based models (\textit{MCTS-RNA} \citep{MCTS}, \textit{LEARNA} \citep{LEARNA}, \textit{eM2dRNAs} \citep{eM2dRNAs}, and \textit{aRNAque} \citep{aRNAque}).

