\subsection{Method Details}
\subsubsection{Beam Search}
The process of beam search is described in Algorithm~\ref{alg:bs1} and Algorithm~\ref{alg:bs2}. The purpose of beam search is to extend the search space the sample process and limit the complexity of the algorithm at the same time. We have two types of beam search, \ie, \textbf{decode position based} and \textbf{decode type based}. 
The decode position-based beam search algorithm starts from different positions to begin our stochastic autoregressive decoding process. For we always choose the decode position with the highest confidence, we will choose top $w$, \ie, beam width, the most confident decoded positions, as the start decode position. Finally, we calculate the average confidence of $w$ decoded sequences and select the best one as the final sample result. The decode type-based beam search algorithm starts from the same decode position but uses different acid types. Subsequently, we select the sequence with the highest confidence from all candidate sequences. Typically, the beam width $w$ is set as the number of candidate types, \ie, four for ribonucleic acids in RNA inverse folding task, to acquire the best performance.

\begin{algorithm*}[h!]
	\caption{Decode position-based beam search} 
 	\renewcommand{\algorithmicrequire}{\textbf{Input:}}
	\renewcommand{\algorithmicensure}{\textbf{Output:}}
	\label{alg:bs1} 
	\begin{algorithmic}
		\REQUIRE $\text{sequence length } N, \text{latent vector } \mathbf{h_V}, \text{beam width } w$ 
            \STATE $i \gets 1$, $\mathbf{h_S\gets0}$
            \STATE $\text{decoded position}\gets \emptyset$, $\text{start positions} \gets \emptyset$, candidate sequence $\gets\emptyset$
            \STATE $\text{probs}\gets \text{decoder}(\mathbf{h_V,h_S})$
            \STATE start position $\{a_1,a_2,\cdots,a_w\}\gets$ top $w$ highest probs' position
            % \STATE start from $\{a_1,a_2,\cdots,a_w\}$
            \FOR{$j=1$ to $w$}
            \STATE Add $a_j$ into decoded position
            \REPEAT
            \STATE Update $\mathbf{h_S}$ according to decoded position
            \STATE $\text{probs}\gets \text{decoder}(\mathbf{h_V,h_S})$
            \STATE $a_\text{max}\gets \text{arg}\max{(\text{probs})}$
            \STATE Add $a_\text{max}$ into decoded position
            \STATE $i\gets i+1$
            \UNTIL{$ i=N $}
            \STATE finish decoding $s_j$
            \STATE Add $s_j$ into candidate sequence
            \STATE decoded position $\gets \emptyset$, $i\gets 1$
            \ENDFOR
            \STATE $s\gets$select best candidate sequence from $\{s_1,\cdots,s_w\}$
		\ENSURE $\text{decoded sequence } s $ 
	\end{algorithmic} 
\end{algorithm*}

\begin{algorithm*}[h!]
	\caption{Decode type-based beam search} 
 	\renewcommand{\algorithmicrequire}{\textbf{Input:}}
	\renewcommand{\algorithmicensure}{\textbf{Output:}}
	\label{alg:bs2} 
	\begin{algorithmic}
		\REQUIRE $\text{sequence length } N, \text{latent vector } \mathbf{h_V}, \text{beam width } w$ 
            \STATE $i \gets 1$, $\mathbf{h_S\gets0}$
            \STATE $\text{decoded position}\gets \emptyset$, $\text{start positions} \gets \emptyset$, candidate sequence $\gets\emptyset$
            \STATE $\text{probs}\gets \text{decoder}(\mathbf{h_V,h_S})$
            \STATE $a_\text{max}\gets \text{arg}\max{(\text{probs})}$
            \STATE start type$\gets \{x_1,\cdots,x_w\}$
            \FOR{$j\gets 1$ to $w$}
                \STATE Set the type of $a_\text{max}$ as $x_j$
                \STATE Add $a_\text{max}$ into decoded position
                \REPEAT
                    \STATE Update $\mathbf{h_S}$ according to decoded position
                    \STATE $\text{probs}\gets \text{decoder}(\mathbf{h_V,h_S})$
                    \STATE $a_\text{max}\gets \text{arg}\max{(\text{probs})}$
                    \STATE Add $a_\text{max}$ into decoded position
                    \STATE $i\gets i+1$
                \UNTIL{$i=N$}
                \STATE finish decoding $s_j$
                \STATE Add $s_j$ into candidate sequence
                \STATE decoded position $\gets \emptyset$, $i\gets 1$
            \ENDFOR
	\end{algorithmic} 
\end{algorithm*}

