%\item[(2)]The coefficient of $1$ in the $\mathbb{Z}$-linear expression of $b_{i}b_{i^{*}}$ with respect to the $\mathbb{Z}_{+}$-basis is $1$;
%\item[(3)]For $j\neq i^{*}\in I$, the coefficient of $1$ in the $\mathbb{Z}$-linear expression of $b_{i}b_{j}$ with respect to the $\mathbb{Z}_{+}$-basis is $0$.
%\end{itemize}

%Let $(R,\{b_{i}\}_{i=1}^{m})$ be a $\mathbb{Z}_{+}$-ring. Recall that $R$ is said to be \textit{transitive}, if for any basis elements $b_{i}$ and $b_{j}$, there are basis elements $b_{k}$ and $b_{t}$ such that the coefficients of $b_{k}$ in the $\mathbb{Z}$-linear expressions of $b_{i}b_{k}$ and $b_{t}b_{j}$ respect to the $\mathbb{Z}_{+}$-basis are non-zero. For example, the Grothendieck ring $\text{Gr}(H)$ of any finite dimensional Hopf algebra $H$ over $\mathbbm{k}$ is transitive.

%For any transitive unital $\mathbb{Z}_{+}$-ring $(R,\{b_{i}\}_{i=1}^{m})$, one considers the \textit{Frobenius-Perron dimension function} $\text{FPdim}:R\to\mathbb{C}$, which is the unique group homomorphism satisfying that for each basis element $b_{i}$, $\text{FPdim}(b_{i})$ is the maximal non-negative eigenvalue of the matrix of the left multiplication by $b_{i}$. In fact, the Frobenius-Perron dimension function $\text{FPdim}:R\to\mathbb{C}$ is the unique ring homomorphism from $R$ to $\mathbb{C}$ that takes non-negative values on $\{b_{i}\}_{i=1}^{m}$, see \cite[Proposition 3.3.6(3)]{MR3242743}. It follows that the Frobenius-Perron dimension function on the Grothendieck ring $\text{Gr}(H)$ of any finite dimensional Hopf algebra $H$ over $\mathbbm{k}$ coincides with the $\mathbbm{k}$-dimension function $\dim_{\mathbbm{k}}:\text{Gr}(H)\to \mathbb{C}, [V]\mapsto \dim_{\mathbbm{k}}V$. Later, we will need the following.
\begin{lemma}
Let $(R,\{b_{i}\}_{i=1}^{m})$ be a transitive unital $\mathbb{Z}_{+}$-ring.\label{lem-z+ring-regel}
\begin{itemize}
\item[(1)]\cite[Prop. 3.3.6 (2)]{MR3242743} There is a unique nonzero element $\mathscr{R}\in R_{\mathbb{C}}\coloneqq R\otimes_{\mathbb{Z}}\mathbb{C}$ up to multiplication by a complex number, such that for all $a\in R$, one has $a\mathscr{R} =\text{FPdim}(a)\mathscr{R}$. Such an element $\mathscr{R}$ is called the \textit{regular element} of $R$.
\item[(2)]\cite[Prop. 3.3.11]{MR3242743} If $R$ is further a fusion ring, then $\sum_{i=1}^{m}\text{FPdim}(b_{i})b_{i} $ is a regular element of $R$, which is called the \textit{canonical regular element} of $R$.
\end{itemize}
\end{lemma}
For a fusion ring $(R,\{b_{i}\}_{i=1}^{m})$, the \textit{Frobenius-Perron dimension} of $R$, denoted by $\text{FPdim}(R)$, is defined to be
$\text{FPdim}(\mathscr{R})=\sum_{i=1}^{m}\text{FPdim}(b_{i})^{2}$. If the Grothendieck ring $\text{Gr}(H)$ of a finite-dimensional Hopf algebra $H$ over an algebraically closed field is a fusion ring (e.g., when $H$ is semisimple, see also \cite[Prop. 4.9.1]{MR3242743}), then
\begin{equation}\label{eq-fus-FPdim}
\text{FPdim}(\text{Gr}(H))=\sum_{[V]\in \text{Irr}(H)}(\dim_{\mathbbm{k}}V)^{2}.
\end{equation}

