\subsection{Orbits of the winding automorphism group action}\label{subsec-orbiwinda}

%\subsection{A stratification on the maximal spectrum of the central Hopf subalgebra} 
Let $(H,C)$ be a pair of Hopf algebras satisfying the hypothesis (FinHopf) over an algebraically closed field  $\mathbbm{k}$ of \textit{arbitrary} characteristic. The \textit{left winding automorphism} $W_{l}(\chi)$ and the \textit{right winding automorphism} $W_{r}(\chi)$ of $H$ associated to a character $\chi \in G(H^{\circ})$  are defined respectively as:
$$W_{l}(\chi)(h)\coloneqq \sum_{(h)}\chi(h_{(1)})h_{(2)} \text{ and\ } W_{r}(\chi)(h)\coloneqq \sum_{(h)}h_{(1)}\chi(h_{(2)}), \forall h\in H.$$

Winding automorphisms are crucial in the study of Noetherian Hopf algebras. Since Noetherian affine PI Hopf algebras are AS-Gorenstein \cite[Thm. 0.2 (1)]{MR1938745}, it follows that $H$ is an AS-Gorenstein Hopf algebra. By \cite[Prop. 4.5 (a)]{MR2437632}, there is a character $\chi_{0}\in G(H^{\circ})$, defined by the \textit{homological integral} of $H$ in the sense of Lu-Wu-Zhang \cite{MR2320655}, such that $W_{l}(\chi_{0})S^{2}$ is a \textit{Nakayama automorphism} of $H$, which is unique up to an inner automorphism.

%(in particular, all Hopf algebras considered in this paper)
%\textcolor{red}{Let $H$ be an AS-Gorenstein Hopf algebra and $\chi_{0}\in G(H^{\circ})$ be a character defined by the \textit{homological integral} of $H$ in the sense of Lu-Wu-Zhang \cite{MR2320655}. Then, by \cite[Prop. 4.5 (a)]{MR2437632}, $W_{l}(\chi_{0})S^{2}$ is a \textit{Nakayama automorphism} of $H$, which is unique up to an inner automorphism.}

Clearly, for any $\chi\in G(H^{\circ})$, one has $W_{l}(\chi)(C)=C$ and $W_{r}(\chi)(C)=C$. It follows that both $W_{l}(\chi)$ and $W_{r}(\chi)$ act on $\text{maxSpec}C$ as homeomorphisms. Moreover, $W_{l}(G(H^{\circ}))$ and $W_{r}(G(H^{\circ}))$ are both subgroups of the algebra automorphism group of $H$, referred to as the \textit{left winding automorphism group} and the \textit{right winding automorphism group} of $H$, respectively.

We consider the cosets of $\text{maxSpec}C$ with respect to the subgroup
\begin{equation}\label{subgroup-I}
 \mathcal{I} \coloneqq \{\mathfrak{m}\in \text{maxSpec}C \mid  H/\mathfrak{m}H\text{ has a }1\text{-dimensional module}\}.   
\end{equation}

The main result of this section is to prove that for any $\mathfrak{m}\in \text{maxSpec}C$, the \textit{left} coset of $\mathcal{I}$ in $\text{maxSpec}C$ which contains $\mathfrak{m}$ is exactly the orbit of $\mathfrak{m}$ of the \textit{right} winding automorphism group action (Theorem \ref{thm-leftcossta-isofiber-or}). %A similar result also holds for the case of right cosets.

The importance of the subgroup $\mathcal{I}$ is based on the fact that the points in $\mathcal{I}$ are exactly those maximal ideals of $C$ for which the corresponding fiber algebras are isomorphic to the identity fiber algebra $H/\mathfrak{m}_{\overline{\varepsilon}}H$. Equivalently, $\mathcal{I}$ is the orbit of $\mathfrak{m}_{\overline{\varepsilon}}$ of the left (or right) winding automorphism group action. In fact, for any maximal ideal $\mathfrak{m}$ of $C$, it is proved in \cite[Thm. 4.3 (a)]{mi2025lowest} that the following are equivalent, where an additional requirement that the identity fiber algebra $H/\mathfrak{m}_{\overline{\varepsilon}}H$ is a basic algebra is added.  
\begin{itemize}
\item[(1)] $\mathfrak{m}$ belongs to the subgroup $\mathcal{I}$;
\item[(2)] $H/\mathfrak{m}H$ and $H/\mathfrak{m}_{\overline{\varepsilon}}H$ are isomorphic as $\mathbbm{k}$-algebras;
\item[(3)] $\mathfrak{m}$ belongs to the orbit of $\mathfrak{m}_{\overline{\varepsilon}}$ of the right winding automorphism group action;
\item[(4)] $\mathfrak{m}$ belongs to the orbit of $\mathfrak{m}_{\overline{\varepsilon}}$ of the left winding automorphism group action.
\end{itemize}
%for any maximal ideal $\mathfrak{m}$ of $C$, $\mathfrak{m}$ belongs to the orbit of $\mathfrak{m}_{\overline{\varepsilon}}$ under the right winding automorphism group $W_{r}(G(H^{\circ}))$ if and only if $H/\mathfrak{m}H$ and $H/\mathfrak{m}_{\overline{\varepsilon}}H$ are isomorphic as $\mathbbm{k}$-algebras.

% It should be noted that in \cite[Thm. 4.3 (a)]{mi2025lowest}, the description of the aforementioned conclusion imposed an additional requirement that the identity fiber algebra $H/\mathfrak{m}_{\overline{\varepsilon}}H$ is a basic algebra in order to characterize those fiber algebras that are basic algebras. The rest of the characterization still holds true with the same proof after removing the condition that $H/\mathfrak{m}_{\overline{\varepsilon}}H$ is basic. 
Now, we proceed to prove the main result of this subsection.
\begin{theorem}\label{thm-leftcossta-isofiber-or}
Let $(H,C)$ be a pair of Hopf algebras satisfying the hypothesis (FinHopf), and let $\mathcal{I}$ be the subgroup of $\text{maxSpec}C$ defined in \eqref{subgroup-I}. Then for any  maximal ideal $\mathfrak{m}$ of $C$, the left coset of $\mathcal{I}$ in $\text{maxSpec}C$ containing $\mathfrak{m}$ coincides with the orbit of $\mathfrak{m}$ of the right winding automorphism group action.
\end{theorem}
%that gives an algebra isomorphism $H/\mathfrak{m}H\cong H/\mathfrak{n}H$.

\begin{remark}
Theorem \ref{thm-leftcossta-isofiber-or} shows that for maximal ideas $\mathfrak{m}$ and $\mathfrak{n}$ of $C$ belonging to the same left coset of $\mathcal{I}$ in $\text{maxSpec}C$, $H/\mathfrak{m}H$ and $H/\mathfrak{n}H$ are isomorphic as $\mathbbm{k}$-algebras. In general, there exist pairs $(H,C)$ satisfying (FinHopf) such that the fiber algebras at maximal ideals from any two different left cosets of $\mathcal{I}$ are non-isomorphic. See Example \ref{eg-Chevnotsembas-dim16}. We remark that Theorem \ref{thm-leftcossta-isofiber-or} can also be regarded as an improvement of \cite[Thm. 4.3 (a)]{mi2025lowest}.
\end{remark}
\begin{proof}[Proof of Theorem \upshape\ref{thm-leftcossta-isofiber-or}]
Let $\mathfrak{m}_{\varphi}$ and $\mathfrak{m}_{\psi}$ be maximal ideals of $C$ in the same left coset of $\mathcal{I}$ in $\text{maxSpec}C$. Then there exists $\mathfrak{m}_{\chi}\in \mathcal{I}$ such that $\mathfrak{m}_{\psi}= \mathfrak{m}_{\varphi}\ast \mathfrak{m}_{\chi}$. It follows that $\psi= \varphi\ast \chi$. According to the definition of $\mathcal{I}$, the fiber algebra $H/\mathfrak{m}_{\chi}H$ has a $1$-dimensional representation $\rho:H/\mathfrak{m}_{\chi}H\to\mathbbm{k}$. Define $\hat{\chi}:H\to\mathbbm{k}$ by $h\mapsto \rho(\overline{h})$. Then $\hat{\chi}\in G(H^{\circ})$ and $\hat{\chi}|_{C}=\chi$.

 For any $c\in \mathfrak{m}_{\psi}=\text{Ker}\psi$, one has 
$$0=\psi(c)=(\varphi\ast\chi)(c)=\sum_{(c)}\varphi(c_{(1)})\chi(c_{(2)})=\varphi\left(\sum_{(c)}c_{(1)}\chi(c_{(2)})\right)=\varphi(W_{r}(\hat{\chi})(c)).$$
Thus $W_{r}(\hat{\chi})(\mathfrak{m}_{\psi})=\mathfrak{m}_{\varphi}$. Therefore, for any maximal ideal $\mathfrak{m}$ of $C$, the left coset $\mathfrak{m}\ast \mathcal{I}$ is a subset of the orbit $W_{r}(G(H^{\circ}))(\mathfrak{m})$. Now, we show that $W_{r}(G(H^{\circ}))(\mathfrak{m})\subseteq \mathfrak{m}\ast \mathcal{I}$ to complete the proof. Suppose $\mathfrak{m}_{\psi}\in W_{r}(G(H^{\circ}))(\mathfrak{m})$ and let $\mathfrak{m}=\mathfrak{m}_{\varphi}$. Then there exist $\hat{\chi}\in G(H^{\circ})$ such that $\mathfrak{m}_{\psi}=W_{r}(\hat{\chi})(\mathfrak{m}_{\varphi})$. Set $\chi\coloneqq \hat{\chi}|_{C}\in G(C^{\circ})$. We claim that $\mathfrak{m}_{\varphi}=\mathfrak{m}_{\psi}\ast \mathfrak{m}_{\chi}$.

Take $c\in \mathfrak{m}_{\varphi}$. Then we have $\psi(W_{r}(\hat{\chi})(c))=0$. Thus
$$0=\psi\left(\sum_{(c)}c_{(1)}\hat{\chi}(c_{(2)})\right)=\psi\left(\sum_{(c)}c_{(1)}\chi(c_{(2)})\right)=(\psi\ast \chi)(c).$$
It follows that $\mathfrak{m}_{\varphi}\subseteq \mathfrak{m}_{\psi\ast \chi}$, which implies that $\mathfrak{m}_{\varphi}=\mathfrak{m}_{\psi}\ast \mathfrak{m}_{\chi}$.
\end{proof}
\begin{remark}\label{rmk-ricoscas-wnorsub1}
A similar argument shows that the \textit{right} cosets of $\mathcal{I}$ in $\text{maxSpec}C$ correspond to the orbits of the \textit{left} winding automorphism group action. Moreover, it is not hard to prove, by Theorem \ref{thm-leftcossta-isofiber-or}, that when $\mathcal{I}$ is a normal subgroup of $\text{maxSpec}C$, for any maximal ideal $\mathfrak{m}$ of $C$, the orbit of $\mathfrak{m}$ of the left winding automorphism group action coincides with the orbit of the right winding automorphism group action. We leave the details to the reader.
\end{remark}
