%$$\mathcal{V}(D_{k}(H/C;\text{tr}_{\text{reg}}))=\mathcal{V}(MD_{k}(H/C;\text{tr}_{\text{reg}}))=
%\begin{cases} 
%\varnothing, & 1\leq k\leq 2, \\
%\{\mathfrak{m}_{\overline{\varepsilon}}\}, & 3\leq k\leq 4,\\
%\text{maxSpec}C, & k\geq 5.
%\end{cases}$$
\end{example}
%However, the converse is not true in general.
%It follows from Example \ref{eg-cheloc=maxSp-notChprop}  that 
%\textcolor{red}{textcolorDenote the unique $2$-dimensional irreducible module of $H/\mathfrak{m}H$ by $V$. Then $V\otimes V$ is not completely reducible as an $H$-module.} 

So, $\text{Chev}_{\overline{\varepsilon}}(H,C)=\text{maxSpec}C$
is not sufficient to ensure that $H$ has the Chevalley property. In fact, it is equivalent to that the identity fiber algebra $H/\mathfrak{m}_{\overline{\varepsilon}}H$ has the Chevalley property.

\begin{proposition}
Let $(H,C)$ be a pair of Hopf algebras satisfying the hypothesis (FinHopf). Then $\text{Chev}_{\overline{\varepsilon}}(H,C)=\text{maxSpec}C$ if and only if $H/\mathfrak{m}_{\overline{\varepsilon}}H$ has the Chevalley property.\label{prop-epiChev-mepiC}
\end{proposition}
\begin{proof}
We need only to prove the ``if part". Since the Jacobson radical $\text{Jac}(H/\mathfrak{m}_{\overline{\varepsilon}}H)$ is a Hopf ideal of the identity fiber algebra $H/\mathfrak{m}_{\overline{\varepsilon}}H$, $R\coloneqq (H/\mathfrak{m}_{\overline{\varepsilon}}H)/\text{Jac}(H/\mathfrak{m}_{\overline{\varepsilon}}H)$ is a finite-dimensional semisimple Hopf algebra. For each $\mathfrak{m}\in \text{maxSpec}C$, the left $H/\mathfrak{m}_{\overline{\varepsilon}}H$-comodule algebra structure on $H/\mathfrak{m}H$ given by \eqref{eq-righlefcomalh9} induces a left $R$-comodule algebra structure on $H/\mathfrak{m}H$. Equivalently, $H/\mathfrak{m}H$ is a right $R^{\circ}$-module algebra. By \cite[Thm. 2.1]{MR1995055} or \cite[Thm. 0.3]{MR3359721}, $\text{Jac}(H/\mathfrak{m}H)$ is stable under the Hopf action of $R^{\circ}$. It follows that $\text{Jac}(H/\mathfrak{m}H)$ is a left $R$-subcomodule of $H/\mathfrak{m}H$. Hence, $\overline{\Delta}(\text{Jac}(H/\mathfrak{m}H))\subseteq  H/\mathfrak{m}_{\overline{\varepsilon}}H\otimes \text{Jac}(H/\mathfrak{m}H)+\text{Jac}(H/\mathfrak{m}_{\overline{\varepsilon}}H)\otimes H/\mathfrak{m}H$. This implies that $\mathfrak{m}\in \text{Chev}_{\overline{\varepsilon}}(H,C)$.
\end{proof}
\begin{remark}\label{rmk-H/mepHbasic-Chev}
In particular, $\text{Chev}_{\overline{\varepsilon}}(H,C)=\text{maxSpec}C$ if the identity fiber algebra $H/\mathfrak{m}_{\overline{\varepsilon}}H$ is either semisimple or basic. Let $(\mathcal{O}_{\epsilon}(G),C_{\epsilon}(G))$ be the pair of Hopf algebras as described in Example \ref{eg-quantizecoornri}. Then its identity fiber algebra $\mathcal{O}_{\epsilon}(G)/\mathfrak{m}_{\overline{\varepsilon}}\mathcal{O}_{\epsilon}(G)$ is basic. 
\end{remark}
\begin{remark}
Combining Example \ref{eg-cheloc=maxSp-notChprop} and Proposition \ref{prop-epiChev-mepiC}, whether the identity fiber algebra of a pair $(H,C)$ of Hopf algebras satisfying the hypothesis (FinHopf) has the Chevalley property depends on the choice of the central Hopf subalgebra $C$.
\end{remark}
% From Example \ref{eg-cheloc=maxSp-notChprop}, we see that in general, determining whether a Hopf algebra (even if the Hopf algebra in question is finite-dimensional) has the Chevalley property by checking if the tensor product of any two irreducible representations is completely reducible is not easy. This is because we need to construct all the irreducible representations of the Hopf algebra in question in advance. 

To sum up, for any pair $(H,C)$ of Hopf algebras satisfying the hypothesis (FinHopf), 
\begin{align*}
H\text{ has the Chevalley property}\Rightarrow &\text{Chev}_{\overline{\varepsilon}}(H,C)=\text{maxSpec}C\\
\Leftrightarrow & H/\mathfrak{m}_{\overline{\varepsilon}}H\text{ has the Chevalley property.}
\end{align*}
In general, it is not easy to check whether a Hopf algebra (even if the Hopf algebra in question is finite-dimensional) has the Chevalley property by definition. 
