\subsection{The behavior of the square dimension function}\label{sec-behSqfun-Chev}
Let $A$ be an affine module-finite $C$-algebra. Consider the \textit{square dimension function} \cite{mi2025lowest}:
\begin{equation}\label{eq-Sd-function}
\text{Sd}:\text{maxSpec}C\to \mathbb{N}, \mathfrak{m}\mapsto \sum_{[V]\in \text{Irr}(A/\mathfrak{m}A)}(\dim_{\mathbbm{k}}V)^{2}.
\end{equation}
Suppose that $(H,C)$  is a pair of Hopf algebras satisfying the hypothesis (FinHopf) such that the identity fiber algebra $H/\mathfrak{m}_{\overline{\varepsilon}}H$ has the Chevalley property.
We investigate the behavior of the square dimension function of the pair $(H,C)$ on the maximal spectrum $\text{maxSpec}C$.

The following is the main result in this subsection, which is used to prove Theorem B (Theorem \ref{thm-Chein-VDneth-cwao}) in the introduction.
\begin{theorem}
Let $(H,C)$ be a pair of Hopf algebras satisfying the hypothesis (FinHopf) such that the identity fiber algebra $H/\mathfrak{m}_{\overline{\varepsilon}}H$ has the Chevalley property.\label{thm-sdchevpo-geqmepi} Set $\text{Irr}(H/\mathfrak{m}_{\overline{\varepsilon}}H)=\{[V_{1}],...,[V_{m}]\}$. Then for any $\mathfrak{m}\in \text{maxSpec}C$, 
\begin{itemize}
 \item[(1)] $\text{Sd}(\mathfrak{m})\geq \text{Sd}(\mathfrak{m}_{\overline{\varepsilon}})\geq |\text{Irr}(H/\mathfrak{m}H)|$.
 \item[(2)] The following are equivalent:
 \begin{itemize}
 \item[(i)]$\text{Sd}(\mathfrak{m})=\text{Sd}(\mathfrak{m}_{\overline{\varepsilon}})$;
 \item[(ii)] For any irreducible $H/\mathfrak{m}H$-module $W$, as $H$-modules, 
 $$W\otimes W^{*}\cong \bigoplus_{i=1}^{m}V_{i}^{\oplus \dim_{\mathbbm{k}}\text{Hom}_{H}(V_{i}\otimes W,W)};$$
  \item[(iii)]For any irreducible $H/\mathfrak{m}H$-module $W$, the tensor product $W\otimes W^{*}$ is a completely reducible $H/\mathfrak{m}_{\overline{\varepsilon}}H$-module.
 \end{itemize}
 \end{itemize}
\end{theorem}

%\begin{remark}
%Example \ref{eg-cheloc=maxSp-notChprop} illustrates that for $\mathfrak{m}\in \overline{\varepsilon}\text{-Chev}(H,C)$, the tensor product of a simple $H/\mathfrak{m}H$-module and a simple $H/\mathfrak{m}^{-1}H$-module may not be semisimple.
%\end{remark}

We need two lemmas to prove the above theorem.
%Write $[W:V]$ for the multiplicity of $V$ in a composition series of $W$.
\begin{lemma}\label{lem-dimHomleq-commlcty}
Let $A$ be a $\mathbbm{k}$-algebra, $V$ a finite-dimensional irreducible $A$-module, and $W$ a finite-dimensional $A$-module.  Then 
$$[W:V]\geq \dim_{\mathbbm{k}}\text{Hom}_{A}(V,W).$$
The equality holds when $W$ is completely reducible.
\end{lemma}
\begin{proof}
Set $n=\dim_{\mathbbm{k}}\text{Hom}_{A}(V,W)$, and choose a $\mathbbm{k}$-basis $\{e_{i}:V\to W\}_{i=1}^{n}$ for the $\mathbbm{k}$-space $\text{Hom}_{A}(V,W)$. Clearly, each $e_{i}(V)$ is an irreducible submodule of $W$ isomorphic to $V$. We claim that $\Gamma\coloneqq\sum_{i=1}^{n}e_{i}(V)$ is a direct sum in $W$. Once the claim is proved, then
$$[W:V]\geq [\Gamma:V]=n=\dim_{\mathbbm{k}}\text{Hom}_{A}(V,W).$$
 Indeed, $\text{Im} f \subseteq \Gamma$ for any $A$-module homomorphism $f:V\to W$. 
 % This gives a standard embedding from $\text{Hom}_{A}(V,W)$ to $\text{Hom}_{A}(V,\Gamma)$. In particular, one has $\dim_{\mathbbm{k}}\text{Hom}_{A}(V,\Gamma)\geq n$. 
It follows that $$\text{Hom}_{A}(V,W)\cong\text{Hom}_{A}(V,\Gamma).$$
In particular, one has $\dim_{\mathbbm{k}}\text{Hom}_{A}(V,\Gamma) = n$. 
 Note that $\Gamma$ is a completely reducible $A$-module, and $\dim_{\mathbbm{k}}\text{Hom}_{A}(V,V)=1$ as $\mathbbm{k}$ is algebraically closed. We conclude that $\Gamma=\sum_{i=1}^{n}e_{i}(V)$ is a direct sum. 

If $W$ is completely reducible, then $V^{\oplus [W:V]}$ is a direct summand of $W$, and so
$$[W:V]\leq \dim_{\mathbbm{k}}\text{Hom}_{A}(V,W).$$
\end{proof}

\begin{lemma}
Let $H$ be a finite-dimensional Hopf algebra with the Chevalley property.\label{lem-fdchevhopf-grfus-cre} Then the Grothendieck ring $\text{Gr}(H)$ of $H$ is a fusion ring with the $\mathbb{Z}_{+}$-basis given by the set of isomorphic classes of all irreducible $H$-modules $\text{Irr}(H)=\{[V_{1}],...,[V_{m}]\}$, and the canonical regular element of $\text{Gr}(H)$ is given by $\sum_{i=1}^{m}(\dim_{\mathbbm{k}}V_{i})[V_{i}].$
\end{lemma}
\begin{proof}
By assumption, the Jacobson radical $J$ of $H$ is a Hopf ideal and $H/J$ is a semisimple Hopf algebra. %and every irreducible $H$-module $V_{i}$ is annihilated by $J$. 
It follows from the ring isomorphism $\text{Gr}(H)\to \text{Gr}(H/J), [V_{i}]\mapsto [V_{i}]$ that $\text{Gr}(H)$ is a fusion ring. The second conclusion follows from Lemma \ref{lem-z+ring-regel}(2).
\end{proof}
%Let $\text{Irr}(H/\mathfrak{m}_{\overline{\varepsilon}}H)=\{[V_{1}],...,[V_{m}]\}$ and 
\begin{proof}
[Proof of Theorem \upshape\ref{thm-sdchevpo-geqmepi}]
(1) Let $\text{Jac}(H/\mathfrak{m}_{\overline{\varepsilon}}H)$ be the Jacobson radical of the identity fiber algebra $H/\mathfrak{m}_{\overline{\varepsilon}}H$. Denote the $H$-module $(H/\mathfrak{m}_{\overline{\varepsilon}}H)/\text{Jac}(H/\mathfrak{m}_{\overline{\varepsilon}}H)$ by $R$. Since the identity fiber algebra $H/\mathfrak{m}_{\overline{\varepsilon}}H$ has the Chevalley property, it follows from Lemma \ref{lem-fdchevhopf-grfus-cre} that
$$\mathscr{R}\coloneqq   [R]=\left[\oplus_{i=1}^{m}V_{i}^{\oplus \dim_{\mathbbm{k}}V_{i}}\right]=\sum_{i=1}^{m}(\dim_{\mathbbm{k}}V_{i})[V_{i}] \in \text{Gr}(H/\mathfrak{m}_{\overline{\varepsilon}}H)$$
is the canonical regular element of the fusion ring $\text{Gr}(H/\mathfrak{m}_{\overline{\varepsilon}}H)$. Now, Lemma \ref{lem-z+ring-regel} (1) yields
\begin{equation}\label{eq-mar2=sdmr}
\mathscr{R}^{2}=(\sum_{i=1}^{m}(\dim_{\mathbbm{k}}V_{i})^{2})\mathscr{R}=\text{Sd}(\mathfrak{m}_{\overline{\varepsilon}})\mathscr{R}.
\end{equation}
Let $\text{Irr}(H/\mathfrak{m}H)=\{[W_{1}],...,[W_{\ell}]\}$. By Corollary \ref{cor-GrirreZ+-hopf},  $\text{Gr}(H/\mathfrak{m}H)$ is an irreducible $\mathbb{Z}_{+}$-module over  $\text{Gr}(H/\mathfrak{m}_{\overline{\varepsilon}}H)$ with the fixed $\mathbb{Z}$-basis $\text{Irr}(H/\mathfrak{m}H)$. It follows that the matrix $T\in \text{M}_{\ell}(\mathbb{Z})$, defined by
$$\mathscr{R}([W_{1}],...,[W_{\ell}])=([W_{1}],...,[W_{\ell}])T,$$
has positive entries. By Frobenius-Perron theorem, the matrix $T$ has a positive eigenvalue, and the maximal positive eigenvalue is a simple root of the characteristic polynomial of $T$. By \eqref{eq-mar2=sdmr}, $T^{2}=\text{Sd}(\mathfrak{m}_{\overline{\varepsilon}})T$. Thus, the characteristic polynomial of the matrix $T$ is given by $t^{\ell-1}(t-\text{Sd}(\mathfrak{m}_{\overline{\varepsilon}}))\in \mathbb{Z}[t]$. In particular, the trace of the matrix $T$ is $\text{Sd}(\mathfrak{m}_{\overline{\varepsilon}})$. Since the entries of the matrix $T$ are all positive integers, we see that 
$$\ell = |\text{Irr}(H/\mathfrak{m}H)|\leq \text{Sd}(\mathfrak{m}_{\overline{\varepsilon}}).$$

Note also that the trace of the matrix $T$ can be calculated by
\begin{equation}\label{eq-trT-2ndfor}
\sum_{j=1}^{\ell}[R\otimes W_{j}:W_{j}].
\end{equation}
Now, we proceed to estimate \eqref{eq-trT-2ndfor}. By Proposition \ref{prop-epiChev-mepiC}, $\text{maxSpec}C=  \text{Chev}_{\overline{\varepsilon}}(H,C)$. It follows that for each $[W_{j}]\in \text{Irr}(H/\mathfrak{m}H)$, $R\otimes W_{j}$ is a  completely reducible $H$-module. Hence, 
$$[R\otimes W_{j}:W_{j}]=\dim_{\mathbbm{k}} \text{Hom}_{H}(R\otimes W_{j},W_{j}).$$
%By Lemma \ref{lem-dimHomleq-commlcty} and the formula \eqref{eq-naadj-isous7}, 
%\begin{align*}
