%=&\sum_{i=1}^{m}\dim_{\mathbbm{k}}\text{Hom}_{H}(V_{i}^{\oplus \dim_{\mathbbm{k}}V_{i}}\otimes W_{j},W_{j})\\
%=&\sum_{i=1}^{m}(\dim_{\mathbbm{k}}V_{i})(\dim_{\mathbbm{k}}\text{Hom}_{H}(V_{i}\otimes W_{j},W_{j}))\\
%=&\sum_{i=1}^{m}(\dim_{\mathbbm{k}}V_{i})(\dim_{\mathbbm{k}}\text{Hom}_{H}(V_{i},W_{j}\otimes W_{j}^{*}))\\
%\leq &\sum_{i=1}^{m}(\dim_{\mathbbm{k}}V_{i})[W_{j}\otimes W_{j}^{*}:V_{i}]\\
%=&\dim_{\mathbbm{k}}(W_{j}\otimes W_{j}^{*})\\
%=&(\dim_{\mathbbm{k}}W_{j})^{2}.
%\end{align*}
Then
\begin{align*}
[R\otimes W_{j}:W_{j}]=&\dim_{\mathbbm{k}}\text{Hom}_{H}(R\otimes W_{j},W_{j}) \\
=&\sum_{i=1}^{m}\dim_{\mathbbm{k}}\text{Hom}_{H}(V_{i}^{\oplus \dim_{\mathbbm{k}}V_{i}}\otimes W_{j},W_{j})\\
=&\sum_{i=1}^{m}(\dim_{\mathbbm{k}}V_{i})(\dim_{\mathbbm{k}}\text{Hom}_{H}(V_{i}\otimes W_{j},W_{j})) \\
=&\sum_{i=1}^{m}(\dim_{\mathbbm{k}}V_{i})(\dim_{\mathbbm{k}}\text{Hom}_{H}(V_{i},W_{j}\otimes W_{j}^{*})) &  (\text{By } \eqref{eq-naadj-isous7})\\
\leq &\sum_{i=1}^{m}(\dim_{\mathbbm{k}}V_{i})[W_{j}\otimes W_{j}^{*}:V_{i}]  &  (\text{By Lemma }\ref{lem-dimHomleq-commlcty})\\
=&\dim_{\mathbbm{k}}(W_{j}\otimes W_{j}^{*})\\
=&(\dim_{\mathbbm{k}}W_{j})^{2}.
\end{align*}


Now it is clear that 
$$\text{Sd}(\mathfrak{m}_{\overline{\varepsilon}})=\sum_{j=1}^{\ell}[R\otimes W_{j}:W_{j}]\leq \sum_{j=1}^{\ell}(\dim_{\mathbbm{k}}W_{j})^{2}=\text{Sd}(\mathfrak{m}).$$
\par(2) The implication (iii)$\Rightarrow$ (i) follows immediately from Lemma \ref{lem-dimHomleq-commlcty} and the proof of (1). The implication (ii) $\Rightarrow$ (iii) is obvious. It is left to prove (i) $\Rightarrow$ (ii). If $\text{Sd}(\mathfrak{m})=\text{Sd}(\mathfrak{m}_{\overline{\varepsilon}})$, then, by the proof of (1), one has
$$\dim_{\mathbbm{k}}\text{Hom}_{H}(V_{i},W_{j}\otimes W_{j}^{*})=[W_{j}\otimes W_{j}^{*}:V_{i}],\forall 1\leq i\leq m\text{ and\ } 1\leq j\leq \ell.$$
It follows from the proof of Lemma \ref{lem-dimHomleq-commlcty} that the left $H/\mathfrak{m}_{\overline{\varepsilon}}H$-module $W_{j}\otimes W_{j}^{*}$ has a submodule isomorphic to 
$$\bigoplus_{i=1}^{m}V_{i}^{\oplus [W_{j}\otimes W_{j}^{*}:V_{i}]}.$$
By comparing the $\mathbbm{k}$-dimensions of these two modules immediately yields
$$W_{j}\otimes W_{j}^{*}\cong \bigoplus_{i=1}^{m}V_{i}^{\oplus [W_{j}\otimes W_{j}^{*}:V_{i}]}.$$
This shows that $W_{j}\otimes W_{j}^{*}$ is complete reducible. It follows from Lemma \ref{lem-dimHomleq-commlcty} that
$$[W_{j}\otimes W_{j}^{*}:V_{i}]=\dim_{\mathbbm{k}}\text{Hom}_{H}(V_{i},W_{j}\otimes W_{j}^{*})=\dim_{\mathbbm{k}}\text{Hom}_{H}(V_{i}\otimes W_{j},W_{j})$$
for all $1\leq j\leq \ell$.
\end{proof}
The following example shows that the two inequalities in Theorem \ref{thm-sdchevpo-geqmepi} (1) may be strict.
\begin{example}
 Let $H=H(n,t,\epsilon)$ be the $\mathbbm{k}$-algebra generated by $x$ and $g$ subject to the relations 
$$g^{n}=1\text{ and\ }xg=\epsilon gx,$$ where $n\geq 2,1\leq t\leq n$ are two coprime integers\label{eg-infiTaft}, and $\epsilon$ is an $n$th primitive root of unity.  
 The coalgebra structure of $H$ is defined by
$$\Delta(g)=g\otimes g,\varepsilon(g)=1\text{ and }\Delta(x)=x\otimes g^{t}+1\otimes x,\varepsilon(x)=0.$$
Then $H$ is a Hopf algebra \cite{MR2320655}, the antipode $S$ of $H$ is given by $S(g)=g^{-1}$ and $S(x)=-xg^{-t}$. Note that the coalgebra structure of $H$ here differs from that given in \cite[Ex. 2.7]{MR2320655} by a coopposite.
Sometimes $H$ is called the \textit{infinite Taft algebra}, which is  an affine prime AS-regular Hopf algebra of GK-dimension one with the center $C=\mathbbm{k}[x^{n}]$. It is direct to check that $C $ is a Hopf subalgebra of $H$ and $H$ is a free $C$-module of rank $n^{2}$. In particular, $\text{dim}_{\mathbbm{k}}H/\mathfrak{m}H=n^{2}$ for any $\mathfrak{m}\in \text{maxSpec}C$. Clearly, $H/\mathfrak{m}_{\overline{\varepsilon}}H$ is precisely the $n^{2}$-dimensional Taft algebra 
$$ H_{n}(\epsilon)=\mathbbm{k}\langle g,x\rangle /(g^{n}-1,xg-\epsilon gx, x^{n}).$$
Hence, the identity fiber algebra $H/\mathfrak{m}_{\overline{\varepsilon}}H$ is basic and $G((H/\mathfrak{m}_{\overline{\varepsilon}}H)^{\circ})$ is a cyclic group of order $n$. In  particular, $H/\mathfrak{m}_{\overline{\varepsilon}}H$ has the Chevalley property. Let $\mathfrak{m}_{\alpha}$ be the maximal ideal of $C$ generated by $(x^{n}-\alpha)$ where $\alpha\in \mathbbm{k}$. Then $\mathfrak{m}_{0}=\mathfrak{m}_{\overline{\varepsilon}}$. For $\alpha\in \mathbbm{k}^{\times}$, one has $H/\mathfrak{m}_{\alpha}H\cong \text{M}_{n}(\mathbbm{k})$. Indeed, it is direct to check that the algebra homomorphism $\zeta:H/\mathfrak{m}_{\chi_{\alpha}}H\to\text{M}_{n}(\mathbbm{k})$, given by
$$\zeta(g)=
\begin{pmatrix}
1& & & & \\
 &\epsilon& & &\\
& & \epsilon^{2} & &\\
& & &\ddots &\\
& & & &\epsilon^{n-1} 
\end{pmatrix},
\zeta(x)=
\begin{pmatrix}
 &\sqrt[n]{\alpha} & & & \\
