%\subsection{A relation between the $\overline{\varepsilon}$-Chevalley locus and the discriminant ideals of a Cayley-Hamilton Hopf algebra}
\subsection{Proof of Theorem B}\label{subsec-epChev-zerodis}
For an algebra with trace $(A,C,\text{tr})$ such that $A$ is a finitely generated free $C$-module, one defines \cite{MR1972204} the \textit{discriminant} of $A$ over $C$ with respect to the trace map $\text{tr}:A\to C$ by
\begin{equation}\label{eq-discri-def1}
\Delta(A/C;\text{tr})\coloneqq \text{det}(\text{tr}(x_{i}x_{j}))_{i,j=1}^{n}\in C,
\end{equation}
where $\{x_{1},...,x_{n}\}$ is a $C$-basis of $A$. The discriminant $\Delta(A/C;\text{tr})$ is unique up to multiplication by an invertible element in $C$. For example, when $A$ is the ring of integers $\mathcal{O}_{L}$ of an algebraic number field $L$ and $C=\mathbb{Z}$, the discriminant of $\mathcal{O}_{L}$ over $\mathbb{Z}$ with respect to the regular trace (Example \ref{eg-regulartr}) is precisely the discriminant of the algebraic number field $L$. 

In general, an algebra with trace $(A,C,\text{tr})$ does not necessarily satisfy the freeness condition. % that $A$ is a finitely generated free $C$-module. 
Instead,  one considers the \textit{discriminant ideals} \cite{MR1972204} and the \textit{modified discriminant ideals} \cite{MR3415697}.
\begin{definition}
Let $(A,C,\text{tr})$ be an algebra with trace. For any positive integer $k$,\label{def-discriid}
\begin{itemize}
\item[(1)]the \textit{$k$-discriminant ideal} $D_{k}(A/C;\text{tr})$ is the ideal of $C$ generated by the set
$$\{\text{det}(\text{tr}(a_{i}a_{j}))_{i,j=1}^{k}\mid (a_{1},...,a_{k})\in A^{k}\}.$$
\item[(2)]the \textit{modified $k$-discriminant ideal} $MD_{k}(A/C;\text{tr})$ is the ideal of $C$ generated by the set
$$\{\text{det}(\text{tr}(a_{i}b_{j}))_{i,j=1}^{k}\mid (a_{1},...,a_{k}),(b_{1},...,b_{k})\in A^{k}\}.$$
\end{itemize}
\end{definition}
Let $(A,C,\text{tr})$ be an algebra with trace. It is direct to check that
$$D_{k}(A/C;\text{tr})\subseteq MD_{k}(A/C;\text{tr})\text{ and\ }MD_{k+1}(A/C;\text{tr})\subseteq MD_{k}(A/C;\text{tr})$$
for all positive integer $k$. If $A$ can be generated by $n$ elements as a $C$-module, then 
$$MD_{k}(A/C;\text{tr})=0,$$
for all $k\geq n+1$. If, furthermore, $A$ is a free $C$-module of rank $n$, then 
\begin{equation}\label{eq-disc=ideal1}
D_{n}(A/C;\text{tr})=MD_{n}(A/C;\text{tr})=\big(\Delta(A/C;\text{tr})\big).
\end{equation}
Therefore, the discriminant can be considered as ``the top discriminant ideal'', while the remaining discriminant ideals provide information that cannot be read off from the discriminant alone. For example, see the formula \eqref{eq-CHzero-ire-sd} below.
%See Theorem \ref{thm-Chein-VDneth-cwao} below.

Now, we fix an affine Cayley-Hamilton Hopf algebra $(H,C,\text{tr})$ in this subsection. We will show that if the identity fiber algebra $H/\mathfrak{m}_{\overline{\varepsilon}}H$ has the Chevalley property, then any non-epmty zero locus of a discriminant ideal of $(H,C,\text{tr})$ contains the orbit of the identity element of $\text{maxSpec}C$ of the winding automorphism group action.  

In general, for an affine Cayley-Hamilton algebra $(A,C,\text{tr})$ over an algebraically closed field of characteristic zero, by \cite[Thm. 4.5 (a)]{MR1288995}, $A$ is a module-finite $C$-algebra and $C$ is an affine $\mathbbm{k}$-algebra. Recall that $\text{Sd}:\text{maxSpec}C\to \mathbb{N}$ is the square dimension function defined in \eqref{eq-Sd-function}. By \cite[Thm. 4.1 (b)]{MR3886192}, one has
\begin{equation}\label{eq-CHzero-ire-sd}
\mathcal{V}_{k}\coloneqq \mathcal{V}(D_{k}(A/C;\text{tr}))=\mathcal{V}(MD_{k}(A/C;\text{tr}))=\{\mathfrak{m}\in \text{maxSpec}C\mid \text{Sd}(\mathfrak{m})<k\},
\end{equation}
for all positive integer $k$. Therefore, it is obvious from \eqref{eq-CHzero-ire-sd} that each zero locus of a discriminant ideal of $(H,C,\text{tr})$ can be decomposed into a disjoint union of some orbits of the left winding automorphism group action. 

Now we proceed to prove the main result of this subsection.
\begin{theorem} (Theorem B)
Let $(H,C,\text{tr})$ be an affine Cayley-Hamilton Hopf algebra such that the identity fiber algebra $H/\mathfrak{m}_{\overline{\varepsilon}}H$ has the Chevalley property. Then any non-empty zero locus of a discriminant ideal of $(H,C,\text{tr})$ contains the orbit of $\mathfrak{m}_{\overline{\varepsilon}}$ of the left winding automorphism group action.\label{thm-Chein-VDneth-cwao}
\end{theorem}

\begin{proof}
Assume that $\mathcal{V}\neq \varnothing$ is the zero locus of the $k$-discriminant ideal, that is, $\mathcal{V}=\mathcal{V}_{k}$.   Suppose $\mathfrak{m}\in \mathcal{V}_{k}$. Since $H/\mathfrak{m}_{\overline{\varepsilon}}H$ has the Chevalley property, by Theorem \ref{thm-sdchevpo-geqmepi} (1) and \eqref{eq-CHzero-ire-sd}, 
$$\text{Sd}(\mathfrak{m}_{\overline{\varepsilon}})\leq \text{Sd}(\mathfrak{m})< k.$$ 
For any point $\mathfrak{n}$ in the orbit of $\mathfrak{m}_{\overline{\varepsilon}}$ of the left winding automorphism group action, there is $\chi\in G(H^{\circ})$ such that $\mathfrak{n}=W_{l}(\chi)(\mathfrak{m}_{\overline{\varepsilon}})$. It follows that
 the winding automorphism $W_{l}(\chi):H\to H$ induces an algebra isomorphism $H/\mathfrak{n}H\cong H/\mathfrak{m}_{\overline{\varepsilon}}H$. Hence
$$
\text{Sd}(\mathfrak{n})=\text{Sd}(\mathfrak{m}_{\overline{\varepsilon}})<k.
$$
It follows from \eqref{eq-CHzero-ire-sd} that $\mathfrak{n}\in \mathcal{V}_{k}$. Hence $W_{l}(G(H^{\circ}))(\mathfrak{m}_{\overline{\varepsilon}})\subseteq \mathcal{V}_{k}$.
%\marginpar{write in more detail, emphasis Theorem 3.12}
\end{proof}
%Moreover, it is clear that any point $\mathfrak{n}$ in the orbit of $\mathfrak{m}_{\overline{\varepsilon}}$ of the left winding automorphism group action satisfies $\text{Sd}(\mathfrak{n})=\text{Sd}(\mathfrak{m}_{\overline{\varepsilon}})$.
%Theorem \ref{thm-leftcossta-isofiber-or} implies
\begin{remark}
Retain the assumptions and notation of Theorem \ref{thm-Chein-VDneth-cwao}. By Lemma \ref{lem-fdchevhopf-grfus-cre}, the Grothendieck ring $\text{Gr}(H/\mathfrak{m}_{\overline{\varepsilon}}H)$ is a fusion ring. It follows from \eqref{eq-fus-FPdim} that
$$\text{FPdim}(\text{Gr}(H/\mathfrak{m}_{\overline{\varepsilon}}H))=\text{Sd}(\mathfrak{m}_{\overline{\varepsilon}})=\sum_{[V]\in \text{Irr}(H/\mathfrak{m}_{\overline{\varepsilon}}H)}(\dim_{\mathbbm{k}}V)^{2}.$$
\end{remark}
\begin{remark}
There exist affine Cayley-Hamilton Hopf algebras $(H,C,\text{tr})$ such that the zero loci of their lowest discriminant ideals are precisely the orbits of $\mathfrak{m}_{\overline{\varepsilon}}$ under the action of the left winding automorphism group. See \cite[Thms. 5.5 (b) and 5.7 (b)]{mi2025lowest}.
\end{remark}


