\subsection{Proof of Theorem D}\label{sec-Chev-alllrti2}
%\subsection{Discriminant ideals of Cayley-Hamilton Hopf algebras with the Chevalley property are all trivial}
For any affine Cayley-Hamilton Hopf algebra $(H,C,\text{tr})$ with the Chevalley property, we prove that all discriminant ideals are trivial, that is, every discriminant ideal is either $0$ or $C$, which gives a necessary condition for a Cayley-Hamilton Hopf algebra to have the Chevalley property via discriminant ideals. 
%Therefore, discriminant ideals (and in particular, the discriminant) can be used to test whether a Cayley-Hamilton Hopf algebra in question has the Chevalley property. % Now we proceed to prove Theorem E in the introduction.

%Therefore, if an affine Cayley-Hamilton Hopf algebra $(H,C,\text{tr})$ admits a non-trivial discriminant ideal, then $H$ does not possess the Chevalley property.

\begin{theorem}\label{thm-CHHopf-Chev-dis} (Theorem D)
Let $(H,C,\text{tr})$ be an affine Cayley-Hamilton Hopf algebra. If $H$ has the Chevalley property, then, for $\ell =\text{FPdim}(\text{Gr}(H/\mathfrak{m}_{\overline{\varepsilon}}H))+1$,
$$D_{k}(H/C;\text{tr})=MD_{k}(H/C;\text{tr})=
\begin{cases} 
C, & 1\leq k\leq \ell-1, \\
0, & k\geq \ell.
\end{cases}$$
\end{theorem}
\begin{proof}
Since $H$ has the Chevalley property, so does $H/\mathfrak{m}_{\overline{\varepsilon}}H$. Moreover, the condition (iv) in Theorem \ref{thm-lowCHHopf-minlif1} (2) is satisfied for any $\mathfrak{m}\in \text{maxSpec}C$, as the left dual of any irreducible $H$-module is still irreducible. Thus, one has 
$$\mathcal{V}(D_{k}(H/C;\text{tr}))=\mathcal{V}(MD_{k}(H/C;\text{tr}))=
\begin{cases} 
\varnothing, & 1\leq k\leq \ell-1, \\
\text{maxSpec}C, & k\geq \ell.
\end{cases}$$
Since $\text{char}\mathbbm{k}=0$,  $C$ is reduced by Cartier's Theorem. The conclusion follows.
\end{proof}
\begin{remark}
%Theoerm D now follows from 
Theorem \ref{thm-CHHopf-Chev-dis}  implies that any affine Cayley-Hamilton Hopf algebra $(H,C,\text{tr})$ with the Chevalley property satisfies that
$$\varnothing =\mathcal{V}(D_{1}(H/C;\text{tr}))=\cdots=\mathcal{V}(D_{\ell-1}(H/C;\text{tr}))\subsetneq \text{maxSpec}C=\mathcal{V}(D_{\ell}(H/C;\text{tr}))=\cdots,
$$
where $\ell\coloneqq \text{FPdim}(\text{Gr}(H/\mathfrak{m}_{\overline{\varepsilon}}H))+1$. Thus, \textit{the number of distinct terms in the ascending chain of zero loci of the discriminant ideals of} $(H,C,\text{tr})$ \textit{can be interpreted as a measure of how far the Hopf algebra $H$ is from having the Chevalley property.}
\end{remark}
%\begin{remark}
%Note that Theorem \ref{thm-CHHopf-Chev-dis} provides a conceptual treatment for the triviality of all discriminant ideals of the group algebras of central extensions of finite groups by finitely generated abelian groups, as considered in Example \ref{eg-discrzer-grpalg}.
%\end{remark}


By Example \ref{eg-discrzer-grpalg}, all the zero loci of discriminant ideals of the group algebras of central extensions of finite groups by finitely generated abelian groups are trivial. This can also be regarded as a direct consequence of Theorem \ref{thm-CHHopf-Chev-dis}.

\begin{example} Let $H=H(n,t,\epsilon)$ be the infinite Taft algebra in Example \ref{eg-infiTaft}, where $n\geq 2, 1\leq t\leq n$ are two coprime integers, and $\epsilon$ is an $n$th primitive root of unity.  By (\ref{eq-zeroset-inftaft}) and Theorem \ref{thm-CHHopf-Chev-dis}, $H$ does not have the Chevalley property.
\end{example}

%Recall that for an algebra with trace $(A,C,\text{tr})$, its discriminant $\Delta(A/C;\text{tr})$  is defined in (\ref{eq-discri-def1}). 
The following is an immediate consequence of \eqref{eq-disc=ideal1} and Theorem \ref{thm-CHHopf-Chev-dis}.
\begin{corollary}\label{cor-discri-chev-test}
Let $(H,C)$ be a pair of Hopf algebras satisfying the hypothesis (FinHopf) and $H$ is a free $C$-module.  If the discriminant $\Delta(H/C;\text{tr}_{\text{reg}})$ (with respect to the regular trace) is neither zero nor an invertible element in $C$, then $H$ does not have the Chevalley property.
\end{corollary}

In fact, for affine prime Cayley-Hamilton Hopf algebras, we can say more.
\begin{corollary}
Let $(H,C,\text{tr})$ be an affine Cayley-Hamilton Hopf algebra, and $H$ be a prime ring. Then the following conditions are equivalent. \label{cor-chev-primiff}
\begin{itemize}
\item[(1)] $H$ has the Chevalley property;
\item[(2)]All the discriminant ideals of $(H,C,\text{tr})$ are trivial;
\item[(3)]The square dimension function $\text{Sd}:\text{maxSpec}C\to\mathbb{N}$ is constant;
\item[(4)]All the fiber algebras $H/\mathfrak{m}H$ are semisimple;
\item[(5)]The identity fiber algebra $H/\mathfrak{m}_{\overline{\varepsilon}}H$ is semisimple;
\item[(6)] $H$ is commutative.
\end{itemize}
\end{corollary}
\begin{proof}
(1)$\Rightarrow$(2) This is clear by Theorem \ref{thm-CHHopf-Chev-dis}.
\par (2)$\Rightarrow$(3) It follows from (\ref{eq-CHzero-ire-sd}).
\par (3)$\Rightarrow$(4) For any $\mathfrak{m},\mathfrak{n}\in \text{maxSpec}C$, $\text{Sd}(\mathfrak{m})=\text{Sd}(\mathfrak{n})$. By \cite[Cor. III.4.10]{MR1898492}, there is a fiber algebra $H/\mathfrak{m}_{0}H$ which is semisimple, which implies that $\text{Sd}(\mathfrak{m}_{0})=\dim_{\mathbbm{k}}H/\mathfrak{m}_{0}H$. It follows from Proposition \ref{prop-equfibalg-conrp} (1) that $\text{Sd}(\mathfrak{m})=\dim_{\mathbbm{k}}H/\mathfrak{m}H$ for all $\mathfrak{m}\in \text{maxSpec}C$. Therefore $H/\mathfrak{m}H$ is semisimple for all $\mathfrak{m}\in \text{maxSpec}C$.
\par(4)$\Rightarrow$(5) Obvious.
\par(5)$\Rightarrow$(6) By Corollary \ref{cor-semisimall1}, the fiber algebra $H/\mathfrak{m}H$ is semisimple for any $\mathfrak{m}\in \text{maxSpec}C$. 
%Since the homomorphic image of any Artinian simple ring is also an Artinian simple ring, 
For any $\hat{\mathfrak{m}}\in \text{maxSpec}Z(H)$, $\hat{\mathfrak{m}}\cap C$ is a maximal ideal of $C$, and so $H/\hat{\mathfrak{m}}H$ is semisimple. Let $n$ be the PI-degree of $H$. By \cite[Thm. 3.1 (b)]{MR3886192}, $H/\hat{\mathfrak{m}}H\cong \text{M}_{n}(\mathbbm{k})$ as $\mathbbm{k}$-algebras. If follows that the $\mathbbm{k}$-dimension of any irreducible $H$-module is $n$. However, the trivial representation of $H$ is $1$-dimensional, which forces $n=1$. Therefore, $H$ is commutative by Posner's Theorem.
\par(6)$\Rightarrow$(1): Clear.
\end{proof}
%\begin{remark}
%Thus, any prime affine Cayley-Hamilton Hopf algebra that is not commutative (over an algebraically closed field of characteristic zero) does not have the Chevalley property.
%\end{remark}
\begin{remark}
In general, the implication (1) $\Rightarrow$ (6) in Corollary \ref{cor-chev-primiff} does not hold without the primeness condition, as Example \ref{eg-grpalg-cenex1} shows.
\end{remark}
Theorem \ref{thm-CHHopf-Chev-dis} provides a necessary condition for any affine Cayley-Hamilton Hopf algebra $(H,C,\text{tr})$ to have the Chevalley property via discriminant ideals. This is clearly not sufficient (for example, take $H$ to be a finite-dimensional Hopf algebra over $\mathbbm{k}$ that does not have the Chevalley property, and consider $C=\mathbbm{k}$). So it is natural to ask:
\begin{que}
Is there a necessary and sufficient condition for all affine Cayley-Hamilton Hopf algebras to have the Chevalley property based on the properties of discriminant ideals?
\end{que}



