\subsection{Categories $\mathcal{O}^{\mathfrak{b},\pm}_{\ZZ}$}\label{sezione categorie O}
 In \cite{hl16o}, the authors have defined the full sub-categories $\mathcal{O}^{\mathfrak{b},\pm}_{\ZZ}$ of $\mathcal{O}^{\mathfrak{b},\pm}$ as follows:
\begin{definition}\cite{hl16o}
    $\mathcal{O}^{\mathfrak{b},\pm}_{\ZZ}$ is the sub-category of $\mathcal{O}^{\mathfrak{b},\pm}$ whose simple constituents have highest $\ell$-weights $\Psi=(\psi_i(z))_{i\in I}$ such that all roots and poles of $\psi_i(z)$ are of the form $q^r$, with $(i,r)\in V$.
\end{definition}

In \cite{hl16o}, the authors proved that the Grothendieck rings $ K_0(\mathcal{O}^{\mathfrak{b},\pm}_{\ZZ})$ are isomorphic to a completion of a cluster algebra.
\begin{definition}\label{def Ae}
    Let $\mathcal{A}_e$ be the cluster algebra with initial seed the quiver $\Gamma_e$ and initial cluster variables $\{z_{i,r}\}_{(i,r)\in V}$. We denote such seed by $\Sigma_e$.
\end{definition}
By Laurent phenomenon $\mathcal{A}_e$ is contained in $\ZZ[z_{i,r}^{\pm 1}]_{(i,r)\in V}$. 
\begin{theorem}[{\cite[Theorem 4.2]{hl16o}}]\label{teorema cluster hl16}
The assignment
\begin{equation}
    z_{i,r}\mapsto \big[L_{i,q^r}^{\mathfrak{b},+}\big],\qquad (i,r)\in V,
\end{equation}
defines an injective morphism of algebras
\begin{equation}
    f:\mathcal{A}_e\hookrightarrow K_0(\mathcal{O}^{\mathfrak{b},+}_{\ZZ}), 
\end{equation}  and the topological closure of $f(\mathcal{A}_e)$ is the entire $ K_0(\mathcal{O}^{\mathfrak{b},+}_{\ZZ})$.
\end{theorem}
\begin{remark}
    The topological closure of $f(\mathcal{A}_e)$ inside $K_0(\mathcal{O}^{\mathfrak{b},+}_{\ZZ})$ is denoted by $f(\mathcal{A}_e)\hat{\otimes}\mathcal{E}$, see \cite{hl16o} for more details. We will use an analogue notation for topological closures also in the rest of the paper. 
\end{remark}
By Theorem 5.17 in \cite{hl16o}, $ K_0(\mathcal{O}^{\mathfrak{b},+}_{\ZZ})$ and $ K_0(\mathcal{O}^{\mathfrak{b},-}_{\ZZ})$ are isomorphic algebras, thus an analogue of Theorem \ref{teorema cluster hl16} can be written for $ K_0(\mathcal{O}^{\mathfrak{b},-}_{\ZZ})$.

\subsection{The quantum Grothendieck ring $K_t(\mathcal{O}^{\mathfrak{b},+}_{\ZZ})$}\label{qgrb}

 Bittmann in \cite{b21} constructed a quantum \Groth ring for the category $\mathcal{O}^{\mathfrak{b},+}_{\ZZ}$ using a quantum cluster algebra approach. We recall here the main ingredients of her construction.\\ The quantum Grothendieck ring $ K_t(\mathcal{O}^{\mathfrak{b},+}_{\ZZ})$ is realized as a quantum cluster algebra, hence it lives inside a quantum torus. In order to define the quantum torus, one needs some information about the so-called Cartan datum, that can be found in \cite[Section 3.2]{b21}. In particular, the entries of the inverse quantum Cartan matrix $\tilde{C}(z)$ ($z$ is an indeterminate) can be expressed as a power series in $z$ as follows.
For $i,j\in I$,
\begin{equation}
    \Tilde{C}_{i,j}=\sum_{m=1}^{\infty}\Tilde{C}_{i,j}(m)z^m\quad \in \ZZ[[z]].
\end{equation}
Furthermore, for all $i,j\in I$, let $\mathcal{F}_{i,j}:\ZZ\to\ZZ$ be the skew-symmetric map such that, for all $m\geq 0$
\begin{equation}\label{F}
    \mathcal{F}_{i,j}(m)=-\sum_{\substack{k\geq 1 \\ m\geq 2k-1}}\Tilde{C}_{i,j}(m-2k+1).
\end{equation}
\begin{definition}\label{quasi toro lea}
    Let $T_{t,e}$ be the $\ZZ[t^{\pm 1}]$-algebra generated by the $z_{i,r}^{\pm 1}$, for $(i,r)\in V$, with non-commutative product $\ast_e$ and $t$-commutation relations
\begin{equation}
    z_{i,r}\ast_e z_{j,s}=t^{\mathcal{F}_{i,j}(s-r)}z_{j,s}\ast_e z_{i,r},\qquad (i,r),(j,s)\in V.
\end{equation}
\end{definition}
Consider now the scalars extension $\ZZ[t^{\pm 1/2}]\otimes_{\ZZ[t^{\pm 1}]}T_{t,e}$ that, by abuse of notation, we keep denoting by $T_{t,e}$.  
The quantum torus considered in \cite{b21} is 
\begin{equation}\label{toro di lea}
    \mathcal{T}_{t,e}:=T_{t,e}\hat{\otimes}_{\ZZ[t^{\pm 1/2}]}\mathcal{E}.
\end{equation}


\begin{example}\label{f}
    For $\g=sl_2$, $I=\{1\}$, Equation \eqref{F} simplifies, yielding
    \[z_{1,r}\ast z_{1,s}=t^{f(s-r)}z_{1,s}\ast z_{1,r},\qquad \forall s,r\in V=2\ZZ,\] where $f : \ZZ\to \ZZ$ is the skew-symmetric function defined by 
\begin{equation}
    f\vert_{\NN} : m\mapsto \frac{(-1)^m-1}{2}.
\end{equation}
\end{example}

As mentioned above, in \cite{b21} the author constructs $ K_t(\mathcal{O}^{\mathfrak{b},+}_{\ZZ})$ as a quantum cluster algebra. We refer to the original paper \cite{bz05} by Fomin and Zelevinsky for the definition and properties of these algebras. We report here the definition of compatible pair, since it is crucial in the sequel. It is given for finite rank cluster algebras, but the same holds for the infinite rank case. Let us denote by $\llbracket 1,m\rrbracket$ the interval of integers from $1$ to $m$.
\begin{definition}\label{def compatibile}
   Let $\tilde{B}=(b_{ij})$ be a $m\times n$ integer matrix, with rows labeled by $\llbracket 1,m\rrbracket$ and columns labeled by $\mathbf{ex}\subset [1,m]$, meaning that in each cluster there are $n$ exchangeable variables and $m-n$ frozen ones. Let $\Lambda=(\lambda_{ij})_{1\leq i,j\leq m}$ be a $m\times m$ skew-symmetric integer matrix. The couple $(\Lambda, \tilde{B})$ is said to be \textit{compatible} if, for all $i\in \mathbf{ex}$ and $1\leq j\leq m$, we have 
   \[\sum_{k=1}^m b_{ki}\lambda_{kj}=\delta_{ij}d_j,\] for some integers $d_j$, $j\in\mathbf{ex}$, either all non-negative or all non-positive. In other words, the $n\times m$ matrix $\tilde{D}=\tilde{B}^T\Lambda$ consists of two blocks: the $\mathbf{ex}\times\mathbf{ex}$ diagonal block $D$ with diagonal entries $d_j$ and a zero block.
\end{definition}
In particular, if $(\Lambda,\tilde{B})$ is a compatible pair, then $\tilde{B}$ has full rank.
In \cite{b21} the author considers the same basic infinite quiver $\Gamma_e$ used \cite{hl16o}. Let us denote by $B_e$ its exchange matrix, which is a $V\times V$ skew-symmetric integer matrix. The quantization matrix encodes the $t$-commutation relations between the initial cluster variables $\{z_{i,r}, (i,r)\in V\}$. In \cite{b21} $\Lambda_e$ is defined as the $V\times V$ skew-symmetric matrix such that for all $s>r$ 
\begin{equation}\label{lambda e}
    \Lambda_{(i,r),(j,s)}=\mathcal{F}_{i,j}(s-r.)
\end{equation}

\begin{proposition}[{\cite[Proposition 6.2.4]{b21}}] \label{compatibilita lea}
The pair $(\Lambda_e,B_e)$ is compatible, in the sense of quantum cluster algebras \cite{bz05}. Moreover, 
\[B_e^T\Lambda_e=-2\mathrm{Id}.\]
\end{proposition}

 Let $\mathcal{A}_{t,e}$ be the quantum cluster algebra associated with the mutation-equivalence class of $(B_e,\Lambda_e)$. By quantum Laurent phenomenon \cite[Corollary 5.2]{bz05}, $\mathcal{A}_e\subset T_{t,e}$.
\begin{definition}\cite[Definition 6.3.4]{b21}\label{def quantum gr ring lea}
    The quantum Grothendieck ring for the category $\mathcal{O}^{\mathfrak{b},+}_{\ZZ}$ is defined as
    \[ K_t(\mathcal{O}^{\mathfrak{b},+}_{\ZZ}):=\mathcal{A}_{t,e}\hat{\otimes}\mathcal{E},\] where the completed tensor product has been defined in \eqref{toro di lea}. Thus, $ K_t(\mathcal{O}^{\mathfrak{b},+}_{\ZZ})$ is a $\mathcal{E}[t^{\pm 1/2}]$-subalgebra of $\mathcal{T}^e_t$.
\end{definition}
A crucial point of Bittmann's result is that her construction is compatible with the quantum \Groth ring $ K_t(\mathcal{C}_{\ZZ}^-)$, where $\mathcal{C}^-$ is a full subcategory of the category of finite-dimensional $\mathcal{U}_q(\hat{\g})$-modules $\mathcal{C}$:
\begin{theorem}[{\cite[Corollary 7.3.5]{b21b}}]\label{inclusione tori hl e lea}
    There is an inclusion of rings:
    \[ K_t(\mathcal{C}_{\ZZ}^-)\subset  K_t(\mathcal{O}^{\mathfrak{b},+}_{\ZZ}).\]
\end{theorem}


\subsection{Geiss-Hernandez-Leclerc construction}\label{ghl construction}
We summarize here the most important theorems contained in \cite{ghl} (from our point of view) and we add some results that are implicit in that work. Recall that $s_i$, $i\in I$, denotes a simple reflection in the Weyl group of $\g$. First, we recall the construction of the quiver $\Gamma_c$. 
\subsubsection{The cluster algebra $\mathcal{A}_{w_0}$}

\begin{definition}\cite[Definition 3.1]{ghl}\label{procedura ghl}
    Consider the basic infinite quiver $\Gamma_e$ with vertex set $V$. For $(i,r)\in V$, we obtain $\Gamma_{s_i,r}$ from $\Gamma_e$ following the procedure:
    \begin{enumerate}
        \item insert a new vertex $\ast$ between vertices $(i,r)$ and $(i,r-2)$;\\
        \item replace the arrow $(i,r)\leftarrow (i,r-2)$ by a pair of arrows $(i,r)\rightarrow \ast \leftarrow (i,r-2)$;\\
        \item for $j$ with $c_{i,j}<0$, replace the arrow $(i,r)\rightarrow (j, r+c_{i,j})$ by an arrow $\ast \rightarrow (j,r+c_{i,j})$;\\
        \item change the labels of the vertices on the lower half of column $i$ as follows:
        \[\ast\mapsto (i,r-2),\qquad (i,r-2k)\mapsto (i,r-2k-2),\ (k\geq 1).\]
    \end{enumerate}
\end{definition}
