\subsection{Compatible pair}
Now we are ready to define:
\begin{equation}\label{definizione lambda c}
    \Lambda_c:= \left(G^{(\infty)}\right)^T \Lambda_e G^{(\infty)}.
\end{equation}
Note that $\Lambda_e$ has infinite non-zero entries in each row and column, but thanks to the form of $G^{\infty}$ the product above is well defined.
\begin{proposition}\label{quantum cluster ade}
    The pair $\left(\Lambda_c,B_c\right)$ is compatible.
\end{proposition}
\begin{proof}
    Thanks to our definition of $\Lambda_c$, to Equation \eqref{formula g matrix} and to the compatibility of $\left(\Lambda_e,B_e\right)$ (see Proposition \ref{compatibilita lea}) the proof of compatibility is straightforward:
    \begin{align*}
        \left(B_c\right)^T\Lambda_c &= \left(\left(G^{(\infty)}\right)^{-1}B_e(G^{(\infty)})^{-T}\right)^{T}\left(G^{(\infty)})^T\Lambda_e(G^{\infty})\right)\\
        &=\left(G^{(\infty)}\right)^{-1}B_e^T\Lambda_e G^{(\infty)}\\
        &=\left(G^{(\infty)}\right)^{-1}(-2Id_{V\times V})\ G^{(\infty)}\\
        &=-2\mathrm{Id}_{V\times V}.
    \end{align*} 
\end{proof}

\subsection{Quantum tori}
We use freely the Notation \ref{notation v}.

\begin{definition}
    The quantum torus $T_{t,c}$ is the $\ZZ[t^{\pm \frac{1}{2}}]$-algebra generated by the $Q_v^{\pm 1}$, for $v\in V$, with non-commutative product $\ast_c$ and $t$-commutation relations
    \[Q_v\ast_c Q_{v'}=t^{(\Lambda_c)_{v,v'}}Q_{v'}\ast_c Q_v,\quad \forall v,v'\in V.\]
\end{definition}

\begin{remark} \label{commutative monomial}
    When dealing with quantum tori, like $(T_{t,c},\ast_c)$ or $(T_{t,e},\ast_e)$ (see Definition \ref{quasi toro lea}), it is useful to consider the so-called \textit{commutative} monomials. Note that for every $v,w$ in $V$, the expression
    \[t^{\frac{1}{2}(\Lambda_c)_{w,v}}Q_v\ast_c Q_w=t^{\frac{1}{2}(\Lambda_c)_{v,w}}Q_w\ast_c Q_v\] is invariant under permutation of $v$ and $w$. Thus, we denote 
    \[Q_vQ_w:=t^{\frac{1}{2}(\Lambda_c)_{w,v}}Q_v\ast_cQ_w\] and we call it a \textit{commutative monomial}. More in general, the non commutative product of elements in the quantum torus depends heavily on the order, so to get rid of this technicality, it is useful to consider commutative monomials of several variables. Let us denote by $\overset{\rightarrow}{\ast}$ the ordered product of elements in $T_{t,c}$. Then, for a family of integers $(n_v)_{v\in V}$ with only finitely many non-zero components, we define
    \[\prod_{v\in V'}Q_v^{n_v}:=t^{\frac{1}{2}\sum_{v<u}n_vn_u(\Lambda_c)_{u,v}}\ \overset{\rightarrow}{\ast_c}Q_v^{n_v}.\] Then, we can consider either the commutative or non-commutative product of commutative monomials.\\Similarly one can define commutative monomials for $T_{t,e}$, see \cite[Equation (5.11)]{b21}. 
\end{remark}

\begin{definition}
    We extend the quantum torus $T_{t,c}$ to 
    \[\mathcal{T}_{t,c}:=[\underline{P}]\otimes_{[P]}(\mathcal{E}\hat{\otimes}_{\ZZ}T_{t,c}).\]  Note that as $\mathcal{E}$-algebra, $\mathcal{T}_{t,c}$ has another set of generators made of the initial $\underline{Q}$-variables.
\end{definition}

\begin{definition}\label{def quantum cluster nostra}
    Let $\mathcal{A}_{t,w_0}$ be the quantum cluster algebra associated with the mutation class of $(\Lambda_c,B_c)$. Then, by the quantum Laurent phenomenon, $\mathcal{A}_{t,w_0}\subset \mathcal{T}_{t,c}$.
\end{definition}

