         &Q_{s_1(\omega_1),q^r}=\Psi_{1,q^{r-2}}^{-1}\Psi_{2,q^{r-1}}\Sigma_{1,q^{r-2}}\  &&\Rightarrow\ (\eta\ \circ\ \Xi)\left(Q_{s_1(\omega_1),q^r}\right)= -\boldsymbol{e}_{(1,r-2)}+\boldsymbol{e}_{(2,r-1)}\\
