\subsection{Invariants counting semistable objects}
\label{sec:InvDef}
Here, I introduce the invariants counting semistable objects following the approach of \cite{JoyceWC} based on \cite{mochizuki}. Their construction will depend on the choice of $k\in K$, so it is of import to show that the result is independent of $k$,  especially in cases of independent interest like Gieseker or slope semistable sheaves. This was presented as Problem (II) in §\ref{sec:introWCeqhom}, while Remark \ref{rem:welldefinednotneeded} mentioned situations when addressing this problem is not necessary.

Fix an indexing set $K$ with subcategories $\{\mA_k\}_{k\in K}$ of $\mA$ as in Definition \ref{Def:quiverpairs}. The motivation behind the definition of the invariants $\langle \mM^\sig_\al\rangle$ stems from the Joyce--Song wall-crossing formula conjecture in \cite[(4.4)]{GJT}. It is formulated using the natural extension of the vertex algebra structure to the homology of $\mN_k$. In Definition \ref{Def:FlagVA} later, it will be generalized to include $\mN_{\Flag_k}$ as I prefer to avoid complicating the exposition of the present subsection. 
\begin{definition}[{\cite[Definition 2.6 and 2.7]{bojko2}}]
\label{def:NkVA}
The following set of data is defined for any $k\in K$.
\begin{itemize}
\item Let $\mu_k,\rho_k$ be the natural extensions of $\mu,\rho$ from \eqref{eq:murho}. 
\item I will use $\mV$ and $\mE$ to denote the universal vector space and the universal object of $\mA$ for the first factor of $\mN_k\times \mN_k$. The universal objects for the second copy of $\mN_k$ will be labeled by $\mW$ and $\mF$. Furthermore, set
\begin{align*}
\Theta_k =& -(\pi\times\pi)^*\Ext^\vee - 2\mV\otimes \mW^* \\&- \mV\otimes \RHom_{\mN_k}\big((1,0),\mF\big)^* - \mW^*\otimes \RHom_{\mN_k}\big((1,0),\mE\big)
\end{align*}
as a K-theory class on $\mN_k\times \mN_k$.
\item Using the expression $\chi\big(\al(k)\big)$ from \eqref{eq:chialk}, define the pairing 
$$
\begin{tikzcd}
\chi_k: \big(\ZZ\times \ov{K}(\mA)\big)^{\times 2}\arrow[r]&\ZZ
\end{tikzcd}
$$
by
$$
\chi_k\big((d,\al),(e,\be)\big) = \chi\big(\al,\be\big) -d\chi\big(\beta(k)\big) - e\chi\big(\al(k)\big) + 2de\,.
$$
\item Introduce the signs 
$$
\varepsilon^k_{(d,\alpha),(e,\beta)} = (-1)^{d\chi(\beta(k))}\varepsilon_{\al,\beta}\qquad \textnormal{for}\quad (d,\al),(e,\be)\in \ZZ\times \ov{K}(\mA)\,.
$$
Note that they satisfy the analog of \eqref{eq:epsidentity} and 
$$
\varepsilon^k_{(d,\al),(e,\beta)} = (-1)^{\chi_k((d,\al),(e,\beta))}\varepsilon_{(e,\beta),(d,\al)}
$$
because of \eqref{eq:symsign}.
\end{itemize}
The vertex algebra on
$$
W^k_* =  H_{*+\vdim}(\mN_k)
$$
and its localized version $W^k_{\loc,*}$ are constructed by following Definition \ref{Def:VAlocal} or \ref{Def:VAglobal} except that the state-field correspondence is determined by
\begin{align*}
    Y(v,z)w &= (-1)^{a\chi_k((d,\al),(e,\beta))}\varepsilon^k_{(d,\al),(e,\beta)} \,\mu_\ast\bigg((e^{zT}\otimes \textnormal{id})\frac{v\boxtimes w}{z^{-\chi_k((d,\al),(e,\be))}c_{z^{-1}}(\Theta_{k})}\bigg)
    \end{align*}
    for $v\in H_a(\mN_{d,\al})$ and $w\in H_*(\mN_{e,\beta})$. When working $\T$-equivariantly, one should use $\boxtimes^{\T}$ from \eqref{eq:Kunnethlocal} or  \eqref{eq:equivKunneth} instead.
\end{definition}

When $\al\in \msE(\mA)$ and $\sig\in W_{\al,k}$, the wall-crossing formula for Joyce--Song pairs that was used in \cite{bojko2, bojko3} for CY fourfolds takes the form
\begin{equation}
\label{eq:JSWC}
\big[N^{\JS}_{k,\al}\big]^{\vir} = \sum_{\begin{subarray}{c}
        \un{\alpha}\,\vdash_{\mA} \alpha\,, \\
          \phi(\alpha_i) =\phi(\alpha) \end{subarray}}\frac{1}{n!}\Big[\big\langle \mM^\sigma_{\alpha_n}\big\rangle, \cdots \Big[\big\langle \mM^\sigma_{\alpha_1}\big\rangle,  e^{(1,0)}_k\Big]\cdots\Big]
\end{equation}
in $W^k_{*+2}/T(W^k_*)$. Here $e^{(1,0)}_k$ is the point class of $\{(1,0)_k\}\in \mN_k$ and one considers $\mM_{\mA_k}$ as a substack of $\mN_k$. For Behrend--Fantechi obstruction theories, the conditions necessary for this formula to hold were checked in \cite[Appendix A]{bojko3}.  

Ideally, one would define the invariants appearing on the right hand side of \eqref{eq:JSWC} by induction on $\rk_{\sig}(\al)$. However, it is not self-evident that they exist.
%$$
%[N^{\JS}_{k,\al}]^{\vir} - \textnormal{ lower rank contributions }= \Big[\langle \mM^\sigma_{\alpha_1}\rangle, e^{(1,0)}_k \Big]\,.
%$$
One can use the following lemma to state the problem differently.
\begin{lemma}
\label{lem:pushJSandinj}
\leavevmode
\vspace{-4pt}
   \begin{enumerate}[label=\roman*)]
       \item  The formula \eqref{eq:JSWC} implies
  \begin{equation}
        \label{eq:Masigdef}
        \blangle \mM^{\sig}_{\alpha}\brangle = \Omega^{\sig}_{\alpha} - \sum_{\begin{subarray}{c}
            \un{\alpha}\,\vdash_{\mA} \alpha \,, n\geq 2\,,\\
          \bph(\alpha_i) =\bph \end{subarray}}\frac{\chi(\al_1(k))}{n!}\Big[\blangle\mM^\sig_{\al_n}\big\rangle,\Big[\cdots\Big[\big\langle\Masit\big\rangle,\langle\Masio\big\rangle \Big]\cdots \Big]\Big]\,.
    \end{equation}
    where 
\begin{equation}
\label{eq:Omegasigal}\chi\big(\alpha(k)\big)\,\Omega^{\sig,k}_{\alpha}=\big(\pi^{\JS}_{\alpha}\big)_*\Big(\Big[N^{\JS}_{k,\alpha}\Big]^{\vir}\cap c_{\chi(\alpha(k))-1}\big(T_{\pi_{\mA_k}} \big)\Big)\,.
\end{equation}
     \item The map 
     \begin{equation}
     \label{eq:brackinj}
    \begin{tikzcd} \Big[-,e^{(1,0)}_k\Big]: H_{*}\Big(\mM^{\rig}_{\mA_k}\cap \mM^{\rig}_{\al}\Big)\arrow[r]&H_*\Big(\mN^{\rig}_k\Big)\end{tikzcd}
     \end{equation}
     is injective whenever $\al\notin \Ker(\chi)$.
   \end{enumerate}
\end{lemma}
\begin{proof}
Both i) and ii) follow from 
\begin{equation}
\label{eq:bracketpushdown}
 (\pi_{\JS})_*\Big(\Big[\ov{v},e^{(1,0)}_k\Big]\cap c_{\chi(\alpha(k))-1}\big(T_{\pi_{\mA_k}} \big)\Big) = (-1)^{a\chi(\al(k))}\chi\big(\al(k)\big)\ov{v}
\end{equation}
for any $\ov{v}\in H_a(\mM^{\rig}_{\mA_k}\cap \mM^{\rig}_{\al})$ whenever $\al\notin \Ker(\chi)$. To see this, choose a lift $v\in H_a(\mM_{\mA_k})$ of $\ov{v}$. Setting $\pi:= \pi_{\JS}$ for now and 
$$
\FG{\mV_k} :=-
\RHom_{\mN_k}\big((1,0)_k,\mE\big)\,, \qquad \FG{\mW_k} :=-
\RHom_{\mN_k}\big((1,0)_k,\mF\big)\,, $$ one computes the left hand side of \eqref{eq:bracketpushdown} to be equal to $(-1)^{a\chi(\al(k))}\ov{(-)}$ of
\begin{align*}
\label{eq:bracketpushcomp}
&\,[z^{-1}]\bigg\{\pi_*\mu_\ast\bigg((e^{zT}\otimes \textnormal{id})\frac{v\boxtimes e^{(1,0)}_k}{z^{\chi(\al(k))}c_{z^{-1}}\big(\mW^*\otimes \FG{\mV_k}\big)}\bigg)\cap c_{\chi(\al(k))-1}\big(\mV^*\otimes \FG{\mV_k}\big) \bigg\}\\
\stackrel{(1)}{=}\,&[z^{-1}]\bigg\{\pi_*\mu_\ast\bigg[(e^{zT}\otimes \textnormal{id})\bigg(\frac{v\boxtimes e^{(1,0)}_k }{z^{\chi(\al(k))}c_{z^{-1}}\big(\mW^*\otimes \FG{\mV_k}\big)}\bigg)\cap c_{\chi(\al(k))-1}\big(\mW^*\otimes \FG{\mV_k}\big)\bigg] \bigg\}\\
\stackrel{(2)}{=}\,&[z^{-1}]\bigg\{\pi_*\mu_\ast\bigg[(e^{zT}\otimes \textnormal{id})\bigg(\frac{v\boxtimes e^{(1,0)}_k}{z^{\chi(\al(k))}c_{z^{-1}}\big( \FG{\mV_k}\big)}\cap\frac{d}{dz}\Big(z^{\chi(\al(k))}c_{z^{-1}}\big(\FG{\mV_k}\big)\Big)\bigg)\bigg]  \bigg\}\\
\stackrel{(3)}{=}\,&[z^{-1}]\bigg\{e^{zT}\bigg(\frac{v\cap\chi(\al(k))z^{\chi(\al(k))-1}c_{z^{-1}}\big(\FG{\mV_k}\big)}{z^{\chi(\al(k))}c_{z^{-1}}\big( \FG{\mV_k}\big)}\bigg) \bigg\}\,.
\numberthis
\end{align*}
This is clearly equal to the right hand side of \eqref{eq:bracketpushdown}. Each step in the computations holds because
\begin{enumerate}[label=(\arabic*)]
    \item $\mu^*(\mV^*\otimes \FG{\mV_k}) = \mW^*\otimes \FG{\mV_k}$ when restricted to $\mM_{\al}\times \mN_{1,0}$.
    \item $\rho^* c_{\chi(\al(k))-1}\big(\mW^*\otimes \FG{\mV_k}\big) = \frac{d}{d\tau} \Big(\tau^{\chi(\al(k))}c_{\tau^{-1}}\big(\mW^*\otimes \FG{\mV_k}\big)\Big)$ where $\tau$ is the first Chern-class of the universal line bundle on $B\GG_m$. Further, one uses $
e^{zT} =\rho_*\Big(\sum_{j\geq 0}z^jp^j\boxtimes -\Big)$ and
\begin{equation}
\label{eq:tzconvolution}
\sum_{j\geq 0}z^jp^j\cap f(\tau) =\sum_{j\geq 0}p^jz^j  \cdot f(z)\end{equation}
for any formal power-series $f(\tau)$. The latter follows from $p^i\cap \tau^n = t^{i-n}$ for $i\geq n\geq 0$.
\item $\pi_*\mu_*(-\boxtimes e^{(1,0)}_k) = \id_{H_*(\mM_{\mA_k})}$ holds. Additionally, any power of $zT$ leads to 0 after projecting to the quotient, so the term containing $\frac{d}{dz}c_{z^{-1}}(\FG{\mV_k})$ only contains powers of $z$  less than -1.
\end{enumerate}
By \eqref{eq:bracketpushdown}, there is a left inverse of \eqref{eq:brackinj} as $\chi\big(\al(k)\big)> 0$. This proves i). 

To show ii), cap \eqref{eq:JSWC} with $c_{\chi(\al(k))-1}\big(\mV^*\otimes \FG{\mV_k}\big)=e(T_{\pi})$ and push it forward along $\pi$. I claim that this produces 
\eqref{eq:Masigdef}, which could be misconstrued as an application of \cite[§2.5]{GJT} that would require working with $c_{\chi(\al(k))}\big(\mV^*\otimes \FG{\mV_k}\big)$ instead. Because this is similar to the computation in \eqref{eq:bracketpushcomp}, I will only sketch the argument. For a K-theory class $\mK$, the notation $c_{\Rk-a}(\mK)$ will be used to represent the degree $\Rk(\mK)-a$ Chern class of $\mK$, where $\Rk(-)$ computes the rank of a K-theory class.

 Commuting $\mu_*$ appearing in the definition of the outermost bracket of each summand in \eqref{eq:JSWC} with $\cap c_{\chi(\al(k))-1}\big(\mV^*\otimes \FG{\mV_k}\big)$ produces
$$
\cap \,c_{\Rk-1}\big(\mW^*\otimes \FG{\mW_k}\big)\cdot c_{\Rk}\big(\mW^*\otimes \FG{\mV_k}\big) + \cap \,c_{\Rk}\big(\mW^*\otimes \FG{\mW_k}\big)\cdot c_{\Rk-1}\big(\mW^*\otimes \FG{\mV_k}\big)\,.
$$
I claim that the term interacting with the second summand vanishes after applying $\pi_*$. For this, choose lifts $\blangle \mM^{\sig}_{\al_i}\brangle\in H_*(\mM_{\mA_k})$, and represent 
\begin{equation}
\label{eq:pullbackofTpi}
\Big[\big\langle \mM^\sigma_{\alpha_{n-1}}\big\rangle, \cdots \Big[\big\langle \mM^\sigma_{\alpha_1}\big\rangle,  e^{(1,0)}_k\Big]\cdots\Big]\,.
\end{equation}
by a class $\mathscr{L}\in H_*(\mN_k)$ computed in terms of these lifts using \eqref{eq:LiefromVA} but without projecting to the quotient by $T$ in each step. This clearly satisfies $\mathscr{L}\cap c_1(\mW) = 0$, so $c_{\Rk-1}\big(\mW^*\otimes \FG{\mW_k}\big)$ can be replaced by $ c_{\Rk-1}\big(\FG{\mW_k}\big)$. This allows me to use the push-pull formula in (co)homology to rewrite the pushforward along $\pi$ of the term associated to the second summand in \eqref{eq:pullbackofTpi} as an expression containing 
$$
\pi_*\Big(\mL\cap c_{\Rk}\big(\mW_*\otimes \FG{\mW_k}\big)\Big)\,.
$$
To this, one may already apply \cite[§2.5]{GJT} (recalled in more detail in the proof of Theorem \ref{thm:independence!}), so it becomes 
$$\Big[\big\langle \mM^\sigma_{\alpha_{n-1}}\big\rangle, \cdots \Big[\big\langle \mM^\sigma_{\alpha_1}\big\rangle,  \pi_*e^{(1,0)}_k\Big]\cdots\Big] = 0$$
where the Lie bracket is on $L_*$. For the vanishing, I used that $\pi_*e^{(1,0)}_k = \ket{0}$. 

As such, I am left with the term coming from $\cap \,c_{\Rk-1}\big(\mW^*\otimes \FG{\mW_k}\big)\cdot c_{\Rk}\big(\mW^*\otimes \FG{\mV_k}\big)$ which can be rewritten by induction and the above vanishing as an iterated Lie bracket 
$$
\Big[\big\langle \mM^\sigma_{\alpha_{n}}\big\rangle, \cdots \Big[\big\langle \mM^\sigma_{\alpha_2}\big\rangle,  \pi_*\Big(\Big[\big\langle \mM^\sigma_{\alpha_1}\big\rangle,  e^{(1,0)}_k\Big]\cap c_{\Rk-1}\big(\mV^*\otimes \FG{\mV_k}\big)\Big)\Big]\cdots\Big]\,.
$$
The induction step uses a computation just like the one in \eqref{eq:bracketpushcomp} to deal with the factor $c_{\Rk}\big(\mW^*\otimes \FG{\mV_k}\big)$. Applying \eqref{eq:bracketpushdown}  and noting that $a$ is even, since it is the virtual dimension, completes the proof.
\end{proof}

This is why \cite{JoyceWC} uses \eqref{eq:Masigdef} to define the invariants as follows.
