\end{proof}
 \begin{remark}
     \label{rem:dagJScomp}
     To give an interpretation of \eqref{eq:JScomparisondiag} in terms of derived schemes rather than just obstruction theories, one can replace the schemes $N^{\JS}_{D_1, \al}, N^{\JS}_{D, \al}$ by their $-2$-shifted symplectic derived enrichments $\bN^{\JS}_{D_1, \al}, \bN^{\JS}_{D, \al}$. Note that there is no map of \textit{derived schemes} 
     $$
   \bN^{\JS}_{D_1, \al}\xlongrightarrow{  \boldsymbol{\iota}_1} \bN^{\JS}_{D, \al}$$
   lifting \eqref{eq:D1embed} because this would imply that there is a distinguished triangle 
   $$
   \begin{tikzcd}
        \MM[-1]\arrow[r]&\iota_1^*(\FF_{1+2})\arrow[r]&\FF_1\arrow[r]&\MM
   \end{tikzcd}
   $$
   for some complex $\MM$. 

Instead, the construction \eqref{eq:VVbundle} applied to the universal sheaf on $\bN^{\JS}_{D, \al}$ leads to a derived vector bundle $\textbf{V}_1$ with the section $\boldsymbol{\mathfrak{v}}_1: \mO\to \textbf{V}_1$ and the \textit{derived vanishing locus}
     $$
    \boldsymbol{\mathfrak{v}}^{-1}_1(0) =: \widetilde{\bN}_{D_1,\al}\xlongrightarrow{\boldsymbol{\iota}_1}\bN^{\JS}_{D, \al}\,.
     $$
     The cotangent complexes fit into the distinguished triangle 
     $$
     \begin{tikzcd}
            \bs{\iota}_1^* \LL_{\bN^{\JS}_{D, \al}} \arrow[r]&\LL_{\widetilde{\bN}_{D_1,\al}}\arrow[r]&\textbf{V}^\vee_1[1]\arrow[r]&              \LL_{\bN^{\JS}_{D, \al}}|_{\boldsymbol{\mathfrak{v}}^{-1}_1(0)} [1]\,.
     \end{tikzcd}
     $$
     The relation to $\bN^{\JS}_{D_1, \al}$ is more subtle, because there is only a morphism
$$
 \widetilde{\bN}_{D_1,\al} \xlongrightarrow{\bs{\pi}} \bN^{\JS}_{D_1, \al}\,,
$$
which induces the distinguished triangle
\begin{equation}
\label{eq:etale}
\begin{tikzcd}
\bs{\pi}^*\LL_{\bN^{\JS}_{D_1, \al}}\arrow[r]&\LL_{\widetilde{\bN}_{D_1,\al}}\arrow[r]&\VV_1[2]\arrow[r]&\bs{\pi}^*\LL_{\bN^{\JS}_{D_1, \al}}[1]\,.
\end{tikzcd}
\end{equation}
Combining the distinguished triangles leads to the diagram
  \begin{equation}
    \label{eq:dagJScomp}
    \begin{tikzcd}[column sep=large]  \LL^\vee_{\widetilde{\bN}_{D_1,\al}}[2]\arrow[d]\arrow[r]&\bs{\pi}^*\LL_{\bN^{\JS}_{D_1, \al}}\arrow[d]\arrow[r]&\VV_1^\vee[1]\arrow[d,equal]\arrow[r]& \LL^\vee_{\widetilde{\bN}_{D_1,\al}}[3]\arrow[d]\\
 \bs{\iota}_1^* \LL_{\bN^{\JS}_{D, \al}} \arrow[r]&\LL_{\widetilde{\bN}_{D_1,\al}}\arrow[r]&\VV_1^\vee[1]\arrow[r]& \bs{\iota}_1^* \LL_{\bN^{\JS}_{D, \al}} [1]
    \end{tikzcd}\,,
    \end{equation}
    on $\widetilde{\bN}_{\nv,D_1}$ instead of $\bN^{\JS}_{D_1, \al}$. However, the truncation 
    $$
\pi = t_0(\bs{\pi}): t_0\big(\widetilde{\bN}_{ D_1,\al}\big)\longrightarrow N^{\JS}_{D_1, \al} 
    $$
    is a bijection and additionally étale by the distinguished diagram \eqref{eq:etale}. As such, it is an isomorphism, so after restricting \eqref{eq:dagJScomp} to $t_0\big(\widetilde{\bN}_{D_1,\al}) = N^{\JS}_{D_1, \al}$, one recovers \eqref{eq:JScomparisondiag}. That it satisfies the necessary self-duality and commutativity would follow from the claim that
    $$
    \begin{tikzcd}[column sep=small]
&\arrow[dl,"\bs{\pi}"]\widetilde{\bN}_{D_1,\al}\arrow[dr,"\boldsymbol{\iota}_1"]&\\
    \bN^{\JS}_{D_1, \al}&&\bN^{\JS}_{D, \al}
    \end{tikzcd}
    $$
    is a \textit{shifted Lagrangian correspondence}. This derived-geometric formulation of Pvp-digrams was observed by Park and stated independently in \cite{LagCor} by Schürg.
 \end{remark}
     \end{proof}

     \section{Applications}
     The second situation of Corollary \ref{cor:WCconsequences} concerning quivers was proved in §\ref{sec:quivers}. I will begin this section by applying it to a quiver that reproduces Hilbert schemes of points on $\CC^4$. The resulting wall-crossing formula is the equivariant version of the one used in \cite{bojko2}.

     The second subsection deals with the claim of Corollary \ref{cor:WCconsequences} that addresses local CY fourfolds. It describes the obstruction theories required by Assumption \ref{ass:obsonflag} and Assumption \ref{ass:pairWC}.c). I then discuss the situations where the rest of the assumptions apply, which, in particular, leads to the proof of Corollary \ref{cor:introDTPT}.    
\subsection{Wall-crossing into $\Hilb^n(\CC^4)$}
\label{sec:CY4dgC4}
Consider the CY4 dg-quiver
\begin{equation}
\label{eq:C4dgquiver}
 \includegraphics[scale=1.2]{C4quiver.pdf}
\end{equation}
with the superpotential 
$$
\BuOr{\mH} =\frac{1}{4} \sum_{\sig\in S_4}(-1)^{\sig}\BuOr{c_{\sig(1)\sig(2)}}\circ[x_{\sig(3)},x_{\sig(4)}]\,.
$$
Here I used $(-1)^{\sig}$ to denote the sign of the the permutation $\sig$ and $\BuOr{c_{ji}}:=-\BuOr{c_{ij}}$ for $i<j$. For any $\sig\in S_4$ and the edge $\BuOr{c_{\sig(1)\sig(2)}}$, I further set $\BuOr{c_{\sig(1)\sig(2)}^*} =(-1)^{\sig}\BuOr{c_{\sig(3)\sig(4)}}$ which is well-defined.

The action of the differential on degree \BuOr{$-1$} edges becomes
$$
d(\BuOr{c_{\sig(1)\sig(2)}}) = (-1)^{\sig}\frac{\partial^{\circ} \BuOr{\mH}}{\partial \BuOr{c_{\sig(3)\sig(4)}}} = [x_{\sig(1)},x_{\sig(2)}] \,.
$$
From this, one sees that the master equation \eqref{eq:mastereq} holds. 

I have used a different description as compared to Definition \ref{def:CY4quiver} because the degree \BuOr{$-1$} loops are not paired with themselves. The original definition can be recovered by introducing $$\BuOr{e_{\sig(1)\sig(2)}} = \BuOr{c_{\sig(1)\sig(2)}}+(-1)^\sig\BuOr{c_{\sig(3)\sig(4)}}$$
for any $\sig\in S_4$. 

The category $\mA$ of degree 0 representations of 
 $\wt{C}_4^{\bullet}$ is equivalent to the category of representations of the quiver $C_4:=H^0(\wt{C}_4^{\bullet})$. This quiver is given by forgetting the edges of degrees $<0$ in \eqref{eq:C4dgquiver} and imposing the relations
 $$
 [x_i,x_j] =0 \qquad\text{whenever}\quad 1\leq i<j\leq 4\,.
 $$ 
This is the quiver used in \cite{KRdraft} to prove Nekrasov's conjecture. Moreover, the obstruction theory described by Lemma \ref{lem:cotangentofQ} and \eqref{eq:C4dgquiver} coincides with the one appearing in this reference. 

Here, I will consider a simple family of stability conditions on the category $\mA$ that is determined by slope stabilities of $C_4$. It is given by 
$$
\begin{tikzcd}
{[-1,1]}\ni t\mapsto \ov{\mu}_{t} = (t,0)
\end{tikzcd}
$$
acting by $\ov{\mu}_{t}(d_{\infty},d_0) = d_{\infty}\cdot t$. This family has two stability chambers $\{t>0\}$, $\{t<0\}$, and one wall $\{t=0\}$. I will consider wall-crossing for representations 
$$
\begin{tikzcd}
&v=m_e(1)\arrow[d, phantom, "{\rotatebox[origin=c]{270}{$\in$}}"]\\
V_\infty\arrow[r,"m_e"]&V_0\arrow[loop,  in=-35,out=35, looseness=14, "X_i"]
\end{tikzcd}
$$
 of dimension vectors $(d_{\infty},d_0)$ with $d_{\infty}=0,1$ and $0\leq d_0<\infty$. Here, $X_i = m_{x_i}$ are endomorphisms of $V_0$ for $i\in [4]$, and when $d_{\infty}=1$, I identify $V_{\infty}=\CC$ and set $v:=m_e(1)$. With this notation, the semistable objects of class $(d_{\infty},d_0)$ are the following representations:
 \begin{table}[h]
 \centering
\begin{tabular}{c|c|c}
&$d_{\infty}=1$&$d_{\infty}=0$\\
\hline
$\{t>0\}$&$\Big\{p(X_i)(v)\colon p\in \CC[x_1,x_2,x_3,x_4]\Big\}=V_{0}$&all\\
$\{t=0\}$&all&all\\
$\{t<0\}$&$V_0=0$&all
\end{tabular}
\end{table}

It is well-known (see for example \cite[§2.2]{Szendroi} and \cite[Example 6.3.1]{Lam}) that  for $d_{\infty}=1$ and $\{t>0\}$, this description implies that 
\begin{equation}
\label{eq:Hilbident}
M^{\mu_{t}}_{(1,n)}\cong \Hilb^n(\CC^4)\qquad \text{and}\qquad \Big[M^{\mu_{t}}_{(1,n)}\Big]^{\vir}= \Big[\Hilb^n(\CC^4)\Big]^{\vir}\,.
\end{equation}
 Let $\mM_{mp}$ denote the moduli stack of 0-dimensional sheaves of characteristic $m$ on $\CC^4$. For $(d_{\infty},d_0) = (0,m)$ and $\{t>0\}$, the identification \begin{equation}\label{eq:Mnpident}\mM^{\mu_{t}}_{(0,m)}\cong \mM_{mp}
\end{equation}
 also holds. 

After an easy check of Assumption \ref{ass:stab} and Assumption \ref{ass:obsonflag}.a), Corollary \ref{cor:WCconsequences} applies to the family of stability conditions $\{\mu_t\}_{t\in [-1,1]}$. Explicitly, this means the following.
\begin{corollary}
\label{cor:hilbWC}
Using the identifications \eqref{eq:Hilbident} and \eqref{eq:Mnpident}, the formula
$$
\sum_{n>0}\big[\Hilb^n(\CC^4)\big]^{\vir}q^n= \exp\bigg\{\sum_{n>0}\Big[\langle \mM_{np}\rangle,- \Big]q^n\bigg\}e^{(1,0)}
$$
holds for the corresponding classes in $L_{\loc,0}$ constructed for $\mA$. Here $e^{(1,0)}$ is the point-class of the connected component $\mM_{(1,0)}$.
\end{corollary} 
The proof of Assumption \ref{ass:stab} will be addressed in a larger generality in the next subsection. 
\subsection{Stable pair wall-crossing on local Calabi--Yau fourfolds}
\label{sec:localCY4}
Due to the limitations explained in §\ref{sec:sheaves}, one needs to impose restrictions on the geometry to construct the obstruction theories of Assumption \ref{ass:obsonflag}. In this subsection, I will work with a fixed 3-fold $Y$ with a $\GG_m$-action. The total space $X$ of its canonical bundle $K_Y$ admits the induced $\GG_m$-action such that the natural projection $\pi: X\to Y$ is $\GG_m$-equivariant. Thus one obtains a short exact sequence of $\GG_m$-equivariant vector bundles
$$
\begin{tikzcd}
0\arrow[r]&\pi^*K_Y\arrow[r]&T_X\arrow[r]&\pi^*T_Y\arrow[r]&0\,.\end{tikzcd}
$$
Taking determinants and duals, one constructs an isomorphism of $\GG_m$-equivariant line bundles $K_X\cong \pi^*K_Y ^* \otimes \pi^*K_Y\cong \mO_X$. Thus $X$ has a $\GG_m$-equivariant Calabi--Yau form and \cite{OT} define equivariant virtual fundamental cycles of perfect complexes on $X$.

I now briefly recall the spectral correspondence argument which was used for curves in \cite{BNR}. I will follow the formulation presented in \cite{TT1}. Thus, let $\pi: X\to Y$ be the above projection with $Y$ not necessarily compact. For each compactly supported sheaf $F$ on $X$, consider the pair $(F,\eta)$ where $\eta:F\to F\otimes \pi^*K_Y$ is the tautological section. Projecting it to $Y$ produces a Higgs pair $(\pi_*F,\phi)$ where
$$
\begin{tikzcd}
\phi:=\pi_*(\eta): \pi_*(F)\arrow[r]&\pi_*(F)\otimes K_Y\,.
\end{tikzcd}
$$
This induces an equivalence between the categories 
$$
\left\{
\begin{array}{c}
F\in\Coh(X) \textnormal{ compactly supported}
\end{array}\right\}\begin{tikzcd}\, \arrow[r, leftrightarrow]&\,\end{tikzcd}\left\{
\begin{array}{c}(E,\phi)\textnormal{ compactly supported}\\
\textnormal{Higgs pairs on }Y
\end{array}\right\}
$$
Here, a compactly supported Higgs pair $(E,\phi)$ consists of a compactly supported sheaf $E$ on $Y$ and a morphism $\phi: E\to E\otimes K_Y$.

The classical stack $\mM^{\sig}_{\al}$ of $\sig$-semistable sheaves of class $\al\in K^0_{\cs,e}(X)$ can be identified with an open substack of compactly supported Higgs pairs. This also holds on the level of derived refinements. To describe its obstruction theory, consider the map $\mathscr{P}: \mM^{\sig}_{\al}\to \mM_Y$ which forgets the morphism $\phi$. Set
\begin{equation}
\label{eq:GGEE}
\GG :=\mathscr{P}^* \RHom_{\mM_Y}(\mE,\mE)^\vee[-1]\,,\qquad \EE := \RHom_{\mM^{\sig}_{\al}}(\mF,\mF)^\vee[-1]
\end{equation}
for the universal objects $\mE$ on $Y\times\mM_Y$ and $\mF$ on $X\times\mM^{\sig}_{\al}$. Then, there exists the homotopy fiber sequence (in black)
\begin{equation}
\label{eq:spectralobs}
\begin{tikzcd}
&\B{\MM_O[-1]}\arrow[dl,blue]\arrow[r, blue,equal]&\B{\MM_O[-1]}\arrow[dl,blue]&\\
\GG\arrow[r]&\EE\arrow[dl,blue]\arrow[r]&{\GG^{\vee}[2]}\arrow[dl,blue]&\\
\B{\MM_O^\vee[3]}\arrow[r, blue,equal]&\B{\MM_O^\vee[3]}&&
\end{tikzcd}
\end{equation}
with connecting morphism $\GG^\vee[2]\to \GG[1]$, which is the dual of
$$
\begin{tikzcd}
{[-,\Phi]}: \mathscr{P}^* \RHom_{\mM_Y}(\mE,\mE)\arrow[r]&\mathscr{P}^* \RHom_{\mM_Y}(\mE,\mE\otimes K_Y)
\end{tikzcd}
$$
for the universal morphisms $\Phi:\mE\to \mE\otimes K_Y$. 

Let us now consider pairs of sheaves and the set-up described in Assumption \ref{ass:pairWC} and modified for the non-compact setting in Remark \ref{rem:afterpairs}. In this case, the choice of the framing object is 
$$
O=\pi^*(L_Y)
$$
for a line bundle $L_Y$ on $Y$. Consider the obstruction theory on $\big(\mN^{\sig^P}_{1,\al}\big)^{\rig}$ for $\al\in \msE_O$ induced by its open embedding into $\mM_{\ov{X},\ov{O}}$ where $\ov{X} = \PP_{Y}\big(\mO_Y\oplus K_Y\big)$ and $\ov{O}$ is the pullback of $L_Y$ along the projection from $\ov{X}$. To describe this obstruction theory in the form of \eqref{eq:spectralobs}, consider the map
\begin{equation}
\label{eq:dequals1}
\begin{tikzcd}
\mathscr{P}_O: \mN^{\sig^P}_{1,\al}\arrow[r]&\mN_{1,\pi_*(\al)}
\end{tikzcd}
\end{equation}
where the latter stack parametrizes pairs of the form $L_Y\to E$ for $\llbracket E\rrbracket =\pi_*(\al)$. This map is induced by the adjunction between $\pi^*$ and $\pi_*$.

Continuing to use $\mF$, respectively $\mE$, for the universal sheaves on $X\times \big(\mN^{\sig^P}_{1,\al}\big)^{\rig}$ and $Y\times \big(\mN_{1,\pi_*(\al)}\big)^{\rig}$, the obstruction theory for the pairs is recovered by taking cones and cocones of the \B{blue arrows} meeting $\EE$ in \eqref{eq:spectralobs}  in the sense of Proposition \ref{prop:sympullback}. This is possible because their composition is naturally homotopic to 0. Here, it is understood that \eqref{eq:GGEE} is used with $\mathscr{P}^{\rig}_O$ replacing $\mathscr{P}$, and I set 
\B{$$\MM_O :=\RHom_{\big(\mN^{\sig^P}_{1,\al}\big)^{\rig}}\big(\pi^*(L_Y),\mF\big) =\big(\mathscr{P}^{\rig}_O\big)^{*}\RHom_{\mN^{\rig}_{1,\pi_*(\al)}}\big(L_Y,\mE\big)\,.$$}
 The null-homotopy of the composition follows because the morphism $\B{\MM_O[-1]\to }\FF$ is given by the composition of $\B{\MM_O[-1]\to }\GG\to \FF$, and the dual statement also holds. The resulting obstruction theory is given by
$$
\FF^{\sig^P}_{1,\al} = \RHom_{\mN^{\sig^P}_{1,\al}}\big(O\to \mF,O\to \mF\big)^\vee_0[-1]
$$
where $(-)_0$ denotes the traceless part.

To prove Corollary \ref{cor:WCconsequences}.2) and its generalization to stable pairs, it is necessary to show that the obstruction theories of Assumption \ref{ass:pairWC}.c) exist.
\begin{proposition}
\label{prop:localCY}
Continue working in the situation above with a fixed $O$, a set of weak stability conditions $W^P$ on $\mB_O$, and $\msE_O$ satisfying Assumption \ref{ass:stab}, \ref{ass:pairWC}.a), and b). If $D_k$ are pullbacks of divisors in $Y$, then Assumption \ref{ass:pairWC}.c) and Assumption \ref{ass:welldef} hold. 
\end{proposition}
\begin{proof}
As before, fix a dimension vector $\un{d}$ of $\mathring{I}$ such that $d_1=1$. I will also assume that $d=1$ as in \eqref{eq:dequals1} and denote the corresponding moduli stack of objects in $\mbB_{O,I_k}$ by $\mbN^{\rig}_{O,(\un{d},1,\al)}$.  Let $\widehat{\pi}_{\un{d},\al}: \mbN^{\rig}_{O,(\un{d},1,\al)}\to \mbN_{O,k}$ be a projection induced by the composition of the arrows in \eqref{eq:OprojmN}. For the rest of the proof, I will omit specifying pullbacks of complexes when they are clear. Setting $\NN_{\un{d},\al}:=T_{\widehat{\pi}_{\un{d},\al}}$, one can construct a CY4 obstruction theory on the appropriate semistable locus of $\mbN^{\rig}_{O,(\un{d},1,\al)}$ from 
$$
\begin{tikzcd}
&\B{\NN_{\un{d},\al}[-1]\oplus\MM_O[-1]}\arrow[dl,blue]\arrow[r, blue,equal]&\B{\NN_{\un{d},\al}[-1]\oplus\MM_O[-1]}\arrow[dl,blue]&\\
\GG\arrow[r]&\EE\arrow[dl,blue]\arrow[r]&{\GG^{\vee}[2]}\arrow[dl,blue]&\\
\B{\NN^\vee_{\un{d},\al}[3]\oplus\MM_O^\vee[3]}\arrow[r, blue,equal]&\B{\NN^\vee_{\un{d},\al}[3]\oplus\MM_O^\vee[3]}&&
\end{tikzcd}
$$
by the same arguments as in the case of \eqref{eq:spectralobs} and $\FF^{\sig}_{1,\beta}$. This addresses Assumption \ref{ass:pairWC}.c). 

The proof of Assumption \ref{ass:welldef} in the case of compactly supported codimension 1 Gieseker and slope-stable sheaves is addressed in Corollary \ref{cor:JSWC} to showcase the quantum Lefschetz-type argument used in \ref{sec:proof}. The general statement follows by the arguments developed in \cite[§9]{JoyceWC} based on \cite[§7.3]{mochizuki}. In combination with spectral correspondence, the latter approach was also used in the case of CY threefolds and dimension 2 sheaves in \cite{LiuVW}.
\end{proof}
The next table summarizes the references that prove the different parts of Assumption \ref{ass:stab}, Assumption \ref{ass:pairWC}.a), and b). Wall-crossing in these situations follows from the above.
