\begin{tabular}{c|c c}
&Assumption \ref{ass:pairWC}.a) & Assumption \ref{ass:pairWC}.b)\\
\hline
\begin{tabular}{c}DT/PT wall-crossing\\
(Example \ref{ex:DTPT})
\end{tabular}&\cite[Lemma 3.15]{todacurve}&\cite[Proposition 6.1.5]{KLT}\\
