Fix $\al\in \msE(\mA), k\in K$ and stability conditions $\sig,\sig'$ as in \eqref{eq:sigprclosetosig}. Let $r$ in the definition of $I_{\Flag}$ be equal to $\chi\big(\al(k)\big)+1$ and fix the dimension vector $\un{d}$ of $\mathring{I}_{\Flag}$ as in step 2) of §\ref{sec:summaryproof}. With it, I will associate the dimension vector $(1,\un{d})$ of $\mathring{I}_{\MS}$ in the case that this quiver is obtained by adding $v_0$ to the above choice of $\mathring{I}_{\Flag}$. Using $\lambda'$ as in §\ref{sec:summaryproof}, there is a virtual fundamental class $\Big[N^{\sig^{\lambda'}}_{(1,\un{d}),\al}\Big]^{\vir}
$ by Assumption \ref{ass:obsonflag}. For $o\in \{1,\ldots,O\}$ and $s_o\in (0,1)$ from \eqref{eq:proofWCgraphic}, consider the  $\GG_m$-action on the moduli space $N^{\sig^{s_o\lam'}}_{(1,\un{d}),\al}$ determined by rescaling the morphisms of representations at the edge $e_{-1}$:
\begin{equation}
\label{eq:QMSaction}
\includegraphics[scale=0.24]{actiononQMSfixed.png}
\end{equation}
I will denote its weight 1 equivariant trivial line bundle by $w=e^z$ with the equivariant first Chern class $c_1(t) = z$.  

The next proposition describes the fixed point loci of this action, their virtual fundamental classes and the virtual normal bundles. The first step is already proved in \cite[Proposition 10.20]{JoyceWC}. I recall the arguments in a more pictorial way using quiver diagrams as this is needed for the explicit description of virtual normal bundles. The pictures of quivers appearing in the statement of the proposition below include the effects of the \Pur{$\GG_m$-action} on the vertices which are explained in the proof and should be ignored on the first read. Because the $\GG_m$-action commutes with the induced $\T$-action on $\mN_{\MS_k}$ from Definition \ref{Def:quiverpairs}, everything below works also $\T$-equivariantly. 
\begin{proposition}[{\cite[Proposition 10.20]{JoyceWC}}]
\label{prop:fixedpoints}
For the above data, let $(\un{d}^j_i,\al^j_i)\in \ZZ^{\chi(\al(k))}\times \msE(\mA)$ for $j\in J_o$ and $i=1,2$ be the  classes that $(\un{d},\al)$ splits into at $s=s_o$ as recalled in step 3) of §\ref{sec:summaryproof}.  The fixed points locus $\Big(N_{(1,\un{d}),\al}^{\sigma^{s_o\lambda'}}\Big)^{\GG_m}$ can be expressed as a disjoint union of the following three types of subsets:
\begin{enumerate}
\item The subscheme $$N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big|_{e_{-1}=0}\subset N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}$$ consisting of objects $(\un{V},\un{m}, E)$ such that $m^{e_{-1}} = 0$.
\begin{equation}
\label{eq:e-1locus}
  \includegraphics[scale = 0.4]{1fixedpointQMS.png}  
\end{equation}
It is canonically isomorphic to $N_{\un{d},\al}^{\sigma^{s^-_{o}\lambda'}}$ for $s^-_{o}\in (s_{o-1}, s_o)$, and its virtual fundamental class is identified up to a sign with 
\begin{equation}
\label{eq:FPvir1}
\Big[N_{\un{d},\al}^{\sigma^{s^-_{o}\lambda'}}\Big]^{\vir}\in H_*\Big(N_{\un{d},\al}^{\sigma^{s^-_{o}\lambda'}}\Big)
\end{equation}
under this isomorphism. Its virtual normal bundle is 
\begin{equation}
\label{eq:Nvir1}
N^{\vir}_{e_{-1}=0}=t \cdot \mV^*_1\otimes\mV_{0} \oplus t^{-1}\cdot \mV_0^*\otimes \mV_1[-2]\,.
\end{equation}
\item The subscheme $$N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big|_{e_{0}=0}\subset N_{\alpha,(1,\un{d})}^{\sigma^{s_o\lambda'}}$$ consisting of objects $(\un{V},\un{m}, E)$ such that $m^{e_{0}} = 0$.
\begin{equation}
\label{eq:e0locus}
  \includegraphics[scale = 0.23]{2fixedpointQMS.png}  
\end{equation}
It is canonically isomorphic to $N_{\un{d},\al}^{\sigma^{s^+_o\lambda'}}$ for $s^+_o\in (s_o,s_{o+1})$, and its virtual fundamental class is identified up to a sign with 
\begin{equation}
\label{eq:FPvir2}
\Big[N_{\un{d},\al}^{\sigma^{s^+_o\lambda'}}\Big]^{\vir}\in H_*\Big(N_{\un{d},\al}^{\sigma^{s^+_o\lambda'}}\Big)
\end{equation}
under this isomorphism. Its virtual normal bundle is 
\begin{equation}
\label{eq:Nvir2}
N^{\vir}_{e_{0}=0}=t^{-1}\cdot \big(\mV_{l}/\mV_{l-1}\big)^*\otimes \mV_0\oplus t\cdot \mV_0^*\otimes \big(\mV_l/\mV_{l-1}\big)[-2]\,.
\end{equation}
\item I fix $j\in J_o$ and omit it from the superscripts when specifying the splitting $(\un{d_i},\alpha_i)$ for $i=1,2$ discussed above to improve readability. The associated fixed point locus
$$N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big|^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}\subset N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}$$
contributes for eacf $j$ and it was described in \cite[Proposition 10.16]{JoyceWC}. This locus is represented by the following quiver:
\begin{equation}
    \label{eq:sumlocus}
    \includegraphics[scale = 1]{middlefixedQMS.pdf}
\end{equation}
The map 
$$
\mu^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}: \begin{tikzcd}
    \mN_{\un{d}_1,\alpha_1}^{\rig}\times \mN_{\un{d}_2,\alpha_2}^{\rig}\arrow[r]& \mN^{\rig}_{(1,\un{d}),\alpha}
\end{tikzcd}
$$
constructed in \eqref{eq:sumtoMSmap} induces an isomorphism 
\begin{equation}
\label{eq:Sigmatofixedsumlocus}
\mu^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}: \begin{tikzcd}N_{\un{d}_1,\alpha_1}^{\sigma^{s_o\lambda'}}\times N_{\un{d}_2,\alpha_2}^{\sigma^{s_o\lambda'}}\arrow[r,"\sim"]&N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big|^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)} \end{tikzcd}
\end{equation}
which identifies the virtual fundamental class of the latter with 
\begin{equation}
\label{eq:FPvir3}
\Big[N_{\un{d}_1,\alpha_1}^{\sigma^{s_o\lambda'}}\Big]^{\vir}\boxtimes \Big[N_{\un{d}_2,\alpha_2}^{\sigma^{s_o\lambda'}}\Big]^{\vir}\in H_*\Big(N_{\un{d}_1,\alpha_1}^{\sigma^{s_o\lambda'}}\times N_{\un{d}_2,\alpha_2}^{\sigma^{s_o\lambda'}}\Big)
\end{equation}
up to a sign. Pulling back the virtual normal bundle $\Big(N^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}\Big)^{\vir}$ along $\mu^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}$ yields
\begin{equation}
\label{eq:Nvirmiddle}
\Big(\mu^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}\Big)^*\Big(N^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}\Big)^{\vir} = t\cdot\Theta_{Q_{\Flag_k}}[-2]\oplus t^{-1}\cdot \sigma^*\Theta_{Q_{\Flag_k}}[-2]\,,
\end{equation}
where, by writing $\Theta_{\mN_{Q_{\Flag_k}}}$, I understand its restriction to $N_{\un{d}_1,\alpha_1}^{\sigma^{s_o\lambda'}}\times N_{\un{d}_2,\alpha_2}^{\sigma^{s_o\lambda'}}$.
\end{enumerate}    
\end{proposition}
\begin{proof}
It was shown in \cite[Proposition 10.20]{JoyceWC}, that these are the only types of fixed point loci one obtains. The rest of the proof will describe how they appear and what their fixed obstruction theories and virtual normal bundles are. This must be done carefully because it will affect the signs in Theorem \ref{thm:FlagWC} below. 
\begin{enumerate}
    \item The first fixed-point locus is clear, as it sets the morphisms rescaled by $\GG_m$ to zero. In \cite[Proposition 10.20 (a)]{JoyceWC}, it is shown that $\sigma^{s_o\lambda'}$-semistability of $(\un{V},\un{f},E)$ implies injectivity of $m^{e_{l-1}}:V_{l-1}\to V_l$. On this fixed point locus, the morphism $m_0$ additionally factors through the isomorphism 
    $$
    \begin{tikzcd}
        \coker\big({m^{e_{l-1}}}\big)\arrow[r,"\sim"]&V_0\,.
    \end{tikzcd}
    $$
    Therefore, $m_0$ presents no additional information, and one can naturally identify $N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big|_{e_{-1}=0}$ with a substack of $\mN^{\rig}_{\un{d},\al}$. Comparing stability conditions, \cite[Proposition 10.20 (a)]{JoyceWC} proves the identification with $N_{\un{d},\al}^{\sigma^{s^-_{o}\lambda'}}$. 


    The obstruction theory on $\mN^{\rig}_{(1, \un{d}),\alpha}$ is explicitly described by applying the description in Lemma  \eqref{eq:fullobsQMS} to \eqref{eq:constructQMSCY4} where \FG{$\circ$} now more generally represents the obstruction theory $\EE$ on $\mM_{\mA}$. From this, it becomes clear that the moving part of the tangent complex  restricted to $N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big|_{e_{-1}=0}$ is represented by 
    $$
    \begin{tikzcd}
        \arrow[dr,"e_{-1}"]&\\
        &\arrow[ul, Maroon, bend left, "e^*_{-1}"]
    \end{tikzcd}\,.
    $$
The weights of $\begin{tikzcd}\,
        \arrow[r,"e_{-1}"]&\,\end{tikzcd}$ and $\begin{tikzcd}\,&\arrow[l, Maroon ,"e^*_{-1}"']\,
        \end{tikzcd}$ are $t$
 and $t^{-1}$ respectively, which is equivalent to \eqref{eq:Nvir1}.

        The left-over fixed part of the obstruction theory has an extra
        $$
        \begin{tikzcd}[column sep=small]&[-10pt]\,\arrow[dl, BurntOrange,"\rho"']&\,&\,\arrow[dlll,"e_0"]\\
\stackrel{\Cya{\bullet}}{v_0} &&\end{tikzcd}
        $$
        and its shifted dual when compared to $\FF^{\rig}_{\un{d},\al}$. However, this term is simply 
        $$
\begin{tikzcd}
\Big(\Cya{\mV_0^*\otimes \mV_0}\arrow[r,"\circ m^{e_{0}}"]&\mV_l^*\otimes \mV_0\arrow[r,"\circ m^{e_{l-1}}"]&\BuOr{\mV_{l-1}^*\otimes \mV_0}\Big)^\vee
\end{tikzcd}
        $$
which is acyclic as a consequence of the choice of stability. I leave the question of comparing orientations for later, so the above only implies that the virtual fundamental classes are equal up to signs.
\item This situation is slightly more complicated. Consider an object $(\un{V}, \un{f}, E)$ corresponding to a point in $N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big|_{e_{0}=0}$. Because this scheme parametrizes such objects up to isomorphisms, one may compensate the action of \Pur{$x\in \GG_m$} on $m^{e_{-1}}$ by scaling the identity of $V_{v_0}$ by \Pur{$x^{-1}$}:
$$
\begin{tikzcd}[column sep= large]
    \arrow[d,"\id_{V_1}"']V_{1}\arrow[r,"\Pur{x}\cdot m^{e_{-1}}"]&V_0\arrow[d,"\Pur{x^{-1}}\cdot \id_{V_0}"]\\
    V_1\arrow[r,"m^{e_{-1}}"']&V_0
\end{tikzcd}\,.
$$
Because $m^{e_0}=0$ this extends to an isomorphism of objects, so $(\un{V}, \un{f}, E)$ indeed represents a fixed point of the $\GG_m$-action. It is shown in \cite[Proposition 10.20 (b)]{JoyceWC} that the stability condition implies that $m^{e_{-1}}$ is an isomorphism. Therefore, the data of $m^{e_{-1}}$ and $V_0$ can be neglected, and $N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda}}\Big|_{e_{0}=0}$ can be identified with an open substack of $\mN^{\rig}_{\un{d},\al}$. After comparing stability conditions, \cite[Proposition 10.20 (b)]{JoyceWC} proves that this substack is $N_{\un{d},\al}^{\sigma^{s^+_{o}\lambda'}}$.

From the description of the fixed point locus and from looking at \eqref{eq:fullobsQMS}, it follows that the moving part of the obstruction theory restricted to $N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big|_{e_{0}=0}$ is represented by 
$$
\begin{tikzcd}[row sep=huge]&[-10pt]\,\arrow[dl, bend right, BurntOrange, "\rho"']&\,&\,\arrow[llld,"e_0"']\\
\,\arrow[urrr,Maroon, bend right, "e^{*}_0"']\arrow[ur, bend right, BurntOrange, "\rho^*" {yshift=-1ex}]&&&\end{tikzcd}
$$
The weights on its dual come from the action rescaling $\mV_0$, so they are $t$ for the terms corresponding to arrows ending at $v_0$ and $t^{-1}$ for the terms corresponding to arrows starting at $v_0$. Explicitly this adds up to
$$
t\cdot\Big(\begin{tikzcd}[column sep= large]\mV_l^*\otimes \mV_0\arrow[r,"\circ m^{e_{l-1}}"]&\BuOr{\mV_{l-1}^*\otimes \mV_0}\end{tikzcd}\Big)
$$
and its dual. To conclude \eqref{eq:Nvir2}, I simply recall that $m^{e_{l-1}}$ is injective. 

The difference between $\FF^{\rig}_{\un{d},\al}$ restricted to $N_{\un{d},\al}^{\sigma^{s_{o}\lambda'}}$ and the fixed part of $\eqref{eq:fullobsQMS}$ is given by 
$$
\begin{tikzcd}
\arrow[dr,"e_{-1}"]&\\
&\stackrel{\bullet}{v_0}
\end{tikzcd}
$$
and its shiftedí dual. The corresponding complex is clearly acyclic because $m^{e_{-1}}$ is an isomorphism.
\item
First of all, I will introduce a stack $\mN^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2),1}$ that parametrizes objects of the form \eqref{eq:sumlocus}. They consist of a pair of objects $P',P''$ in $\mB_k$ of classes $(\alpha_i,d_{r-1,i})$ for $i=1,2$ respectively together with a representation of the quiver obtained from \eqref{eq:sumlocus} after removing both $\stackrel{v'_r}{\circ}$ and $\stackrel{v''_r}{\circ}$. As before, I require that the vector spaces in the definition of $P'$ and $P''$ in \eqref{eq:exacttriple} are identified with the vector spaces $V'_{r-1}$ at $v'_{r-1}$ and $V''_{r-1}$ at $v''_{r-1}$. Note that I use the convention explained in Remark \ref{rem:d1d2} to shorten the dimension vectors $\un{d}_i$. Lastly, I take the stack $\mN^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2),1}$ to be the rigidified one, meaning that the objects it parametrizes carry a fixed isomorphism $V_1\cong \CC$. 

There is then a natural map 
$$
\Lambda^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}: \begin{tikzcd}N_{\un{d}_1,\alpha_1}^{\sigma^{s_o\lambda'}}\times N_{\un{d}_2,\alpha_2}^{\sigma^{s_o\lambda'}}\arrow[r]&\mN^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2),1} \end{tikzcd}
$$
which maps a pair of objects represented by the two quivers 
\begin{equation}
\label{eq:twoFlags2}
\includegraphics[scale=0.9]{twoFlags.pdf}
\end{equation}
with classes $(\un{d}_i,\alpha_i)$ for $i=1,2$ (labelling from the bottom) to an object described by \eqref{eq:sumlocus} by setting $V_0 = \CC$ and $m^{e_{-1}} = \id_{\CC}=m^{e''_0}$ while keeping the rest unchanged. Due to $N_{\un{d}_1,\alpha_1}^{\sigma^{s_o\lambda'}}$ being rigidified, there are fixed isomorphisms $V''_l\cong \CC, V_1 \cong \CC$. This is an open embedding because the contributions of $e_{-1}$ and $e''_0$ for the target cancel with the ones of $v_0$ and $v''_{l}$ respectively. Next, there is a map 
$$
\widetilde{\mu}^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}: \begin{tikzcd}\mN^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2),1}\arrow[r]&\mN^{\rig}_{(1,\un{d}),\alpha}\end{tikzcd}
$$
that acts by preserving the vector spaces $V_j$ for $0\geq j\leq l-1$ and by taking pairwise sums of the rest:
$$
V_k = V'_k\oplus V''_k\qquad\textnormal{for}\quad k\geq l\,,\qquad E = E'\oplus E''\,.
$$
Following \cite[Proposition 10.20 (c)]{JoyceWC}, I claim that 
\begin{equation}
\label{eq:sumtoMSmap}
\mu^{\un{d}_1,\alpha_1}_{\un{d}_2,\alpha_2}:=\widetilde{\mu}^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}\circ \Lambda^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}
\end{equation}
is an isomorphism on its image which is equal to a union of some connected components of the fixed point locus. I will also denote the obvious extension of this map to $ \mN_{\un{d}_1,\alpha_1}^{\rig}\times \mN_{\un{d}_2,\alpha_2}^{\rig}$ in the same way by $\mu^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}$.

To get this fixed point locus, one uses the same argument that introduced the \Pur{weight $-1$} $\GG_m$-action at $v_0$ in \eqref{eq:e0locus}. Going in the opposite direction, one gets the trivial $\GG_m$-action on $V_{0}$ and the \Pur{weight 1} action on $V_{1}$. Because of this, there needs to be a non-trivial action on $V_j$ for $j>1$ and on $E$. The weight decomposition of these terms will have only weight 0 and weight 1 summands due to stability. Thus \cite[Proposition 10.20 (c)]{JoyceWC} concludes that each fixed point of this type is of the form \eqref{eq:sumlocus} for $j\in J_o$ where the action is of \Pur{weight $1$} at the vertices of the longer horizontal sequence. It is trivial for the upper sequence. Moreover, it is shown there that $m^{e_0}$ can be decomposed as a sum of 
$$m^{e'_0}:\begin{tikzcd} V'_{l}\arrow[r,"0"]& V_0\end{tikzcd}\quad \textnormal{and}\quad m^{e''_0}: \begin{tikzcd} V''_{l}\arrow[r,"\sim"]& V_0\end{tikzcd}\,,$$
and that $m^{e_{-1}}$ and $m^{e'_{l-1}}: V_{l-1}\xrightarrow{\sim} V'_l$ are isomorphisms. This is then used to conclude that \eqref{eq:Sigmatofixedsumlocus} indeed identifies the two schemes.

Consider the projection 
\begin{equation}
\label{eq:PiV}
\Pi_{\mathsf{V}}:\begin{tikzcd}N_{(1,\un{d}),\alpha}^{\sigma^{s_{o}\lambda'}}\arrow[r]& \mN_{\un{d},\al}\end{tikzcd}
\end{equation}
that corresponds to forgetting the vertex $v_0$ in \eqref{eq:QMSaction} and all the arrows pointing towards it. This map is defined even though the latter stack is not rigidified because $d_1=d_0=1$. The restriction of $\FF_{(1,\un{d}),\alpha}$ to $N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big|^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}$ differs from the pull-back of $\FF_{\un{d},\al}$ along $\Pi_{\mathsf{V}}$ by the term corresponding to 
\begin{equation}
\label{eq:PiVobsdiff}
\includegraphics[scale=0.9]{extrasumobsterm.pdf}
\end{equation}
and its dual. Since $m^{e_{-1}},m_{e''_0}$ are isomorphisms, the terms $\begin{tikzcd}
    \,\arrow[r,"e_{-1}"]&\,
\end{tikzcd}$ and $\begin{tikzcd}
    \, &\arrow[l,"e''_{0}"']\,
\end{tikzcd}$ cancel with $\stackrel{v_0}{\bullet}$ and $\stackrel{v''_{l-1}}{\bullet}$. Finally, the contribution of $\begin{tikzcd}\,\arrow[r,"\rho",BurntOrange]& \,\end{tikzcd}$ is mapped to the one of $\begin{tikzcd}\,&\arrow[l,"e'_0"']\,\end{tikzcd}$ by the isomorphism $m^{e_{l-1}}\circ $, so that after including $\stackrel{v''_{l-1}}{\bullet}$ into the above diagram, the combined complex is acyclic. This implies that one needs to remove the term $\begin{tikzcd}
    \stackrel{v''_{l-1}}{\bullet}
\end{tikzcd}$ and its dual from 
$\Big(\mu^{(\un{d}_1,\al_1)}_{(\un{d}_2,\al_2)}\Big)^*\circ \Pi_{\mathsf{V}}^*\FF_{\un{d},\al}$ to get $\Big(\mu^{(\un{d}_1,\al_1)}_{(\un{d}_2,\al_2)}\Big)^*\FF_{(1,\un{d}),\al}$. Note that 
$$
\Pi_{\mathsf{V}}\circ \mu^{(\un{d}_1,\al_1)}_{(\un{d}_2,\al_2)} = \mu_{\Flag} \circ \big(s_{\un{d}_1,\al_1}\times s_{\un{d}_2,\al_2}\big)
$$
so 
\begin{align*}
\Big(\mu^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}\Big)^*\FF_{(1,\un{d}),\alpha}&\cong \Big(\mu^{(\un{d}_1,\al_1)}_{(\un{d}_2,\al_2)}\Big)^*\circ \Pi_{\mathsf{V}}^*\FF_{\un{d},\al}+(\textnormal{remove }
\begin{tikzcd}[ampersand replacement = \&]
    \Cya{\bullet}\arrow[loop, ForestGreen, in=55,out=115, looseness=10,"v''_{l-1}"]
\end{tikzcd})\\
&\cong  \mu_{\Flag}^*\FF_{\un{d},\al}+(\textnormal{remove }
\begin{tikzcd}[ampersand replacement = \&]
    \Cya{\bullet}\arrow[loop, ForestGreen, in=55,out=115, looseness=10,"v''_{l-1}"]
\end{tikzcd})\\
&\cong \FF_{\un{d}_1,\al_1} \boxplus \FF_{\un{d}_2,\alpha_2}\oplus \Theta_{\Flag}\oplus \sigma^*\Theta_{\Flag}+(\textnormal{remove }
\begin{tikzcd}[ampersand replacement = \&]
    \Cya{\bullet}\arrow[loop, ForestGreen, in=55,out=115, looseness=10,"v''_{l-1}"]
\end{tikzcd})
\end{align*}
by \eqref{eq:additivityofFFflag}. Furthermore, another copy of $\mO$ and $\mO[-4]$ are removed by starting from $\FF^{\rig}_{(1,\un{d}),\al}$ instead. Because this only affects the diagonal terms, I will focus on them. For the classical obstruction theory \eqref{eq:wtFFI}, rigidifying and removing $\stackrel{v''_{l-1}}{\Cya{\bullet}}$ would produce 
\begin{equation}
\label{eq:rigidifiedsumFFna}
\begin{tikzcd}\Big(\wt{\FF}_{\un{d}_1,\al_1}\arrow[r]&\mO[-1]\Big) \boxplus \Big(
\wt{\FF}_{\un{d}_2,\alpha_2}\arrow[r]&\mO[-1]\Big) 
\end{tikzcd}
\end{equation}
which are the classical rigidified obstruction theories. Symmetrizing this observation, one gets 
$$
\Big(\mu^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}\Big)^*\FF_{(1,\un{d}),\alpha}\cong \FF^{\rig}_{\un{d}_1,\al_1}\boxplus \FF^{\rig}_{\un{d}_2,\al_2}\oplus \Theta_{\Flag}\oplus \sigma^*\Theta_{\Flag}\,.
$$
 To understand the weights of each term, observe that \eqref{eq:sumlocus} implies that the objects on first line of \eqref{eq:twoFlags2} have weight 0, while the ones on the second line are weight $1$. Combined with the description of $\Theta_{\Fl}$ from \eqref{eq:extendTheta} using Corollary \ref{cor:sumobstructiontheory}, this implies that
$$\Big(\mu^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}\Big)^*\FF^{\rig}_{(1,\un{d}),\alpha}\cong \FF^{\rig}_{\un{d}_1,\alpha_1}\boxplus \FF^{\rig}_{\un{d}_2,\alpha_2}\oplus t\cdot \Theta_{\Flag}\oplus t^{-1}\cdot\sigma^*\Theta_{\Flag}$$
 in $D^b_{\GG_m}\Big(N_{\un{d}_1,\alpha_1}^{\sigma^{s_o\lambda'}}\times N_{\un{d}_2,\alpha_2}^{\sigma^{s_o\lambda'}}\Big)$.
\end{enumerate}
\end{proof}
The wall-crossing formula will be a consequence of the virtual equivariant localization in Theorem \ref{thm:eqvirloc} applied to
$$\Big[N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big]^{\vir}\in H^{\GG_m}_*\Big(N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big)\,.$$
I choose to state the wall-crossing formula for objects in $\mB_{Q_{\Flag}}$ first and then deduce Theorem \ref{thm:familyWC} as a consequence of the more general result. This will allow a simpler derivation of alternative wall-crossing formulae in the future, in which case one can directly use Theorem \ref{thm:FlagWC} below. The computation is heavily based on \cite[Proposition 10.23 and 10.24]{JoyceWC}. Still, because of the additional attention one needs to pay to orientations, and due to the present result being stated for $\mB_{\Flag}$ rather than for $\mA$, I choose to present complete arguments within reason. I will denote by $\big[N^{\sigma^{\lambda}}_{\un{d},\al}\big]^{\vir}$ both the virtual fundamental class in $H_*\big(N^{\sigma^{\lambda}}_{\un{d},\al}\big)$ and its pushforward to $H_*\big(\mN^{\rig}_{\un{d},\al}\big)$ along the open embedding \eqref{eq:Nsigmalambda}. 
\begin{theorem}
\label{thm:FlagWC}
For $(\un{d},\al)$ and each $o\in O$ as in \eqref{eq:proofWCgraphic}, the formula
\begin{equation}
\label{eq:FlagWC}
\Big[N^{\sig^{s^+_o\lam'}}_{\un{d},\al}\Big]^{\vir}-\Big[N^{\sig^{s^-_o\lam'}}_{\un{d},\al}\Big]^{\vir} = \sum_{j\in J_o}\bigg[\Big[N^{\sig^{s_o\lam'}}_{\un{d}^j_1,\al^j_1}\Big]^{\vir},\Big[N^{\sig^{s_o\lam'}}_{\un{d}^j_2,\al^j_2}\Big]^{\vir}\bigg]
\end{equation}
holds in $L\iFlag_{*}$.
\end{theorem} 
\begin{proof}
After applying equivariant localization to
$$
\Big[N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big]^{\vir}\in H^{\GG_m}_*\Big(N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big)
$$
one needs to take the pushforward along
\begin{equation}
\label{eq:NVspacetoNstack}
\Pi_{\mathsf{V}}:\begin{tikzcd}
    N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\arrow[r] & \mN^{\rig}_{\un{d},\al}\,.
\end{tikzcd}
\end{equation}
and extract the residue. The last operation uses that the $\GG_m$-action on $\mN^{\rig}_{\un{d},\al}$ is trivial, so 
$$
H^{\GG_m}_*\big(\mN^{\rig}_{\un{d},\al}\big)\otimes_{R[z]}R[z^{-1}] = H_*\big(\mN^{\rig}_{\un{d},\al}\big)[z,z^{-1}]\,.
$$
 Because $N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}$ has proper $\T$-fixed points by Assumption \ref{ass:obsonflag}, the residue in $z$ of the pushforward of its (localized) equivariant virtual fundamental class vanishes. Therefore, the residue of the sum of the contributions of the fixed point loci described in Proposition \ref{prop:fixedpoints} is zero. 

I will compute each summand separately labelling them in the same way as in Proposition \ref{prop:fixedpoints}. In the process, I will always implicitly push forward along \eqref{eq:NVspacetoNstack} without mentioning it to avoid cluttering the computation with lengthy notation.
\begin{enumerate}
    \item The orientation from \eqref{eq:oNgeq} applied to \eqref{eq:Nvir1} makes $t^{-1}\cdot \mV^*_0\otimes \mV_1$ positive. Because this is visibly the same as the orientation induced by Definition \ref{def:orpullback} (see also \eqref{eq:FtoDiso}) on this piece of $\det\big(\FF^{\rig}_{Q_{\MS}}\big)$, I conclude that the correct sign of the induced virtual fundamental class \eqref{eq:FPvir1} is 
    $$
    \RX{+}\Big[N_{\un{d},\al}^{\sigma^{s^-_{o}\lambda'}}\Big]^{\vir}\,.
    $$
    Consequently, the term assigned to this fixed point locus becomes
    \begin{equation}
    \label{eq:virlocus1}
    [z^{-1}]\left\{ \frac{\Big[N_{\un{d},\al}^{\sigma^{s^-_{o}\lambda'}}\Big]^{\vir}}{z\big(1+z^{-1}\mV^*_1\otimes \mV_0\big)}\right\} = \Big[N_{\un{d},\al}^{\sigma^{s^-_{o}\lambda'}}\Big]^{\vir}\in H_*\big(\mN^{\rig}_{\un{d},\al}\big)\,.
    \end{equation}
    \item
    In this case, the orientation from \eqref{eq:oNgeq} makes $t^{-1}\cdot  \big(\mV_{l}/\mV_{l-1}\big)^*\otimes\mV_0$ positive. This time, this differs from the orientation induced by Definition \ref{def:orpullback}, for which $t\cdot \mV_0^*\otimes (\mV_{l}/\mV_{l-1}\big) $ is positive. This gives rise to the additional sign
    $$
    \RX{-}\Big[N_{\un{d},\al}^{\sigma^{s^+_{o}\lambda'}}\Big]^{\vir}
    $$
    and leads to the expression
\begin{equation}
    \label{eq:virlocus2}
    [z^{-1}]\left\{ \frac{-\Big[N_{\un{d},\al}^{\sigma^{s^+_{o}\lambda'}}\Big]^{\vir}}{z\big(1+z^{-1}\mV^*_0\otimes (\mV_l/\mV_{l-1})\big)}\right\} =- \Big[N_{\un{d},\al}^{\sigma^{s^+_{o}\lambda'}}\Big]^{\vir}\in H_*\big(\mN^{\rig}_{\un{d},\al}\big)\,.
\end{equation}
    \item In the third and last situation, the orientation on the virtual normal bundle is given by $o_{\sig^*\Theta_{Q_{\Flag}}}$. First note that $F_{\un{d},\al} \cong F_{(1,\un{d}),\alpha}$ because of the term \eqref{eq:PiVobsdiff} being acyclic once $\stackrel{v_{1}}{\bullet}$ is included. This implies that one needs to compare the orientations of $F_{\un{d},\al}$ and $F_{\un{d}_1,\alpha_1}\boxtimes F_{\un{d}_2,\alpha_2}$ in the same way as in Definition \ref{def:varepsflag}. Thus, one needs to modify \eqref{eq:FPvir3} by the sign 
    $$
\RX{\varepsilon^{\un{d}_1,\alpha_1}_{\un{d}_2,\alpha_2}\cdot }\Big[N_{\un{d}_1,\alpha_1}^{\sigma^{s_o\lambda'}}\Big]^{\vir}\boxtimes \Big[N_{\un{d}_2,\alpha_2}^{\sigma^{s_o\lambda'}}\Big]^{\vir}\,,
    $$
    where I again omit the superscripts $j$. The corresponding localization term is expressed as
    \begin{equation}
    \label{eq:residueFlag}
    [z^{-1}]\left\{ \varepsilon^{\un{d}_1,\alpha_1}_{\un{d}_2,\alpha_2}\Big(\Pi_{\mathsf{V}}\circ\mu^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}\Big)^{\GG_m}_*\left(\frac{\Big[N_{\un{d}_1,\alpha_1}^{\sigma^{s_{o}\lambda'}}\Big]^{\vir}\boxtimes \Big[N_{\un{d}_2,\alpha_2}^{\sigma^{s_{o}\lambda'}}\Big]^{\vir}}{z^{\Rk\big(\Theta_{Q_{\Flag}}\big)}c_{z^{-1}}\Big(\Theta_{Q_{\Flag}}\Big)}\right)\right\}\,,
    \end{equation}
    where $(-)^{\GG_m}_*$  denotes the $\GG_m$-equivariant pushforward. To bring it into the form appearing in \eqref{eq:gammaFlagWC}, I follow the observation from \cite[(9.50)]{JoyceWC} and adapt it to $\mN_{\Flag_k}$. 

    First note that the map $\mu^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}$ is $\GG_m$-equivariant only up to a 2-morphism $\mathfrak{a}$ in the sense of \cite[(2)]{Romagny}. For each \Pur{$x\in \GG_m$}, this 2-morphism is determined by a natural transformation that assigns to each object of the form \eqref{eq:sumlocus} with $m^{e_{-1}}$ rescaled by \Pur{$x$} a morphism to the same object without the scaling at the edge $e_{-1}$. This morphism acts as represented in \eqref{eq:sumlocus} by \Pur{$x\cdot \id$} on each vertex of the longer horizontal $A_r$ quiver. Taking the stacky quotient $ (-)/\GG_m$ of such a weakly $\GG_m$-equivariant morphism, the natural transformation $\mathfrak{a}$ contributes to the resulting morphism between the quotient stacks described in the proof of \cite[Proposition 2.6]{Romagny}. Carefully following the cited construction, one arrives at the following commutative diagram involving $\Big(\Pi_V\circ \mu^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}\Big)/\GG_m$:
    $$
    \begin{tikzcd}[column sep = 3cm, row sep= 1.3cm]
          \arrow[d,"\Big(\Pi_V\circ \mu^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}\Big)/\GG_m"']  B\GG_m\times \mN^{\rig}_{\un{d}_1,\alpha_1}\times \mN^{\rig}_{\un{d}_2,\alpha_2}\arrow[r,"\id\times s_{\un{d}_1,\al_1}\times s_{\un{d}_2,\al_2}"]&B\GG_m\times \mN_{\un{d}_1,\alpha_1}\times \mN_{\un{d}_2,\alpha_2}\arrow[d,"\id\times \rho_{12}\times \id"]\\
     B\GG_m\times \mN^{\rig}_{\un{d},\al}&\arrow[l,"\id\times (\Pi_{\un{d},\al} \circ \mu_{\Flag})"] B\GG_m\times \mN_{\un{d}_1,\alpha_1}\times \mN_{\un{d}_2,\alpha_2}\,.
    \end{tikzcd}
    $$
    The morphism $\id\times \rho_{12}: B\GG_m\times \mN_{\un{d}_1,\alpha_1}\to B\GG_m\times\mN_{\un{d}_1,\alpha_1}$ is the identity on $B\GG_m$, but also lets $B\GG_m$ act on the second factor.  The factor $\rho_{12}$ is precisely the correction corresponding to the 2-morphism $\mathfrak{a}$.    

    Taking $H^*(-)$ of the above diagram, expresses the $\GG_m$-equivariant pull-back $\Big(\Pi_V\circ \mu^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}\Big)^*_{\GG_m}$ in terms of the composition of the other three arrows. Because $H^*_{\GG_m}(-)$ is dual as an $R[z] = H^*(B\GG_m)$ module to $H_*^{\GG_m}(-)$ in all the above cases, this shows that
    \begin{align*}
    \label{eq:ezTorigin}
    \Big(\Pi_V\circ \mu^{(\un{d}_1,\alpha_1)}_{(\un{d}_2,\alpha_2)}\Big)^{\GG_m}_* &= \big(\Pi_{\un{d},\al} \circ \mu_{\Flag}\big)_*\circ  (\rho_{12}\otimes \id)_* \Big(\sum_{i\geq 0}z^ip^i\boxtimes \big(s_{\un{d}_1,\al_1}\times s_{\un{d}_2,\al_2}\big)_*\Big)\\
    &=\big(\Pi_{\un{d},\al} \circ \mu_{\Flag}\big)_*\circ (e^{zT}\otimes \id)  \circ \big(s_{\un{d}_1,\al_1}\times s_{\un{d}_2,\al_2}\big)_*\,.
    \numberthis
    \end{align*}
     Here $(\rho_{12})_* \Big(\sum_{i\geq 0}z^ip^i\boxtimes -\Big):H_*^{\GG_m}\big(\mN_{\un{d}_1,\alpha_1}\big)\to H_*^{\GG_m}\big(\mN_{\un{d}_1,\alpha_1}\big)$ can be directly seen to be dual to $(\id\times \rho_{12})^*: H^*\big(B\GG_m\times\mN_{\un{d}_1,\alpha_1}\big)\to H^*\big(B\GG_m\times\mN_{\un{d}_1,\alpha_1}\big)$. Using \eqref{eq:srig}, I introduce the notation 
$$
\big[N^{\sigma^{\lambda'}}_{\un{d},\al}\big]^{\svir} = (s_{\un{d},\al})_*\big[N^{\sigma^{\lambda'}}_{\un{d},\al}\big]^{\vir}\in H_*(\mN_{\un{d},\al})\,.
$$
Applying \eqref{eq:ezTorigin} to \eqref{eq:residueFlag} produces \begin{align*}
\label{eq:gammaFlagWC}\big(\Pi_{\un{d},\al}\big)_*  \big[z^{-1}\big]\left\{ \varepsilon^{\un{d}_1,\alpha_1}_{\un{d}_2,\alpha_2}\big(\mu_{\Flag}\big)_*\left(\big(e^{zT}\otimes \id\big)\frac{\Big[N_{\un{d}_1,\alpha_1}^{\sigma^{s_{o}\lambda'}}\Big]^{\svir}\boxtimes \Big[N_{\un{d}_2,\alpha_2}^{\sigma^{s_{o}\lambda'}}\Big]^{\svir}}{z^{\Rk\big(\Theta_{\Flag_k}\big)}c_{z^{-1}}\Big(\Theta_{\Flag_k}\Big)}\right)\right\}
\numberthis
\end{align*}
   in $H_*\big(\mN^{\rig}_{\un{d},\al}\big)$.
    \end{enumerate}
Setting the sum of all 3 terms to be zero proves \eqref{eq:FlagWC} after comparing with the vertex algebra structure from Definition \ref{Def:FlagVA}.
\end{proof}  
\subsection{The $\T$-equivariant case}
\label{sec:equivariantWC}
In this subsection, I refine the arguments in Theorem \ref{thm:FlagWC}. That this requires special attention was pointed out to me by Henry Liu. I will first focus on the local approach from §\ref{sec:equivariantVA} using the fixed point stack. It is simpler and, as far as I know, has not appeared anywhere else. It is additionally more flexible due to fewer assumptions needed. The global approach is discussed for completeness's sake and to compare the present wall-crossing framework to the one in \cite{Liu} for K-homology. In Remark \ref{rem:globalapproachfail}, it is explained that it is most suitable for CY3 wall-crossing.

\begin{enumerate}[wide, align=left]
\item[\textbf{Local approach}]
I will be working with the rigidified substack of $\T$-equivariant objects $\big(\mN^{\T}_{\un{d}, \al}\big)^{\rig}$ which inherits the natural projection 
\begin{equation}
\label{eq:PiVT}
\begin{tikzcd}
\Pi^{\T}_{\mathsf{V}}: \Big(N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big)^{\T}\arrow[r] & \big(\mN^{\T}_{\un{d},\al}\big)^{\rig}
\end{tikzcd}
\end{equation}
induced by \eqref{eq:PiV}. This map is $\GG_m$-equivariant for the trivial action of $\GG_m$ on the target.

One then considers the class
$$
\Big[N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big]^{\vir}\in H^{\GG_m\times \T}_*\Big(N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big)_{\loc} \cong  H_*\Big(\big(N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\big)^{\GG_m\times \T}\Big)\otimes_R R\big(\GG_a\times\Ft\big).
$$
in the localized equivariant homology. Applying the localization formula \eqref{eq:vireqlocgeneral} for $\GG_m\times \T$ and pushing forward along $\Pi^{\T}_{\mathsf{V}}$ gives rise to the sum of terms inside of the curly brackets in \eqref{eq:virlocus1}, \eqref{eq:virlocus2}, and \eqref{eq:residueFlag}. Each terms needs to be interpreted carefully as I will explain now. Each expression of the form $\Big[N_{\un{d},\alpha}^{\sigma^{s\lambda'}}\Big]^{\vir}$ is defined by applying Example \ref{ex:mMvir} for the local approach. Note, that the normal bundle to the $\T$-fixed point locus could also contain non-trivial $\GG_m$-weights, so the result could, a priori, be an element of $$H_*\Big(\big(\mN^{\T}_{\un{d}, \al}\big)^{\rig}\Big)\otimes_{R}R(\GG_a\times \Ft)\,.$$
Using Lemma \ref{lem:noGGmweight} below, one can replace $R(\GG_a\times \Ft)$ by $R(\Ft)$.
The only place where mixed weights of $\GG_a\times \Ft$ appear is the denominator before taking residues in \eqref{eq:residueFlag}. The corresponding terms have the form $
(\lambda+z)^{\Rk}c_{(\lambda+z)^{-1}}\big(Q_{\lambda}\big).$
Recall from §\ref{sec:equivariantVA} that any negative power of $(\lambda + z)$ is expanded for $|z|<|\lambda|$, so only pure $\GG_m$-weights can contribute to the poles at $z=0$ by \eqref{eq:explicitexpand}. A well-known argument (see \cite[Proposition 3.2]{Arbesfeld}) proves that in total, there are no such poles because the $\T$-fixed point locus of $N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}$ is proper by Assumption \ref{ass:obsonflag}.a). In particular, the vanishing
$$
\eqref{eq:virlocus1} + \eqref{eq:virlocus2}+\eqref{eq:gammaFlagWC} = 0
$$
still holds in $L\iFlag_{\,\loc,*}$. It can be expressed as \eqref{eq:FlagWC} in terms of the Lie bracket induced by \eqref{eq:LiefromVA} from $ V\iFlag_{\,\loc,*}$.

\item[\textbf{Global approach}]
The above discussion still applies to expressing $\big(\Pi^{\T}_{\mathsf{V}}\big)_*\Big[N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big]^{\vir}$ in terms of 
$$
\Big[N_{\un{d},\alpha}^{\sigma^{s\lambda'}}\Big]^{\vir}\in H_*\Big(\big(\mN^{\T}_{\un{d}, \al}\big)^{\rig}\Big)\otimes_{R}R(\GG_a\times \Ft)
$$
in this scenario. However, one expands in $|z|>|\lambda|$ now. Replacing $z$ by $\lambda$ in \eqref{eq:explicitexpand}, this introduces additional poles at $z=0$. One can argue that the only mixed poles appear in the denominator of \eqref{eq:residueFlag} by the following lemma.
\begin{lemma}
\label{lem:noGGmweight}
The normal bundle of $\Big(N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big)^{\T}$ restricted to $\Big(N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big)^{\GG_m\times\T}$ has no $\GG_m$-weights.
\end{lemma}
\begin{proof}
I prove this by considering each $\GG_m$-fixed point locus from Proposition \ref{prop:fixedpoints} separately.

For 1), the argument is very similar to the one in Remark \ref{rem:invdef}.ii) Let $(\un{V},\un{m},P)$ be an element of  $N_{\un{d},\al}^{\sigma^{s^-_{o}\lambda'}}$ corresponding to a $\T$-fixed point of $N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}\Big|_{e_{0}=0}$. The fiber of this point in $N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}$ is an open subset of
$$\PP\big(V_l/V_{l-1}\oplus V_1\big)$$
isomorphic to either $\GG_a$ or the entire $\PP^1$. This depends on whether $(\un{V},\un{m},P)\in N_{\un{d},\al}^{\sigma^{s^+_{o}\lambda'}}$. Since $(\un{V},\un{m},P)$ is stable, the only possible action on this $\T$-fixed point is by scalar multiples of identity. This implies that the action on- the fiber contained in $\PP\big(V_l/V_{l-1}\oplus V_1\big)$ is trivial. Thus the virtual normal bundle with respect to the $\T$-action restricted to this $\GG_m\times \T$ fixed point locus is simply a pullback of the virtual normal bundle from $\Big(N_{\un{d},\al}^{\sigma^{s^-_{o}\lambda'}}\Big) ^{\T}$ and only contains $\T$-weights.

The same argument applies to 2).

For 3) there are two cases, one needs to separate. Using the isomorphism \eqref{eq:Sigmatofixedsumlocus}, one knows that each $\GG_m\times\T$-fixed point projected to $\mN^{\rig}_{\ov{d},\al}$ splits as 
$$
(\un{V},\un{m},P)\cong (\un{V}_1,\un{m}_1,P_1)\oplus (\un{V}_2,\un{m}_2,P_2)
$$
where $(\un{V}_i,\un{m}_i,P_i)\in N_{\un{d}_i,\alpha_i}^{\sigma^{s_o\lambda'}}$ are stable. Since the $\T$-action at this point splits into the action on each factor, one needs to distinguish the case
\begin{enumerate}[label=\roman*)]
\item when the two actions have the same weights. In this situation, the argument reduces to the one for 1).
\item when the two actions are of different weight. Then note that the fiber in $N_{(1,\un{d}),\alpha}^{\sigma^{s_o\lambda'}}$ over this point is $\GG_m\subset \PP(V''_l\oplus V_1)$ without $0$ and $\infty$ for stability reasons. Here, I used the notation from \eqref{eq:sumlocus}. Combined with the $\T$-action at  $(\un{V}_1,\un{m}_1,P_1)\oplus (\un{V}_2,\un{m}_2,P_2)$, this implies that the $\T$-action on this fiber is transitive. Thus there is no such $\GG_m\times \T$ fixed point to begin with. 
\end{enumerate}
\end{proof}
For the sum of the three terms \eqref{eq:virlocus1}, \eqref{eq:virlocus2}, and \eqref{eq:gammaFlagWC} to be zero, one needs the following assumption, which is rather limiting in practice. 
\begin{assumption}
    \label{ass:globalapproach}    
    Let $\Theta^{m}_{\Flag_k}$ be the part of $\Theta_{\Flag_k}$ consisting of non-zero $\T$-weights when restricted to $\big(\mN^T_{\ov{d},\al}\big)^{\rig}$. The total residue of
   $$\frac{1}{z^{\Rk}c_{z^{-1}}\Big(\Theta^m_{\Flag_k}\Big)}$$
   after expanding in $|z|>|\lambda|$ is required to be zero.
\end{assumption}
This assumption implies that the residue of the \eqref{eq:virlocus1}, \eqref{eq:virlocus2}, and \eqref{eq:gammaFlagWC} comes from pure $\GG_m$-weights only. Thus the sum is zero by the same argument as before. This proves the wall-crossing \eqref{eq:FlagWC} in $H_*\Big(\big(\mN^{\T}_{\un{d},\al}\big)^{\rig}\Big)$ while using the expansion in $|z|>|\lambda|$ and the vertex algebra structure discussed in Remark \ref{rem:globalapproach}. To obtain the formula in $H^{\T}_*\Big(\mN^{\rig}_{\un{d},\al}\Big)$, one just needs to push forward along $\big(\mN^{\T}_{\un{d},\al}\big)^{\rig}\hookrightarrow \mN^{\rig}_{\un{d},\al}$. 
\begin{remark}
\label{rem:globalapproachfail}
The resulting formulae should be the homology version of what appears in \cite{Liu}. There, Liu makes a yet stronger assumption that implies that each residue at $z+\lambda=0$ vanishes when taking the sum over the 3 types of $\GG_m$-fixed loci. This seems unlikely to be true in any reasonable generality. In fact, the two situation when poles cancel are noted down in \cite{LiuVW} and \cite{KLT}. There, one works with a CY3 moduli problem with an extra equivariant weight $e^{\mu}$. In those situations, one gets cancellation of residues at $z+\lambda = 0$ and $z+\lambda -\mu = 0$ which is not included in the assumptions of \cite[§4.2.1]{Liu} as an option.
\end{remark}
\end{enumerate}



\subsection{Projecting flags to pairs and sheaves}
\label{sec:Flagtosheaves}
Here, I will detail the argument of step 3 from §\ref{sec:summaryproof} represented by the vertical arrows $\to\!\to\!\to\!\to$ in \eqref{eq:proofWCgraphic}. The section culminates in the proof of Proposition \ref{prop:OmegaWC} which implies the wall-crossing formula in $\mA$. 

From \eqref{eq:Nsig'0}, recall that $N^{\sig^{\lambda'}}_{\un{d},\al} = N^{(\sig')^{0}}_{\un{d},\al}$ holds implying that $\Omega^{\sig^{\lambda'}}_{\un{d},\al} = \Omega^{\sig',k}_{\al}$. For both $\zeta = \sig,\sig'$, there is a commutative diagram of algebraic spaces
\begin{equation}
\label{eq:NrigstoMrig}
\begin{tikzcd}[column sep=large, row sep= large]
\arrow[dr,"\pi^{\zeta}_{\un{d},\al}"']N^{\zeta^0}_{\un{d},\al}\arrow[r,"\pi^{\zeta}_{\un{d}/1,\al}"]& N^{\zeta_{\JS}}_{1,\al}\arrow[d,"\pi^{\JS}_{\al}"]\\
    &\mM^{\rig}_{\al}\,.
\end{tikzcd}
\end{equation}
Their obstruction theories are related by the corresponding $\infty$-Pvp diagrams from Assumption \ref{ass:obsonflag}. They are compatible in the sense of Theorem \ref{thm:functsympull} explained in §\ref{Sec:pullback}.

Using that 
$$
\chi\big(\pi^{\zeta}_{\un{d}/1,\al}\big) = \Big(\chi\big(\al(k)\big)-1\Big)!\,,
$$
Theorem \ref{thm:virtualpullpush} implies that
\begin{align*}
\chi(\al(k))!\cdot \Omega^{\zeta^0}_{\un{d},\al} &= 
\big(\pi^{\zeta}_{\un{d},\alpha}\big)_*\Big(\big[N_{\un{d},\alpha}^{\zeta^{0}}\big]^{\vir}\cap c_{\Rk}\big(T_{\pi^{\zeta}_{\un{d},\alpha}}\big)\Big)\\
&= \big(\pi^{\JS}_{\al}\big)_*\big(\pi^{\zeta}_{\un{d}/1,\alpha}\big)_*\Big(\big[N_{\un{d},\alpha}^{\zeta^{0}}\big]^{\vir}\cap c_{\Rk}\big(T_{\pi^{\zeta}_{\un{d}/1,\alpha}}\big)\Big)\\  &= \big(\chi(\al(k))-1\big)!\cdot\big(\pi^{\JS}_{\al}\big)_*\Big(\big[N^{\zeta_{\JS}}_{1,\alpha}\big]^{\vir}\cap c_{\Rk}\big(T_{\pi^{\JS}_{\alpha}}\big)\Big)\\
