\section{Lemma 1 and other derivations} 


\paragraph{Proof of Lemma 1}
We compute the conditional expectation of \( Z_u \) given \( X_u = x_u \), and deduce \( \eta_u \) by taking successive expectations under \( q \).

\[
\begin{aligned}
\mathbb{E}_{q}[Z_u \mid \mathbf{X}_u]
&= \sqrt{w_u(\mathbf{X}_u)} \cdot \mathbb{E}_{q} \left[ w_{\bar{u}}(\mathbf{X}_{\bar{u}} \mid \mathbf{X}_u) \cdot \mathbb{E}[Y \mid \mathbf{X}] \,\middle|\, \mathbf{X}_u \right] \\[6pt]
&= \sqrt{w_u(\mathbf{X}_u)} \cdot \mathbb{E}_{p} \left[ \mathbb{E}[Y \mid \mathbf{X}] \,\middle|\, \mathbf{X}_u \right] \\[6pt]
&= \sqrt{w_u(\mathbf{X}_u)} \cdot m_u(\mathbf{X}_u), 
\end{aligned}
\]
and
\[
\mathbb{E}_{q}[\mathbb{E}_{q}[Z_u \mid \mathbf{X}_u]^2 ] = \mathbb{E}_{q}[w_u(\mathbf X_u) m_u^2(\mathbf{X}_u) ] = \mathbb{E}_{p}[m_u^2(\mathbf{X}_u) ] 
\]

\paragraph{Derivation of the optimal variance under \texorpdfstring{$p_u$}{pu} in (3.7)}

We start from the expression

\[
\sigma^2_{\mathrm{opt}, u}(q)
= 4\, \mathbb{E}_{q} \left[ \mathbb{E}_{q}[Z_u \mid \mathbf{X}_u]^2 \cdot \mathbb{E}_{q}[Z_u^2 \mid \mathbf{X}_u] \right]
- 3\, \mathbb{E}_{q} \left[ \left( \mathbb{E}_{q}[Z_u \mid \mathbf{X}_u] \right)^4 \right]
- \eta_u^2.
\]

Using the last identity  we deduce
\[
\mathbb{E}_{q}[Z_u \mid \mathbf{X}_u]^2
= w_u(\mathbf{X}_u) \, m_u^2(\mathbf{X}_u),
\quad
\left( \mathbb{E}_{q}[Z_u \mid \mathbf{X}_u] \right)^4
= w_u^2(\mathbf{X}_u) \, m_u^4(\mathbf{X}_u).
\]

For the second term $\mathbb{E}_{q_{\bar{u}}}[Z_u^2 \mid \mathbf{X}_u]$, we write

\[
\begin{aligned}
\mathbb{E}_{q}[Z_u^2 \mid \mathbf{X}_u]
&= \mathbb{E}_{q}\left[ \left(\sqrt{w_u(\mathbf{X}_u)} \, w_{\bar{u}}(\mathbf{X}_{\bar{u}} \mid \mathbf{X}_u) \, Y \right)^2 \middle| \mathbf{X}_u \right] \\
&= w_u(\mathbf{X}_u) \cdot \mathbb{E}_{p}\left[ w_{\bar{u}}(\mathbf{X}_{\bar{u}} \mid \mathbf{X}_u) \, \phi^2(\mathbf{X}) \mid \mathbf{X}_u \right].
\end{aligned}
\]

Combining all terms, we obtain:
\[
\begin{aligned}
\sigma^2_{\mathrm{opt}, u}(q)
&= 4\, \mathbb{E}_{q} \left[ w_u^2(\mathbf{X}_u)\, m_u^2(\mathbf{X}_u) \cdot 
\mathbb{E}_{p} \left[ w_{\bar{u}}(\mathbf{X}_{\bar{u}} \mid \mathbf{X}_u) \cdot \phi^2(\mathbf{X}) 
\,\middle|\, \mathbf{X}_u \right] \right] \\[6pt]
&\quad - 3\, \mathbb{E}_{q} \left[ w_u^2(\mathbf{X}_u)\, m_u^4(\mathbf{X}_u) \right]
- \eta_u^2 \\[10pt]
&= 4\, \mathbb{E}_{p} \left[ w_u(\mathbf{X}_u)\, m_u^2(\mathbf{X}_u) \cdot 
\mathbb{E}_{p} \left[ w_{\bar{u}}(\mathbf{X}_{\bar{u}} \mid \mathbf{X}_u) \cdot \phi^2(\mathbf{X}) 
\,\middle|\, \mathbf{X}_u \right] \right] \\[6pt]
&\quad - 3\, \mathbb{E}_{p} \left[ w_u(\mathbf{X}_u)\, m_u^4(\mathbf{X}_u) \right]
- \eta_u^2.
\end{aligned}
\]




\paragraph{Computing optimal variance bounds} 
Plugging $ q^*_{\bar{u} \mid u}(\mathbf{x}_{\bar{u}} \mid \mathbf{x}_u) $, we compute the quantity 
that contributes to the variance 
$\sigma^2_{\mathrm{opt}}(q = (p_u, q^*_{\bar{u} \mid u}))$. 
We obtain:

\begin{align*}
\mathbb{E}_{p} 
\left[ w(\mathbf{X}) \cdot \phi^2(\mathbf{X}) \mid \mathbf{X}_u \right]
&= \mathbb{E}_{p} 
\left[ \frac{p(\mathbf{X})}{q^*(\mathbf{X} \mid \mathbf{X}_u)} \cdot \phi^2(\mathbf{X}) \,\middle|\, \mathbf{X}_u \right] \\[0.6em]
&= \mathbb{E}_{p} 
\left[ \frac{\mathbb{E}_{p}[\phi(\mathbf{X}) \mid \mathbf{X}_u]}{\phi(\mathbf{X})} \cdot \phi^2(\mathbf{X}) \,\middle|\, \mathbf{X}_u \right] \\[0.6em]
&= \mathbb{E}_{p} 
\left[ \phi(\mathbf{X}) \cdot \mathbb{E}_{p}[\phi(\mathbf{X}) \mid \mathbf{X}_u] \,\middle|\, \mathbf{X}_u \right] \\
&= \left( \mathbb{E}_{p}[\phi(\mathbf{X}) \mid \mathbf{X}_u] \right)^2.
\end{align*}



Similarly for \(q^*(\mathbf{x}_u)\):
\[
\begin{aligned}
\mathbb{E}_{p} \left[ w(\mathbf{X}_u)\, S(\mathbf{X}_u) \right] - \eta_u^2
&= \mathbb{E}_{p} \left[ \frac{p(\mathbf{X}_u)}{q^*(\mathbf{X}_u)}\, S(\mathbf{X}_u) \right] - \eta_u^2 \\[0.6em]
&= \mathbb{E}_{p} \left[ \frac{ \mathbb{E}_{p}[\sqrt{S(\mathbf{X}_u)}] }{ \sqrt{S(\mathbf{X}_u)} }\, S(\mathbf{X}_u) \right] - \eta_u^2 \\[0.6em]
&= \mathbb{E}_{p} \left[ \mathbb{E}_{p}[\sqrt{S(\mathbf{X}_u)}] \cdot \sqrt{S(\mathbf{X}_u)} \right] - \eta_u^2 \\[0.6em]
&= \left( \mathbb{E}_{p}[\sqrt{S(\mathbf{X}_u)}] \right)^2 - \eta_u^2.
\end{aligned}
\]



\paragraph{Derivation of the zero-variance formula}

We start from the general expression:
\[
\sigma^2_{\mathrm{opt}, u}(q)
= \mathbb{E}_{p} \left[
    w_u(\mathbf{X}_u) \cdot \left(
        4\, m_u^2(\mathbf{X}_u) \cdot \mathbb{E}_{p}\left[ w_{\bar{u}}(\mathbf{X}_{\bar{u}} \mid \mathbf{X}_u)\, \phi^2(\mathbf{X}) \mid \mathbf{X}_u \right]
        - 3\, m_u^4(\mathbf{X}_u)
    \right)
\right]
- \eta_u^2.
\]


Now Plugging both optimal densities simultaneously:

$$
q_u^*(\mathbf{x}_u) = \frac{p_u(\mathbf{x}_u)\, m_u^2(\mathbf{x}_u)}{\eta_u}  \qquad
q_{\bar u}^*(\mathbf{x}_{\bar u} \mid \mathbf{x}_u) =
\frac{p_{\bar u}(\mathbf{x}_{\bar u})\, f(\mathbf{x})}{m_u^2(\mathbf x_u)}
$$

\[
\begin{aligned}
\sigma^2_{\mathrm{opt}, u}(q)
&= \mathbb{E}_{p} \left[
    w(\mathbf{X}) \cdot \left(
        4\, m^2(\mathbf{X}) \cdot \mathbb{E}_{p} \left[
            w(\mathbf{X}) \cdot \phi^2(\mathbf{X}) \mid \mathbf{X} \right]
        - 3\, m^4(\mathbf{X})
    \right)
\right]
- \eta_u^2 \\[0.6em]
&= \mathbb{E}_{p} \left[
    \frac{\eta_u}{m^2(\mathbf{X})} \cdot \left(
        4\, m^2(\mathbf{X}) \cdot \mathbb{E}_{p} \left[
            \frac{m(\mathbf{X})}{f(\mathbf{X})} \cdot f^2(\mathbf{X}) \mid \mathbf{X}
        \right]
        - 3\, m^4(\mathbf{X})
    \right)
\right]
- \eta_u^2 \\[0.6em]
&= \mathbb{E}_{p} \left[
    \frac{\eta_u}{m^2(\mathbf{X})} \cdot \left(
        4\, m^3(\mathbf{X}) \cdot m(\mathbf{X})
        - 3\, m^4(\mathbf{X})
    \right)
\right]
- \eta_u^2 \\[0.6em]
&= \mathbb{E}_{p} \left[
    \frac{\eta_u}{m^2(\mathbf{X})} \cdot m^4(\mathbf{X})
\right]
- \eta_u^2 \\[0.6em]
&= \eta_u \cdot \mathbb{E}_{p} \left[ m^2(\mathbf{X}) \right]
- \eta_u^2 \\[0.6em]
&= \eta_u^2 - \eta_u^2 = 0.
\end{aligned}
\]

