\title{Programmable Governance \\for Group-Controlled \\Decentralized Identifiers
}

\author{\IEEEauthorblockN{Carlo Segat, Sandro Rodriguez Garzon, Axel Küpper}
\IEEEauthorblockA{\textit{Service-centric Networking} \\
