\section{Proofs}
\label{sec:Proofs}

\subsection{Proof of Theorem~\ref{ImplicitFormula}}
\label{proofImplicit}

Fix $T > 0$ and consider a European call option with strike $k$ and 
maturity $t \leq T$ on the forward rate $f_t(T)$.  
Let 
$
C^T(t,k) := \mathbb{E}^{\T}\left(\left( f_t(T) - k \right)_+\right)
$
be the non-discounted price of the option at time $t$ under the $T$-forward measure.
At $t = T$, we have $f_T(T)=x_T$, so that 
$C^T(T,k) = \mathbb{E}^{\T}\left( x_T - k \right)_+ = C(T,k)$,
where $C(T,k)$ denotes the non-discounted price of the option on the rolling forward rate.
According to the Dupire's framework, 
we have that 
\begin{equation}
\label{Dupire1}
 \sigma^2(T,k)  =  2\,\frac{ \partial_t C^T(t,k)\big|_{t=T} }{ \partial_{kk} C^{T}(T,k) }
 =2\,\frac{ \partial_t C^T(t,k)\big|_{t=T} }{ \partial_{kk} C(T,k) }.
\end{equation}
The denominator 
$\partial_{kk} C^{T}(T,k)=\partial_{kk} C(T,k)$ can be extracted from the market, but the numerator 
$\partial_t C^T(t,k)\big|_{t=T}$ is not directly observable, since options with maturities $t<T$ are not traded.
We therefore relate $\partial_t C^T(t,k)\big|_{t=T}$ to market data.

First, note  that 
\begin{equation}
\label{total_diff}
\partial_t C^T(t,k)\big|_{t=T} = d_T C^T(T,k) - \partial_T C^T(t,k)\big|_{t=T},
\end{equation}
where $d_T$ denotes the full derivative with respect to $T$,  
and 
\[
d_T C^T(T,k) = \partial_T C(T,k).
\]
Therefore, it suffices to compute the derivative $\partial_T C^T(t,k)\big|_{t=T}$.
To this end, recall that
\[
C^{T+dT}(t,k) = \mathbb{E}^{\T+dT}\left( f_t(T+dT) - k \right)_+ 
= \mathbb{E}^{\T}\left( P_t(T+dT)\, (f_t(T+dT) - k)_+ \right)
\]
and compute 
\begin{equation*}
\begin{split}
-\partial_T C^T(t,k)\big|_{t=T}
&= -\mathbb{E}^{\T}\left( \partial_T \left( P_t(T)(f_t(T) - k)_+ \right) \Big|_{t=T} \right) \\
&= - \mathbb{E}^{\T}\left( (f_T(T)-k)_+\,\partial_T P_t(T)\big|_{t=T} \right) - 
\mathbb{E}^{\T}\left( P_t(T)\,\partial_T (f_t(T)-k)_+\big|_{t=T} \right) .
\end{split}
\end{equation*}
Since $P_T(T) = 1$, the second term simplifies, and we have that
\begin{align}
\label{eq:generic}
-\partial_T C^T(t,k)\big|_{t=T}
&= -\mathbb{E}^{\T}\left( (f_T(T)-k)_+\,\partial_T P_t(T)\big|_{t=T} \right) - 
\mathbb{E}^{\T}\left( \theta(f_T(T)-k)\,\partial_T f_t(T)\big|_{t=T} \right).
\end{align}
By~\eqref{f(t,T)-0}), 
$
\partial_T P_t(T)\big|_{t=T} = -f_T(T) = -x_T$ and $\partial_T f_t(T)\big|_{t=T} = y_T - \mu x_T$.
Therefore, 
\[
-\partial_T C^T(t,k)\big|_{t=T}
= \mathbb{E}^{\T}\left( x_T(x_T-k)_+ \right) -
 \mathbb{E}^{\T}\left( y_T\,\theta(x_T-k) \right) + \mu\,\mathbb{E}^{\T}\left( x_T\,\theta(x_T-k) \right).
\]
Using 
$
x_T\,\theta(x_T-k) = (x_T-k)_+ - k\,\partial_k (x_T-k)_+
$
we obtain that 
\begin{equation}
\label{partial_T-C}
\begin{split}
-\partial_T C^T(t,k)\big|_{t=T}
&= \mu\left( C(T,k) - k\,\partial_k C(T,k) \right) +
 \E^{\T}\left( x_T(x_T-k)_+ \right) - \E^{\T}\left( y_T\,\theta(x_T-k) \right).
\end{split}
\end{equation}
Substituting this result into~\eqref{total_diff} and recalling~\eqref{Dupire1} gives 
that
\begin{align*}
%\label{Dupire12}
\sigma^2(T,k) &= 2\frac{ \partial_T C(T,k) - \mathbb{E}^{\T}(x_T-k)_+
\partial_T P_t(T)\big|_{t=T} - 
\mathbb{E}^{\T} \theta(x_T-k)\,\partial_T f_t(T)\big|_{t=T} }
{ \partial_{kk} C(T,k) }\\
&= 2\,\frac{ \partial_T C(T,k) + \mu\left( C(T,k) - k\,\partial_k C(T,k) \right) + 
\mathbb{E}^{\T}\left( x_T(x_T-k)_+ \right) - \mathbb{E}^{\T}\left( y_T\,\theta(x_T-k) \right) }
{\partial_{kk} C(T,k)},
\end{align*}
which proves Theorem~\ref{ImplicitFormula}.



\subsection{Proof of Theorem~\ref{thm:first_order}}
\label{proof:first_order}

Fix $T>0$ and consider
 the semigroup $(P_{t}^{\varepsilon},\, t\in [0, T])$ corresponding to the diffusion process $(x_t,\, t\in[0,T])$
 that follows equation~\eqref{eps-x}, 
i.e.
$$P_{t}^{\varepsilon}q(x)=\E(q(x_t)|x_0=x)$$
for an appropriate function $q$.
For ease of notations, we will write $P_{t}^{\varepsilon}q=\E(q(x_t))$.
In addition, denote
$$\xi(x)=x(x-k)_+,\quad \eta(x)=(x-k)_+,\quad \theta_k(x)=\theta(x-k)
\quad\text{and}\quad  \delta_k(x)=\delta(x-k),$$
where $\delta$ is the Dirac delta-function, 
and recall some useful equations
\begin{equation}
\label{used-equations}
\partial_{xx}\xi(x)=2\theta_k(x)+x\delta(x-k),\quad \partial_{xx}\eta(x)=\delta(x-k).
\end{equation}
In the above notations we have that
\begin{align*}
\E(x_T(x_T-k)_+)&=P_T^\eps\xi,\\
\E\left(y_T\theta(x_T-k)\right)&=\E\left(y_T\theta_k(x_T)\right)
=\int_0^TP_t\sigma^2(x_t,t)P^\eps_{T-t}\theta_kdt
=(P^{\varepsilon}\ast \sigma^2 P^{\varepsilon})_{T} \theta_k, 
\end{align*}
where $\ast$ denotes the convolution,  and 
by $\sigma^2$ we denot the operator of multiplication on the function $\sigma^2(x_t,t)$, so that 
 \begin{equation}
 \label{A5}
A 
=P^{\varepsilon}_{T}\xi - 
(P^{\varepsilon} \ast\sigma^2P^{\varepsilon})_{T}\theta_k.
\end{equation}
Observe now that 
the generator of the semigroup is 
$$G^{\eps}=\frac{1}{2} 
\sigma^2(t,x)\partial_{xx}=\frac{1}{2}\left(\sigma_0^2(t)+\eps\Delta\sigma^2(t,x)\right)\partial_{xx}
=G+\eps B,
$$
where 
$B = \frac{1}{2} \Delta \sigma^2(t,x)\partial_{xx}$ 
and the operator 
$
G = \frac{1}{2} \sigma_0^2(t)\partial_{xx}
$
 is the generator of the semigroup 
$(P^0_{t},\, t\in [0,T])$ of the
 diffusion  process  with the zero drift and 
time-dependent local volatility $\sigma_0(t)$, i.e. the process corresponding 
to the case when $\eps=0$.
Thus, 
the semigroup  $P_{t}^{\varepsilon}$  can be regarded as 
 a perturbation of the (unperturbed) semigroup $P^0_{t}$, which is determined by the equation
 \[
P_{t}^0 = e^{\frac{1}{2} w_{t,T} \partial_{xx}},\quad t\in[0,T],
\]
where
\begin{equation}
\label{w:eps=0}
w_{t,T} = \int_t^T \sigma_0^2(s)\,ds,\quad t\in [0,T].
\end{equation}
By Duhamel’s principle, 
\begin{equation}
\label{Duh}
\begin{split}
P_{T}^{\varepsilon} &= P_{T}^0 + \varepsilon \int_0^T P_{t}^{\varepsilon} B P_{T-t}^0 \,dt
=P_{T}^0 + \varepsilon \left(P^{\varepsilon} \ast B P^0\right)_{T}
 = P_T^0 + \frac{1}{2} \varepsilon (P^{\varepsilon} \ast \Delta \sigma^2 \partial_{xx}P^0)_T,
\end{split}
\end{equation}
so that the equation~\eqref{A5} becomes
\[
A = P_T^0\xi + \frac{1}{2} \varepsilon 
(P^{\varepsilon} \ast \Delta \sigma^2 \partial_{xx} P^0)_{T}\xi-
 (P^{\varepsilon} \ast \sigma^2 P^{\varepsilon})_{T}\theta_k.
\]
A direct calculation gives that
\begin{equation}
\label{P-xi=w}
P_{T}^0\xi= w_{0,T} P^0_{T}\theta_k,
\end{equation}
where $w_{0,T}$ is defined in~\eqref{w:eps=0}.
Using commutativity of operators $P^0_T$ and $\partial_{xx}$, and~\eqref{used-equations}
 we obtain that 
\begin{equation}
\label{partial-P-xi}
\partial_{xx} P_{T}^0\xi = 
 P_{T}^0 \partial_{xx} \xi= 
 P_{T}^0\left(2\theta_k + x\delta_k \right),
\end{equation}
Furthermore, observe that
\begin{equation}
\label{=0}
(P^{\varepsilon} \ast \Delta\sigma^2P^0)_T\delta_k = 0.
\end{equation}
Indeed, by the assumption~\eqref{wT2}, we have 
the pricing equality
$
C(T,k) = P^{\varepsilon}_T\eta = P^0_T\eta,
$
where $C(T,k)$ denotes the non-discounted 
price under the  perturbed dynamics.
Therefore, by~\eqref{Duh} and commutativity of $P^0_T$ and $\partial_{xx}$, we obtain that 
\[
 (P^{\varepsilon}\ast\Delta\sigma^2
\partial_{xx}P^0)_T\eta=(P^{\varepsilon}\ast\Delta\sigma^2P^0)_T
\partial_{xx}\eta=0.
\]
Since $\partial_{xx}\eta=\delta_k$ (see~\eqref{used-equations}, we get~\eqref{=0},
as claimed.

Further, by~\eqref{P-xi=w},~\eqref{partial-P-xi} and~\eqref{=0},
\begin{equation*}
A=w_{0,T}P_T^0\theta_k+
\varepsilon (P^{\varepsilon}\ast\Delta\sigma^2P^0)_T\theta_k-(P^{\varepsilon}
\ast\sigma^2P^{\varepsilon})_T\theta_k.
\end{equation*}
Recalling that $\sigma^2=\sigma_0^2+\Delta\sigma^2$ and using 
the equation
$(P^{\varepsilon}\ast\sigma^2_0P^{\varepsilon})_T=w_{0,T}P_T^{\varepsilon}$
 rewrite the preceding equation for $A$
as follows
\begin{align}
\label{A6}
A
&=w_{0,T}\Big(P^0_T-P^{\varepsilon}_T\Big)\theta_k-
\varepsilon\,
(P^{\varepsilon}\ast\Delta\sigma^2(P^0-P^\eps))_T\theta_k.
\end{align}
By assumption~\eqref{wT2}, 
$w_{0,T}=w(T,k).$
Regarding the Bachelier's price as a function of the strike and the
 total variance $w$ (see Remark~\ref{BH(w)}) we have the following 
 equations
\begin{align*}
P^0_T\theta_k&=-\partial_k\mathrm{BH}(k,w(T, k)),\nonumber\\[1mm]
P^{\varepsilon}_T\theta&
=-\partial_k\mathrm{BH}(k,w(T, k))-\partial_w\mathrm{BH}(k,w(T, k))\partial_kw(T,k)\\
&=-\partial_k\mathrm{BH}(k,w(T, k))-
\frac{1}{2}p(T,k)\partial_kw(T,k),
\end{align*}
where 
\[
p(T,k)=\partial_w\mathrm{BH}(k,w(T,k))=\frac{1}{\sqrt{2\pi w(T,k)}} \exp\left( -\frac{k^2}{2 w(T,k)} \right).
\]
Collecting the above equations 
gives  the following for  the first term in the right-hand side of~\eqref{A6}  
$$
w_{0,T}\Big(P_T^0-P^{\varepsilon}_T\Big)\theta_k
=\frac{1}{2}p(T,k) w(T,k) \partial_kw(T,k).
$$
Finally, since the  term 
$- \varepsilon (P^{\varepsilon} \ast 
 \Delta \sigma^2(P^0-P^\eps))_T\theta_k$ in~\eqref{A6} is of order $\eps^2$,
  we conclude that
\[
A =  \frac{1}{2} p(T,k)w(T,k) \partial_kw(T,k) + o(\varepsilon),
\]
which proves Theorem~\ref{thm:first_order}.




\subsection{Proof of Theorem~\ref{thm:linear}}
\label{proof:linear}


Start with the following lemma, which might be of interest on its own right.
\begin{lemma}
\label{IG}
$$
\E(x_T(x_T-k)_+)
=
\frac{1}{2}\mathbb{E}\left(\tau\,{\bf 1}_{\{\tau>a+bk\}} \right)
+\frac{1}{2a}\mathbb{E}\left(\tau^2\,{\bf 1}_{\{\tau>a+bk\}} \right),
$$
where $\tau$ is a random variable which has an inverse Gaussian distribution  (IG distribution, 
aka Wald distribution, e.g., see~\cite{JohnsonKotz} and references therein)
with parameters $a$ and $a^2/b^2$, i.e. $\tau\sim \mathrm{IG}(a,a^2/b^2)$.
\end{lemma}

\begin{proof}[Proof of Lemma~\ref{IG}]

Start with expressing the expectation  $\E(x_T(x_T-k)_+)$
 in terms of the call value $C(T,k)=\E((x_T-k)_+)$ (with maturity $T$ and strike $k$).
To this end, recalling  that the second derivative 
 $\partial_{xx} C(T,x)$ is equal to the pdf of $x_T$,
and integrating by parts, we get that 
\begin{align*}
\E(x_T(x_T-k)_+)
&
=\int_k^{\infty}
x(x-k)\partial_{xx}C(T,x)\,dx\\
&=\left(x(x-k)\partial_xC(x))\right]_k^{\infty}-\int_k^{\infty}(2x-k)\partial_x C(x)\,dx\\
&=-2\int_k^{\infty}x\partial_xC(x)\,dx-kC(k)\\
&=
k\,C(T,k)+2\int_{k}^{\infty}C(T,x)\,dx.
\end{align*}
Then, since
$$kC(T,k)+\int_k^{\infty}C(T,x)\,dx=\int_k^{\infty}x\partial_xC(x)\,dx,$$
we obtain that 
\begin{equation*}
\E(x_T(x_T-k)_+)
= \int_{k}^{\infty} \left(C(T,x)-x\partial_x C(T,x) \right)\,dx.
\end{equation*}
In the linear case $w(T,x)=a+bx$ 
the equation~\eqref{eq:CminusTerm} reduces to
\begin{equation*}
C(T,x)-x\,\partial_x C(T,x)
= p(T,x) \left( a+\frac{b}{2}x \right),
\end{equation*}
where 
$$p(T, x)=\frac{1}{\sqrt{2\pi(a+bx)}} \exp\left(-\frac{x^2}{2(a+bx)}\right),\quad x>-\frac{a}{b}.$$
Therefore,
\begin{equation*}
\E(x_T(x_T-k)_+)=\int_k^{\infty}p(T,x) \left(a+\frac{b}{2}x \right)dx
=
\frac{1}{2b} \int_{a+bk}^{\infty}
\frac{\exp\left( -\frac{(u-a)^2}{2b^2u} \right)}{\sqrt{2\pi} u^{3/2}} (a+u) u\,du.
\end{equation*}
It is left to note that  the function 
$$g(u)=\frac{a}{b}\frac{1}{\sqrt{2\pi}u^{3/2}}\exp\left(-\frac{(u-a)^2}{2b^2u}\right),\quad u>0,$$
is the density of an inverse Gaussian (IG) distribution, $\mathrm{IG}\left(a,a^2/b^2\right)$. The lemma is proved.
\end{proof}

By the properties of  IG distribution, 
$$
\E(\tau)=a \quad\text{and}\quad \E(\tau^2)=a^2+ab^2.
$$
Therefore, since  $\E(x_T)=0$, we get  that 
$$
\E(x_T^2)
= \frac{1}{2}\E(\tau)+\frac{1}{2a}\E(\tau^2)
= a + \frac{1}{2}b^2,
$$
and, hence, the adjustment term in the linear case  is 
\begin{equation*}
\epsilon
= \E(x_T^2)- \E(a+bx_T)
= \E(x_T^2)-a= \frac{1}{2}b^2,
\end{equation*}
as claimed.

Further, the   truncated 
moments of $\tau\sim \mathrm{IG}\left(a,a^2/b^2\right)$  are given by 
\begin{align*}
\E(\tau\,{\bf 1}_{\{\tau>a+bk\}})
   &=a\,\Phi\bigl(-\delta_1(a+bk)\bigr)
     +a\,e^{2a/b^2}\,\Phi\bigl(\delta_2(a+bk)\bigr), \notag\\
\E(\tau^{2}\,{\bf 1}_{\{\tau>a+bk\}})
   &=b^2\,e^{2a/b^2}
     \frac{2a}{b}\sqrt{a+bk}\phi\left(\delta_2(a+bk)\right)\\
     & +e^{-2a/b^2}\left(a+\frac{a^2}{b^2}\right)\Phi\!\left(-\delta_1(a+bk)\right)
  +\left(a-\frac{a^2}{b^2}\right)\Phi\left(\delta_2(a+bk)\bigr)\right),
\end{align*}
where $\Phi$ and $\phi$ are the cumulative distribution function and the probability density function 
of the standard normal distribution,
respectively,
\[
\delta_1(x)=\frac{a}{b\sqrt{x}}\Bigl(\frac{x}{a}-1\Bigr)
\quad\text{and}\quad
\delta_2(x)=-\frac{a}{b\sqrt{x}}\Bigl(\frac{x}{a}+1\Bigr).
\]
Expanding in a Taylor series with respect to the parameter $b$
yields that
$$
\frac{\A}{p(T,k)} = \frac{1}{2}b(a+bk+b^2) + o(b^3).
$$
The theorem is proved.

\section{Multi-factor model}
\label{SecNFactorCase}



In this section, we demonstrate how the local volatility formula can be extended to 
multi-factor Cheyette models. The extension is relatively straightforward, so 
we provide only a brief outline of the procedure, highlighting the main modifications required. 

Start with recalling the model  (see, e.g.,~\cite{AndersenPiterbarg2}).
 Under the risk-neutral measure \(\mathbb Q\) the model equations are
\begin{align*}
  d x_t &= \bigl( y_t \e-\mu x_t\bigr)\,dt + \sigma_r(t,x_t)\,dW_t,\\
  d y_t &= \bigl(\sigma_r(t,x_t)\sigma_r(t,x_t)^{\top}-\mu y_t-y_t\mu^{\top}\bigr)\,dt,
 \label{eq:ySDE}
\end{align*}
where \(x_t=(x_{1,t},\ldots, x_{d,t})^\top\in\mathbb R^d\) is the state vector, 
\(y_t=(y_{ij,t})_{i,j=1}^d\) is a real $d\times d$ symmetric matrix, 
$
{\bf\mu}=\mathrm{diag}(\mu_1,\dots,\mu_d)
$
is 
a  diagonal mean reversion matrix, $ \sigma_r(t,x)$ is a volatility matrix, 
 $\e\in\R^d$ is a vector whose components are all equal to $1$ and $W_t=(W_{1,t},\ldots,W_{d,t})^\top$
 is a d-dimensional standard Brownian motion.
 We assume that 
 $
 \sigma_r(t,x)=\sigma(t, \bar{x}) V,
 $
  where $ \bar{x} = \e^\top x = \sum_{i=1}^dx_{i}$ for $x=(x_1,\ldots,x_d)^\top\in \R^d$, 
  $\sigma(\cdot, \cdot)$ is a deterministic function of two
  variables and $V$ is a $d\times d$ real matrix which satisfies 
 the normalisation condition
$\e^{\top}VV^{\top}\e=1$.
In these notations,
\begin{align*}
  d x_t &= \bigl(y_t \e -\mu x_t\bigr)\,dt + \sigma(t, \bar{x}_t) V dW_t,\\
  d y_t &= \bigl(\sigma^2(t, \bar{x}_t)V V^{\top}-\mu y_t-y_t\mu^{\top}\bigr)\,dt.
\end{align*}
In the multi-factor case
the bond price and the  instantaneous forward rate are given by 
\begin{equation}
\label{P-mult}
  P_t(T)=e^{-G(T-t)^{\top}x_t-\tfrac12\,G(T-t)^{\top}y_t\,G(T-t)}
\end{equation}
and 
\begin{align}
\label{forw-mult}
 f_t(T)&=\e^{\top}e^{-\mu (T-t)}(x_t + y_t\,G(T-t)),\\
r_T &= \e^{\top}x_T 
\end{align}
respectively, 
where $G(t) = {\mu}^{-1}(1-e^{-\mu t})\e$.

\begin{theorem}
\label{ImplicitFormula2F}
In the multi-factor Cheyette model, the local volatility is given by
\begin{equation*}
\label{localVol2F}
\begin{split}
&\sigma^2(T,k) \\
&=
 2\,\frac{ \partial_T C(T,k) + \mu_{{\rm eff}}\left( C(T,k) - k\,\partial_k C(T,k) \right) + 
  \mathbb{E}^{\T}\left(r_T(r_T-k)_+\right) -
   \mathbb{E}^{\T}\left(\theta(r_T-k)\, \e^\top y_T\e\right)}
{ \partial_{kk} C(T,k) },
\end{split}
\end{equation*}
where
$$
\mu_{{\rm eff}} = 
\frac{\mathbb{E}^{\T}\left(\theta(r_T-k)\, \e^{\top} 
\mu x_T\right) }{\mathbb{E}^{\T}\left( \theta(r_T-k)\, r_T\right)}.
$$
\end{theorem}


\begin{proof}[Proof of Theorem~\ref{ImplicitFormula2F}]
\label{proof:ImplicitFormula2F}
The proof of Theorem~\ref{ImplicitFormula2F} follows the same 
steps as in the one-factor case, with additional details provided below.
First, under the $\T$‑forward measure $\mathbb Q^{T}$ we have the equation for the instantaneous 
forward rate
$$ df_t(T)= \sigma_T(t,x_t) \,dW_t^{\T},\quad, t\in [0,T],$$
where    $\sigma_T(t,x)=\e^{\top}e^{-\mu (T-t)} \sigma_r(t,x)$.
The  matrix  $y_t$ can be expressed explicitly in the integral form
\[
  y_t  =  \int_{0}^{t} e^{-\mu (t-s)}\, \sigma_r(s)\sigma_r(s)^{\top}\, e^{-\mu (t-s)}\,ds
\]
and,  hence, the  total variance is given by 
$$
\e^{\top} y_T\e =  \int_{0}^{T}  \sigma_T(t,x_t) \sigma_T(t,x_t)^{\top}\,dt.
$$
By Gyöngy's lemma, 
a one-dimensional Markovian projection  $\hat{f}_t(T)$ of $f_t(T)$
follows the equation
\begin{equation*}
  d \hat{f}_t(T) =  \hat{\sigma}_{T}(t,\hat{f}_t(T))\,d\hat{W_t},
\end{equation*}
where  $\hat{W}_t$ is a one-dimensional standard Brownian motion and 
\[
\hat{\sigma}_{T}(t,k)^2 =\E^{\T}\left(   \sigma_T(t,x_t)   \sigma_T(t,x_t)^{\top} \mid f_t(T) = k\right).
\]
The standard Dupire equation is applicable for process $\hat{f}_t(T)$ i.e.
$$
\hat{\sigma}^2_{T}(t,k) = 2\,\frac{ \partial_t C^T(t,k) }{ \partial_{kk}  C^T(t,k) }.
$$
For $t=T$ we have that
\begin{align*}
  \hat{\sigma}^2_{T}(T,k)&=
  \E^{\T}\left(  \e^{\top} \sigma_r(T,x_T)  \sigma_r(T,x_T)^{\top}\e  \mid f_T(T) = k\right) \\
&=\E^{\T}\left( \sigma^2(T,\bar{x}_T)\e^{\top} V V^{\top}\e  \mid\bar{x}_T = k\right)
= \sigma^2(T,k). 
\end{align*}
Hence,
$$
 \sigma^2(T,k) =  2\,\frac{ \partial_t C^T(t,k)\big|_{t=T} }{ \partial_{kk} C(T,k) }.
$$
The rest of the proof is similar to the one-factor case. Namely, 
it remains to use 
equation~\eqref{eq:generic}  for expressing 
the derivative $\partial_tC^T(t,k)\big|_{t=T}$ in terms of derivatives 
 $\partial_T P_t(T)\big|_{t=T}  = -\e^{\top}x_T= -f_T(T)$ (i.e. of the  bond price~\eqref{P-mult})   and
     $\partial_T f_t(T)\big|_{t=T} =\e^{\top} y_T\e - \e^{\top} \mu x_T$ (i.e. of 
      the instantaneous forward rate~\eqref{forw-mult}) and 
   to apply the analogue of equation~\eqref{partial_T-C} to complete the proof (we skip the details).
\end{proof}

By property of the 
Markovian projection marginal distribution of $f_t(T)$ and  $\hat{f}_t(T)$ at $t = T$ are identical.
Hence, we have the identity 
$$\mathbb{E}^T\left(f_T(T)\left(f_T(T)-k\right)_+\right) =
 \mathbb{E}\left(\hat{f}_T(T)(\hat{f}_T(T)-k)_+\right)$$
 and the approximation
\begin{align*}
 \mathbb{E}^{\T}\left(\theta(f_T(T)-k)\e^{\top} y_T\e\right)& = 
 \int_0^T \mathbb{E}^{\T}
 \left(\theta(f_T(T)-k)\sigma_T(t,x_t) {\sigma_T(t,x_t) }^{\top}\right)dt\\
 &
\approx \mathbb{E}\left(\theta(\hat{f}_T(T)-k)\,  \hat{\sigma}^2_{T}(t,\hat{f}_T(t))\right).
\end{align*}
Proceeding similarly to the one-factor case,  we obtain 
the following approximation for the multi-factor analogue of the quantity $\A$
\begin{align*}
&
\mathbb{E}^T\left(f_T(T)\left(f_T(T)-k\right)_+\right)  - \mathbb{E}^T\left(
 \theta\left(f_T(T)-k\right)\e^{\top} y_T\e\right) \\
&\approx \mathbb{E}\left(\hat{f}_T(T)(\hat{f}_T(T)-k)_+\right) - 
\mathbb{E}^T\left(\theta(\hat{f}_T(T)-k )   \int_0^T  \,  \hat{\sigma}^2_{T}(t,\hat{f}_T(t)) dt\right) \\
&\approx \frac{1}{2}p(T,k)\left( (\partial_kw)^3 + \partial_kw \right),
\end{align*}
which gives the approximation
$$
\sigma^2(T, k)
 \approx \frac{ \partial_T w + \mu_{\text{eff}} \left( 2w - k\,\partial_k w \right) + w\,\partial_k w }
{\left(1 - \frac{k\,\partial_k w}{2w} \right)^2 +
 \frac{1}{2}\left( \partial_{kk}w - \frac{(\partial_k w)^2}{2w} \right)} + (\partial_k w)^3
$$
for the local volatility in the multi-factor case.

\begin{remark}
{\rm 
Note that, in comparison with the one-factor case, the following additional 
term arises in the multi-factor setting
$\mathbb{E}^{\T}\left( \theta(f_T(T)-k)\e^{\top} \mu x_T   \right)$.
In the  Gaussian case this term can be estimated by
$$
 \mathbb{E}^{\T}\left( x_{T}\Big|\e^{\top} x_T = r \right) =
  r \frac{\Cov(x_{T}, \e^{\top} x_T)}{\Var(\e^{\top} x_T)}=  r \frac{\bar{y}_T\e}{\e^{\top} \bar{y}_T\e},
$$
 where 
$\bar{y}_T$ denotes the matrix $y_T$, calibrated within the 
Gaussian model to match the at-the-money (ATM) term structure of the  implied volatility.
This gives 
 the following equation for the effective mean-reversion
$$
\mu_{\text{eff}} =  \frac{\e^{\top} \mu \bar{y}_T\e}{\e^{\top} \bar{y}_T\e}.
$$
In Section~\ref{2-factor} we show how 
 this quantity can be evaluated in the case of the two-factor model. 
 }
 \end{remark}


\section{Example: the two-factor model}
\label{2-factor}

In this section we consider
the two-factor Cheyette model. 
Let 
\[
x_t = 
\begin{pmatrix}
x_{1,t} \\
x_{2,t}
\end{pmatrix},
\quad
y_t =
\begin{pmatrix}
y_{1,t} & y_{3,t} \\
y_{3,t} & y_{2,t}
\end{pmatrix},
\quad
\mu = 
\begin{pmatrix}
\mu_1 & 0 \\
0 & \mu_2
\end{pmatrix},
\]
where, for convenience, we denoted $y_{11,t}=y_{1,t},\,  y_{22,t}=y_{2,t}$ and $y_{12,t}=y_{21,t}=y_{3,t}$.
The volatility matrix is given by 
\[
\sigma_r(t,x_t) = \sigma(t, x_{1,t}+x_{2,t})
\begin{pmatrix}
\alpha & 0 \\
\rho \beta & \sqrt{1-\rho^2}\beta
\end{pmatrix},
\]
where $-1 \leq \rho \leq 1$, $\alpha>0$ and $\beta>0$ are given constants, 
and the normalization condition is 
\begin{equation}
\label{norm-2}
\e^{\top}VV^{\top}\e=1 \iff
\alpha^2 + 2\rho \alpha \beta + \beta^2 = 1.
\end{equation}
In the Gaussian case, i.e. when $\sigma^2(t,x)=\sigma^2(t)$,
the following approximation 
holds for the effective mean-reversion parameter  
 (see Appendix~\ref{Gaussian} for details)
\[
\mu_{\text{eff}}(T) \approx \frac{\mu_1 + \mu_2}{2} + \frac{\mu_1 - \mu_2}{2w(T)}
\frac{1}{2\gamma} \int_0^T \left( e^{(t-T)\lambda_2}(a+\gamma b) - 
e^{(t-T)\lambda_1}(a-\gamma b) \right) u(t)\,dt,
\]
where 
\begin{equation}
\label{u}
u(t)= \partial_t w(t)+ (\mu_1+\mu_2) w(t),\quad t\geq 0,
\end{equation}
$w(t)=(w(t),\, t\geq 0),$ is the implied total variance,
and
\begin{align}
\label{gamma}
\gamma &= \sqrt{ (1+2\rho\alpha\beta)^2 - (2\alpha\beta)^2 },
\\
\label{lamb1}
\lambda_{1} &= \mu_1 + \mu_2 + (\beta^2-\alpha^2)
\frac{\mu_1-\mu_2}{2}+\gamma\frac{\mu_1-\mu_2}{2},
\\
\lambda_{2} &= \lambda_1- \gamma(\mu_1-\mu_2),
\label{lamb2}\\
\nonumber
a &= (\alpha^2 - \beta^2)^2 - 2(\alpha^2+\beta^2),\\
\nonumber
b &= \alpha^2 - \beta^2.
\end{align}
We use the ATM term structure of the implied variance, i.e. 
$w(t) = t\sigma^2_{\text{imp}}(t,0)$,  to evaluate $u(t)$.
Figure~\ref{fig:2F} presents the implied volatility curve for a 10-year option,
 together with Monte Carlo estimates using (i) a one-factor model 
 with the  mean reversion parameter  $\mu=0.5$ and (ii) a two-factor model
 with parameters $ \rho = 0.5$, $\mu_1 = 0.0005$, $\mu_2 = 0.5$, $\alpha = 0.7$.
\begin{figure}[h!]
\centering
\includegraphics[scale=1]{2Fand1F.pdf}
\caption{Ten-year implied volatility curve and 1F and 2F cases.}
\label{fig:2F}
\end{figure}


\section{Calibration of the Cheyette model to swaptions}
\label{section:calibration}

In this section, we discuss the calibration of the Cheyette model to swaption market data.
The key idea is to transform  implied volatilities of swaptions into implied volatilities 
of rolling maturity options on the short rate.
This transformation enables the application 
 of the methodology developed in the previous sections.

A swaption can be regarded  as an option written on a function of $x_T$ and $y_T$, 
the state variables of the model at expiry. Consequently, its
 price  can be expressed 
in terms of the implied distribution of the short rate, which is characterized by the total implied variance $w(T,k)$.
%In particular, the model-implied total variance $y_T$ is 
% be approximated by $w(T,k)$.
The objective of the calibration is to determine $w(T,k)$ such 
that the resulting model-implied  swaption prices match the observed market prices.
This process requires numerical techniques, which are described in Section~\ref{sw-price}.

\subsection{Swaption pricing and implied volatility}
\label{sw-price}

Consider a swap with fixing date $T=T_0$, maturity $T_n$ and interest payments at $T_i, i=1,..,n$.
The fair swap rate realized at time $T$ is given by
$$S_T = \frac{1 - P_T(T_n)}{A_T},$$
where $A_T = \sum_{i=0}^{n-1} P_T(T_{i+1}) \Delta T_i$ is the
 value of an annuity at time $T$ paying $\$1 \cdot \Delta T_i$ at $T_i, i=1,..,n$ and
  $\Delta T_i = T_{i+1} - T_i$. 
The price of a swaption with maturity $T$ and strike $k$ at time $t=0$ is given by
$$
V(T,k) = \mathbb{E}^{\Q}\left(\frac{1}{B_T} A_T (S_T - k)_+ \right),
$$
where $B_T = e^{\int_0^T r_u du}$ is the value of  the money-market account.
This price can also be expressed in terms of the annuity measure (with the expectation $\E^A$)
and the $T$-forward measure, that is 
\begin{equation}
\label{V-A-T}
V(T,k)= A_0 \mathbb{E}^{A}\left((S_T - k)_+ \right) 
= P_0(T) \mathbb{E}^{\T}\left(A_T (S_T - k)_+ \right),
\end{equation}
where $A_0 = \sum_{i=0}^{n-1} P_0(T_{i+1}) \Delta T_i$
 is the value of  annuity at time $0$. 
Thus, swaption pricing is directly connected to the implied distribution 
of $S_T$ and $A_T$ under the $T$-forward measure.



Note that  both $A_T$ and $S_T$ are functions of the state variables $x_T$ and $y_T$.
Using the adjusted approximation~\eqref{y_T-adj} for $y_T$
 allows to 
 express $A_T$ and $S_T$ as functions of $x_T$: $A_T = A(x_T)$ and $S_T = S(x_T)$, so that 
 the expectations on the  right-hand side of~\eqref{V-A-T} 
can be computed using the implied distribution determined  by the implied total variance
$w(x_T)=w(T,x_T)$.
Instead of performing numerical integration, it is more efficient to work directly with 
the densities
$p_S$ and $p_x$ of $S_T$ and $x_T$, respectively,  under the $T$-forward measure. These densities 
are related by the equation
$$
p_S(k) = \partial_{kk} C(T,k) = \frac{P_0(T)}{A_0}
 \mathbb{E}^{\T}\left(A(x_T) \delta\left( S(x_T) - k \right) \right) 
 = \frac{P_0(T)}{A_0} \frac{A(x_k)}{|S'(x_k)|} p_x(x_k),
 $$
 where $C(T,k)=\frac{V(T,k)}{A_0}$, $x_k=S^{-1}(k)$ 
  and $S'(x_k) := \partial_{x_T} S(x_T)\big|_{x_T = x_k}$. 
The derivative $S'(x)$ is as follows
$$
S'(x_k) = -\frac{1}{A(x_k)} \left( S(x_k) A'(x_k) + \partial_x P_T(x_k, T_n) \right),
$$
where
$$
A'(x_k) := \partial_{x_T} A(x_T)\big|_{x_T = x_k}, \quad\text{and}\quad
 \partial_x P_T(x_k, T_n) :=  \partial_{x_T} P_T(x, T_n) \big|_{x_T = x_k}.
$$ 
Combining the results, we obtain
$$
p_S(k) = \frac{P_0(T)}{A_0} \frac{A^2(x_k)}{ |S(x)A'(x_k) + P_T'(x_k,T_n)| } p_x(x_k).
$$
Next, we express both $p_S(k)$ and $p_x(x_k)$ in terms of their implied variances
 $z(k)=z(T,k)$ (the implied variance of the 
 swaption at time $T$) and $w(x_k)$, respectively. 
  This yields the calibration identity
\begin{align*}
\frac{1}{\sqrt{2 \pi z(k)}} e^{-\frac{k^2}{2 z(k)}}& 
\bigg(\bigg(1 - \frac{k z'(k)}{2 z(k)}\bigg)^2 + \frac{1}{2} z''(k) - \frac{z'(k)^2}{4 z(k)}\bigg)\\
&= \frac{P_0(T)}{A_0} \frac{A^2(x_k)}{|S(x_k) A'(x_k) + P'_T(x_k, T_n)|} \\
& \quad \times \frac{1}{\sqrt{2 \pi w(x_k)}} e^{-\frac{x_k^2}{2 w(x_k)}}
 \bigg(\bigg(1 - \frac{x_k w'(x_k)}{2 w(x_k)}\bigg)^2 + \frac{1}{2} w''(x_k) - \frac{w'(x_k)^2}{4 w(x_k)}\bigg), 
\end{align*}
where  $z'(x)$ and $w'(x)$ are derivatives   of $z$ and $w$, respectively.
Solving this equation numerically enables the recovery of the implied variance $w(x_T)$
of rolling forward options from observed swaption market data. This completes 
the calibration of the model to the swaption market.

\subsection{Numerical example}

In this section, we provide a numerical illustration
 of the calibration procedure for the Cheyette model with local volatility.
We use a typical example of a 5Y/5Y payer swaption.
The market input is given by the swaption implied volatility surface 
$\mathrm{IV}_S=\mathrm{IV}_S(k,T)$.
First, we  transform the swaption implied volatilities into implied volatilities 
$\mathrm{IV}_f=\mathrm{IV}_f(k,T)$
of rolling maturity options on the short rate.
This transformation is performed by using the calibration method 
described in the previous section.
% i.e. by solving the relation between swaption densities and forward densities.
The resulting implied forward volatilities $\mathrm{IV}_f$ are shown in Figure~\ref{fig:ivFS}.

\begin{figure}[h!]
\centering
\includegraphics[width=0.65\textwidth]{ivFS.pdf}
\caption{Implied forward volatilities $\mathrm{IV}_f$ derived from swaption volatilities $\mathrm{IV}_S$.}
\label{fig:ivFS}
\end{figure}
Next, we use the obtained forward implied volatilities to calibrate the local volatility surface 
via the approximation~\eqref{main-1-factor}.
Based on  this local volatility surface, 
we simulate the dynamics of the forward rate using a Monte Carlo method.
The swaption price is then reconstructed from the simulated  paths, and
 the corresponding implied volatility is computed.
The comparison between the model-implied swaption volatilities and the original market 
swaption volatilities is shown in Figure~\ref{fig:iv}.
\begin{figure}[h!]
\centering
\includegraphics[width=0.65\textwidth]{iv.pdf}
\caption{Model-implied swaption volatilities compared to market swaption volatilities.}
\label{fig:iv}
\end{figure}
The results demonstrate a good fit between the model and the market data,
 confirming the practical applicability and accuracy of the proposed calibration method.


\section{Appendix. Two-factor  Gaussian case}
\label{Gaussian}

In this appendix, we derive explicit formulas for $y_{1,t}$, $y_{2,t}$, and $y_{3,t}$ in the Gaussian case, i.e. when 
$\sigma(t,x) = \sigma(t)$.
In this case we have that 
\begin{equation*}
\mu_{\text{eff}}(t) =  \frac{\e^{\top} \mu y_t \e}{\e^{\top} y_t \e}= 
\frac{\mu_1 y_{1,t} + (\mu_1 + \mu_2)y_{3,t}+ \mu_2 y_{2,t}}{w(t)},
\end{equation*}
where $w(t)$ is the implied  total variance.
  Note that 
\begin{align*}
w(t) &=\e^{\top} y_t \e =  y_{1,t} +2 y_{3,t}+y_{2,t}\\
y_{3,t} &= \frac{w(t) - y_{1,t} - y_{2,t}}{2}.
\end{align*}
Therefore,
\begin{equation*}
\mu_{\text{eff}}(t)  =  \frac{\mu_1 + \mu_2}{2} + \frac{\mu_1 - \mu_2}{2} \frac{y_{1,t} - y_{2,t}}{w(t)}.
\end{equation*}

Let us  express  the variables $y_{1,t}$, $y_{2,t}$ and $y_{3,t}$  in terms of 
 $w(t)$. This will, in turn, allow us to 
 express  $\mu_{\text{eff}}(t)$ as a function of $w(t)$.
In the Gaussian case we have the  following ODEs
\begin{align*}
%\label{y1}
\partial_t y_{1,t} + 2\mu_1 y_{1,t} &= \alpha^2 \sigma^2(t), \\
%\label{y2}
\partial_t y_{2,t} + 2\mu_2 y_{2,t} &= \beta^2 \sigma^2(t), \\
%\label{y3}
\partial_t y_{3,t} + (\mu_1+\mu_2) y_{3,t} &= \rho \alpha \beta \sigma^2(t),
\end{align*}
that yield the following two  equations 
\begin{align}
\label{y11}
u(t)-\left(\mu_1+\mu_2+4\rho
 \frac{\beta }{\alpha}\mu_1\right)y_{1,t}-\left(\mu_1+\mu _2\right)y_{2,t}
&=\left(1+2\rho
 \frac{\beta }{\alpha }\right)\partial_ty_{1,t}+\partial _ty_{2,t}\\
 \label{y21}
u(t)-\left(\mu_1+\mu_2+4\rho
\frac{\alpha }{\beta } \mu_2\right)y_{2,t}-\left(\mu_1+\mu_2\right)y_{1,t}
&=\left(1+2\rho\frac{\alpha}{\beta}\right)\partial_ty_{2,t}+\partial_ty_{1,t},
\end{align}
where  $u(t)$ is the function defined in~\eqref{u}.
Introducing  the vector 
$
Y(t) = 
\begin{pmatrix}
y_{1,t} \\
y_{2,t}
\end{pmatrix}
$
  rewrite equations~\eqref{y11} and~\eqref{y21} in the 
matrix form 
\begin{align*}
u(t)\e-Q Y(t)=P\frac{dY(t)}{dt},
\end{align*}
or, equivalently, 
\begin{equation}
\label{Y}
\frac{dY(t)}{dt} = (u(t) P^{-1}\e - M Y(t)),
\end{equation}
where
\begin{align*}
P &= 
\begin{pmatrix}
1+2\rho \beta/\alpha & 1 \\
1 & 1+2\rho \alpha/\beta
\end{pmatrix},
\\
Q &= 
\begin{pmatrix}
\mu_1+\mu_2 + \frac{4\beta \rho \mu_1}{\alpha} & \mu_1+\mu_2 \\
\mu_1+\mu_2 & \mu_1+\mu_2 + \frac{4\alpha \rho \mu_2}{\beta}
\end{pmatrix}
,\\
M &= P^{-1} Q.
\end{align*}
The solution of~\eqref{Y} is 
\[
Y(t) = \int_0^t e^{-M(t-s)} P^{-1}\e\, u(s) ds.
\]
Noting that 
$$
P^{-1}\e= 
\begin{pmatrix}
\alpha^2 \\
\beta^2
\end{pmatrix},
$$
we obtain that 
\begin{align*}
y_{1,T} &= \frac{\alpha^2}{2\gamma} \int_0^T
 \left( e^{(t-T)\lambda_1}(\gamma+\beta^2-\alpha^2+2) + 
 e^{(t-T)\lambda_2}(\gamma-\beta^2+\alpha^2-2) \right) u(t)\,dt, \\
y_{2,T} &= \frac{\beta^2}{2\gamma} \int_0^T
 \left( e^{(t-T)\lambda_1}(\gamma+\beta^2-\alpha^2-2) + 
 e^{(t-T)\lambda_2}(\gamma-\beta^2+\alpha^2+2) \right) u(t)\,dt,
\end{align*}
where $\gamma$, $\lambda_1$ and $\lambda_2$ are the quantities defined in~\eqref{gamma},~\eqref{lamb1}
and~\eqref{lamb2}, respectively.
Thus, we have obtained explicit formulas for $y_{1,T}$, $y_{2,T}$, and $y_{3,T}$
 (via the relation $2y_3=w-y_1-y_2$) in the Gaussian setting.



