    % elastic_pendulum_rowlands_convergence.ipynb
    \centering
    \includegraphics[width=\textwidth]{Fig3}
    \vspace*{-4ex}
    \caption{Demonstration of the fourth-order convergence of the Rowlands method versus the second-order convergence of the St\"{o}rmer--Verlet method through the example of the planar elastic pendulum in Cartesian coordinates. (Parameters: $l{=}1,\, m{=}1,\, k{=}1,\, g{=}0.2,\, t_\mathrm{max}{=}4$.)}
    \label{fig:rowlandsconvergence}
