\section*{Appendix B: Model-B-like Equation and Effective Free Energy}



As given in Eq. (\ref{NSEq})  of main text, the density and velocity fields satisfy the Navier-Stokes equations,
\begin{eqnarray}
    \frac{\partial \phi}{\partial t} &=& -  \nabla\cdot (\phi \mathbf{u})\label{continuity}  \\
      m\frac{\phi}{\sigma^2} \frac{ \mathcal{D} \mathbf{u}}{\mathcal{D} t} &=&  - \nabla P 
      +  {(\eta' + \eta_o' \boldsymbol{\epsilon}\cdot) } \nabla^2 \mathbf{u} 
      + ( {\zeta} +  {\zeta_o}\boldsymbol{\epsilon}\cdot ) \nabla(\nabla\cdot \mathbf{u}) -
      \gamma_t  \frac{\phi}{\sigma^2} \mathbf{u}  + \nabla \cdot \boldsymbol{\sigma}_{ \mathbf{u}}\label{NSEquation} 
\end{eqnarray}
In the long wave length limit, the inertia term $\frac{ \mathcal{D} \mathbf{u}}{\mathcal{D} t}=\left( \frac{\partial }{\partial t} + \mathbf{u}\cdot\nabla \right)\mathbf{u}$ is neglected, so we have
\begin{eqnarray}\label{NS}
    0 = 
    -\nabla P + {\eta'}\nabla^2 \mathbf{u} 
    + \eta_o' \boldsymbol{\epsilon}\cdot \nabla^2\mathbf{u}
    + {\zeta}\nabla(\nabla\cdot \mathbf{u})
    + {\zeta_o}\boldsymbol{\epsilon}\cdot\nabla(\nabla\cdot \mathbf{u})
    - \frac{\gamma_t}{\sigma^2} {\phi} \mathbf{u}
    + \nabla\cdot\boldsymbol{\sigma}_{\mathbf{u}}
\end{eqnarray}
Assume perturbation near the steady state $\phi(\mathbf{r},t)=\Bar{\phi},~T_t(\mathbf{r},t)=\Bar{T}_t,~P(\mathbf{r},t)=\Bar{P},~\mathbf{u}(\mathbf{r},t)=0$, we have
\begin{eqnarray}\label{pert}
   \delta \phi = \phi(\mathbf{r},t) - \Bar{\phi},~   \delta T =T_t(\mathbf{r},t)-{\Bar{T}_t} ,~\delta P = P(\mathbf{r},t)-\Bar{P},~ \delta \mathbf{u} = \mathbf{u}(\mathbf{r},t)
\end{eqnarray}
Then Eqs.~(\ref{continuity}-\ref{NSEquation}) reduce to a set of linear equations:
\begin{eqnarray}
    &&\frac{\partial \delta \phi}{\partial t} + \Bar{\phi} \nabla\cdot\left( \delta \mathbf{u} \right) = 0\\
    &&0=-\nabla\delta P + \eta' \nabla^2\delta \mathbf{u} 
    + \eta_o' \boldsymbol{\epsilon}\cdot \nabla^2\delta \mathbf{u}
    + {\zeta}\nabla(\nabla\cdot \delta \mathbf{u})
    + {\zeta_o}\boldsymbol{\epsilon}\cdot\nabla(\nabla\cdot \delta \mathbf{u})
    - \frac{\gamma_t}{\sigma^2} \Bar{\phi} \delta \mathbf{u} + \nabla\cdot\boldsymbol{\sigma}_{\mathbf{u}}
\end{eqnarray}
Under the Fourier transform 
\begin{eqnarray}\begin{aligned}
    \widetilde{ \delta \phi } 
    &=
    \int dt\int d^dx\ e^{i\omega t}e^{-i\mathbf{q}\cdot\mathbf{x}}\delta \phi\\
    \widetilde{ \delta T \ }
    &=
    \int dt\int d^dx\ e^{i\omega t}e^{-i\mathbf{q}\cdot\mathbf{x}}\delta T\\
    \widetilde{ \delta P } 
    &=
    \int dt\int d^dx\ e^{i\omega t}e^{-i\mathbf{q}\cdot\mathbf{x}}\delta P\\
    \widetilde{ \delta \mathbf{u} } 
    &=
    \int dt\int d^dx\ e^{i\omega t}e^{-i\mathbf{q}\cdot\mathbf{x}}\delta \mathbf{u}\\
    \widetilde{ \boldsymbol{\sigma} }_{\mathbf{u}} 
    &=
    \int dt\int d^dx\ e^{i\omega t}e^{-i\mathbf{q}\cdot\mathbf{x}}\boldsymbol{\sigma}_{\mathbf{u}}
\end{aligned}\end{eqnarray}
and Helmholtzde composition $\widetilde{\delta\mathbf{u}}=\widetilde{\delta\mathbf{u}}_{\parallel}+\widetilde{\delta\mathbf{u}}_{\perp}$~\cite{gross2011modelling}, we can obtain
\begin{eqnarray}
    &&-i\omega \widetilde{\delta \phi} = i\Bar{\phi}\mathbf{q}\cdot  \widetilde{\delta\mathbf{u}}_{\parallel}\label{continuity_k} \\
    &&i\mathbf{q}\widetilde{\delta P} 
    - (\eta'+\zeta) q^2 \widetilde{\delta \mathbf{u}}_{\parallel} 
    - (\eta_o'+\zeta_o) q^2 \boldsymbol{\epsilon}\cdot \widetilde{\delta \mathbf{u}}_{\parallel}
    - \Bar{\phi}\frac{\gamma_t}{\sigma^2} \widetilde{\delta \mathbf{u}_{\parallel}} - i \mathbf{q} \widetilde{\sigma}_{\parallel, u}=0\label{NS_k}\\
    &&i\mathbf{q}\widetilde{\delta P} 
    - \eta' q^2 \widetilde{\delta \mathbf{u}}_{\perp}
    - \eta_o' q^2 \boldsymbol{\epsilon}\cdot \widetilde{\delta \mathbf{u}}_{\perp}
    -\Bar{\phi}\frac{\gamma_t}{\sigma^2}\widetilde{\delta \mathbf{u}_{\perp}}
    - i \mathbf{q} \widetilde{\sigma}_{\perp, u}=0
\end{eqnarray}
Generally, the  pressure field $P$ is a function of local fields and the local field derivatives,
\begin{eqnarray}
    \delta P(\phi,T_t,\nabla \phi, \nabla T_t, \nabla^2 \phi, \cdots)
    =
    \frac{1}{\Bar{\chi}_T} \delta\phi + \beta_V\delta T 
    +
    \mathbf{L}_{\phi}\cdot \nabla\delta\phi + \mathbf{L}_T\cdot \nabla\delta T
    -
    K_{\phi}\nabla^2\delta\phi \cdots
\end{eqnarray}
where
\begin{eqnarray}
    &&\frac{1}{\Bar{\chi}_T}=\left. \frac{\partial P}{\partial \phi} \right|_{\Bar{\phi},\Bar{T}_t},~\beta_V=\left. \frac{\partial P}{\partial T_t} \right|_{\Bar{\phi},\Bar{T}_t} 
    ,~\mathbf{L}_{\phi}=\left. \frac{\partial P}{\partial \nabla\phi} \right|_{\Bar{\phi},\Bar{T}_t},~\mathbf{L}_{T}=\left. \frac{\partial P}{\partial \nabla T_t} \right|_{\Bar{\phi},\Bar{T}_t},~
    K_{\phi} = - \left. \frac{\partial P}{\partial \nabla^2\phi} \right|_{\Bar{\phi},\Bar{T}_t}
\end{eqnarray}
The pressure must be invariant to the reflection and rotation symmetry, therefore $\mathbf{L}_{\phi}=\mathbf{L}_{T}=0$. Hence $\delta P$ reduces to
\begin{eqnarray}\label{delta_P}
    \delta P(\phi,T_t,\nabla \phi, \nabla T_t, \nabla^2 \phi, \cdots)
    =
    \frac{1}{\Bar{\chi}_T} \delta\phi + \beta_V\delta T 
    -
    K_{\phi}\nabla^2\delta\phi +\cdots
\end{eqnarray}
Combining Eq.~(\ref{delta_P}) and Eq.~(\ref{NS_k}), we  obtain
\begin{eqnarray}\label{delta_u}
    \mathbf{A}\cdot\widetilde{\delta \mathbf{u}}_{\parallel}={ i\mathbf{q}\left[ 
        \left(\frac{1}{\Bar{\chi}_T}+K_{\phi}q^2\right)\widetilde{\delta \phi}
        +
        \beta_V\widetilde{\delta T}
        -  \widetilde{\sigma}_{\parallel, u}
    \right] }.
\end{eqnarray}
where
\begin{eqnarray}
    \mathbf{A}
    =
    \begin{pmatrix}
        (\eta'+\zeta)q^2+\bar{\phi} \frac{\gamma_t}{\sigma^2} & (\eta_o'+\zeta_o)q^2\\
        -(\eta_o'+\zeta_o)q^2 & (\eta'+\zeta)q^2+\bar{\phi} \frac{\gamma_t}{\sigma^2}
    \end{pmatrix}
\end{eqnarray}
Combining Eq.~(\ref{delta_u}) and Eq.~(\ref{continuity_k}), we  obtain 
\begin{eqnarray}\label{delta_phi}
    -i\omega \widetilde{\delta \phi} 
    &&=
    -   { \Bar{\phi}\left[ 
        \left(\frac{1}{\Bar{\chi}_T}+K_{\phi}q^2\right)\widetilde{\delta \phi}
        +
        \beta_V\widetilde{\delta T}
        -  \widetilde{\sigma}_{\parallel, u}
    \right] }
    \mathbf{q}^T\cdot\mathbf{A}^{-1}\cdot\mathbf{q}
    \nonumber \\
    &&=
    -\Bar{\phi} q^2 \dfrac{ 
        \left(\dfrac{1}    {\Bar{\chi}_T}+K_{\phi}q^2\right)\widetilde{\delta \phi}
        +
        \beta_V\widetilde{\delta T}
        -  \widetilde{\sigma}_{\parallel, u}
    }
    {
        (\eta'+\zeta)q^2+\bar{\phi}\frac{\gamma_t}{\sigma^2} + \dfrac{(\eta_o'+\zeta_o)^2q^4}{(\eta'+\zeta)q^2+\bar{\phi}\frac{\gamma_t}{\sigma^2}}
    }
    \nonumber\\
    &&\approx 
    -\frac{\sigma^2 q^2}{\gamma_t} 
    \left[ 
        \left(\frac{1}{\Bar{\chi}_T}+K_{\phi}q^2\right)\widetilde{\delta \phi}
        +
        \beta_V\widetilde{\delta T}
        -   \widetilde{\sigma}_{\parallel, u}
    \right],
\end{eqnarray}
where we take $q\ll 1$, since we are only concerned with the large scale behavior of the system. The inverse Fourier transform of Eq.~(\ref{delta_phi}) yields
\begin{eqnarray}\label{preFieldEqn}
    \frac{\partial \phi }{\partial t} = {\gamma_t}^{-1}\nabla^2\left( \mu_b - \sigma^2K_{\phi} \nabla^2 \phi  \right)    - \sigma^2{\gamma_t}^{-1} \nabla^2 \sigma_{\parallel, u}
\end{eqnarray}
where the effective chemical potential can be written as 
\begin{eqnarray}
    \mu_b
    =\frac{\delta f_b}{\delta \rho}
    =\sigma^2\frac{\delta f_b}{\delta \phi} = \frac{\sigma^2}{ \Bar\chi_T}  \phi+  \sigma^2\beta_V T_t(\phi)
\end{eqnarray}
with $f_b$ the effective bulk free energy. Combining with effective surface energy, Eq.~(\ref{preFieldEqn}) can be written as 
\begin{eqnarray}
    \frac{\partial  \phi}{\partial t}
    =
    \sigma^2{\gamma_t}^{-1}\nabla^2\frac{\delta F}{\delta \phi}
    -
    \sigma^2{\gamma_t}^{-1}\nabla^2 \sigma_{\parallel, u}
\end{eqnarray}
 with the effective free energy $F$
\begin{eqnarray}
    F[\phi] = \int d^dx~ f_b(\phi) + \frac{1}{2}K_{\phi}|\nabla \phi|^2
\end{eqnarray}


\section*{Appendix C: Universality of Absorbing Phase Transition}

\begin{figure*}[!bhtp]
	\resizebox{130mm}{!}{\includegraphics[trim=0.0in 0.0in 0.0in 0.0in]{figure/CDP.png} }
\caption{Finite size scaling of absorbing phase transition of active spinner system at $\Omega=2\epsilon,~\rho=0.2402\sigma^{-2}$. (a) fraction of translationally active spinners averaged over survival trials as a function of time $f_a(t)$. (b) Data collapse of equilibrated  fraction of translationally active spinners $f_a^{\infty}=f_a(\infty)$. (c) fraction of translationally active spinners averaged over all trials $f_b(t)$~\cite{rossi2000universality}. (d) Data collapse of $f_b(t)$. All the simulation are started from natural initial states~\cite{basu2012fixed,lee2013comment}.  The critical exponents can be obtained from the data: $\alpha=0.52(3)$, $\beta=0.63(2)$, $\nu_{\perp}=0.82(2)$, $z=1.54(2)$.}\label{CDPFig}
\end{figure*}


In the simulations of spinner fluids, we obtain the critical exponents of the absorbing transition, which consistent with CDP universal class (Fig.~\ref{CDPFig})~\cite{henkel2008non,lee2013comment}. In this section we prove that  the  hydrodynamic theory Eqs.(\ref{contiEq}-\ref{kineticEqn2}) can be reduced to CPD field theory near the critical point. As shown in Fig.~\ref{Fig2}a, near the critical point,  we have $\delta T_t/\delta \phi \gg 1$. Therefore, the $\delta\phi$ term in the right side of Eq.~(\ref{delta_phi}) can be ignored, which gives
\begin{eqnarray}
    -i\omega \delta \phi 
    \approx 
    -\frac{\sigma^2q^2}{\gamma_t} 
    \left(
        \beta_V\widetilde{\delta T}
        -   \widetilde{\sigma}_{\parallel, u}
    \right)
\end{eqnarray}
The inverse Fourier transform of above equation yields
\begin{eqnarray} \label{TDiffu}
    \frac{\partial  \phi}{\partial t}
    =    M\nabla^2T_t+\Gamma\nabla^2 \sigma_{\parallel, u}
\end{eqnarray}
with $M= {\sigma^2\beta_V}/{\gamma_t}$ and $\Gamma = -  \sigma^2\gamma_t^{-1}$. Recalling the kinetic energy field Eq.~(\ref{kineticEqn2}) in the main text
\begin{eqnarray}
    \frac{\mathcal{D}T_t}{\mathcal{D}t} &=& D_t\nabla^2 T_t + s_3 \Bar{Z} T_r - s_4\Bar{Z} T_t - \frac{2\gamma_t }{m} T_t  + \eta_t(\mathbf{x},t)
\end{eqnarray}
where $\langle \eta_t(\mathbf{x},t)\eta_t(\mathbf{x}',t') \rangle=
    F_t(T_t)\delta^d(\mathbf{x}'-\mathbf{x})\delta(t-t')$ and $F_t(0)=0$. Neglecting the effect of convection and expanding $T_r(\phi,T_t)$ and $\Bar{Z}(\phi,T_t)$ at $\phi={\phi}_c,~T_t=0$ as
\begin{eqnarray}
    \bar{Z} &=& z_1 T_t + z_2(\phi-\phi_c)+\cdots,\\
         T_r &=& T_{ss} + t_1T_t + t_2(\phi-\phi_c)+\cdots
\end{eqnarray}
Ignoring higher-order terms,  then we can get
\begin{eqnarray}\label{CDP_1}
    \frac{\partial T_t}{\partial t} = D_t\nabla^2 T_t - u_0  - rT_t - u_1T_t^2 + u_2 \phi T_t + 
    u_3\phi + u_4\phi^2 +
    \eta_t(\mathbf{x},t)    
\end{eqnarray}
One can notice that $r=2\gamma_t/m-s_3 z_1 T_{ss}$, so the larger the friction $\gamma_t$ the easier it is for the system to fall into the absorbing state, and the larger the driving power $T_{ss}$ the easier it is for the system to enter the active state, consistent with the simulation results. For the existence of absorbing transition, we must have $u_0=u_3=u_4=0$. Combining Eq.~(\ref{TDiffu}) and Eq.~(\ref{CDP_1}), the field equations for the system near the absorbing critical point can be written as
\begin{eqnarray}
    &&\frac{\partial  \phi}{\partial t}
    =
    M\nabla^2T_t\label{CDP1}\\
    &&\frac{\partial T_t}{\partial t} = D_t\nabla^2 T_t - rT_t - u_1T_t^2 + u_2 \phi T_t + \eta_t(\mathbf{x},t)\label{CDP2}\\
    &&\langle \eta_t(\mathbf{x},t)\eta_t(\mathbf{x}',t') \rangle
    =
    \sigma T_t\delta^d(\mathbf{x}'-\mathbf{x})\delta(t-t')\label{CDP3}
\end{eqnarray}
Note that in the above, we omit higher order noise terms like $\Gamma\nabla^2 \sigma_{\parallel, u}$ in Eq.~(\ref{TDiffu}), and only keep the lowest order in the noise term Eq.~(\ref{CDP3}), because higher order terms are irrelevant in the renormalization group sense.   Since Eqs.~(\ref{CDP1}-\ref{CDP3}) is essentially the Reggeon field theory coupled to a conserved nondiffusing field~\cite{PhysRevE.62.R5875}, which means the absorbing transition of active spinner fluids belongs to CDP universality class.





\section*{Appendix D: Dynamical Field Theory and Renormalization Group Method}

\subsection{Preliminary of Dynamical Field Theory based on Martin-Siggia-Rose-Jansen-De Dominicis Action}
Let's consider the dynamical Langevin-type equation for stochastic field variables $\psi(\mathbf{x},t)$~\cite{CriDyn}
\begin{eqnarray}\label{LangevinEquations}
    \frac{\partial \psi(\mathbf{x},t)}{\partial t}
    =  f [\psi](\mathbf{x},t) 
    +
    \zeta(\mathbf{x},t).
\end{eqnarray}
Here, $\psi(\mathbf{x},t)$ can be understood as a trajectory of a system in configuration space. The  `forces' $  f [\psi](\mathbf{x},t) $ are functional of stochastic field variables $\psi(\mathbf{x},t)$. And $\zeta(\mathbf{x},t)$ is the Gaussian white noise 
\begin{eqnarray}\label{noiseCorrelations}
    \langle \zeta(\mathbf{x},t) \rangle = 0,\ \ \ 
    \langle \zeta(\mathbf{x},t) \zeta(\mathbf{x}',t') \rangle = 2L\delta(\mathbf{x}-\mathbf{x}')\delta(t-t')
\end{eqnarray}
In general, the noise `strength' $L$ is an operator. The noise correlations (\ref{noiseCorrelations}) can be obtained from Gaussian probability distribution $W[\zeta]$
\begin{eqnarray}
    {W}[\zeta]
    \propto
    \exp
    \left(
        -\frac{1}{4}\int d^dx\int dt~  \zeta(\mathbf{x},t)[L^{-1}\zeta(\mathbf{x},t)]
    \right)  \label{noiseCorrelations2}
\end{eqnarray}
We can verify this conclusion by the ratio of the Gaussian integrals
\begin{eqnarray*}
    &&\int \mathcal{D}[\zeta]~ 
    \exp\left(
        -\frac{1}{4}\int d^dy\int dt~ \zeta(\boldsymbol{y},t)  [L^{-1}\zeta(\boldsymbol{y},t)]
    \right) = \det(L)^{1/2}\\
    &&\int \mathcal{D}[\zeta]~ \zeta(\mathbf{x},t)
    \exp\left(
        -\frac{1}{4}\int d^dy\int dt~   \zeta(\boldsymbol{y},t)[L^{-1}\zeta(\boldsymbol{y},t)]
    \right) = 0\\
    &&{\int \mathcal{D}[\zeta]~ \zeta(\mathbf{x},t) \zeta(\mathbf{x}',t') 
    \exp\left(
        -\frac{1}{4}\int d^dy\int dt~   \zeta(\boldsymbol{y},t)[L^{-1}\zeta(\boldsymbol{y},t)]
    \right)
    =
    2\det(L)^{1/2} L  \delta(\mathbf{x}-\mathbf{x}')\delta(t-t')  }
\end{eqnarray*}
Here $\mathcal{D}[\zeta]$ represents the functional integral measure.  The constrain that the fields $\psi$ are subject to the Langevin equations (\ref{LangevinEquations}) can be written as a delta function in path integration,
\begin{eqnarray}
    1
    &=&
    {\int \mathcal{D}[\psi]}  \prod_{(\mathbf{x},t)}
    \delta \left(
        \frac{\partial \psi(\mathbf{x},t)}{\partial t}
    -
    F[\psi](\mathbf{x},t)
    -
    \zeta(\mathbf{x},t)
    \right)      \nonumber \\
    &=&
    \int\mathcal{D}[\psi]  \int\mathcal{D}[i\tilde{\psi}] \cdot  \exp
    \left[
        -\int d^dx \int dt
        \Tilde{\psi}
        \left(
        \frac{\partial \psi}{\partial t}
        -
        F[\psi]
        -
        \zeta
        \right)
    \right]      \label{renormalization}
\end{eqnarray}
In the last line we use the functional integral representation of the the delta function by introducing Martin-Siggia-Rose auxiliary fields $\Tilde{\psi}$. In addition, $2\pi i$ is absorbed into $\mathcal{D}[i\Tilde{\psi}]$
\begin{eqnarray}\label{Dmeasure}
  \mathcal{D}[i\Tilde{\psi}] \mathcal{D}[\psi]
    = \prod_{(\mathbf{x},t)} 
 \frac{ d\Tilde{\psi}(  \mathbf{x}, t) d{\psi}(  \mathbf{x}, t ) }{2\pi i}   
\end{eqnarray}
Our goal is to compute averages of observable $A$ over noise histories, $\langle A[\psi]\rangle_{\zeta}$. Using Eq.~(\ref{noiseCorrelations2}), we arrive at
\begin{eqnarray}
    \langle A[\psi]\rangle_{\zeta} 
    &\propto&
    \int\mathcal{D}[i\tilde{\psi}]\int\mathcal{D}[\psi] \int \mathcal{D}[\zeta] \cdot A[\psi]\cdot \exp
    \left\{
        -\int d^dx \int dt
        \left[
        \Tilde{\psi}  \left(
            \frac{\partial \psi}{\partial t}
            -
            F[\psi]
        \right) +   
            \frac{1}{4}\zeta L^{-1}\zeta-\Tilde{\psi}\zeta
        \right] 
    \right\} ~~~
\end{eqnarray}
The noise average can be performed via Gaussian integral
\begin{eqnarray} \label{Gaussian_integral}
\int \mathcal{D}[\zeta]~ \exp\left\{
    \int d^dx \int dt~ \left[\tilde{\psi}(\mathbf{x},t)\zeta(\mathbf{x},t)-\zeta(\mathbf{x},t) L^{-1}\zeta(\mathbf{x},t)/4\right]
    \right\}
    =
    \det{({L})}^{1/2}\exp\left[\int d^dx\int dt~ \tilde{\psi}(\mathbf{x},t)L \tilde{\psi}(\mathbf{x},t)\right]
\end{eqnarray}
Then we can obtain  the probability distribution of system evolving according to trajectory $\psi(\mathbf{x},t)$,
\begin{eqnarray}
    \mathcal{P}[\psi]
    =
    \mathcal{C}^{-1}\int \mathcal{D}[i\Tilde{\psi}]e^{-\mathcal{A}[\Tilde{\psi},\psi]}
\end{eqnarray}
with a statistical weight determined by the dynamical Martin-Siggia-Rose-Jansen-De Dominicis (MSRJD) action~\cite{CriDyn}
\begin{eqnarray}
    \mathcal{A}[\Tilde{\psi},\psi]
    =
    \int d^dx\int dt~
    \left[
        \Tilde{\psi}(\mathbf{x},t)
        \left(
            \dfrac{\partial {\psi}(\mathbf{x},t)}{\partial t}
            -
            F[\psi](\mathbf{x},t)
        \right)
        -
        \Tilde{\psi}(\mathbf{x},t) L \Tilde{\psi}(\mathbf{x},t)
    \right]
\end{eqnarray}
{The normalization factor $\mathcal{C}=\int \mathcal{D}[i\Tilde{\psi}]\int \mathcal{D}[\psi]e^{-\mathcal{A}[\Tilde{\psi},\psi]}=1$~\cite{CriDyn}.}  As shown latter, physical quantities can generally {be expanded into} correlation functions of the fields $\psi$ and $\Tilde{\psi}$, taken with the statistical weight $e^{-\mathcal{A}[\Tilde{\psi},\psi]}$
\begin{eqnarray}\label{statisticalMoments}
    \left\langle 
        \prod_{ij} \psi(\mathbf{x}_i, t_i) \Tilde{\psi}(\mathbf{x}_j, t_j)
    \right \rangle
    =
    \frac{
        \int \mathcal{D}[i\Tilde{\psi}]\int \mathcal{D}[\psi] 
        \prod_{ij} \psi(\mathbf{x}_i, t_i)
        \Tilde{\psi}(\mathbf{x}_j, t_j) 
        e^{-\mathcal{A}[\Tilde{\psi}, \psi]}
    }
    {
        \int \mathcal{D}[i\Tilde{\psi}]\int \mathcal{D}[\psi]
        e^{-\mathcal{A}[\Tilde{\psi}, \psi]}
    }
\end{eqnarray}
So technically, the aim is to compute all kinds of such correlation functions.  

We also introduce the analysis of scaling dimension based on action, which should be dimensionless.  For example, through $ \mathcal{A} = \int d^dx\int dt~\Tilde{\psi}\frac{\partial }{\partial t}\psi$ we can obtain $d\Delta_x+\Delta_{\Tilde{\psi}}+\Delta_{\psi}=0$, and because $\Delta_x=-1$, we obtain $\Delta_{\Tilde{\psi}}+\Delta_{\psi}=d$. Other scaling dimension can be obtained likewisely.


\subsection{Dynamical Field Theory for Generalized Model B with Spatially Correlated Noise}

Based on the above preliminary, we now study the dynamic field theory of a generalized model B 
\begin{eqnarray}\label{CMC-modelB-AP}
    \frac{\partial \psi}{\partial t}
    =
    \nabla^2\left({
        r\psi - \nabla^2 \psi + \frac{u}{6} \psi^3 - h
    }\right)
    + 
    {\xi}(\mathbf{x},t)
\end{eqnarray}
Here, $h\to 0$ is a weak external field and noise correlation is
\begin{eqnarray}
    \langle{ \xi(\mathbf{x},t)\xi(\mathbf{x}',t') }\rangle = 2D (i\nabla)^{2+\theta}\delta^d(\mathbf{x}-\mathbf{x}')\delta(t-t')
\end{eqnarray}
Here, $\theta=0$ corresponds to claissical model B~\cite{hohenberg1977theory,CriDyn}, while $\theta=2$ corresponds  to Eq.~(\ref{CMC-modelB-s}), the proposed model B theory for HU fluid.


We first discuss the finite-size scaling of the density
fluctuation or static structure factor
\begin{eqnarray*}
    S(\tau,q)=\int \frac{d\omega}{2\pi} C(q,\omega)=\int \frac{d\omega}{2\pi}
    \int d^dx\int dt~e^{-i\boldsymbol{q}\cdot\boldsymbol{x} -i\omega t}
    C(x,t)
    =
    \int \frac{d\omega}{2\pi}
    \int d^dx\int dt~e^{-i\boldsymbol{q}\cdot\boldsymbol{x} -i\omega t}
    \langle \psi(x,t)\psi(x',t') \rangle\
\end{eqnarray*}
Noting $\Delta_{\psi}=\frac{d-2+\theta+\eta}{2},~\Delta_t=-\Delta_{\omega}=-4,~\Delta_x=-\Delta_q=-1$, based on the method in the previous subsection we can obtain the scaling dimension of the static structure factor $\Delta_S=\theta+\eta-2=\theta-\gamma/\nu$. 
So, the static structure factor has the homogeneous form
\begin{eqnarray}\label{PrimeScaling}
    S(\tau,q) = q^{\theta-\gamma/\nu}\mathcal{S}(\tau/q^{1/\nu})
\end{eqnarray}
Then, the  amplitude of the static structure factor at the minimum wave number $2\pi/L$, i.e., $\chi_{\rho}(\tau,L)=S(\tau,2\pi/L)$, satisfies~\cite{Torquato2003}   
\begin{eqnarray}
    \chi_{\rho}(\tau,L)   =    L^{\gamma/\nu-\theta}{S}_{\rho}(\tau L^{1/\nu})
\end{eqnarray}

 The dynamical MSRJD action of Eq.(\ref{CMC-modelB-AP}) can be divided into Gaussian and non-Gaussian parts $\mathcal{A}[\Tilde{\psi},\psi]=\mathcal{A}_0[\Tilde{\psi},\psi]+\mathcal{A}_{I}[\Tilde{\psi},\psi]$. The Gaussian part is
\begin{eqnarray}\label{action_0}
\begin{aligned}
        \mathcal{A}_0[\Tilde{\psi},\psi]
    =&
    \int d^dx\int dt\ \left(
        \Tilde{\psi}(\mathbf{x},t)\left[{
            \frac{\partial }{\partial t}-\nabla^2(r-\nabla^2)    
        }\right]  \psi(\mathbf{x},t)
        -
        D\Tilde{\psi}(\mathbf{x},t)(i\nabla)^{2+\theta}\Tilde{\psi}(\mathbf{x},t)
        -
        \Tilde{\psi}\nabla^2 h(\mathbf{x},t) \right)
\end{aligned}
\end{eqnarray}
The non-Gaussian part  is
\begin{eqnarray}\label{action_ini}
    \mathcal{A}_{I}[\Tilde{\psi},\psi]
    =
    \frac{u}{6}\int d^dx\int dt\
    \Tilde{\psi}(\mathbf{x},t)(i\nabla)^{2+\theta}[{\psi}(\mathbf{x},t)]^3.
\end{eqnarray}


The complete action $\mathcal{A}=\mathcal{A}_0+\mathcal{A}_{I}$ cannot be integrated directly. However, one can express all  physical quantities as perturbative expansions of Gaussian action $\langle \cdots \rangle_0$ which can be calculated analytically. Under the Fourier transform
\begin{eqnarray}\label{Fourier}
\begin{aligned}
    &\psi(\mathbf{x},t)=\int_q \int_{\omega}~ e^{-i\omega t}e^{i\mathbf{q}\cdot\mathbf{x}}\psi(\mathbf{q},\omega)\\
    &\Tilde{\psi}(\mathbf{x},t)=\int_q \int_{\omega}~ e^{-i\omega t}e^{i\mathbf{q}\cdot\mathbf{x}}\Tilde{\psi}(\mathbf{q},\omega)\\
    &(2\pi)^{d+1}\delta^d(\mathbf{q})\delta(\omega)=\int d^dx \int dt~e^{-i\omega t}e^{i\mathbf{q}\cdot\mathbf{x}}
\end{aligned}
\end{eqnarray}
where $\int_q\int_{\omega}=\int\frac{d^dk}{(2\pi)^d}\int\frac{d\omega}{2\pi}$. 
We can write the Gaussian action Eq.(\ref{action_0}) as ($h(\mathbf{x},t)\to 0$)
\begin{eqnarray}\label{actionGaussian}
    \begin{aligned}
     \mathcal{A}_0[\Tilde{\psi},\psi]
     =&
     (2\pi)^{d+1}\int_q\int_{\omega}\int_{q'}\int_{\omega'}\delta(\omega+\omega')\delta^d(\mathbf{q}+\mathbf{q}')
     \left(
         \Tilde{\psi}(\mathbf{q}',\omega')
         \left[{
             -i\omega+q^2(r+q^2)    
         }\right]
         {\psi}(\mathbf{q},\omega)
         -
         Dq^{2+\theta}\Tilde{\psi}(\mathbf{q}',\omega')\Tilde{\psi}(\mathbf{q},\omega)
        \right)\\
     =&
     \int_q\int_{\omega}
     \left(
         \Tilde{\psi}(-\mathbf{q},-\omega)
         \left[{
             -i\omega+q^2(r+q^2)    
         }\right]
         {\psi}(\mathbf{q},\omega)
         -
         Dq^{2+\theta}\Tilde{\psi}(-\mathbf{q},-\omega)\Tilde{\psi}(\mathbf{q},\omega)
        \right)\\
        =&
        \frac{1}{2}\int_q\int_{\omega}
        \begin{pmatrix}
            \Tilde{\psi}(-\mathbf{q},-\omega) &{\psi}(-\mathbf{q},-\omega)
        \end{pmatrix}
        \mathbf{A}(\mathbf{q},\omega)
        \begin{pmatrix}
            \Tilde{\psi}(\mathbf{q},\omega)\\
            {\psi}(\mathbf{q},\omega)
        \end{pmatrix}
 \end{aligned}
\end{eqnarray}
where the Hermitian matrix
 \begin{eqnarray*}
     \mathbf{A}(\mathbf{q},\omega)
     =
     \begin{pmatrix}
         -2Dq^{2+\theta} &-i\omega+q^2(r+q^2)\\
         i\omega+q^2(r+q^2) &0
     \end{pmatrix}
 \end{eqnarray*}
In order to compute correlations functions, it's useful to introduce the generating functional, 
\begin{eqnarray}
    \mathcal{Z}[\Tilde{j},j]
    &=&
    \left\langle 
        \exp \int_q \int_{\omega}~
        \left[
            \Tilde{j}(-\mathbf{q},-\omega)\Tilde{\psi}(\mathbf{q},\omega)
            +
            {j}(-\mathbf{q},-\omega){\psi}(\mathbf{q},\omega)
        \right]
    \right \rangle  \\
            &=&        
            \dfrac{\displaystyle \int \mathcal{D}[i\Tilde{\psi}]\int \mathcal{D}[\psi]\cdot  \exp \left[-\mathcal{A}[\Tilde{\psi},\psi] 
            +
            \int_q\int_{\omega}
            \begin{pmatrix}
                \Tilde{j} &{j}
            \end{pmatrix}
            \begin{pmatrix}
                \Tilde{\psi}\\
                {\psi}
            \end{pmatrix} \right]
     }
     {\displaystyle \int \mathcal{D}[i\Tilde{\psi}]\int \mathcal{D}[\psi]\cdot  \exp \left(-\mathcal{A}[\Tilde{\psi},\psi] 
      \right)
     }  
\end{eqnarray} 
where we use the fact that Jacobian of Fourier transformation is 1, because the Fourier transformation is an unitary transformation~\cite{peskin2018introduction}.
Based on the generating functional, the correlation functions can be obtained via functional derivatives
\begin{eqnarray}\label{functionalDerivatives}
    \left \langle
        \prod_{i,k}{\psi}(\mathbf{q}_i,\omega_i)\Tilde{\psi}(\mathbf{q}_k,\omega_k)
    \right \rangle
    =
    \left. \prod_{i} (2\pi)^{d+1} 
    \frac{\delta}{\delta {j}(\mathbf{q}_i,\omega_i)}
    \prod_{k}(2\pi)^{d+1} 
    \frac{\delta}{\delta \Tilde{j}(\mathbf{q}_k,\omega_k)} \mathcal{Z}[\Tilde{j},j]\right|_{\Tilde{j}=j=0}.
\end{eqnarray}
For Gaussian action $ \mathcal{A}_0 $, the generating functional can be calculated by Gaussian integral Eq.~(\ref{Gaussian_integral})
\begin{eqnarray}
     \begin{aligned}
     \mathcal{Z}_0[\Tilde{j},j]
     =&
     \dfrac{\displaystyle
         \int \mathcal{D}[i\Tilde{\psi}]\int \mathcal{D}[\psi]\exp 
         \left[
             -\frac{1}{2}\int_q\int_{\omega}
            \begin{pmatrix}
                \Tilde{\psi} &{\psi}
            \end{pmatrix}
            \boldsymbol{A}
            \begin{pmatrix}
                \Tilde{\psi}\\
                {\psi}
            \end{pmatrix}
            +
            \int_q\int_{\omega}
            \begin{pmatrix}
                \Tilde{j} &{j}
            \end{pmatrix}
            \begin{pmatrix}
                \Tilde{\psi}\\
                {\psi}
            \end{pmatrix}
         \right]
     }
     {\displaystyle
         \int \mathcal{D}[i\Tilde{\psi}]\int \mathcal{D}[\psi]\exp 
             \left[
                 -\frac{1}{2}\int_q\int_{\omega}
                \begin{pmatrix}
                    \Tilde{\psi} &{\psi}
                \end{pmatrix}
                \boldsymbol{A}
                \begin{pmatrix}
                    \Tilde{\psi}\\
                    {\psi}
                \end{pmatrix}
             \right]
         }
     \\
     =&
     \exp\left[
         \frac{1}{2}\int_q\int_{\omega}
        \begin{pmatrix}
            \Tilde{j}(-\mathbf{q},-\omega) &{j}(-      \mathbf{q},-\omega)
        \end{pmatrix}
        \boldsymbol{A}^{-1}(\mathbf{q},\omega)
        \begin{pmatrix}
            \Tilde{j}(\mathbf{q},\omega)\\
            {j}(\mathbf{q},\omega)
        \end{pmatrix}
     \right]
 \end{aligned}
\end{eqnarray}
We can infer the matrix of two-point correlation functions by functional derivatives,
\begin{eqnarray}\label{2moments}
    \begin{pmatrix}
        \langle{\Tilde{\psi}(\mathbf{q},\omega)\Tilde{\psi}(\mathbf{q}',\omega')}\rangle_0
        &\langle{\Tilde{\psi}(\mathbf{q},\omega){\psi}(\mathbf{q}',\omega')}\rangle_0\\
        \langle{{\psi}(\mathbf{q},\omega)\Tilde{\psi}(\mathbf{q}',\omega')}\rangle_0
        &\langle{{\psi}(\mathbf{q},\omega){\psi}(\mathbf{q}',\omega')}\rangle_0
    \end{pmatrix}
    =
    \mathbf{A}^{-1}(\mathbf{q},\omega)(2\pi)^{d+1}
    \delta^d(\mathbf{q}+\mathbf{q}')\delta(\omega+\omega')
\end{eqnarray}
with the inverse of the matrix
\begin{eqnarray}\label{harmonicMatrix}
    \begin{aligned}
        \mathbf{A}^{-1}(\mathbf{q},\omega)
        =&
        \frac{1}{\omega^2+[q^2(r+q^2)]^2}
        \begin{pmatrix}
            0&-i\omega+q^2(r+q^2)\\
            i\omega+q^2(r+q^2)&2Dq^{2+\theta}
        \end{pmatrix}
    \end{aligned}
\end{eqnarray}
Using Eqs.~(\ref{functionalDerivatives}-\ref{harmonicMatrix}) we can obtain all physical quantities by averaging on Gaussian action $\langle \cdots \rangle_0$. In fact, according to Wick's theorem for Gaussian ensemble~\cite{CriDyn}, any odd order moments is zero, and any even order moments can always be expressed as a sum of products of two-point correlation functions (\ref{2moments}). For example
\begin{eqnarray*}
    \langle \psi(\mathbf{q}_1,t_1) \psi(\mathbf{q}_2,t_2) \psi(\mathbf{q}_3,t_3) \psi(\mathbf{q}_4,t_4) \rangle_0
    &=&
    \langle \psi(\mathbf{q}_1,t_1) \psi(\mathbf{q}_2,t_2) \rangle_0
    \langle \psi(\mathbf{q}_3,t_3) \psi(\mathbf{q}_4,t_4) \rangle_0
    \\
    &&+
    \langle \psi(\mathbf{q}_1,t_1) \psi(\mathbf{q}_3,t_3) \rangle_0
    \langle \psi(\mathbf{q}_2,t_2) \psi(\mathbf{q}_4,t_4) \rangle_0
    \\
    &&+
    \langle \psi(\mathbf{q}_1,t_1) \psi(\mathbf{q}_4,t_4) \rangle_0
    \langle \psi(\mathbf{q}_2,t_2) \psi(\mathbf{q}_3,t_3) \rangle_0
\end{eqnarray*}
In the Gaussian field theory, the bare response propagator and bare correlation function is defined as
\begin{eqnarray}
    &&\langle{{\psi}(\mathbf{q},\omega)\Tilde{\psi}(\mathbf{q}',\omega')}\rangle_0
    =
    G_0(q,\omega)(2\pi)^{d+1}\delta^d(\mathbf{q}+\mathbf{q}')\delta(\omega+\omega')
    \\
    &&\langle{{\psi}(\mathbf{q},\omega){\psi}(\mathbf{q}',\omega')}\rangle_0
    =
    C_0(q,\omega)(2\pi)^{d+1}\delta^d(\mathbf{q}+\mathbf{q}')\delta(\omega+\omega')
\end{eqnarray}
from which the bare response propagator and correlation function can be obtained
\begin{eqnarray}
    G_0(q,\omega)
    &=&
    \frac{1}{ -i\omega + q^2(r+q^2) }\label{Sus0q} \\
    C_0(q,\omega)
    &=&
    \frac{2D q^{2+\theta}}{ \omega^2 + [ q^2(r+q^2) ]^2 } = 2Dq^{2+\theta} G_0(q,\omega)G_0(-q,-\omega)  \label{C0q}
\end{eqnarray}


By the generating functional and the definition of the dynamic susceptibility we get
\begin{eqnarray}
    \chi_0(q,\omega) = \left.\frac{\partial\langle \psi(\mathbf{q},\omega) \rangle_0}{\partial h(\mathbf{q},\omega)}\right|_{h=0} = q^2G_0(q,\omega) 
\end{eqnarray}
Obviously, classical fluids ($\theta=0$) satisfy the fluctuation-dissipation relation $\mathrm{Im}~ \chi_0(q,\omega)=\omega C_0(q,\omega)/(2k_B T)$, where $k_BT=D$. And HU fluids ($\theta=2$) obviously do not satisfy. However, if we assume a scale-dependent effective temperature $k_B T_{\text{eff}}(q) = Dq^{\theta}$ then we have a general fluctuation-dissipation relation $\mathrm{Im}~ \chi_0(q,\omega)=\omega C_0(q,\omega)/T_{\text{eff}}(q)~$\cite{Young2020}. This means that HU fluids becomes cooler at larger length scale.

The bare susceptibility function at long time ($\omega=0$) in real space can be obtained by the Fourier transform
\begin{eqnarray}
    \chi_0(x)
    =
    \int\frac{d^dq}{(2\pi)^d} e^{-i\mathbf{q}\cdot\mathbf{x}}   \chi_0(q,0) 
    =\int_q \frac{e^{-i\mathbf{q}\cdot\mathbf{x}}}{r+q^2}  
\end{eqnarray}
Then we use the asymptotic behavior of the Ornstein-Zernicke correlation function \cite{Tong,ElementsCri}
\begin{eqnarray}\label{sus}
    \chi_0(x)
    =
    \int\frac{d^dq}{(2\pi)^d} e^{-i\mathbf{q}\cdot\mathbf{x}}   \chi_0(q,0) 
    =\int_q \frac{e^{-i\mathbf{q}\cdot\mathbf{x}}}{\xi^{-2}+q^2}  
    \sim 
    \left\{
    \begin{aligned}
        \dfrac{1}{x^{d-2}},\ \ \ 
    x\ll \xi \\
    \dfrac{e^{-x/\xi}}{x^{(d-1)/2}},\ \ \ 
    x\gg \xi \\
    \end{aligned}
    \right.
\end{eqnarray}
where the characteristic length $\xi=r^{-1/2}$ is the correlation length.
Eq.~(\ref{sus}) indicates that the response of the system to the external field decays exponentially at $x\gg \xi$. At the critical point $r=0$ the correlation length $\xi$ diverges, whereupon the response of the system to the external field is always power-law decaying, indicating that at the critical point the system is very susceptible 
similar to classical LG critical point.

When $\theta=0$, the bare correlation function in real space can be obtained by the Fourier transform
\begin{eqnarray}
    C_0(x)
    =
    \int\frac{d^dq}{(2\pi)^d} e^{-i\mathbf{q}\cdot\mathbf{x}} \int\frac{d\omega}{2\pi}  C_0(q,\omega) 
    =D\int_q \frac{e^{-i\mathbf{q}\cdot\mathbf{x}}}{r+q^2} 
    \sim
    \left\{
    \begin{aligned}
        \dfrac{D}{x^{d-2}},\ \ \ 
    x\ll \xi \\
    \dfrac{De^{-x/\xi}}{x^{(d-1)/2}},\ \ \ 
    x\gg \xi \\
    \end{aligned}
    \right.
\end{eqnarray}
For $\theta=2$ we have
\begin{eqnarray}
\begin{aligned}
    C_0(x)
    =  D\int_q \frac{q^2e^{-i\mathbf{q}\cdot\mathbf{x}}}{r+q^2}    
    =  D\int_q e^{-i\mathbf{q}\cdot\mathbf{x}}    
    - 
    Dr\int_q \frac{e^{-i\mathbf{q}\cdot\mathbf{x}}}{r+q^2}  
    ~~ \sim ~~
    \left\{
    \begin{aligned}
        &D\delta(\mathbf{x})-\dfrac{Dr}{x^{d-2}},\ \ \ 
    & x\ll \xi \\
    &D\delta(\mathbf{x})-\dfrac{Dre^{-x/\xi}}{x^{(d-1)/2}},\ \ \ 
    & x\gg \xi \\
    \end{aligned}
    \right.
\end{aligned}
\end{eqnarray}

As mentioned above, the complete action $\mathcal{A}=\mathcal{A}_0+\mathcal{A}_{I}$  includes the non-linear terms like $-\frac{u}{6} \Tilde{\psi}\nabla^2 {\psi}^3$ which can not be calculated analytically. Therefore, we need to write correlation functions of the complete  average $\langle \cdots \rangle$ as correlation functions of Gaussian average $\langle \cdots \rangle_0$ by polynomial expansion. In this sense, Eq.~(\ref{statisticalMoments}) can be written as 
\begin{eqnarray}\label{perturbationOrigin}
    \begin{aligned}
        \left\langle
            \prod_{ij}\psi(\mathbf{q}_i,\omega_i) \Tilde{\psi}(\mathbf{q}_j,\omega_j) 
        \right\rangle
        &=
        \frac{
            \left\langle
            \prod_{ij}\psi(\mathbf{q}_i,\omega_i) \Tilde{\psi}(\mathbf{q}_j,\omega_j) e^{-\mathcal{A}_{I}[\Tilde{\psi}, \psi]}
            \right\rangle_0
        }
        {
            \left\langle
                e^{-\mathcal{A}_{I}[\Tilde{\psi}, \psi]}
            \right\rangle_0
        }
        \\
        &=
        \frac{
            \left\langle
            \prod_{ij}\psi(\mathbf{q}_i,\omega_i) \Tilde{\psi}(\mathbf{q}_j,\omega_j) 
            \sum_{l=0}^{\infty}\left( -\mathcal{A}_{I}[\Tilde{\psi}, \psi]^l \right)/l!
            \right\rangle_0
        }
        {
            \left\langle
                \sum_{l=0}^{\infty}\left( -\mathcal{A}_{I}[\Tilde{\psi}, \psi]^l \right)/l!
            \right\rangle_0
        }
    \end{aligned}
\end{eqnarray}
where the correlation functions in complete average $\langle \cdots \rangle$ is written as the perturbation series consisting of correlation functions in the Gaussian average $\langle \cdots \rangle_0$.  Theoretically we can get perturbative approximations for all physical quantities $\langle \cdots \rangle$ by Eq.~(\ref{perturbationOrigin}).
However the process of writing perturbation terms in Eq.~(\ref{perturbationOrigin}) is  notoriously difficult. This procedure can be simplified by Feynman diagrams~\cite{CriDyn}, here we introduce elements of Feynman diagrams of our models:
