We note that in \cite{BourgeoisEkholmEliashberg12}, the hypothesis of the previous theorem was established for $n=2$. While it is likely that the techniques in that paper established the hypothesis for all $n>2$ too, we have not been able to verify that. 

We now turn to lesser-sloped, non-integral cable links. 

\begin{theorem}\label{negative}
  Let $K$ be a uniformly thick knot type and $p$ and $q$ relatively prime with $q/p<\tbb(K)$. Let $L_1, \ldots, L_k$ be the distinct Legendrian knots in $\mathcal{L}(K)$ with $\tb=\lceil q/p\rceil$. Every element in $\mathcal{L}(K_{n(p,q)})$ destabilizes to $(L_i)^\pm_{n(p,q)}$ for some $i$ and $\pm$.

  We distinguish the $(L_i)^\pm_{n(p,q)}$ as follows.
  \begin{enumerate}
    \item If $\rot(L_i)\not= \rot(L_j)$, then $(L_i)^\pm_{n(p,q)}$ and $(L_j)^\pm_{n(p,q)}$ are distinct. 
    \item If $\rot(L_i)=\rot(L_j)$ but $S_\pm(L_i)\not=S_\pm(L_j)$, then $(L_i)^\pm_{n(p,q)}$ and $(L_j)^\pm_{n(p,q)}$ are distinct. 
    \item If $\rot(L_i)=\rot(L_j)$ but Legendrian surgery in $L_i$ and $L_j$ yield distinct contact manifolds, then $(L_i)^\pm_{n(p,q)}$ and $(L_j)^\pm_{n(p,q)}$ are distinct. 
    \item Otherwise, it is not clear if $(L_i)^\pm_{n(p,q)}$ and $(L_j)^\pm_{n(p,q)}$ are distinct. 
  \end{enumerate} 

  We  distinguish stabilizations of the $(L_i)^\pm_{n(p,q)}$ as follows.
  \begin{enumerate}
    \item Stabilizations of $(L_i)^+_{n(p,q)}$ and $(L_i)^-_{n(p,q)}$ remain distinct until each component of the first link has been  $-$-stabilized $|p\tb(L)-q|$ or more times, each component of the second link has been $+$ -stabilized $|p\tb(L)-q|$ or more times, and the classical invariants of the components of one link match those of the other, in this case they are Legendrian isotopic.
    \item If $S_+(L_i)=S_-(L_j)$, then $(L_i)^+_{n(p,q)}$ and $(L_j)^-_{n(p,q)}$ will have distinct rotation numbers until each component of the first has been $+$-stabilized $|p(\tb(L)-1)-q|$ times and each component of the second has been $-$-stabilized $|p(\tb(L)-1)-q|$ times. After each has been stabilized as indicated, they become Legendrian isotopic. 
    \item If $S_\pm(L_i)=S_\pm(L_j)$, but Legendrian surgery on $L_i$ and $L_j$ yield distinct contact manifolds, then stabilizations of $(L_i)^\pm_{n(p,q)}$ and $(L_j)^\pm_{n(p,q)}$ remain distinct until each component of the of both links have been $\pm$-stabilized $|p(\tb(L)-1)-q|$ or more times, and the classical invariants of the components of one link match those of the other, in this case they are Legendrian isotopic.
    \item If $S^l_\pm(L_i)$ is not Legendrian isotopic to $S^l_\pm(L_j)$ for any $l$, then any number of $\pm$-stabilizations of $(L_i)^\pm_{n(p,q)}$ and $(L_j)^\pm_{n(p,q)}$ remain distinct.
  \end{enumerate} 
\end{theorem}

The statements in the theorem do not necessarily classify all Legendrian cable knots of uniformly thick knot types, but the theorem and its proof are sufficient in many cases. In particular, we have the following result. 

\begin{theorem}\label{lesserlink}
  Let $K$ be the $-2n$-twist knot, $p$ and $q$ relatively prime with $-q/p<1$ and $n>1$ an integer. Let $L_1, \ldots, L_k$ be the distinct Legendrian knots in $\mathcal{L}(K)$ with $\tb=\lceil -q/p\rceil$. Every element in $\mathcal{L}(K_{n(p,-q)})$ destabilizes to $(L_i)^\pm_{n(p,-q)}$ for some $i$ and $\pm$. Two Legendrian links in $\mathcal{L}(K_{n(p,-q)})$ are Legendrian isotopic if and only if they are component-wise isotopic. The classification of Legendrian realizations of $K_{n(p,q)}$ now follows from Theorem~\ref{knotcable} when $q/p<0$ and from Theorem~\ref{ifsurg} if Legendrian surgery on the maximal Thurston-Bennequin invariant representatives of $K$ are distinct. 
\end{theorem}

